-- 06_functions.sql: 1037 statements, exported from production's catalog
-- @@ function public.update_timestamp()
CREATE OR REPLACE FUNCTION public.update_timestamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$;
-- @@ function public.log_vehicle_state_change()
CREATE OR REPLACE FUNCTION public.log_vehicle_state_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
BEGIN
  IF OLD.current_state IS DISTINCT FROM NEW.current_state THEN
    INSERT INTO vehicle_state_log (
      vehicle_id, depot_id, previous_state, new_state,
      triggered_by, stall_id, metadata
    ) VALUES (
      NEW.id,
      NEW.current_depot_id,
      OLD.current_state,
      NEW.current_state,
      'otto_q_engine',  -- Default; overridden by application layer when appropriate
      NEW.current_stall_id,
      jsonb_build_object(
        'soc_at_transition', NEW.current_soc,
        'previous_stall_id', OLD.current_stall_id
      )
    );
    /* ══════════ 0057: PRESERVE THE CALLER'S CLOCK ══════════
       This trigger unconditionally stamped NOW() over last_state_change,
       clobbering the SIM-CLOCK stamp that every twin write site carefully
       passes (p_sim_clock / v_clock / p_sim_clock_now — 40+ sites swept).
       That made last_state_change a REAL-clock column in twin runs, and two
       decide-path fairness cursors ORDER BY it — so vehicle processing order
       tracked wall-clock execution physics instead of the seed (measured:
       re-cert #11, tick-4 task_start order fully scrambled across a same-seed
       pair with every state and SoC paired). The guard keeps the old behavior
       byte-for-byte for callers that DON'T set the column (it defaults to
       NOW() exactly as before) and stops clobbering callers that DO. */
    /* ══════════ 0061: THE 0057 GUARD HAD A BLIND SPOT ══════════
       A caller that passes the SAME stamp the row already holds is, inside a
       BEFORE UPDATE trigger, indistinguishable from one that passes nothing —
       and that is exactly what happens when a vehicle changes state TWICE IN
       ONE TICK: the second write carries the same sim clock the first stored,
       the guard reads "unset", and NOW() (a REAL clock) lands in the column two
       decide-path fairness cursors and the service-flow release cursor ORDER BY.
       Measured (re-cert #15, arms c5dbc377/943936c5, 19/20, sole divergence
       sim-min 600): vehicle 964bd583 went charging_l2 -> charge_complete_holding
       -> staged_for_departure inside tick 20, and that second write stamped
       2026-08-20T18:06:36 (wall clock) over the run's own 2026-08-21T04:05:32
       (sim clock); the cap-limited release cursor then admitted a different
       member set in each arm.
       The default stamp is now SIM-DOMAIN whenever this vehicle's depot has a
       RUNNING sim run, so the equal-value case re-stamps the identical sim clock
       (a no-op) instead of a wall clock. Production is unchanged: a depot with no
       running sim run still falls back to NOW(), exactly as before. */
    IF NEW.last_state_change IS NOT DISTINCT FROM OLD.last_state_change THEN
      NEW.last_state_change = COALESCE(
        (SELECT r.sim_clock_current FROM public.ottoq_sim_runs r
          WHERE r.status = 'running'
            AND r.depot_id = COALESCE(NEW.current_depot_id, NEW.home_depot_id)
          ORDER BY r.started_at DESC, r.sim_run_id
          LIMIT 1),
        /* 0256: THE SECOND BRANCH. The branch above asks for a RUNNING run, and at a
           teardown there is none -- ottoq_sim_stop_and_reset flips the status via
           mark_stopped, and ottoq_sim_advance_tick_world writes status='completed'
           mid-function (0103), both BEFORE ottoq_sim_release_depot touches a vehicle. So
           the equal-value case the 0061 guard exists to catch fell through to NOW() at
           every teardown, putting a WALL clock into a column ottoq_world_fingerprint
           hashes -- 20 of 116 flagship vehicles, measured in db/checks/0176, in the same
           statement whose other 96 rows took 0255's sim clock. Both teardown routes pin
           the run in this GUC one line before they call release_depot (0092, added for
           this exact class of blindness); this branch reads it, status-independent.
           Same depot predicate as above: a GUC naming another depot's run must not stamp
           this vehicle. run_by excludes production, which keeps NOW() unchanged -- all 8
           production_live runs carry a real-clock sim_clock_current and production_start
           /_stop are themselves GUC setters, so the branch would otherwise change
           production behaviour that nothing here can test. The uuid shape test is not
           decoration: a bad cast inside this trigger would abort a tick. */
        (SELECT r.sim_clock_current FROM public.ottoq_sim_runs r
          WHERE r.sim_run_id = (CASE WHEN COALESCE(current_setting('ottoq.sim_run_id', true), '')
                                          ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                                     THEN current_setting('ottoq.sim_run_id', true)::uuid END)
            AND r.depot_id = COALESCE(NEW.current_depot_id, NEW.home_depot_id)
            AND COALESCE(r.run_by, '') <> 'production_live'),
        NOW());
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
-- @@ function public.sync_stall_occupancy()
CREATE OR REPLACE FUNCTION public.sync_stall_occupancy()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
BEGIN
  -- Clear old stall
  -- 0011-TETHER: ...unless a robot is still mated to it. Deliberately tested against
  -- NEW's own columns only -- no function call and no extra read, because this trigger
  -- fires on every vehicles UPDATE and must stay cheap and unable to raise.
  IF OLD.current_stall_id IS NOT NULL AND OLD.current_stall_id IS DISTINCT FROM NEW.current_stall_id
     AND NOT (NEW.robotic_tether_until IS NOT NULL
              AND NEW.robotic_tether_stall_id IS NOT DISTINCT FROM OLD.current_stall_id) THEN
    UPDATE stalls SET
      status = 'available',
      current_vehicle_id = NULL
    WHERE id = OLD.current_stall_id;
  END IF;

  -- Occupy new stall
  IF NEW.current_stall_id IS NOT NULL AND OLD.current_stall_id IS DISTINCT FROM NEW.current_stall_id THEN
    UPDATE stalls SET
      status = 'occupied',
      current_vehicle_id = NEW.id
    WHERE id = NEW.current_stall_id;
  END IF;

  RETURN NEW;
END;
$function$;
-- @@ function public.update_wave_count()
CREATE OR REPLACE FUNCTION public.update_wave_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
    IF NEW.wave_id IS NOT NULL THEN
      UPDATE waves SET vehicle_count = (
        SELECT COUNT(*) FROM vehicle_schedules WHERE wave_id = NEW.wave_id AND status != 'cancelled'
      ) WHERE id = NEW.wave_id;
    END IF;
  END IF;

  IF TG_OP = 'DELETE' OR TG_OP = 'UPDATE' THEN
    IF OLD.wave_id IS NOT NULL AND (TG_OP = 'DELETE' OR OLD.wave_id IS DISTINCT FROM NEW.wave_id) THEN
      UPDATE waves SET vehicle_count = (
        SELECT COUNT(*) FROM vehicle_schedules WHERE wave_id = OLD.wave_id AND status != 'cancelled'
      ) WHERE id = OLD.wave_id;
    END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$;
