-- @@ function public.ottoq_eval_sm_004_role_gating(p_entity_type text, p_entity_id uuid, p_context jsonb, p_parameters jsonb)
CREATE OR REPLACE FUNCTION public.ottoq_eval_sm_004_role_gating(p_entity_type text, p_entity_id uuid, p_context jsonb, p_parameters jsonb)
 RETURNS public.ottoq_rule_result
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_actor_type      TEXT;
  v_action          TEXT;
  v_allowed_actors  TEXT[];
BEGIN
  v_actor_type := COALESCE(
    p_context ->> 'actor_type',
    NULLIF(current_setting('ottoq.actor_type', TRUE), ''),
    'unknown'
  );
  v_action := p_context ->> 'action';

  -- Action-to-roles map (parameterized; safe defaults baked in)
  v_allowed_actors := COALESCE(
    ARRAY(SELECT jsonb_array_elements_text(p_parameters -> 'allowed_actors')),
    CASE v_action
      WHEN 'tech_override'    THEN ARRAY['depot_tech','depot_supervisor']
      WHEN 'flag_abnormality' THEN ARRAY['depot_tech','depot_supervisor','oem_admin_console','oem_dispatch_webhook']
      WHEN 'resolve_abnormality_tech' THEN ARRAY['depot_tech','depot_supervisor']
      WHEN 'resolve_abnormality_oem'  THEN ARRAY['depot_tech','depot_supervisor','oem_admin_console']
      WHEN 'oem_accept'       THEN ARRAY['oem_dispatch_webhook','oem_admin_console']
      WHEN 'oem_flag_midflow' THEN ARRAY['oem_admin_console','oem_dispatch_webhook']
      WHEN 'emergency_stop'   THEN ARRAY['depot_supervisor','command_center_operator','external_sensor']
      WHEN 'brain_pause'      THEN ARRAY['command_center_operator','depot_supervisor']
      ELSE ARRAY[]::TEXT[]
    END
  );

  IF cardinality(v_allowed_actors) = 0 THEN
    RETURN ROW(TRUE, 'no role restriction for action', NULL, '{}'::jsonb, NULL)::ottoq_rule_result;
  END IF;

  IF NOT (v_actor_type = ANY(v_allowed_actors)) THEN
    RETURN ROW(FALSE,
      format('actor %s not authorized for action %s', v_actor_type, v_action),
      'critical',
      jsonb_build_object(
        'actor_type', v_actor_type,
        'action', v_action,
        'allowed_actors', v_allowed_actors
      ),
      'use_authorized_actor'
    )::ottoq_rule_result;
  END IF;

  RETURN ROW(TRUE, format('actor %s authorized for %s', v_actor_type, v_action), NULL,
    jsonb_build_object('actor_type', v_actor_type, 'action', v_action), NULL)::ottoq_rule_result;
END;
$function$;
-- @@ function public.ottoq_eval_sm_005_audit_note_required(p_entity_type text, p_entity_id uuid, p_context jsonb, p_parameters jsonb)
CREATE OR REPLACE FUNCTION public.ottoq_eval_sm_005_audit_note_required(p_entity_type text, p_entity_id uuid, p_context jsonb, p_parameters jsonb)
 RETURNS public.ottoq_rule_result
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_decision     TEXT;
  v_audit_note   TEXT;
  v_min_chars    INTEGER := COALESCE((p_parameters ->> 'min_chars')::INT, 3);
  v_override_decisions TEXT[] := ARRAY[
    'tech_override_skip','tech_override_reroute','tech_override_hold',
    'tech_override_flag_exception','tech_override_defer','tech_override_escalate',
    'oem_rejected','oem_flagged_mid_flow','abnormality_blocked','abnormality_resolved'
  ];
BEGIN
  v_decision   := p_context ->> 'decision';
  v_audit_note := p_context ->> 'audit_note';

  IF v_decision IS NULL THEN
    RETURN ROW(TRUE, 'no decision context', NULL, '{}'::jsonb, NULL)::ottoq_rule_result;
  END IF;

  IF NOT (v_decision = ANY(v_override_decisions)) THEN
    RETURN ROW(TRUE, 'decision not in override class', NULL,
      jsonb_build_object('decision', v_decision), NULL)::ottoq_rule_result;
  END IF;

  IF v_audit_note IS NULL OR length(trim(v_audit_note)) < v_min_chars THEN
    RETURN ROW(FALSE,
      format('audit_note required (min %s chars) for decision=%s', v_min_chars, v_decision),
      'critical',
      jsonb_build_object(
        'decision', v_decision,
        'audit_note_length', COALESCE(length(trim(v_audit_note)),0),
        'min_chars', v_min_chars
      ),
      'provide_substantive_audit_note'
    )::ottoq_rule_result;
  END IF;

  RETURN ROW(TRUE,
    format('audit_note present (%s chars)', length(trim(v_audit_note))),
    NULL,
    jsonb_build_object('audit_note_length', length(trim(v_audit_note))),
    NULL
  )::ottoq_rule_result;
END;
$function$;
-- @@ function public.ottoq_progression_decisions_enforce_audit_note()
CREATE OR REPLACE FUNCTION public.ottoq_progression_decisions_enforce_audit_note()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_override_decisions TEXT[] := ARRAY[
    'tech_override_skip','tech_override_reroute','tech_override_hold',
    'tech_override_flag_exception','tech_override_defer','tech_override_escalate',
    'oem_rejected','oem_flagged_mid_flow','abnormality_blocked'
  ];
BEGIN
  IF NEW.decision = ANY(v_override_decisions) THEN
    IF NEW.audit_note IS NULL OR length(trim(NEW.audit_note)) < 3 THEN
      RAISE EXCEPTION 'OTTOQ_AUDIT_NOTE_REQUIRED: decision=% requires audit_note (min 3 chars)',
        NEW.decision
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
-- @@ function public.ottoq_trigger_emergency_cascade(p_protocol_code text, p_depot_id uuid, p_triggered_by_actor_type text, p_triggered_by_actor_id text, p_source_payload jsonb, p_triggered_by_event_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_trigger_emergency_cascade(p_protocol_code text, p_depot_id uuid, p_triggered_by_actor_type text, p_triggered_by_actor_id text DEFAULT NULL::text, p_source_payload jsonb DEFAULT '{}'::jsonb, p_triggered_by_event_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_protocol         ottoq_emergency_protocols%ROWTYPE;
  v_invocation_id    UUID := gen_random_uuid();
  v_correlation      UUID := COALESCE(
                        NULLIF(current_setting('ottoq.correlation_id', TRUE), '')::UUID,
                        gen_random_uuid()
                      );
  v_event_id         UUID;
  v_action           JSONB;
  v_action_results   JSONB := '[]'::jsonb;
  v_action_status    TEXT;
  v_action_details   JSONB;
  v_outcome          TEXT := 'completed';
  v_affected_stalls  INTEGER := 0;
  v_affected_vehicles INTEGER := 0;
  v_affected_chargers INTEGER := 0;
BEGIN
  -- 1. Lookup protocol
  SELECT * INTO v_protocol
    FROM ottoq_emergency_protocols
   WHERE protocol_code = p_protocol_code AND status = 'active';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'OTTOQ_PROTOCOL_NOT_FOUND: %', p_protocol_code USING ERRCODE = 'P0001';
  END IF;

  -- 2. Emit "emergency.triggered" event FIRST (before any side effects)
  v_event_id := ottoq_record_event(
    p_actor_type        := p_triggered_by_actor_type,
    p_actor_id          := p_triggered_by_actor_id,
    p_event_type        := 'emergency.triggered',
    p_entity_type       := 'emergency_invocation',
    p_entity_id         := v_invocation_id,
    p_depot_id          := p_depot_id,
    p_payload           := jsonb_build_object(
                             'protocol_code', p_protocol_code,
                             'category', v_protocol.category,
                             'severity', v_protocol.severity,
                             'source', p_source_payload
                           ),
    p_severity          := v_protocol.severity,
    p_parent_event_id   := p_triggered_by_event_id,
    p_correlation_id    := v_correlation
  );

  -- 3. Insert invocation row
  INSERT INTO ottoq_emergency_invocations (
    invocation_id, protocol_code, triggered_at,
    triggered_by_actor_type, triggered_by_actor_id, triggered_by_event_id,
    source_payload, depot_id, affects_scope,
    outcome, linked_event_id, correlation_id
  ) VALUES (
    v_invocation_id, p_protocol_code, NOW(),
    p_triggered_by_actor_type, p_triggered_by_actor_id, p_triggered_by_event_id,
    p_source_payload, p_depot_id, v_protocol.affects_scope,
    'in_progress', v_event_id, v_correlation
  );

  -- 4. Execute cascade actions in order
  FOR v_action IN SELECT jsonb_array_elements(v_protocol.cascade_actions)
  LOOP
    BEGIN
      v_action_status := 'ok';
      v_action_details := '{}'::jsonb;

      CASE v_action ->> 'action'
        WHEN 'de_energize_all_chargers' THEN
          UPDATE ottoq_ocpp_chargers
             SET station_state = 'Unavailable',
                 station_state_changed_at = NOW()
           WHERE depot_id = p_depot_id;
          GET DIAGNOSTICS v_affected_chargers = ROW_COUNT;
          v_action_details := jsonb_build_object('chargers_de_energized', v_affected_chargers);

        WHEN 'sequester_all_vehicles' THEN
          -- Move all in-flow vehicles at this depot to emergency_staged
          BEGIN
            EXECUTE format('
              UPDATE vehicles SET current_state = ''emergency_staged''
               WHERE current_state IN (''queued'',''assigned'',''in_service'',''charging'',''washing'',''calibrating'',''staged_for_departure'')
                 AND id IN (SELECT current_vehicle_id FROM stalls WHERE depot_id = $1 AND current_vehicle_id IS NOT NULL)
            ') USING p_depot_id;
            GET DIAGNOSTICS v_affected_vehicles = ROW_COUNT;
          EXCEPTION WHEN OTHERS THEN
            v_affected_vehicles := 0;
          END;
          v_action_details := jsonb_build_object('vehicles_sequestered', v_affected_vehicles);

        WHEN 'lock_all_stalls' THEN
          BEGIN
            EXECUTE 'UPDATE stalls SET status = ''offline'' WHERE depot_id = $1 AND status <> ''offline'''
              USING p_depot_id;
            GET DIAGNOSTICS v_affected_stalls = ROW_COUNT;
          EXCEPTION WHEN OTHERS THEN
            v_affected_stalls := 0;
          END;
          v_action_details := jsonb_build_object('stalls_locked', v_affected_stalls);

        WHEN 'pause_arrivals' THEN
          -- Insert a grid_event-style marker; arrival logic checks for active
          -- 'arrival_pause' rows during admission.
          INSERT INTO ottoq_grid_events (
            depot_id, event_type, severity, effective_at, source, payload
          ) VALUES (
            p_depot_id, 'curtailment_request', 'safety_critical', NOW(),
            'emergency_cascade',
            jsonb_build_object('reason','arrival_pause_emergency',
                               'protocol_code', p_protocol_code,
                               'invocation_id', v_invocation_id)
          );
          v_action_details := jsonb_build_object('arrival_pause_set', TRUE);

        WHEN 'notify_actors' THEN
          -- Notification is downstream; we just emit an event other systems
          -- subscribe to. ottoq_event 'emergency.notify_actors' carries the list.
          PERFORM ottoq_record_event(
            p_actor_type     := 'ottoq_engine',
            p_event_type     := 'emergency.notify_actors',
            p_entity_type    := 'emergency_invocation',
            p_entity_id      := v_invocation_id,
            p_depot_id       := p_depot_id,
            p_payload        := jsonb_build_object(
                                  'protocol_code', p_protocol_code,
                                  'actors_to_notify', v_protocol.notify_actors,
                                  'webhooks', v_protocol.external_notify_webhooks
                                ),
            p_severity       := v_protocol.severity,
            p_parent_event_id := v_event_id,
            p_correlation_id := v_correlation
          );
          v_action_details := jsonb_build_object('notify_actors', v_protocol.notify_actors);

        WHEN 'engage_bess' THEN
          UPDATE ottoq_bess_units
             SET current_state = 'discharging'
           WHERE depot_id = p_depot_id
             --: 0397 / G96. DELIBERATELY TOLERANT, and the only place that is. Every WRITER
             --: now emits 'standby', and this migration rewrites the live rows -- but this is
             --: a READER, and rows written before 0397 across the engine's whole life say
             --: 'idle'. Narrowing it to 'standby' alone would silently stop matching any such
             --: row. The tolerance belongs here and nowhere else: a second writer of 'idle'
             --: would re-open the split this migration closes. db/checks/0298.
             AND current_state IN ('standby', 'idle')
             AND current_soc_pct > soc_min_floor_pct;
          GET DIAGNOSTICS v_action_details = ROW_COUNT;
          v_action_details := jsonb_build_object('bess_engaged_count', v_action_details);

        WHEN 'isolate_bess' THEN
          UPDATE ottoq_bess_units
             SET current_state = 'offline'
           WHERE depot_id = p_depot_id;
          v_action_details := jsonb_build_object('bess_isolated', TRUE);

        WHEN 'log_only' THEN
          -- Pure observation, no side effects
          v_action_details := jsonb_build_object('logged', TRUE);

        ELSE
          v_action_status := 'unknown_action';
          v_action_details := jsonb_build_object('unknown_action', v_action ->> 'action');
      END CASE;

    EXCEPTION WHEN OTHERS THEN
      v_action_status := 'failed';
      v_action_details := jsonb_build_object('error', SQLERRM, 'sqlstate', SQLSTATE);
      v_outcome := 'partial';
    END;

    v_action_results := v_action_results || jsonb_build_object(
      'action', v_action ->> 'action',
      'status', v_action_status,
      'details', v_action_details,
      'executed_at', NOW()
    );

    -- Per-action event for granular audit
    PERFORM ottoq_record_event(
      p_actor_type      := 'ottoq_engine',
      p_event_type      := 'emergency.action_executed',
      p_entity_type     := 'emergency_invocation',
      p_entity_id       := v_invocation_id,
      p_depot_id        := p_depot_id,
      p_payload         := jsonb_build_object(
                             'protocol_code', p_protocol_code,
                             'action', v_action ->> 'action',
                             'status', v_action_status,
                             'details', v_action_details
                           ),
      p_severity        := CASE WHEN v_action_status='ok' THEN 'info' ELSE 'critical' END,
      p_parent_event_id := v_event_id,
      p_correlation_id  := v_correlation
    );
  END LOOP;

  -- 5. Finalize invocation row
  UPDATE ottoq_emergency_invocations
     SET cascade_executed = v_action_results,
         outcome          = v_outcome
   WHERE invocation_id = v_invocation_id;

  -- 6. Emit completion event
  PERFORM ottoq_record_event(
    p_actor_type      := 'ottoq_engine',
    p_event_type      := 'emergency.cascade_complete',
    p_entity_type     := 'emergency_invocation',
    p_entity_id       := v_invocation_id,
    p_depot_id        := p_depot_id,
    p_payload         := jsonb_build_object(
                          'protocol_code', p_protocol_code,
                          'outcome', v_outcome,
                          'actions_executed', jsonb_array_length(v_action_results)
                        ),
    p_severity        := v_protocol.severity,
    p_parent_event_id := v_event_id,
    p_correlation_id  := v_correlation
  );

  RETURN v_invocation_id;
END;
$function$;
-- @@ function public.ottoq_emergency_clear(p_invocation_id uuid, p_cleared_by_actor_type text, p_cleared_by_actor_id text, p_resolution_note text)
CREATE OR REPLACE FUNCTION public.ottoq_emergency_clear(p_invocation_id uuid, p_cleared_by_actor_type text, p_cleared_by_actor_id text, p_resolution_note text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_inv ottoq_emergency_invocations%ROWTYPE;
  v_protocol ottoq_emergency_protocols%ROWTYPE;
BEGIN
  IF p_resolution_note IS NULL OR length(trim(p_resolution_note)) < 5 THEN
    RAISE EXCEPTION 'resolution_note must be ≥ 5 chars' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO v_inv FROM ottoq_emergency_invocations WHERE invocation_id = p_invocation_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'invocation % not found', p_invocation_id;
  END IF;
  IF v_inv.cleared_at IS NOT NULL THEN
    RAISE EXCEPTION 'invocation % already cleared at %', p_invocation_id, v_inv.cleared_at;
  END IF;

  SELECT * INTO v_protocol FROM ottoq_emergency_protocols WHERE protocol_code = v_inv.protocol_code;

  UPDATE ottoq_emergency_invocations
     SET cleared_at           = NOW(),
         cleared_by_actor_type = p_cleared_by_actor_type,
         cleared_by_actor_id   = p_cleared_by_actor_id,
         resolution_note       = p_resolution_note,
         outcome               = 'cleared'
   WHERE invocation_id = p_invocation_id;

  -- Clear any arrival_pause records tied to this invocation
  UPDATE ottoq_grid_events
     SET cleared_at = NOW()
   WHERE depot_id = v_inv.depot_id
     AND payload @> jsonb_build_object('invocation_id', p_invocation_id::text)
     AND cleared_at IS NULL;

  PERFORM ottoq_record_event(
    p_actor_type    := p_cleared_by_actor_type,
    p_actor_id      := p_cleared_by_actor_id,
    p_event_type    := 'emergency.cleared',
    p_entity_type   := 'emergency_invocation',
    p_entity_id     := p_invocation_id,
    p_depot_id      := v_inv.depot_id,
    p_payload       := jsonb_build_object(
                         'protocol_code', v_inv.protocol_code,
                         'resolution_note', p_resolution_note,
                         'duration_seconds', EXTRACT(EPOCH FROM (NOW() - v_inv.triggered_at))
                       ),
    p_severity      := 'warning'
  );

  RETURN TRUE;
END;
$function$;
-- @@ function public.ottoq_depot_local_time(p_depot_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_depot_local_time(p_depot_id uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE v_tz TEXT;
BEGIN
  SELECT operating_timezone INTO v_tz FROM depots WHERE id = p_depot_id;
  v_tz := COALESCE(v_tz, 'UTC');
  RETURN (ottoq.ottoq_run_now() AT TIME ZONE v_tz);  /* 0204: the run's clock, NOW() outside a run */
END;
$function$;
-- @@ function public.ottoq_eval_tw_001_operational_hours(p_entity_type text, p_entity_id uuid, p_context jsonb, p_parameters jsonb)
CREATE OR REPLACE FUNCTION public.ottoq_eval_tw_001_operational_hours(p_entity_type text, p_entity_id uuid, p_context jsonb, p_parameters jsonb)
 RETURNS public.ottoq_rule_result
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_depot_id   UUID;
  v_depot      depots%ROWTYPE;
  v_local_time TIME;
  v_in_hours   BOOLEAN;
BEGIN
  v_depot_id := COALESCE(NULLIF(p_context ->> 'depot_id','')::UUID,
                         CASE WHEN p_entity_type='depot' THEN p_entity_id END);
  IF v_depot_id IS NULL THEN
    RETURN ROW(TRUE,'no depot context',NULL,'{}'::jsonb,NULL)::ottoq_rule_result;
  END IF;

  SELECT * INTO v_depot FROM depots WHERE id = v_depot_id;
  IF v_depot.operational_hours_start IS NULL OR v_depot.operational_hours_end IS NULL THEN
    RETURN ROW(TRUE,'depot operates 24/7',NULL,'{}'::jsonb,NULL)::ottoq_rule_result;
  END IF;

  v_local_time := (ottoq_depot_local_time(v_depot_id))::TIME;

  IF v_depot.operational_hours_start <= v_depot.operational_hours_end THEN
    v_in_hours := v_local_time BETWEEN v_depot.operational_hours_start AND v_depot.operational_hours_end;
  ELSE
    v_in_hours := v_local_time >= v_depot.operational_hours_start
               OR v_local_time <= v_depot.operational_hours_end;
  END IF;

  IF NOT v_in_hours THEN
    RETURN ROW(FALSE,
      format('outside operational hours [%s, %s] (local %s)',
        v_depot.operational_hours_start, v_depot.operational_hours_end, v_local_time),
      'warning',
      jsonb_build_object(
        'depot_id', v_depot_id,
        'local_time', v_local_time,
        'hours_start', v_depot.operational_hours_start,
        'hours_end', v_depot.operational_hours_end,
        'timezone', v_depot.operating_timezone
      ),
      'queue_for_next_operational_window'
    )::ottoq_rule_result;
  END IF;

  RETURN ROW(TRUE,'within operational hours',NULL,
    jsonb_build_object('local_time', v_local_time),NULL)::ottoq_rule_result;
END;
$function$;
-- @@ function public.ottoq_eval_tw_002_overnight_staging(p_entity_type text, p_entity_id uuid, p_context jsonb, p_parameters jsonb)
CREATE OR REPLACE FUNCTION public.ottoq_eval_tw_002_overnight_staging(p_entity_type text, p_entity_id uuid, p_context jsonb, p_parameters jsonb)
 RETURNS public.ottoq_rule_result
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_depot_id     UUID;
  v_minutes      NUMERIC;
  v_threshold    INTEGER;
  v_depot        depots%ROWTYPE;
BEGIN
  v_depot_id := NULLIF(p_context ->> 'depot_id','')::UUID;
  v_minutes  := NULLIF(p_context ->> 'minutes_to_departure','')::NUMERIC;

  IF v_depot_id IS NULL OR v_minutes IS NULL THEN
    RETURN ROW(TRUE,'insufficient context',NULL,'{}'::jsonb,NULL)::ottoq_rule_result;
  END IF;

  SELECT * INTO v_depot FROM depots WHERE id = v_depot_id;
  v_threshold := COALESCE(
    (p_parameters ->> 'threshold_minutes')::INT,
    v_depot.overnight_staging_threshold_minutes,
    120
  );

  IF v_minutes > v_threshold THEN
    -- This rule SUGGESTS staging — it's not a hard block on the alternative
    RETURN ROW(TRUE,
      format('staging recommended: %s min > threshold %s', v_minutes, v_threshold),
      'info',
      jsonb_build_object(
        'minutes_to_departure', v_minutes,
        'threshold_minutes', v_threshold,
        'recommendation', 'overnight_stage'
      ),
      'overnight_stage'
    )::ottoq_rule_result;
  END IF;

  RETURN ROW(TRUE,
    format('immediate flow recommended: %s ≤ %s', v_minutes, v_threshold),
    NULL,
    jsonb_build_object('minutes_to_departure', v_minutes, 'threshold', v_threshold),
    'continue_immediate'
  )::ottoq_rule_result;
END;
$function$;
-- @@ function public.ottoq_eval_tw_003_quiet_hours(p_entity_type text, p_entity_id uuid, p_context jsonb, p_parameters jsonb)
CREATE OR REPLACE FUNCTION public.ottoq_eval_tw_003_quiet_hours(p_entity_type text, p_entity_id uuid, p_context jsonb, p_parameters jsonb)
 RETURNS public.ottoq_rule_result
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_depot_id     UUID;
  v_service_code TEXT;
  v_loud_kinds   TEXT[];
  v_depot        depots%ROWTYPE;
  v_local_time   TIME;
  v_in_quiet     BOOLEAN;
BEGIN
  v_depot_id    := NULLIF(p_context ->> 'depot_id','')::UUID;
  v_service_code := p_context ->> 'service_code';
  v_loud_kinds  := COALESCE(
    ARRAY(SELECT jsonb_array_elements_text(p_parameters -> 'loud_services')),
    ARRAY['exterior_wash','pressure_wash','tire_rotation','brake_service']
  );

  IF v_depot_id IS NULL OR v_service_code IS NULL THEN
    RETURN ROW(TRUE,'no context',NULL,'{}'::jsonb,NULL)::ottoq_rule_result;
  END IF;
  IF NOT (v_service_code = ANY(v_loud_kinds)) THEN
    RETURN ROW(TRUE,
      format('service %s is not noise-class', v_service_code),
      NULL, jsonb_build_object('service_code', v_service_code), NULL
    )::ottoq_rule_result;
  END IF;

  SELECT * INTO v_depot FROM depots WHERE id = v_depot_id;
  IF v_depot.quiet_hours_start IS NULL OR v_depot.quiet_hours_end IS NULL THEN
    RETURN ROW(TRUE,'depot has no quiet hours configured',NULL,'{}'::jsonb,NULL)::ottoq_rule_result;
  END IF;

  v_local_time := (ottoq_depot_local_time(v_depot_id))::TIME;
  IF v_depot.quiet_hours_start <= v_depot.quiet_hours_end THEN
    v_in_quiet := v_local_time BETWEEN v_depot.quiet_hours_start AND v_depot.quiet_hours_end;
  ELSE
    v_in_quiet := v_local_time >= v_depot.quiet_hours_start
               OR v_local_time <= v_depot.quiet_hours_end;
  END IF;

  IF v_in_quiet THEN
    RETURN ROW(FALSE,
      format('service %s during quiet hours [%s, %s] (local %s)',
        v_service_code, v_depot.quiet_hours_start, v_depot.quiet_hours_end, v_local_time),
      'warning',
      jsonb_build_object(
        'service_code', v_service_code,
        'local_time', v_local_time,
        'quiet_start', v_depot.quiet_hours_start,
        'quiet_end', v_depot.quiet_hours_end
      ),
      'defer_to_after_quiet_hours'
    )::ottoq_rule_result;
  END IF;

  RETURN ROW(TRUE,'outside quiet hours',NULL,
    jsonb_build_object('local_time', v_local_time),NULL)::ottoq_rule_result;
END;
$function$;
-- @@ function public.ottoq_eval_tw_004_tariff_window(p_entity_type text, p_entity_id uuid, p_context jsonb, p_parameters jsonb)
CREATE OR REPLACE FUNCTION public.ottoq_eval_tw_004_tariff_window(p_entity_type text, p_entity_id uuid, p_context jsonb, p_parameters jsonb)
 RETURNS public.ottoq_rule_result
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_depot_id     UUID;
  v_local_time   TIME;
  v_peak_start   TIME := COALESCE((p_parameters ->> 'peak_start')::TIME, '14:00'::TIME);
  v_peak_end     TIME := COALESCE((p_parameters ->> 'peak_end')::TIME, '20:00'::TIME);
  v_is_peak      BOOLEAN;
BEGIN
  v_depot_id := NULLIF(p_context ->> 'depot_id','')::UUID;
  IF v_depot_id IS NULL THEN
    RETURN ROW(TRUE,'no depot context',NULL,'{}'::jsonb,NULL)::ottoq_rule_result;
  END IF;

  v_local_time := (ottoq_depot_local_time(v_depot_id))::TIME;
  v_is_peak := v_local_time BETWEEN v_peak_start AND v_peak_end;

  RETURN ROW(TRUE,
    format('tariff window: %s', CASE WHEN v_is_peak THEN 'PEAK (avoid heavy charging)' ELSE 'OFF-PEAK (prefer heavy charging)' END),
    NULL,
    jsonb_build_object(
      'depot_id', v_depot_id,
      'local_time', v_local_time,
      'is_peak', v_is_peak,
      'peak_start', v_peak_start,
      'peak_end', v_peak_end,
      'cost_preference_score', CASE WHEN v_is_peak THEN 0.3 ELSE 0.9 END
    ),
    CASE WHEN v_is_peak THEN 'prefer_defer_or_bess' ELSE 'prefer_immediate_charge' END
  )::ottoq_rule_result;
END;
$function$;
-- @@ function public.ottoq_eval_tw_005_shift_buffer(p_entity_type text, p_entity_id uuid, p_context jsonb, p_parameters jsonb)
CREATE OR REPLACE FUNCTION public.ottoq_eval_tw_005_shift_buffer(p_entity_type text, p_entity_id uuid, p_context jsonb, p_parameters jsonb)
 RETURNS public.ottoq_rule_result
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_depot_id    UUID;
  v_buffer_min  INTEGER;
  v_local_time  TIME;
  v_local_dow   INTEGER;
  v_shift       RECORD;
  v_minutes_to_boundary NUMERIC;
BEGIN
  v_depot_id := NULLIF(p_context ->> 'depot_id','')::UUID;
  IF v_depot_id IS NULL THEN
    RETURN ROW(TRUE,'no depot context',NULL,'{}'::jsonb,NULL)::ottoq_rule_result;
  END IF;

  SELECT shift_change_buffer_minutes INTO v_buffer_min FROM depots WHERE id = v_depot_id;
  v_buffer_min := COALESCE((p_parameters ->> 'buffer_minutes')::INT, v_buffer_min, 15);
  IF v_buffer_min <= 0 THEN
    RETURN ROW(TRUE,'buffer disabled',NULL,'{}'::jsonb,NULL)::ottoq_rule_result;
  END IF;

  v_local_time := (ottoq_depot_local_time(v_depot_id))::TIME;
  v_local_dow  := EXTRACT(ISODOW FROM ottoq_depot_local_time(v_depot_id))::INT;

  -- Find nearest upcoming shift boundary within v_buffer_min minutes
  FOR v_shift IN
    SELECT shift_name, start_time
      FROM ottoq_depot_shifts
     WHERE depot_id = v_depot_id
       AND status = 'active'
       AND v_local_dow = ANY(days_of_week)
  LOOP
    v_minutes_to_boundary :=
      EXTRACT(EPOCH FROM (v_shift.start_time - v_local_time)) / 60.0;

    IF v_minutes_to_boundary > 0 AND v_minutes_to_boundary <= v_buffer_min THEN
      RETURN ROW(FALSE,
        format('within %s min of shift change to %s (%s min)',
          v_buffer_min, v_shift.shift_name, v_minutes_to_boundary),
        'warning',
        jsonb_build_object(
          'shift', v_shift.shift_name,
          'shift_start', v_shift.start_time,
          'minutes_to_boundary', v_minutes_to_boundary,
          'buffer_minutes', v_buffer_min
        ),
        'wait_for_shift_handoff'
      )::ottoq_rule_result;
    END IF;
  END LOOP;

  RETURN ROW(TRUE,'outside shift change buffer',NULL,'{}'::jsonb,NULL)::ottoq_rule_result;
END;
$function$;
-- @@ function public.ottoq_verify_event_signature(p_event_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_verify_event_signature(p_event_id uuid)
 RETURNS TABLE(event_id uuid, has_signature boolean, valid boolean, algorithm text, key_id text, computed text, stored text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_event       ottoq_events%ROWTYPE;
  v_recomputed  TEXT;
BEGIN
  SELECT * INTO v_event FROM ottoq_events e WHERE e.event_id = p_event_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Event % not found', p_event_id;
  END IF;
  IF v_event.signature IS NULL THEN
    RETURN QUERY SELECT v_event.event_id, FALSE, FALSE, v_event.signature_algorithm,
      v_event.signature_key_id, NULL::TEXT, NULL::TEXT;
    RETURN;
  END IF;
  v_recomputed := ottoq_sign_event(
    v_event.event_id, v_event.occurred_at,
    v_event.actor_type, v_event.event_type,
    v_event.entity_type, v_event.entity_id,
    v_event.payload_hash, v_event.signature_key_id
  );
  RETURN QUERY SELECT
    v_event.event_id, TRUE, (v_recomputed = v_event.signature),
    v_event.signature_algorithm, v_event.signature_key_id,
    v_recomputed, v_event.signature;
END;
$function$;
-- @@ function public.ottoq_record_prediction(p_prediction_type text, p_depot_id uuid, p_fleet_operator_id uuid, p_vehicle_id uuid, p_predicted_value jsonb, p_p10 numeric, p_p50 numeric, p_p90 numeric, p_confidence numeric, p_prediction_interval_method text, p_prediction_baseline text, p_target_at timestamp with time zone, p_horizon_minutes integer, p_title text, p_description text, p_recommendation jsonb, p_action_type text, p_action_parameters jsonb, p_model_version_id uuid, p_ab_test_id uuid, p_ab_test_variant text, p_inputs jsonb, p_feature_snapshot_ids uuid[], p_latency_ms integer, p_shadow_only boolean, p_correlation_id uuid, p_parent_event_id uuid, p_expires_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ottoq_record_prediction(p_prediction_type text, p_depot_id uuid DEFAULT NULL::uuid, p_fleet_operator_id uuid DEFAULT NULL::uuid, p_vehicle_id uuid DEFAULT NULL::uuid, p_predicted_value jsonb DEFAULT NULL::jsonb, p_p10 numeric DEFAULT NULL::numeric, p_p50 numeric DEFAULT NULL::numeric, p_p90 numeric DEFAULT NULL::numeric, p_confidence numeric DEFAULT NULL::numeric, p_prediction_interval_method text DEFAULT NULL::text, p_prediction_baseline text DEFAULT 'heuristic'::text, p_target_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_horizon_minutes integer DEFAULT NULL::integer, p_title text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_recommendation jsonb DEFAULT NULL::jsonb, p_action_type text DEFAULT NULL::text, p_action_parameters jsonb DEFAULT NULL::jsonb, p_model_version_id uuid DEFAULT NULL::uuid, p_ab_test_id uuid DEFAULT NULL::uuid, p_ab_test_variant text DEFAULT NULL::text, p_inputs jsonb DEFAULT NULL::jsonb, p_feature_snapshot_ids uuid[] DEFAULT NULL::uuid[], p_latency_ms integer DEFAULT NULL::integer, p_shadow_only boolean DEFAULT false, p_correlation_id uuid DEFAULT NULL::uuid, p_parent_event_id uuid DEFAULT NULL::uuid, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_prediction_id  UUID := gen_random_uuid();
  v_event_id       UUID;
  v_inputs_hash    TEXT;
  v_correlation    UUID;
  v_type           ottoq_prediction_types_catalog%ROWTYPE;
  v_title          TEXT;
BEGIN
  SELECT * INTO v_type FROM ottoq_prediction_types_catalog
   WHERE prediction_type = p_prediction_type AND status IN ('active','shadow');
  IF NOT FOUND THEN
    PERFORM ottoq_record_event(
      p_actor_type := 'ottoq_engine',
      p_event_type := 'system.catalog_miss',
      p_entity_type := 'prediction',
      p_payload := jsonb_build_object('unknown_prediction_type', p_prediction_type),
      p_severity := 'warning'
    );
  END IF;

  -- Default title to prediction_type description or the type code itself
  v_title := COALESCE(p_title, v_type.title, p_prediction_type);

  IF p_inputs IS NOT NULL THEN
    v_inputs_hash := encode(digest(jsonb_strip_nulls(p_inputs)::text, 'sha256'), 'hex');
  END IF;

  v_correlation := COALESCE(p_correlation_id,
    NULLIF(current_setting('ottoq.correlation_id', TRUE), '')::UUID,
    gen_random_uuid()
  );

  v_event_id := ottoq_record_event(
    p_actor_type        := 'ottoq_engine',
    p_event_type        := 'prediction.emitted',
    p_entity_type       := COALESCE(v_type.target_entity_type, 'prediction'),
    p_entity_id         := v_prediction_id,
    p_fleet_operator_id := p_fleet_operator_id,
    p_depot_id          := p_depot_id,
    p_payload           := jsonb_build_object(
                            'prediction_type', p_prediction_type,
                            'predicted_value', p_predicted_value,
                            'p10', p_p10, 'p50', p_p50, 'p90', p_p90,
                            'confidence', p_confidence,
                            'horizon_minutes', p_horizon_minutes,
                            'baseline', p_prediction_baseline,
                            'shadow_only', p_shadow_only,
                            'model_version_id', p_model_version_id
                          ),
    p_severity          := CASE WHEN p_shadow_only THEN 'debug' ELSE 'info' END,
    p_correlation_id    := v_correlation,
    p_parent_event_id   := p_parent_event_id,
    p_latency_ms        := p_latency_ms
  );

  INSERT INTO ottoq_predictions (
    id, depot_id, fleet_operator_id, vehicle_id,
    prediction_type, title, description,
    predicted_value, p10, p50, p90,
    confidence, prediction_interval_method, prediction_baseline,
    recommendation, action_type, action_parameters,
    target_at, horizon_minutes, expires_at,
    model_version_id, ab_test_id, ab_test_variant,
    supporting_data, inputs_hash, feature_snapshot_ids,
    shadow_only, event_id, correlation_id, latency_ms,
    status, created_at
  ) VALUES (
    v_prediction_id, p_depot_id, p_fleet_operator_id, p_vehicle_id,
    p_prediction_type, v_title, p_description,
    p_predicted_value, p_p10, p_p50, p_p90,
    p_confidence, p_prediction_interval_method, p_prediction_baseline,
    p_recommendation, p_action_type, p_action_parameters,
    p_target_at, p_horizon_minutes,
    COALESCE(p_expires_at,
             p_target_at + INTERVAL '1 hour',
             NOW() + (COALESCE(p_horizon_minutes, 60) || ' minutes')::INTERVAL),
    p_model_version_id, p_ab_test_id, p_ab_test_variant,
    p_inputs, v_inputs_hash, p_feature_snapshot_ids,
    p_shadow_only, v_event_id, v_correlation, p_latency_ms,
    'proposed', NOW()
  );

  RETURN v_prediction_id;
END;
$function$;
-- @@ function public.ottoq_get_feature(p_feature_name text, p_entity_type text, p_entity_id uuid, p_as_of timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ottoq_get_feature(p_feature_name text, p_entity_type text, p_entity_id uuid DEFAULT NULL::uuid, p_as_of timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS public.ottoq_feature_values
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_as_of TIMESTAMPTZ := COALESCE(p_as_of, NOW());
  v_row   ottoq_feature_values%ROWTYPE;
BEGIN
  SELECT * INTO v_row
    FROM ottoq_feature_values fv
   WHERE fv.feature_name = p_feature_name
     AND ((fv.entity_id IS NULL AND p_entity_id IS NULL)
          OR fv.entity_id = p_entity_id)
     AND fv.entity_type = p_entity_type
     AND fv.valid_from <= v_as_of
     AND (fv.valid_until IS NULL OR fv.valid_until > v_as_of)
   ORDER BY fv.valid_from DESC
   LIMIT 1;
  RETURN v_row;
END;
$function$;
-- @@ function public.ottoq_get_feature_value_jsonb(p_feature_name text, p_entity_type text, p_entity_id uuid, p_as_of timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ottoq_get_feature_value_jsonb(p_feature_name text, p_entity_type text, p_entity_id uuid DEFAULT NULL::uuid, p_as_of timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_row    ottoq_feature_values%ROWTYPE;
  v_result JSONB;
BEGIN
  v_row := ottoq_get_feature(p_feature_name, p_entity_type, p_entity_id, p_as_of);
  IF v_row.value_id IS NULL THEN
    RETURN jsonb_build_object('feature_name', p_feature_name, 'available', FALSE);
  END IF;
  v_result := jsonb_build_object(
    'feature_name', v_row.feature_name,
    'available', TRUE,
    'value', COALESCE(
      to_jsonb(v_row.value_numeric),
      to_jsonb(v_row.value_integer),
      to_jsonb(v_row.value_boolean),
      to_jsonb(v_row.value_text),
      to_jsonb(v_row.value_timestamp),
      v_row.value_json
    ),
    'observation_time', v_row.observation_time,
    'valid_from', v_row.valid_from,
    'age_seconds', EXTRACT(EPOCH FROM (NOW() - v_row.observation_time)),
    'feature_version', v_row.feature_version,
    'quality_score', v_row.quality_score,
    'is_imputed', v_row.is_imputed
  );
  RETURN v_result;
END;
$function$;
-- @@ function public.ottoq_feature_is_fresh(p_feature_name text, p_entity_type text, p_entity_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_feature_is_fresh(p_feature_name text, p_entity_type text, p_entity_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_row     ottoq_feature_values%ROWTYPE;
  v_sla     INTEGER;
BEGIN
  SELECT freshness_sla_seconds INTO v_sla FROM ottoq_features WHERE feature_name = p_feature_name;
  IF v_sla IS NULL THEN
    RETURN TRUE; -- no SLA configured; assume fresh
  END IF;
  v_row := ottoq_get_feature(p_feature_name, p_entity_type, p_entity_id);
  IF v_row.value_id IS NULL THEN
    RETURN FALSE;
  END IF;
  RETURN EXTRACT(EPOCH FROM (NOW() - v_row.observation_time)) <= v_sla;
END;
$function$;
-- @@ function public.ottoq_log_inference_start(p_prediction_type text, p_model_version_id uuid, p_route_id uuid, p_serving_runtime text, p_fleet_operator_id uuid, p_depot_id uuid, p_vehicle_id uuid, p_vehicle_class text, p_features_used jsonb, p_feature_snapshot_ids uuid[], p_inputs_hash text, p_ab_test_id uuid, p_ab_test_variant text, p_is_shadow boolean, p_correlation_id uuid, p_parent_event_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_log_inference_start(p_prediction_type text, p_model_version_id uuid DEFAULT NULL::uuid, p_route_id uuid DEFAULT NULL::uuid, p_serving_runtime text DEFAULT NULL::text, p_fleet_operator_id uuid DEFAULT NULL::uuid, p_depot_id uuid DEFAULT NULL::uuid, p_vehicle_id uuid DEFAULT NULL::uuid, p_vehicle_class text DEFAULT NULL::text, p_features_used jsonb DEFAULT NULL::jsonb, p_feature_snapshot_ids uuid[] DEFAULT NULL::uuid[], p_inputs_hash text DEFAULT NULL::text, p_ab_test_id uuid DEFAULT NULL::uuid, p_ab_test_variant text DEFAULT NULL::text, p_is_shadow boolean DEFAULT false, p_correlation_id uuid DEFAULT NULL::uuid, p_parent_event_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_inference_id UUID := gen_random_uuid();
  v_correlation  UUID;
BEGIN
  v_correlation := COALESCE(p_correlation_id,
    NULLIF(current_setting('ottoq.correlation_id', TRUE), '')::UUID,
    gen_random_uuid()
  );

  INSERT INTO ottoq_inference_log (
    inference_id, requested_at,
    prediction_type, model_version_id, route_id, serving_runtime,
    fleet_operator_id, depot_id, vehicle_id, vehicle_class,
    features_used, feature_snapshot_ids, inputs_hash,
    ab_test_id, ab_test_variant, is_shadow,
    status, correlation_id, parent_event_id
  ) VALUES (
    v_inference_id, NOW(),
    p_prediction_type, p_model_version_id, p_route_id, p_serving_runtime,
    p_fleet_operator_id, p_depot_id, p_vehicle_id, p_vehicle_class,
    p_features_used, p_feature_snapshot_ids, p_inputs_hash,
    p_ab_test_id, p_ab_test_variant, p_is_shadow,
    'pending', v_correlation, p_parent_event_id
  );
  RETURN v_inference_id;
END;
$function$;
-- @@ function public.ottoq_log_inference_complete(p_inference_id uuid, p_predicted_value jsonb, p_p10 numeric, p_p50 numeric, p_p90 numeric, p_confidence numeric, p_uncertainty_method text, p_prediction_id uuid, p_inference_ms integer, p_feature_fetch_ms integer, p_status text, p_error_message text, p_error_code text, p_shadow_compared_to uuid, p_shadow_disagreement numeric, p_cost_estimate_cents numeric)
CREATE OR REPLACE FUNCTION public.ottoq_log_inference_complete(p_inference_id uuid, p_predicted_value jsonb DEFAULT NULL::jsonb, p_p10 numeric DEFAULT NULL::numeric, p_p50 numeric DEFAULT NULL::numeric, p_p90 numeric DEFAULT NULL::numeric, p_confidence numeric DEFAULT NULL::numeric, p_uncertainty_method text DEFAULT NULL::text, p_prediction_id uuid DEFAULT NULL::uuid, p_inference_ms integer DEFAULT NULL::integer, p_feature_fetch_ms integer DEFAULT NULL::integer, p_status text DEFAULT 'completed'::text, p_error_message text DEFAULT NULL::text, p_error_code text DEFAULT NULL::text, p_shadow_compared_to uuid DEFAULT NULL::uuid, p_shadow_disagreement numeric DEFAULT NULL::numeric, p_cost_estimate_cents numeric DEFAULT NULL::numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
BEGIN
  UPDATE ottoq_inference_log
     SET completed_at = NOW(),
         latency_ms = EXTRACT(MILLISECOND FROM (NOW() - requested_at))::INTEGER,
         feature_fetch_ms = p_feature_fetch_ms,
         inference_ms = p_inference_ms,
         predicted_value = p_predicted_value,
         p10 = p_p10, p50 = p_p50, p90 = p_p90,
         confidence = p_confidence,
         uncertainty_method = p_uncertainty_method,
         prediction_id = p_prediction_id,
         status = p_status,
         error_message = p_error_message,
         error_code = p_error_code,
         shadow_compared_to = p_shadow_compared_to,
         shadow_disagreement = p_shadow_disagreement,
         cost_estimate_cents = p_cost_estimate_cents
   WHERE inference_id = p_inference_id;
END;
$function$;
-- @@ function public.ottoq_score_observation(p_detector_code text, p_entity_type text, p_entity_id uuid, p_observed_value jsonb, p_observed_numeric numeric, p_observed_at timestamp with time zone, p_fleet_operator_id uuid, p_depot_id uuid, p_context jsonb)
CREATE OR REPLACE FUNCTION public.ottoq_score_observation(p_detector_code text, p_entity_type text, p_entity_id uuid DEFAULT NULL::uuid, p_observed_value jsonb DEFAULT NULL::jsonb, p_observed_numeric numeric DEFAULT NULL::numeric, p_observed_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fleet_operator_id uuid DEFAULT NULL::uuid, p_depot_id uuid DEFAULT NULL::uuid, p_context jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_detector       ottoq_anomaly_detectors%ROWTYPE;
  v_observation_id UUID := gen_random_uuid();
  v_score          NUMERIC := 0;
  v_is_anomaly     BOOLEAN := FALSE;
  v_severity       TEXT := 'info';
  v_event_id       UUID;
  v_context        JSONB;
  v_correlation    UUID;
  v_observed_at    TIMESTAMPTZ := COALESCE(p_observed_at, NOW());
  -- threshold params
  v_low            NUMERIC;
  v_high           NUMERIC;
  -- z_score params
  v_window_size    INTEGER;
  v_z_threshold    NUMERIC;
  v_mean           NUMERIC;
  v_stddev         NUMERIC;
  v_z              NUMERIC;
  -- iqr params
  v_iqr_mult       NUMERIC;
  v_q1             NUMERIC;
  v_q3             NUMERIC;
BEGIN
  SELECT * INTO v_detector
    FROM ottoq_anomaly_detectors
   WHERE detector_code = p_detector_code AND status IN ('active','shadow');
  IF NOT FOUND THEN
    -- Unknown detector — log catalog miss, return NULL
    PERFORM ottoq_record_event(
      p_actor_type := 'ottoq_engine',
      p_event_type := 'system.catalog_miss',
      p_entity_type := 'anomaly_detector',
      p_payload := jsonb_build_object('unknown_detector_code', p_detector_code),
      p_severity := 'warning'
    );
    RETURN NULL;
  END IF;

  v_context := p_context;
  v_correlation := NULLIF(current_setting('ottoq.correlation_id', TRUE), '')::UUID;

  -- Method dispatch
  CASE v_detector.method

    WHEN 'threshold' THEN
      v_low  := (v_detector.parameters ->> 'low')::NUMERIC;
      v_high := (v_detector.parameters ->> 'high')::NUMERIC;
      IF p_observed_numeric IS NOT NULL THEN
        IF (v_low IS NOT NULL AND p_observed_numeric < v_low)
           OR (v_high IS NOT NULL AND p_observed_numeric > v_high) THEN
          v_score := 1.0;
          v_is_anomaly := TRUE;
        END IF;
        v_context := v_context || jsonb_build_object('low', v_low, 'high', v_high, 'observed', p_observed_numeric);
      END IF;

    WHEN 'z_score' THEN
      v_window_size := COALESCE((v_detector.parameters ->> 'window_size')::INTEGER, 100);
      v_z_threshold := COALESCE((v_detector.parameters ->> 'score_threshold')::NUMERIC, 3.0);
      -- Compute mean + stddev over recent observations
      SELECT avg(observed_value::text::numeric)::NUMERIC,
             COALESCE(stddev_samp(observed_value::text::numeric), 0)
        INTO v_mean, v_stddev
        FROM (
          SELECT observed_value FROM ottoq_anomaly_observations
           WHERE detector_id = v_detector.detector_id
             AND entity_type = p_entity_type
             AND (p_entity_id IS NULL OR entity_id = p_entity_id)
             AND observed_value IS NOT NULL
           ORDER BY observed_at DESC LIMIT v_window_size
        ) recent;
      IF v_stddev IS NULL OR v_stddev = 0 THEN
        v_z := 0;
      ELSE
        v_z := abs((p_observed_numeric - COALESCE(v_mean, p_observed_numeric)) / v_stddev);
      END IF;
      -- Normalize to 0..1 (capped at 1.0)
      v_score := LEAST(v_z / (v_z_threshold * 2.0), 1.0);
      v_is_anomaly := v_z >= v_z_threshold;
      v_context := v_context || jsonb_build_object('mean', v_mean, 'stddev', v_stddev, 'z', v_z, 'threshold', v_z_threshold);

    WHEN 'iqr' THEN
      v_window_size := COALESCE((v_detector.parameters ->> 'window_size')::INTEGER, 50);
      v_iqr_mult    := COALESCE((v_detector.parameters ->> 'iqr_multiplier')::NUMERIC, 1.5);
      SELECT percentile_cont(0.25) WITHIN GROUP (ORDER BY (observed_value::text::numeric)),
             percentile_cont(0.75) WITHIN GROUP (ORDER BY (observed_value::text::numeric))
        INTO v_q1, v_q3
        FROM (
          SELECT observed_value FROM ottoq_anomaly_observations
           WHERE detector_id = v_detector.detector_id
             AND entity_type = p_entity_type
             AND (p_entity_id IS NULL OR entity_id = p_entity_id)
             AND observed_value IS NOT NULL
           ORDER BY observed_at DESC LIMIT v_window_size
        ) recent;
      IF v_q1 IS NULL OR v_q3 IS NULL THEN
        v_score := 0;
      ELSE
        v_low := v_q1 - (v_q3 - v_q1) * v_iqr_mult;
        v_high := v_q3 + (v_q3 - v_q1) * v_iqr_mult;
        IF p_observed_numeric < v_low OR p_observed_numeric > v_high THEN
          v_score := 1.0; v_is_anomaly := TRUE;
        END IF;
      END IF;
      v_context := v_context || jsonb_build_object('q1', v_q1, 'q3', v_q3, 'mult', v_iqr_mult);

    ELSE
      -- ml_isoforest / ml_lstm / custom — populated when models deploy
      v_score := 0;
      v_context := v_context || jsonb_build_object('method', v_detector.method, 'note', 'method not yet implemented in pg layer; awaiting model deployment');
  END CASE;

  -- Severity mapping
  v_severity := CASE
    WHEN NOT v_is_anomaly THEN 'info'
    WHEN v_score >= v_detector.severity_critical_threshold THEN 'safety_critical'
    WHEN v_score >= v_detector.severity_high_threshold THEN 'critical'
    WHEN v_score >= v_detector.severity_low_threshold THEN 'warning'
    ELSE 'info'
  END;

  -- Insert observation
  INSERT INTO ottoq_anomaly_observations (
    observation_id, detector_id, detector_code, observed_at,
    entity_type, entity_id, feature_name, observed_value,
    anomaly_score, is_anomaly, severity, context,
    fleet_operator_id, depot_id, correlation_id
  ) VALUES (
    v_observation_id, v_detector.detector_id, v_detector.detector_code, v_observed_at,
    p_entity_type, p_entity_id, v_detector.target_feature, p_observed_value,
    v_score, v_is_anomaly, v_severity, v_context,
    p_fleet_operator_id, p_depot_id, v_correlation
  );

  -- Update detector stats
  UPDATE ottoq_anomaly_detectors
     SET observations_total = observations_total + 1,
         observations_anomalous = observations_anomalous + (CASE WHEN v_is_anomaly THEN 1 ELSE 0 END),
         last_observation_at = v_observed_at,
         last_anomaly_at = CASE WHEN v_is_anomaly THEN v_observed_at ELSE last_anomaly_at END
   WHERE detector_id = v_detector.detector_id;

  -- Emit safety event if anomalous + detector says so
  IF v_is_anomaly AND v_detector.emit_event THEN
    v_event_id := ottoq_record_event(
      p_actor_type        := 'ottoq_engine',
      p_event_type        := CASE
                               WHEN v_severity IN ('safety_critical','critical') THEN 'anomaly.critical_detected'
                               ELSE 'anomaly.detected'
                             END,
      p_entity_type       := p_entity_type,
      p_entity_id         := p_entity_id,
      p_fleet_operator_id := p_fleet_operator_id,
      p_depot_id          := p_depot_id,
      p_payload           := jsonb_build_object(
                              'detector_code', v_detector.detector_code,
                              'category', v_detector.category,
                              'anomaly_score', v_score,
                              'severity', v_severity,
                              'method', v_detector.method,
                              'context', v_context,
                              'observation_id', v_observation_id
                            ),
      p_severity          := v_severity,
      p_correlation_id    := v_correlation
    );
    UPDATE ottoq_anomaly_observations
       SET event_emitted = TRUE, linked_event_id = v_event_id
     WHERE observation_id = v_observation_id;
  END IF;

  RETURN v_observation_id;
END;
$function$;
-- @@ function public.ottoq_start_training_run(p_prediction_type text, p_model_family text, p_parent_model_version_id uuid, p_dataset_window_start timestamp with time zone, p_dataset_window_end timestamp with time zone, p_hyperparameters jsonb, p_trainer text, p_trainer_user text, p_notebook_url text, p_git_commit_sha text, p_fleet_operator_id uuid, p_depot_id uuid, p_vehicle_class text, p_triggered_by text, p_notes text)
CREATE OR REPLACE FUNCTION public.ottoq_start_training_run(p_prediction_type text, p_model_family text, p_parent_model_version_id uuid DEFAULT NULL::uuid, p_dataset_window_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_dataset_window_end timestamp with time zone DEFAULT NULL::timestamp with time zone, p_hyperparameters jsonb DEFAULT '{}'::jsonb, p_trainer text DEFAULT 'colab'::text, p_trainer_user text DEFAULT NULL::text, p_notebook_url text DEFAULT NULL::text, p_git_commit_sha text DEFAULT NULL::text, p_fleet_operator_id uuid DEFAULT NULL::uuid, p_depot_id uuid DEFAULT NULL::uuid, p_vehicle_class text DEFAULT NULL::text, p_triggered_by text DEFAULT 'manual'::text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_id UUID := gen_random_uuid();
BEGIN
  INSERT INTO ottoq_training_runs (
    training_run_id, prediction_type, model_family,
    parent_model_version_id, started_at,
    dataset_window_start, dataset_window_end,
    hyperparameters, trainer, trainer_user, notebook_url, git_commit_sha,
    fleet_operator_id, depot_id, vehicle_class,
    triggered_by, notes, status
  ) VALUES (
    v_id, p_prediction_type, p_model_family,
    p_parent_model_version_id, NOW(),
    p_dataset_window_start, p_dataset_window_end,
    p_hyperparameters, p_trainer, p_trainer_user, p_notebook_url, p_git_commit_sha,
    p_fleet_operator_id, p_depot_id, p_vehicle_class,
    p_triggered_by, p_notes, 'running'
  );

  PERFORM ottoq_record_event(
    p_actor_type    := 'system_scheduler',
    p_actor_id      := p_trainer_user,
    p_event_type    := 'training.started',
    p_entity_type   := 'training_run',
    p_entity_id     := v_id,
    p_payload       := jsonb_build_object(
                        'prediction_type', p_prediction_type,
                        'model_family', p_model_family,
                        'trainer', p_trainer,
                        'triggered_by', p_triggered_by
                      ),
    p_severity      := 'info'
  );

  RETURN v_id;
END;
$function$;
-- @@ function public.ottoq_complete_training_run(p_training_run_id uuid, p_status text, p_resulting_model_version_id uuid, p_training_metrics jsonb, p_test_metrics jsonb, p_artifact_storage_path text, p_artifact_sha256 text, p_artifact_size_bytes bigint, p_dataset_n_samples bigint, p_dataset_hash text, p_failure_reason text)
CREATE OR REPLACE FUNCTION public.ottoq_complete_training_run(p_training_run_id uuid, p_status text, p_resulting_model_version_id uuid DEFAULT NULL::uuid, p_training_metrics jsonb DEFAULT '{}'::jsonb, p_test_metrics jsonb DEFAULT '{}'::jsonb, p_artifact_storage_path text DEFAULT NULL::text, p_artifact_sha256 text DEFAULT NULL::text, p_artifact_size_bytes bigint DEFAULT NULL::bigint, p_dataset_n_samples bigint DEFAULT NULL::bigint, p_dataset_hash text DEFAULT NULL::text, p_failure_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_run ottoq_training_runs%ROWTYPE;
BEGIN
  UPDATE ottoq_training_runs tr
     SET completed_at = NOW(),
         duration_seconds = EXTRACT(EPOCH FROM (NOW() - started_at))::INTEGER,
         status = p_status,
         resulting_model_version_id = p_resulting_model_version_id,
         training_metrics = p_training_metrics,
         test_metrics = p_test_metrics,
         artifact_storage_path = p_artifact_storage_path,
         artifact_sha256 = p_artifact_sha256,
         artifact_size_bytes = p_artifact_size_bytes,
         dataset_n_samples = p_dataset_n_samples,
         dataset_hash = p_dataset_hash,
         failure_reason = p_failure_reason
   WHERE tr.training_run_id = p_training_run_id
   RETURNING * INTO v_run;

  PERFORM ottoq_record_event(
    p_actor_type    := 'system_scheduler',
    p_event_type    := CASE WHEN p_status='succeeded' THEN 'training.succeeded' ELSE 'training.failed' END,
    p_entity_type   := 'training_run',
    p_entity_id     := p_training_run_id,
    p_payload       := jsonb_build_object(
                        'prediction_type', v_run.prediction_type,
                        'duration_seconds', v_run.duration_seconds,
                        'metrics', p_training_metrics,
                        'resulting_model_version_id', p_resulting_model_version_id
                      ),
    p_severity      := CASE WHEN p_status='failed' THEN 'error' ELSE 'info' END
  );
END;
$function$;
-- @@ function public.ottoq_seed_oem_route_slots(p_prediction_type text, p_priority_base integer)
CREATE OR REPLACE FUNCTION public.ottoq_seed_oem_route_slots(p_prediction_type text, p_priority_base integer DEFAULT 100)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_inserted INTEGER := 0;
  v_oem      RECORD;
BEGIN
  -- Generic route (priority_base; matches when no more-specific route applies)
  INSERT INTO ottoq_model_routes (
    prediction_type, priority, traffic_share_pct, shadow_mode,
    rationale, created_by
  )
  SELECT p_prediction_type, p_priority_base, 100, FALSE,
         'Generic fallback route (auto-seeded by ottoq_seed_oem_route_slots)',
         'ottoq_seed_oem_route_slots'
  WHERE NOT EXISTS (
    SELECT 1 FROM ottoq_model_routes r
     WHERE r.prediction_type = p_prediction_type
       AND r.fleet_operator_id IS NULL
       AND r.depot_id IS NULL
       AND r.vehicle_class IS NULL
  );
  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  -- Per-OEM route slot for each fleet_operator (NULL model_version until trained)
  FOR v_oem IN
    SELECT id, name FROM fleet_operators WHERE is_active = TRUE
  LOOP
    INSERT INTO ottoq_model_routes (
      prediction_type, fleet_operator_id, priority,
      traffic_share_pct, shadow_mode,
      rationale, created_by
    )
    SELECT p_prediction_type, v_oem.id, p_priority_base + 100, 100, FALSE,
           format('Per-OEM route slot for %s (auto-seeded; awaiting trained model)', v_oem.name),
           'ottoq_seed_oem_route_slots'
    WHERE NOT EXISTS (
      SELECT 1 FROM ottoq_model_routes r
       WHERE r.prediction_type = p_prediction_type
         AND r.fleet_operator_id = v_oem.id
         AND r.depot_id IS NULL
         AND r.vehicle_class IS NULL
    );
    v_inserted := v_inserted + 1;
  END LOOP;

  -- Per-vehicle-class route slot for each known vehicle class
  FOR v_oem IN
    SELECT vehicle_class_code, oem_fleet_operator_id FROM ottoq_vehicle_classes WHERE status = 'active'
  LOOP
    INSERT INTO ottoq_model_routes (
      prediction_type, vehicle_class, fleet_operator_id, priority,
      traffic_share_pct, shadow_mode,
      rationale, created_by
    )
    SELECT p_prediction_type, v_oem.vehicle_class_code, v_oem.oem_fleet_operator_id,
           p_priority_base + 200, 100, FALSE,
           format('Per-vehicle-class route slot for %s (auto-seeded; awaiting trained model)', v_oem.vehicle_class_code),
           'ottoq_seed_oem_route_slots'
    WHERE NOT EXISTS (
      SELECT 1 FROM ottoq_model_routes r
       WHERE r.prediction_type = p_prediction_type
         AND r.vehicle_class = v_oem.vehicle_class_code
    );
    v_inserted := v_inserted + 1;
  END LOOP;

  RETURN v_inserted;
END;
$function$;
-- @@ function public.ottoq_emit_recommendation(p_proposed_action text, p_prediction_id uuid, p_prediction_type text, p_action_parameters jsonb, p_entity_type text, p_entity_id uuid, p_fleet_operator_id uuid, p_depot_id uuid, p_shadow_only boolean, p_correlation_id uuid, p_parent_event_id uuid, p_expires_in_seconds integer)
CREATE OR REPLACE FUNCTION public.ottoq_emit_recommendation(p_proposed_action text, p_prediction_id uuid DEFAULT NULL::uuid, p_prediction_type text DEFAULT NULL::text, p_action_parameters jsonb DEFAULT '{}'::jsonb, p_entity_type text DEFAULT 'system'::text, p_entity_id uuid DEFAULT NULL::uuid, p_fleet_operator_id uuid DEFAULT NULL::uuid, p_depot_id uuid DEFAULT NULL::uuid, p_shadow_only boolean DEFAULT false, p_correlation_id uuid DEFAULT NULL::uuid, p_parent_event_id uuid DEFAULT NULL::uuid, p_expires_in_seconds integer DEFAULT 300)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_rec_id           UUID := gen_random_uuid();
  v_correlation      UUID;
  v_event_id         UUID;
  v_eval_rows        JSONB := '[]'::jsonb;
  v_blocked_rules    TEXT[] := '{}'::text[];
  v_eval_record      RECORD;
  v_admitted         BOOLEAN := TRUE;
  v_decision_reason  TEXT;
BEGIN
  v_correlation := COALESCE(p_correlation_id,
    NULLIF(current_setting('ottoq.correlation_id', TRUE), '')::UUID,
    gen_random_uuid()
  );

  -- 1. Record initial 'pending' row
  INSERT INTO ottoq_recommendations (
    recommendation_id, emitted_at,
    prediction_id, prediction_type,
    proposed_action, action_parameters,
    entity_type, entity_id, fleet_operator_id, depot_id,
    status, shadow_only,
    expires_at, correlation_id, parent_event_id
  ) VALUES (
    v_rec_id, NOW(),
    p_prediction_id, p_prediction_type,
    p_proposed_action, p_action_parameters,
    p_entity_type, p_entity_id, p_fleet_operator_id, p_depot_id,
    CASE WHEN p_shadow_only THEN 'shadow' ELSE 'validating' END,
    p_shadow_only,
    NOW() + (p_expires_in_seconds || ' seconds')::INTERVAL,
    v_correlation, p_parent_event_id
  );

  -- 2. Run Layer 1 rules for this proposed action
  --    Use SAVEPOINT so a blocking rule's RAISE doesn't kill our transaction
  BEGIN
    FOR v_eval_record IN
      SELECT * FROM ottoq_evaluate_rules_for_action(
        p_action_context        := p_proposed_action,
        p_entity_type           := p_entity_type,
        p_entity_id             := p_entity_id,
        p_context               := p_action_parameters,
        p_fleet_operator_id     := p_fleet_operator_id,
        p_depot_id              := p_depot_id,
        p_triggered_by_event_id := p_parent_event_id
      )
    LOOP
      v_eval_rows := v_eval_rows || jsonb_build_object(
        'rule_code', v_eval_record.rule_code,
        'passed', v_eval_record.passed,
        'reason', v_eval_record.reason,
        'enforcement_taken', v_eval_record.enforcement_taken,
        'evaluation_id', v_eval_record.evaluation_id
      );
      IF NOT v_eval_record.passed AND v_eval_record.enforcement_taken = 'blocked' THEN
        v_blocked_rules := array_append(v_blocked_rules, v_eval_record.rule_code);
        v_admitted := FALSE;
      END IF;
    END LOOP;
  EXCEPTION WHEN sqlstate 'P0001' THEN
    -- Layer 1 blocking rule raised. Capture and continue.
    IF SQLERRM LIKE 'OTTOQ_RULE_BLOCKED:%' THEN
      v_admitted := FALSE;
      v_decision_reason := SQLERRM;
      -- The blocked rule_code is in the message; we capture generically
      v_blocked_rules := array_append(v_blocked_rules, 'see_decision_reason');
    ELSE
      RAISE;
    END IF;
  END;

  -- 3. Finalize status
  IF p_shadow_only THEN
    v_decision_reason := 'shadow mode: not actuated';
    UPDATE ottoq_recommendations
       SET decided_at = NOW(),
           rules_evaluated = v_eval_rows,
           rules_blocked_by = v_blocked_rules,
           status = 'shadow',
           decision_reason = v_decision_reason
     WHERE recommendation_id = v_rec_id;
  ELSIF v_admitted THEN
    UPDATE ottoq_recommendations
       SET decided_at = NOW(),
           rules_evaluated = v_eval_rows,
           rules_blocked_by = v_blocked_rules,
           status = 'admitted',
           decision_reason = 'all_rules_passed'
     WHERE recommendation_id = v_rec_id;
  ELSE
    UPDATE ottoq_recommendations
       SET decided_at = NOW(),
           rules_evaluated = v_eval_rows,
           rules_blocked_by = v_blocked_rules,
           status = 'rejected',
           decision_reason = COALESCE(v_decision_reason, 'blocked_by_rules: ' || array_to_string(v_blocked_rules, ','))
     WHERE recommendation_id = v_rec_id;
  END IF;

  -- 4. Emit Layer-1 event
  v_event_id := ottoq_record_event(
    p_actor_type        := 'ottoq_engine',
    p_event_type        := CASE
                            WHEN p_shadow_only THEN 'recommendation.shadow'
                            WHEN v_admitted THEN 'recommendation.admitted'
                            ELSE 'recommendation.rejected'
                          END,
    p_entity_type       := 'recommendation',
    p_entity_id         := v_rec_id,
    p_fleet_operator_id := p_fleet_operator_id,
    p_depot_id          := p_depot_id,
    p_payload           := jsonb_build_object(
                            'prediction_id', p_prediction_id,
                            'prediction_type', p_prediction_type,
                            'proposed_action', p_proposed_action,
                            'action_parameters', p_action_parameters,
                            'rules_evaluated', v_eval_rows,
                            'rules_blocked_by', v_blocked_rules,
                            'shadow_only', p_shadow_only
                          ),
    p_severity          := CASE WHEN v_admitted OR p_shadow_only THEN 'info' ELSE 'warning' END,
    p_correlation_id    := v_correlation,
    p_parent_event_id   := p_parent_event_id
  );

  RETURN v_rec_id;
END;
$function$;
-- @@ function public.ottoq_mark_recommendation_executed(p_recommendation_id uuid, p_executed_by text, p_outcome text, p_execution_event_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_mark_recommendation_executed(p_recommendation_id uuid, p_executed_by text, p_outcome text, p_execution_event_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
BEGIN
  UPDATE ottoq_recommendations
     SET executed_at        = NOW(),
         executed_by        = p_executed_by,
         execution_outcome  = p_outcome,
         execution_event_id = p_execution_event_id,
         status             = CASE
                                WHEN p_outcome = 'rolled_back' THEN 'rolled_back'
                                ELSE 'executed'
                              END
   WHERE recommendation_id = p_recommendation_id;
END;
$function$;
-- @@ function public.ottoq_resolve_model_for_prediction(p_prediction_type text, p_fleet_operator_id uuid, p_depot_id uuid, p_vehicle_class text, p_entity_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_resolve_model_for_prediction(p_prediction_type text, p_fleet_operator_id uuid DEFAULT NULL::uuid, p_depot_id uuid DEFAULT NULL::uuid, p_vehicle_class text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(out_model_version_id uuid, out_fallback_model_version_id uuid, out_shadow_mode boolean, out_route_id uuid, out_specificity_score integer, out_match_reason text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_now TIMESTAMPTZ := NOW();
  v_hash NUMERIC;
BEGIN
  v_hash := COALESCE(
    (abs(hashtext(COALESCE(p_entity_id::text, p_prediction_type) || COALESCE(p_depot_id::text,''))) % 10000)::NUMERIC / 100.0,
    50.0
  );

  RETURN QUERY
  WITH scored_routes AS (
    SELECT
      r.route_id AS r_route_id,
      r.model_version_id AS r_model_version_id,
      r.fallback_model_version_id AS r_fallback_model_version_id,
      r.shadow_mode AS r_shadow_mode,
      r.traffic_share_pct AS r_traffic_share_pct,
      r.priority AS r_priority,
      ( CASE WHEN r.fleet_operator_id IS NOT NULL AND r.fleet_operator_id = p_fleet_operator_id THEN 10 ELSE 0 END
      + CASE WHEN r.depot_id IS NOT NULL AND r.depot_id = p_depot_id THEN 10 ELSE 0 END
      + CASE WHEN r.vehicle_class IS NOT NULL AND r.vehicle_class = p_vehicle_class THEN 10 ELSE 0 END
      ) AS r_scope_score,
      ( CASE WHEN r.fleet_operator_id IS NULL OR r.fleet_operator_id = p_fleet_operator_id THEN 0 ELSE -1000 END
      + CASE WHEN r.depot_id IS NULL OR r.depot_id = p_depot_id THEN 0 ELSE -1000 END
      + CASE WHEN r.vehicle_class IS NULL OR r.vehicle_class = p_vehicle_class THEN 0 ELSE -1000 END
      ) AS r_exclusion_score
    FROM ottoq_model_routes r
    WHERE r.prediction_type = p_prediction_type
      AND r.effective_from <= v_now
      AND (r.effective_until IS NULL OR r.effective_until > v_now)
  ),
  eligible AS (
    SELECT * FROM scored_routes WHERE r_exclusion_score = 0
  ),
  top_priority AS (
    SELECT * FROM eligible
     ORDER BY (r_scope_score + r_priority) DESC, r_route_id
  ),
  selected AS (
    SELECT *,
      SUM(r_traffic_share_pct) OVER (ORDER BY (r_scope_score + r_priority) DESC, r_route_id) AS r_cumulative_pct
    FROM top_priority
  )
  SELECT
    s.r_model_version_id,
    s.r_fallback_model_version_id,
    s.r_shadow_mode,
    s.r_route_id,
    s.r_scope_score::INTEGER,
    format('matched route_id=%s priority=%s scope_score=%s', s.r_route_id, s.r_priority, s.r_scope_score)
  FROM selected s
  WHERE v_hash <= s.r_cumulative_pct
  ORDER BY (s.r_scope_score + s.r_priority) DESC, s.r_route_id
  LIMIT 1;
END;
$function$;
-- @@ function public.ottoq_sign_bundle(p_bundle_id uuid, p_window_start timestamp with time zone, p_window_end timestamp with time zone, p_sha256 text, p_signing_key_id text)
CREATE OR REPLACE FUNCTION public.ottoq_sign_bundle(p_bundle_id uuid, p_window_start timestamp with time zone, p_window_end timestamp with time zone, p_sha256 text, p_signing_key_id text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_secret      TEXT;
  v_canonical   TEXT;
BEGIN
  v_secret := ottoq_resolve_signing_secret(p_signing_key_id);
  IF v_secret IS NULL THEN
    RETURN NULL;
  END IF;
  v_canonical := concat_ws('|',
    p_bundle_id::text,
    to_char(p_window_start AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    to_char(p_window_end   AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    p_sha256
  );
  RETURN encode(hmac(v_canonical, v_secret, 'sha256'), 'hex');
END;
$function$;
-- @@ function public.ottoq_verify_audit_bundle(p_bundle_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_verify_audit_bundle(p_bundle_id uuid)
 RETURNS TABLE(out_bundle_id uuid, out_has_signature boolean, out_valid boolean, out_algorithm text, out_signing_key_id text, out_computed text, out_stored text, out_manifest_match boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_bundle ottoq_audit_bundles%ROWTYPE;
  v_recomputed TEXT;
BEGIN
  SELECT * INTO v_bundle FROM ottoq_audit_bundles b WHERE b.bundle_id = p_bundle_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Bundle % not found', p_bundle_id;
  END IF;

  v_recomputed := ottoq_sign_bundle(
    v_bundle.bundle_id, v_bundle.window_start, v_bundle.window_end,
    v_bundle.sha256, v_bundle.signature_key_id
  );

  RETURN QUERY SELECT
    v_bundle.bundle_id,
    (v_bundle.signature IS NOT NULL),
    (v_recomputed IS NOT NULL AND v_recomputed = v_bundle.signature),
    v_bundle.signature_algorithm,
    v_bundle.signature_key_id,
    v_recomputed,
    v_bundle.signature,
    TRUE;
END;
$function$;
-- @@ function public.ottoq_register_audit_report(p_report_type text, p_report_subtype text, p_fleet_operator_id uuid, p_depot_id uuid, p_window_start timestamp with time zone, p_window_end timestamp with time zone, p_requested_by_actor_type text, p_requested_by_actor_id text, p_title text, p_description text, p_format text, p_expires_at timestamp with time zone, p_parent_report_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_register_audit_report(p_report_type text, p_report_subtype text DEFAULT NULL::text, p_fleet_operator_id uuid DEFAULT NULL::uuid, p_depot_id uuid DEFAULT NULL::uuid, p_window_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_window_end timestamp with time zone DEFAULT NULL::timestamp with time zone, p_requested_by_actor_type text DEFAULT 'system'::text, p_requested_by_actor_id text DEFAULT NULL::text, p_title text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_format text DEFAULT 'json'::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_parent_report_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_report_id UUID := gen_random_uuid();
  v_event_id  UUID;
BEGIN
  INSERT INTO ottoq_audit_reports (
    report_id, report_type, report_subtype,
    fleet_operator_id, depot_id,
    window_start, window_end,
    requested_by_actor_type, requested_by_actor_id, requested_at,
    generation_status, generation_started_at,
    title, description, format, expires_at, parent_report_id
  ) VALUES (
    v_report_id, p_report_type, p_report_subtype,
    p_fleet_operator_id, p_depot_id,
    COALESCE(p_window_start, NOW() - INTERVAL '24 hours'),
    COALESCE(p_window_end, NOW()),
    p_requested_by_actor_type, p_requested_by_actor_id, NOW(),
    'generating', NOW(),
    p_title, p_description, p_format, p_expires_at, p_parent_report_id
  );

  v_event_id := ottoq_record_event(
    p_actor_type        := p_requested_by_actor_type,
    p_actor_id          := p_requested_by_actor_id,
    p_event_type        := 'audit.report_requested',
    p_entity_type       := 'audit_report',
    p_entity_id         := v_report_id,
    p_fleet_operator_id := p_fleet_operator_id,
    p_depot_id          := p_depot_id,
    p_payload           := jsonb_build_object(
      'report_type', p_report_type, 'report_subtype', p_report_subtype,
      'window_start', p_window_start, 'window_end', p_window_end
    ),
    p_severity          := 'info'
  );

  UPDATE ottoq_audit_reports SET source_event_id = v_event_id WHERE report_id = v_report_id;
  RETURN v_report_id;
END;
$function$;
-- @@ function public.ottoq_complete_audit_report(p_report_id uuid, p_payload jsonb, p_event_count bigint, p_rule_eval_count bigint, p_prediction_count bigint, p_anomaly_count bigint, p_override_count bigint, p_emergency_count bigint, p_visit_count bigint, p_audit_trail_complete boolean, p_data_quality_score numeric, p_signing_key_id text)
CREATE OR REPLACE FUNCTION public.ottoq_complete_audit_report(p_report_id uuid, p_payload jsonb, p_event_count bigint DEFAULT NULL::bigint, p_rule_eval_count bigint DEFAULT NULL::bigint, p_prediction_count bigint DEFAULT NULL::bigint, p_anomaly_count bigint DEFAULT NULL::bigint, p_override_count bigint DEFAULT NULL::bigint, p_emergency_count bigint DEFAULT NULL::bigint, p_visit_count bigint DEFAULT NULL::bigint, p_audit_trail_complete boolean DEFAULT true, p_data_quality_score numeric DEFAULT 1.0, p_signing_key_id text DEFAULT 'system:v1'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_report     ottoq_audit_reports%ROWTYPE;
  v_hash       TEXT;
  v_signature  TEXT;
BEGIN
  v_hash := encode(digest(jsonb_strip_nulls(p_payload)::text, 'sha256'), 'hex');

  SELECT * INTO v_report FROM ottoq_audit_reports r WHERE r.report_id = p_report_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'audit report % not found', p_report_id;
  END IF;

  v_signature := ottoq_sign_event(
    v_report.report_id, v_report.requested_at,
    'ottoq_engine', 'audit.report_completed',
    'audit_report', v_report.report_id,
    v_hash, p_signing_key_id
  );

  UPDATE ottoq_audit_reports
     SET generation_completed_at = NOW(),
         generation_duration_ms = EXTRACT(MILLISECOND FROM (NOW() - generation_started_at))::INTEGER,
         generation_status = 'completed',
         payload = p_payload,
         payload_hash = v_hash,
         signature = v_signature,
         signature_key_id = p_signing_key_id,
         event_count = p_event_count,
         rule_eval_count = p_rule_eval_count,
         prediction_count = p_prediction_count,
         anomaly_count = p_anomaly_count,
         override_count = p_override_count,
         emergency_count = p_emergency_count,
         visit_count = p_visit_count,
         audit_trail_complete = p_audit_trail_complete,
         data_quality_score = p_data_quality_score
   WHERE report_id = p_report_id;

  PERFORM ottoq_record_event(
    p_actor_type    := 'ottoq_engine',
    p_event_type    := 'audit.report_completed',
    p_entity_type   := 'audit_report',
    p_entity_id     := p_report_id,
    p_fleet_operator_id := v_report.fleet_operator_id,
    p_depot_id      := v_report.depot_id,
    p_payload       := jsonb_build_object(
      'report_type', v_report.report_type,
      'event_count', p_event_count,
      'audit_trail_complete', p_audit_trail_complete,
      'data_quality_score', p_data_quality_score,
      'signature_present', (v_signature IS NOT NULL)
    ),
    p_severity      := 'info',
    p_parent_event_id := v_report.source_event_id
  );
END;
$function$;
-- @@ function public.ottoq_generate_audit_bundle(p_fleet_operator_id uuid, p_report_ids uuid[], p_bundle_code text, p_window_start timestamp with time zone, p_window_end timestamp with time zone, p_format text, p_storage_path text, p_size_bytes bigint, p_sha256 text, p_signing_key_id text, p_generated_by_actor_type text, p_generated_by_actor_id text, p_expires_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ottoq_generate_audit_bundle(p_fleet_operator_id uuid, p_report_ids uuid[], p_bundle_code text, p_window_start timestamp with time zone, p_window_end timestamp with time zone, p_format text DEFAULT 'jsonl'::text, p_storage_path text DEFAULT NULL::text, p_size_bytes bigint DEFAULT NULL::bigint, p_sha256 text DEFAULT NULL::text, p_signing_key_id text DEFAULT 'system:v1'::text, p_generated_by_actor_type text DEFAULT 'system'::text, p_generated_by_actor_id text DEFAULT NULL::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_bundle_id   UUID := gen_random_uuid();
  v_sha256      TEXT;
  v_signature   TEXT;
  v_manifest    JSONB;
  v_event_low   BIGINT;
  v_event_high  BIGINT;
BEGIN
  -- Compute event_seq range from the period
  SELECT MIN(event_seq), MAX(event_seq) INTO v_event_low, v_event_high
    FROM ottoq_events
   WHERE occurred_at BETWEEN p_window_start AND p_window_end
     AND (p_fleet_operator_id IS NULL OR fleet_operator_id = p_fleet_operator_id);

  -- Build manifest summarizing what's inside
  v_manifest := jsonb_build_object(
    'report_count', cardinality(p_report_ids),
    'event_count',  COALESCE(v_event_high - v_event_low + 1, 0),
    'window_start', p_window_start,
    'window_end',   p_window_end,
    'rule_eval_count', (
      SELECT count(*) FROM ottoq_rule_evaluations
       WHERE evaluated_at BETWEEN p_window_start AND p_window_end
         AND (p_fleet_operator_id IS NULL OR fleet_operator_id = p_fleet_operator_id)
    ),
    'prediction_count', (
      SELECT count(*) FROM ottoq_predictions
       WHERE created_at BETWEEN p_window_start AND p_window_end
         AND (p_fleet_operator_id IS NULL OR fleet_operator_id = p_fleet_operator_id)
    ),
    'anomaly_count', (
      SELECT count(*) FROM ottoq_anomaly_observations
       WHERE observed_at BETWEEN p_window_start AND p_window_end
         AND (p_fleet_operator_id IS NULL OR fleet_operator_id = p_fleet_operator_id)
         AND is_anomaly = TRUE
    ),
    'emergency_count', (
      SELECT count(*) FROM ottoq_emergency_invocations
       WHERE triggered_at BETWEEN p_window_start AND p_window_end
    ),
    'audit_trail_complete', TRUE
  );

  -- sha256 placeholder until file upload provides the real hash
  v_sha256 := COALESCE(p_sha256, encode(digest(v_manifest::text, 'sha256'), 'hex'));

  -- Sign
  v_signature := ottoq_sign_bundle(v_bundle_id, p_window_start, p_window_end, v_sha256, p_signing_key_id);
  IF v_signature IS NULL THEN
    -- Fail-open: record bundle but flag missing signature
    v_signature := 'UNSIGNED:no_signing_secret_available';
  END IF;

  INSERT INTO ottoq_audit_bundles (
    bundle_id, bundle_code, fleet_operator_id,
    report_ids, event_id_range_low, event_id_range_high,
    window_start, window_end,
    format, storage_path, size_bytes, sha256,
    signature, signature_key_id, signature_algorithm,
    manifest, generated_by_actor_type, generated_by_actor_id, expires_at
  ) VALUES (
    v_bundle_id, p_bundle_code, p_fleet_operator_id,
    p_report_ids, v_event_low, v_event_high,
    p_window_start, p_window_end,
    p_format, p_storage_path, p_size_bytes, v_sha256,
    v_signature, p_signing_key_id, 'HMAC-SHA-256',
    v_manifest, p_generated_by_actor_type, p_generated_by_actor_id, p_expires_at
  );

  PERFORM ottoq_record_event(
    p_actor_type        := p_generated_by_actor_type,
    p_actor_id          := p_generated_by_actor_id,
    p_event_type        := 'audit.bundle_generated',
    p_entity_type       := 'audit_bundle',
    p_entity_id         := v_bundle_id,
    p_fleet_operator_id := p_fleet_operator_id,
    p_payload           := jsonb_build_object(
      'bundle_code', p_bundle_code,
      'report_ids', to_jsonb(p_report_ids),
      'manifest', v_manifest,
      'signature_present', (v_signature NOT LIKE 'UNSIGNED:%')
    ),
    p_severity          := 'info'
  );

  RETURN v_bundle_id;
END;
$function$;
-- @@ function public.ottoq_compute_sla_conformance_for_day(p_fleet_operator_id uuid, p_depot_id uuid, p_date date)
CREATE OR REPLACE FUNCTION public.ottoq_compute_sla_conformance_for_day(p_fleet_operator_id uuid, p_depot_id uuid, p_date date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_window_start    TIMESTAMPTZ := p_date::timestamptz;
  v_window_end      TIMESTAMPTZ := (p_date + 1)::timestamptz;
  v_conformance_id  UUID;

  v_total           INTEGER := 0;
  v_compliant       INTEGER := 0;
  v_partial         INTEGER := 0;
  v_noncompliant    INTEGER := 0;

  v_pct_soc         NUMERIC;
  v_pct_visit_time  NUMERIC;
  v_pct_services    NUMERIC;
  v_pct_oem_gate    NUMERIC;
  v_pct_queue       NUMERIC;
  v_pct_maint       NUMERIC;
  v_pct_no_excep    NUMERIC;

  v_overall         NUMERIC;
  v_grade           TEXT;

  v_contract_ref    TEXT;
  v_sample_evals    UUID[];
BEGIN
  -- Active SLA contract reference
  SELECT contract_reference INTO v_contract_ref
    FROM ottoq_get_active_sla(p_fleet_operator_id);

  -- Per-clause conformance using rule_evaluations as the substrate
  WITH evals AS (
    SELECT rule_code, passed, evaluation_id
      FROM ottoq_rule_evaluations
     WHERE fleet_operator_id = p_fleet_operator_id
       AND (p_depot_id IS NULL OR depot_id = p_depot_id)
       AND evaluated_at >= v_window_start
       AND evaluated_at < v_window_end
       AND rule_code LIKE 'SLA.%'
  ),
  per_rule AS (
    SELECT rule_code,
           count(*) AS total,
           count(*) FILTER (WHERE passed) AS passed_count
      FROM evals GROUP BY rule_code
  )
  SELECT
    MAX(CASE WHEN rule_code = 'SLA.001.min_soc_at_deployment'  THEN (passed_count::NUMERIC / NULLIF(total,0)) END) * 100,
    MAX(CASE WHEN rule_code = 'SLA.003.max_visit_duration'      THEN (passed_count::NUMERIC / NULLIF(total,0)) END) * 100,
    MAX(CASE WHEN rule_code = 'SLA.004.required_services_complete' THEN (passed_count::NUMERIC / NULLIF(total,0)) END) * 100,
    MAX(CASE WHEN rule_code = 'SLA.005.oem_acceptance_timing'  THEN (passed_count::NUMERIC / NULLIF(total,0)) END) * 100,
    MAX(CASE WHEN rule_code = 'SLA.002.max_queue_depth'        THEN (passed_count::NUMERIC / NULLIF(total,0)) END) * 100,
    MAX(CASE WHEN rule_code = 'SLA.006.maintenance_window'     THEN (passed_count::NUMERIC / NULLIF(total,0)) END) * 100,
    MAX(CASE WHEN rule_code = 'SLA.007.redeployment_readiness' THEN (passed_count::NUMERIC / NULLIF(total,0)) END) * 100
  INTO v_pct_soc, v_pct_visit_time, v_pct_services,
       v_pct_oem_gate, v_pct_queue, v_pct_maint, v_pct_no_excep
  FROM per_rule;

  -- Visit-level totals from depot_visit_reports (if table exists)
  BEGIN
    EXECUTE format('
      SELECT
        count(*),
        count(*) FILTER (WHERE deviation_count = 0 AND audit_trail_complete),
        count(*) FILTER (WHERE deviation_count > 0 AND audit_trail_complete),
        count(*) FILTER (WHERE NOT audit_trail_complete OR deviation_count > 5)
      FROM depot_visit_reports
      WHERE fleet_operator_id = $1
        AND ($2 IS NULL OR depot_id = $2)
        AND visit_completed_at >= $3
        AND visit_completed_at < $4
    ') INTO v_total, v_compliant, v_partial, v_noncompliant
      USING p_fleet_operator_id, p_depot_id, v_window_start, v_window_end;
  EXCEPTION WHEN OTHERS THEN
    -- visit_reports not yet populated; fall back to rule-eval counts
    v_total := COALESCE((SELECT count(DISTINCT entity_id) FROM ottoq_rule_evaluations
                          WHERE fleet_operator_id = p_fleet_operator_id
                            AND evaluated_at >= v_window_start AND evaluated_at < v_window_end), 0);
    v_compliant := 0;
    v_partial := 0;
    v_noncompliant := 0;
  END;

  -- Composite weighted score
  v_overall := COALESCE(
    (COALESCE(v_pct_soc, 100) * 0.25)        -- 25% weight: SOC floor (highest value)
    + (COALESCE(v_pct_visit_time, 100) * 0.15) -- 15%: visit duration
    + (COALESCE(v_pct_services, 100) * 0.20) -- 20%: required services
    + (COALESCE(v_pct_oem_gate, 100) * 0.10) -- 10%: OEM gate
    + (COALESCE(v_pct_queue, 100) * 0.10)    -- 10%: queue depth
    + (COALESCE(v_pct_maint, 100) * 0.05)    -- 5%: maintenance window
    + (COALESCE(v_pct_no_excep, 100) * 0.15) -- 15%: redeployment readiness
  , 100);

  v_grade := CASE
    WHEN v_overall >= 95 THEN 'A'
    WHEN v_overall >= 90 THEN 'B'
    WHEN v_overall >= 80 THEN 'C'
    WHEN v_overall >= 70 THEN 'D'
    ELSE 'F'
  END;

  -- Sample evaluation IDs for forensic drill-down
  SELECT array_agg(evaluation_id ORDER BY evaluated_at DESC) FILTER (WHERE NOT passed)
    INTO v_sample_evals
    FROM (
      SELECT evaluation_id, evaluated_at, passed FROM ottoq_rule_evaluations
       WHERE fleet_operator_id = p_fleet_operator_id
         AND (p_depot_id IS NULL OR depot_id = p_depot_id)
         AND evaluated_at >= v_window_start
         AND evaluated_at < v_window_end
         AND rule_code LIKE 'SLA.%'
         AND NOT passed
       LIMIT 25
    ) failed_evals;

  -- Upsert
  INSERT INTO ottoq_sla_conformance_daily (
    fleet_operator_id, depot_id, report_date, sla_contract_reference,
    total_visits, compliant_visits, partial_visits, non_compliant_visits,
    pct_meeting_min_soc, pct_meeting_max_visit_time, pct_meeting_required_services,
    pct_meeting_oem_gate, pct_within_queue_depth, pct_in_maintenance_window,
    pct_no_blocking_exceptions, overall_compliance_pct, composite_grade,
    rule_eval_sample_ids
  ) VALUES (
    p_fleet_operator_id, p_depot_id, p_date, v_contract_ref,
    v_total, v_compliant, v_partial, v_noncompliant,
    v_pct_soc, v_pct_visit_time, v_pct_services,
    v_pct_oem_gate, v_pct_queue, v_pct_maint,
    v_pct_no_excep, v_overall, v_grade,
    COALESCE(v_sample_evals, '{}'::uuid[])
  )
  ON CONFLICT (fleet_operator_id, depot_id, report_date) DO UPDATE
    SET total_visits             = EXCLUDED.total_visits,
        compliant_visits         = EXCLUDED.compliant_visits,
        partial_visits           = EXCLUDED.partial_visits,
        non_compliant_visits     = EXCLUDED.non_compliant_visits,
        pct_meeting_min_soc      = EXCLUDED.pct_meeting_min_soc,
        pct_meeting_max_visit_time = EXCLUDED.pct_meeting_max_visit_time,
        pct_meeting_required_services = EXCLUDED.pct_meeting_required_services,
        pct_meeting_oem_gate     = EXCLUDED.pct_meeting_oem_gate,
        pct_within_queue_depth   = EXCLUDED.pct_within_queue_depth,
        pct_in_maintenance_window = EXCLUDED.pct_in_maintenance_window,
        pct_no_blocking_exceptions = EXCLUDED.pct_no_blocking_exceptions,
        overall_compliance_pct   = EXCLUDED.overall_compliance_pct,
        composite_grade          = EXCLUDED.composite_grade,
        rule_eval_sample_ids     = EXCLUDED.rule_eval_sample_ids,
        computed_at              = NOW()
  RETURNING conformance_id INTO v_conformance_id;

  RETURN v_conformance_id;
END;
$function$;
-- @@ function public.ottoq_record_sla_violation(p_fleet_operator_id uuid, p_depot_id uuid, p_vehicle_id uuid, p_schedule_id uuid, p_rule_code text, p_rule_evaluation_id uuid, p_severity text, p_clause_text text, p_expected_value jsonb, p_observed_value jsonb, p_variance_amount numeric, p_variance_unit text, p_correlation_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_record_sla_violation(p_fleet_operator_id uuid, p_depot_id uuid, p_vehicle_id uuid, p_schedule_id uuid, p_rule_code text, p_rule_evaluation_id uuid, p_severity text, p_clause_text text, p_expected_value jsonb, p_observed_value jsonb, p_variance_amount numeric, p_variance_unit text, p_correlation_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_id UUID := gen_random_uuid();
  v_event_id UUID;
BEGIN
  v_event_id := ottoq_record_event(
    p_actor_type        := 'ottoq_engine',
    p_event_type        := 'sla.violation_recorded',
    p_entity_type       := 'sla_violation',
    p_entity_id         := v_id,
    p_fleet_operator_id := p_fleet_operator_id,
    p_depot_id          := p_depot_id,
    p_payload           := jsonb_build_object(
      'rule_code', p_rule_code,
      'severity', p_severity,
      'variance_amount', p_variance_amount,
      'variance_unit', p_variance_unit,
      'vehicle_id', p_vehicle_id,
      'schedule_id', p_schedule_id
    ),
    p_severity          := CASE p_severity WHEN 'critical_breach' THEN 'critical' WHEN 'breach' THEN 'error' ELSE 'warning' END,
    p_correlation_id    := p_correlation_id
  );

  INSERT INTO ottoq_sla_violations (
    violation_id, fleet_operator_id, depot_id, vehicle_id, schedule_id,
    rule_code, rule_evaluation_id, clause_text,
    expected_value, observed_value, variance_amount, variance_unit, severity,
    linked_event_id, correlation_id
  ) VALUES (
    v_id, p_fleet_operator_id, p_depot_id, p_vehicle_id, p_schedule_id,
    p_rule_code, p_rule_evaluation_id, p_clause_text,
    p_expected_value, p_observed_value, p_variance_amount, p_variance_unit, p_severity,
    v_event_id, p_correlation_id
  );
  RETURN v_id;
END;
$function$;
-- @@ function public.ottoq_oem_fleet_overview(p_fleet_operator_id uuid, p_lookback_days integer)
CREATE OR REPLACE FUNCTION public.ottoq_oem_fleet_overview(p_fleet_operator_id uuid, p_lookback_days integer DEFAULT 7)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_window TIMESTAMPTZ := NOW() - (p_lookback_days || ' days')::INTERVAL;
  v_result JSONB;
BEGIN
  v_result := jsonb_build_object(
    'fleet_operator_id',         p_fleet_operator_id,
    'window_start',              v_window,
    'window_end',                NOW(),
    'lookback_days',             p_lookback_days,

    'live', jsonb_build_object(
      'active_emergencies',      (SELECT count(*) FROM ottoq_emergency_invocations ei
                                   JOIN depots d ON d.id = ei.depot_id
                                   WHERE ei.cleared_at IS NULL),
      'active_recommendations',  (SELECT count(*) FROM ottoq_recommendations
                                   WHERE fleet_operator_id = p_fleet_operator_id
                                     AND status IN ('pending','validating','admitted')
                                     AND (expires_at IS NULL OR expires_at > NOW())),
      'pending_oem_gates',       0
    ),

    'totals', jsonb_build_object(
      'events',                  (SELECT count(*) FROM ottoq_events
                                   WHERE fleet_operator_id = p_fleet_operator_id
                                     AND occurred_at > v_window),
      'predictions',             (SELECT count(*) FROM ottoq_predictions
                                   WHERE fleet_operator_id = p_fleet_operator_id
                                     AND created_at > v_window),
      'rule_evaluations',        (SELECT count(*) FROM ottoq_rule_evaluations
                                   WHERE fleet_operator_id = p_fleet_operator_id
                                     AND evaluated_at > v_window),
      'rule_failures',           (SELECT count(*) FROM ottoq_rule_evaluations
                                   WHERE fleet_operator_id = p_fleet_operator_id
                                     AND evaluated_at > v_window
                                     AND passed = FALSE),
      'sla_violations',          (SELECT count(*) FROM ottoq_sla_violations
                                   WHERE fleet_operator_id = p_fleet_operator_id
                                     AND detected_at > v_window),
      'anomalies_flagged',       (SELECT count(*) FROM ottoq_anomaly_observations
                                   WHERE fleet_operator_id = p_fleet_operator_id
                                     AND observed_at > v_window
                                     AND is_anomaly = TRUE),
      'recommendations_admitted',(SELECT count(*) FROM ottoq_recommendations
                                   WHERE fleet_operator_id = p_fleet_operator_id
                                     AND emitted_at > v_window
                                     AND status IN ('admitted','executed')),
      'recommendations_rejected',(SELECT count(*) FROM ottoq_recommendations
                                   WHERE fleet_operator_id = p_fleet_operator_id
                                     AND emitted_at > v_window
                                     AND status = 'rejected')
    ),

    'sla_compliance', jsonb_build_object(
      'most_recent', (SELECT row_to_json(sc) FROM (
        SELECT report_date, overall_compliance_pct, composite_grade,
               total_visits, compliant_visits, non_compliant_visits
        FROM ottoq_sla_conformance_daily
        WHERE fleet_operator_id = p_fleet_operator_id
        ORDER BY report_date DESC LIMIT 1
      ) sc),
      'rolling_avg_pct', (SELECT ROUND(AVG(overall_compliance_pct)::NUMERIC, 2)
        FROM ottoq_sla_conformance_daily
        WHERE fleet_operator_id = p_fleet_operator_id
          AND report_date >= v_window::DATE)
    ),

    'top_rule_failures', (
      SELECT jsonb_agg(jsonb_build_object(
        'rule_code', rule_code, 'title', title,
        'severity', rule_severity, 'failure_count', failure_count
      ) ORDER BY failure_count DESC)
      FROM ottoq_oem_rule_failure_top
      WHERE fleet_operator_id = p_fleet_operator_id
      LIMIT 10
    ),

    'top_anomaly_detectors', (
      SELECT jsonb_agg(jsonb_build_object(
        'detector_code', detector_code, 'category', detector_category,
        'title', detector_title, 'anomalies_7d', anomalies_7d
      ) ORDER BY anomalies_7d DESC)
      FROM ottoq_oem_anomaly_summary
      WHERE fleet_operator_id = p_fleet_operator_id
      LIMIT 5
    ),

    'computed_at',               NOW()
  );

  RETURN v_result;
END;
$function$;
-- @@ function public.ottoq_generate_incident_report(p_triggering_event_id uuid, p_incident_type text, p_window_minutes_before integer, p_window_minutes_after integer, p_root_cause_summary text, p_generated_by_actor_type text)
CREATE OR REPLACE FUNCTION public.ottoq_generate_incident_report(p_triggering_event_id uuid, p_incident_type text DEFAULT NULL::text, p_window_minutes_before integer DEFAULT 15, p_window_minutes_after integer DEFAULT 60, p_root_cause_summary text DEFAULT NULL::text, p_generated_by_actor_type text DEFAULT 'ottoq_engine'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_id                 UUID := gen_random_uuid();
  v_event              ottoq_events%ROWTYPE;
  v_window_start       TIMESTAMPTZ;
  v_window_end         TIMESTAMPTZ;
  v_timeline           JSONB := '[]'::jsonb;
  v_event_ids          UUID[];
  v_events_count       INTEGER;
  v_rule_failures_count INTEGER;
  v_anomaly_count      INTEGER;
  v_override_count     INTEGER;
  v_vehicles_affected  INTEGER;
  v_stalls_affected    INTEGER;
  v_incident_code      TEXT;
BEGIN
  -- Pull triggering event
  SELECT * INTO v_event FROM ottoq_events e WHERE e.event_id = p_triggering_event_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Triggering event % not found', p_triggering_event_id;
  END IF;

  v_window_start := v_event.occurred_at - (p_window_minutes_before || ' minutes')::INTERVAL;
  v_window_end   := v_event.occurred_at + (p_window_minutes_after  || ' minutes')::INTERVAL;

  -- Build timeline
  SELECT
    jsonb_agg(jsonb_build_object(
      'at', out_occurred_at, 'kind', out_kind, 'subject', out_subject,
      'summary', out_summary, 'severity', out_severity,
      'actor_type', out_actor_type, 'actor_id', out_actor_id,
      'event_id', out_event_id, 'payload', out_payload
    ) ORDER BY out_occurred_at),
    array_agg(out_event_id) FILTER (WHERE out_event_id IS NOT NULL)
    INTO v_timeline, v_event_ids
  FROM ottoq_replay_window(v_window_start, v_window_end,
                           v_event.fleet_operator_id, v_event.depot_id,
                           NULL, v_event.correlation_id);

  -- Stats
  v_events_count       := jsonb_array_length(COALESCE(v_timeline, '[]'::jsonb));
  v_rule_failures_count := (
    SELECT count(*) FROM ottoq_rule_evaluations
     WHERE evaluated_at BETWEEN v_window_start AND v_window_end
       AND passed = FALSE
       AND ((v_event.depot_id IS NULL) OR depot_id = v_event.depot_id)
  );
  v_anomaly_count := (
    SELECT count(*) FROM ottoq_anomaly_observations
     WHERE observed_at BETWEEN v_window_start AND v_window_end
       AND is_anomaly = TRUE
       AND ((v_event.depot_id IS NULL) OR depot_id = v_event.depot_id)
  );
  v_override_count := (
    SELECT count(*) FROM ottoq_rule_evaluations
     WHERE evaluated_at BETWEEN v_window_start AND v_window_end
       AND enforcement_taken = 'overridden'
       AND ((v_event.depot_id IS NULL) OR depot_id = v_event.depot_id)
  );
  v_vehicles_affected := (
    SELECT count(DISTINCT entity_id) FROM ottoq_events
     WHERE occurred_at BETWEEN v_window_start AND v_window_end
       AND entity_type = 'vehicle'
       AND ((v_event.depot_id IS NULL) OR depot_id = v_event.depot_id)
  );
  v_stalls_affected := (
    SELECT count(DISTINCT entity_id) FROM ottoq_events
     WHERE occurred_at BETWEEN v_window_start AND v_window_end
       AND entity_type = 'stall'
       AND ((v_event.depot_id IS NULL) OR depot_id = v_event.depot_id)
  );

  v_incident_code := 'INC-' || to_char(v_event.occurred_at AT TIME ZONE 'UTC', 'YYYY-MM-DD-HH24MI')
                     || '-' || upper(substr(v_id::text, 1, 6));

  -- Insert report
  INSERT INTO ottoq_incident_reports (
    incident_report_id, incident_code,
    incident_type, triggered_at, triggering_event_id, source_correlation_id,
    fleet_operator_id, depot_id,
    window_start, window_end,
    timeline, event_ids_in_timeline,
    duration_seconds, events_in_window, rule_failures_count,
    anomaly_count, override_count, vehicles_affected, stalls_affected,
    root_cause_summary, generated_by_actor_type,
    payload
  ) VALUES (
    v_id, v_incident_code,
    COALESCE(p_incident_type,
             CASE
               WHEN v_event.event_type LIKE 'emergency.%' THEN 'emergency_cascade'
               WHEN v_event.severity = 'safety_critical'  THEN 'safety_event'
               WHEN v_event.event_type LIKE 'anomaly.critical%' THEN 'anomaly_critical'
               WHEN v_event.event_type = 'sla.violation_recorded' THEN 'sla_critical_breach'
               ELSE 'other'
             END),
    v_event.occurred_at, p_triggering_event_id, v_event.correlation_id,
    v_event.fleet_operator_id, v_event.depot_id,
    v_window_start, v_window_end,
    COALESCE(v_timeline, '[]'::jsonb), COALESCE(v_event_ids, '{}'::uuid[]),
    EXTRACT(EPOCH FROM (v_window_end - v_window_start))::INTEGER,
    v_events_count, v_rule_failures_count,
    v_anomaly_count, v_override_count, v_vehicles_affected, v_stalls_affected,
    p_root_cause_summary, p_generated_by_actor_type,
    jsonb_build_object('triggering_event_type', v_event.event_type,
                       'triggering_severity', v_event.severity)
  );

  -- Emit Layer-1 event
  PERFORM ottoq_record_event(
    p_actor_type    := p_generated_by_actor_type,
    p_event_type    := 'incident.report_generated',
    p_entity_type   := 'incident_report',
    p_entity_id     := v_id,
    p_fleet_operator_id := v_event.fleet_operator_id,
    p_depot_id      := v_event.depot_id,
    p_payload       := jsonb_build_object(
      'incident_code', v_incident_code,
      'triggering_event_id', p_triggering_event_id,
      'window_minutes_before', p_window_minutes_before,
      'window_minutes_after', p_window_minutes_after,
      'events_in_window', v_events_count
    ),
    p_severity      := 'info',
    p_parent_event_id := p_triggering_event_id,
    p_correlation_id := v_event.correlation_id
  );

  RETURN v_id;
END;
$function$;
-- @@ function public.ottoq_record_counterfactual(p_source_kind text, p_source_id uuid, p_scenario_label text, p_scenario_description text, p_alternate_inputs jsonb, p_alternate_model_version_id uuid, p_alternate_parameters jsonb, p_actual_outcome jsonb, p_counterfactual_outcome jsonb, p_outcome_kind text, p_actual_value numeric, p_counterfactual_value numeric, p_delta_unit text, p_fleet_operator_id uuid, p_depot_id uuid, p_vehicle_id uuid, p_ran_by_actor_type text, p_ran_by_actor_id text, p_source_correlation_id uuid, p_source_decision_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ottoq_record_counterfactual(p_source_kind text, p_source_id uuid, p_scenario_label text, p_scenario_description text DEFAULT NULL::text, p_alternate_inputs jsonb DEFAULT '{}'::jsonb, p_alternate_model_version_id uuid DEFAULT NULL::uuid, p_alternate_parameters jsonb DEFAULT '{}'::jsonb, p_actual_outcome jsonb DEFAULT NULL::jsonb, p_counterfactual_outcome jsonb DEFAULT NULL::jsonb, p_outcome_kind text DEFAULT NULL::text, p_actual_value numeric DEFAULT NULL::numeric, p_counterfactual_value numeric DEFAULT NULL::numeric, p_delta_unit text DEFAULT NULL::text, p_fleet_operator_id uuid DEFAULT NULL::uuid, p_depot_id uuid DEFAULT NULL::uuid, p_vehicle_id uuid DEFAULT NULL::uuid, p_ran_by_actor_type text DEFAULT 'system'::text, p_ran_by_actor_id text DEFAULT NULL::text, p_source_correlation_id uuid DEFAULT NULL::uuid, p_source_decision_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_id UUID := gen_random_uuid();
  v_delta NUMERIC;
  v_dir TEXT;
BEGIN
  IF p_actual_value IS NOT NULL AND p_counterfactual_value IS NOT NULL THEN
    v_delta := p_counterfactual_value - p_actual_value;
    -- Direction is domain-specific; we default to "neutral" and let caller override.
    v_dir := 'neutral';
  END IF;

  INSERT INTO ottoq_counterfactuals (
    counterfactual_id, ran_at,
    source_kind, source_id, source_correlation_id, source_decision_at,
    scenario_label, scenario_description,
    alternate_inputs, alternate_model_version_id, alternate_parameters,
    actual_outcome, counterfactual_outcome,
    outcome_kind, actual_value, counterfactual_value,
    delta, delta_unit, delta_direction,
    fleet_operator_id, depot_id, vehicle_id,
    status, ran_by_actor_type, ran_by_actor_id
  ) VALUES (
    v_id, NOW(),
    p_source_kind, p_source_id, p_source_correlation_id, p_source_decision_at,
    p_scenario_label, p_scenario_description,
    p_alternate_inputs, p_alternate_model_version_id, p_alternate_parameters,
    p_actual_outcome, p_counterfactual_outcome,
    p_outcome_kind, p_actual_value, p_counterfactual_value,
    v_delta, p_delta_unit, v_dir,
    p_fleet_operator_id, p_depot_id, p_vehicle_id,
    'completed', p_ran_by_actor_type, p_ran_by_actor_id
  );

  PERFORM ottoq_record_event(
    p_actor_type    := p_ran_by_actor_type,
    p_actor_id      := p_ran_by_actor_id,
    p_event_type    := 'counterfactual.computed',
    p_entity_type   := 'counterfactual',
    p_entity_id     := v_id,
    p_fleet_operator_id := p_fleet_operator_id,
    p_depot_id      := p_depot_id,
    p_payload       := jsonb_build_object(
      'source_kind', p_source_kind, 'scenario', p_scenario_label,
      'actual_value', p_actual_value, 'counterfactual_value', p_counterfactual_value,
      'delta', v_delta
    ),
    p_severity      := 'info'
  );
  RETURN v_id;
END;
$function$;
-- @@ function public.ottoq_compute_accuracy_for_window(p_prediction_type text, p_depot_id uuid, p_fleet_operator_id uuid, p_vehicle_class text, p_horizon_minutes integer, p_report_date date, p_hour_of_day integer, p_day_of_week integer, p_model_version_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_compute_accuracy_for_window(p_prediction_type text, p_depot_id uuid, p_fleet_operator_id uuid, p_vehicle_class text, p_horizon_minutes integer, p_report_date date, p_hour_of_day integer DEFAULT NULL::integer, p_day_of_week integer DEFAULT NULL::integer, p_model_version_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_id        UUID;
  v_window_s  TIMESTAMPTZ := p_report_date::timestamptz;
  v_window_e  TIMESTAMPTZ := (p_report_date + 1)::timestamptz;
  v_n_pred    INTEGER;
  v_n_scored  INTEGER;
  v_mae       NUMERIC;
  v_rmse      NUMERIC;
  v_mape      NUMERIC;
  v_bias      NUMERIC;
  v_dir_acc   NUMERIC;
  v_cov_80    NUMERIC;
  v_cov_50    NUMERIC;
  v_avg_width NUMERIC;
BEGIN
  WITH paired AS (
    SELECT
      p.id AS prediction_id,
      p.p10, p.p50, p.p90, p.predicted_value,
      po.actual_value, po.accuracy_score,
      CASE
        WHEN p.predicted_value ? 'value' THEN (p.predicted_value->>'value')::NUMERIC
        WHEN p.p50 IS NOT NULL THEN p.p50
        ELSE NULL
      END AS pred_num,
      CASE
        WHEN po.actual_value ? 'value' THEN (po.actual_value->>'value')::NUMERIC
        ELSE NULL
      END AS act_num
    FROM ottoq_predictions p
    JOIN prediction_outcomes po ON po.prediction_id = p.id
    WHERE p.prediction_type = p_prediction_type
      AND p.created_at >= v_window_s
      AND p.created_at <  v_window_e
      AND (p_depot_id          IS NULL OR p.depot_id = p_depot_id)
      AND (p_fleet_operator_id IS NULL OR p.fleet_operator_id = p_fleet_operator_id)
      AND (p_horizon_minutes   IS NULL OR p.horizon_minutes = p_horizon_minutes)
      AND (p_model_version_id  IS NULL OR p.model_version_id = p_model_version_id)
      AND (p_hour_of_day       IS NULL OR EXTRACT(HOUR FROM p.created_at) = p_hour_of_day)
      AND (p_day_of_week       IS NULL OR EXTRACT(ISODOW FROM p.created_at) = p_day_of_week)
  )
  SELECT
    count(*),
    count(*) FILTER (WHERE pred_num IS NOT NULL AND act_num IS NOT NULL),
    avg(abs(pred_num - act_num)),
    sqrt(avg(power(pred_num - act_num, 2))),
    100.0 * avg(abs(pred_num - act_num) / NULLIF(abs(act_num), 0)),
    avg(pred_num - act_num),
    avg(CASE WHEN sign(pred_num) = sign(act_num) THEN 1 ELSE 0 END)::NUMERIC,
    count(*) FILTER (WHERE p10 IS NOT NULL AND p90 IS NOT NULL AND act_num BETWEEN p10 AND p90)::NUMERIC
      / NULLIF(count(*) FILTER (WHERE p10 IS NOT NULL AND p90 IS NOT NULL), 0),
    NULL::NUMERIC,
    avg(p90 - p10)
  INTO v_n_pred, v_n_scored, v_mae, v_rmse, v_mape, v_bias, v_dir_acc,
       v_cov_80, v_cov_50, v_avg_width
  FROM paired;

  INSERT INTO ottoq_prediction_accuracy_heatmap (
    prediction_type, depot_id, fleet_operator_id, vehicle_class,
    horizon_minutes, hour_of_day, day_of_week, report_date,
    n_predictions, n_scored,
    mae, rmse, mape, bias, directional_accuracy,
    coverage_80, coverage_50, avg_interval_width,
    model_version_id, computed_at
  ) VALUES (
    p_prediction_type, p_depot_id, p_fleet_operator_id, p_vehicle_class,
    p_horizon_minutes, p_hour_of_day, p_day_of_week, p_report_date,
    COALESCE(v_n_pred, 0), COALESCE(v_n_scored, 0),
    v_mae, v_rmse, v_mape, v_bias, v_dir_acc,
    v_cov_80, v_cov_50, v_avg_width,
    p_model_version_id, NOW()
  )
  ON CONFLICT (prediction_type, depot_id, fleet_operator_id, vehicle_class,
               horizon_minutes, hour_of_day, day_of_week, report_date, model_version_id)
  DO UPDATE SET
    n_predictions = EXCLUDED.n_predictions,
    n_scored      = EXCLUDED.n_scored,
    mae           = EXCLUDED.mae,
    rmse          = EXCLUDED.rmse,
    mape          = EXCLUDED.mape,
    bias          = EXCLUDED.bias,
    directional_accuracy = EXCLUDED.directional_accuracy,
    coverage_80   = EXCLUDED.coverage_80,
    avg_interval_width = EXCLUDED.avg_interval_width,
    computed_at   = NOW()
  RETURNING heatmap_id INTO v_id;

  RETURN v_id;
END;
$function$;
-- @@ function public.ottoq_compute_visit_cost(p_schedule_id uuid, p_visit_report_id uuid, p_kwh_delivered numeric, p_kwh_from_grid numeric, p_kwh_from_solar numeric, p_kwh_from_bess numeric, p_avg_rate_per_kwh numeric, p_demand_charge_usd numeric, p_labor_cost_usd numeric, p_opportunity_cost_usd numeric, p_consumables_cost_usd numeric, p_billable_amount_usd numeric, p_carbon_intensity_kg_per_kwh numeric, p_fleet_operator_id uuid, p_depot_id uuid, p_vehicle_id uuid, p_visit_started_at timestamp with time zone, p_visit_completed_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ottoq_compute_visit_cost(p_schedule_id uuid, p_visit_report_id uuid DEFAULT NULL::uuid, p_kwh_delivered numeric DEFAULT NULL::numeric, p_kwh_from_grid numeric DEFAULT NULL::numeric, p_kwh_from_solar numeric DEFAULT NULL::numeric, p_kwh_from_bess numeric DEFAULT NULL::numeric, p_avg_rate_per_kwh numeric DEFAULT NULL::numeric, p_demand_charge_usd numeric DEFAULT 0, p_labor_cost_usd numeric DEFAULT 0, p_opportunity_cost_usd numeric DEFAULT 0, p_consumables_cost_usd numeric DEFAULT 0, p_billable_amount_usd numeric DEFAULT NULL::numeric, p_carbon_intensity_kg_per_kwh numeric DEFAULT 0.4, p_fleet_operator_id uuid DEFAULT NULL::uuid, p_depot_id uuid DEFAULT NULL::uuid, p_vehicle_id uuid DEFAULT NULL::uuid, p_visit_started_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_visit_completed_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_id              UUID;
  v_energy_cost     NUMERIC := COALESCE(p_kwh_delivered, 0) * COALESCE(p_avg_rate_per_kwh, 0);
  v_total_cost      NUMERIC;
  v_margin          NUMERIC;
  v_margin_pct      NUMERIC;
  v_carbon_offset   NUMERIC;
  v_duration_min    NUMERIC;
BEGIN
  v_total_cost := v_energy_cost
                + COALESCE(p_demand_charge_usd, 0)
                + COALESCE(p_labor_cost_usd, 0)
                + COALESCE(p_opportunity_cost_usd, 0)
                + COALESCE(p_consumables_cost_usd, 0);

  IF p_billable_amount_usd IS NOT NULL THEN
    v_margin := p_billable_amount_usd - v_total_cost;
    v_margin_pct := CASE WHEN p_billable_amount_usd > 0 THEN v_margin / p_billable_amount_usd * 100 ELSE NULL END;
  END IF;

  -- Avoided carbon: kWh × (ICE equivalent factor - grid factor)
  -- ICE car emits ~ 0.35 kg CO2/mile, 4 mi/kWh → 0.087 kg CO2/kWh for similar travel
  -- This is highly simplified; calibrate per pilot.
  v_carbon_offset := COALESCE(p_kwh_delivered, 0) * GREATEST(0.45 - COALESCE(p_carbon_intensity_kg_per_kwh, 0.4), 0);

  IF p_visit_started_at IS NOT NULL AND p_visit_completed_at IS NOT NULL THEN
    v_duration_min := EXTRACT(EPOCH FROM (p_visit_completed_at - p_visit_started_at)) / 60.0;
  END IF;

  INSERT INTO ottoq_visit_cost_attribution (
    attribution_id, schedule_id, visit_report_id,
    vehicle_id, fleet_operator_id, depot_id,
    visit_started_at, visit_completed_at, visit_duration_min,
    kwh_delivered, kwh_from_grid, kwh_from_solar, kwh_from_bess,
    energy_cost_usd, demand_charge_usd, labor_cost_usd,
    opportunity_cost_usd, consumables_cost_usd, total_cost_usd,
    billable_amount_usd, margin_usd, margin_pct,
    carbon_offset_kg_co2, grid_carbon_intensity_kg_per_kwh,
    compute_method
  ) VALUES (
    gen_random_uuid(), p_schedule_id, p_visit_report_id,
    p_vehicle_id, p_fleet_operator_id, p_depot_id,
    p_visit_started_at, p_visit_completed_at, v_duration_min,
    p_kwh_delivered, p_kwh_from_grid, p_kwh_from_solar, p_kwh_from_bess,
    v_energy_cost, p_demand_charge_usd, p_labor_cost_usd,
    p_opportunity_cost_usd, p_consumables_cost_usd, v_total_cost,
    p_billable_amount_usd, v_margin, v_margin_pct,
    v_carbon_offset, p_carbon_intensity_kg_per_kwh,
    'rule_based'
  )
  ON CONFLICT (schedule_id) DO UPDATE SET
    kwh_delivered    = EXCLUDED.kwh_delivered,
    kwh_from_grid    = EXCLUDED.kwh_from_grid,
    kwh_from_solar   = EXCLUDED.kwh_from_solar,
    kwh_from_bess    = EXCLUDED.kwh_from_bess,
    energy_cost_usd  = EXCLUDED.energy_cost_usd,
    demand_charge_usd = EXCLUDED.demand_charge_usd,
    labor_cost_usd   = EXCLUDED.labor_cost_usd,
    total_cost_usd   = EXCLUDED.total_cost_usd,
    billable_amount_usd = EXCLUDED.billable_amount_usd,
    margin_usd       = EXCLUDED.margin_usd,
    margin_pct       = EXCLUDED.margin_pct,
    carbon_offset_kg_co2 = EXCLUDED.carbon_offset_kg_co2,
    computed_at      = NOW()
  RETURNING attribution_id INTO v_id;
  RETURN v_id;
END;
$function$;
-- @@ function public.ottoq_compute_depot_benchmark(p_depot_id uuid, p_date date)
CREATE OR REPLACE FUNCTION public.ottoq_compute_depot_benchmark(p_depot_id uuid, p_date date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_id             UUID;
  v_window_s       TIMESTAMPTZ := p_date::timestamptz;
  v_window_e       TIMESTAMPTZ := (p_date + 1)::timestamptz;

  v_visits         INTEGER;
  v_vehicles       INTEGER;
  v_oems           INTEGER;
  v_service_hours  NUMERIC;

  v_kwh            NUMERIC;
  v_revenue        NUMERIC;
  v_cost           NUMERIC;

  v_rule_failures  INTEGER;
  v_anomalies      INTEGER;
  v_emergencies    INTEGER;
  v_overrides      INTEGER;

  v_carbon_offset  NUMERIC;
  v_avg_sla        NUMERIC;
  v_worst_sla      NUMERIC;
  v_sla_violations INTEGER;
BEGIN
  -- Throughput from visit_cost_attribution (will be zero until pipeline produces visits)
  SELECT count(*), count(DISTINCT vehicle_id), count(DISTINCT fleet_operator_id),
         COALESCE(SUM(visit_duration_min) / 60.0, 0),
         COALESCE(SUM(kwh_delivered), 0),
         COALESCE(SUM(billable_amount_usd), 0),
         COALESCE(SUM(total_cost_usd), 0),
         COALESCE(SUM(carbon_offset_kg_co2), 0)
    INTO v_visits, v_vehicles, v_oems, v_service_hours,
         v_kwh, v_revenue, v_cost, v_carbon_offset
    FROM ottoq_visit_cost_attribution
   WHERE depot_id = p_depot_id
     AND visit_completed_at >= v_window_s
     AND visit_completed_at <  v_window_e;

  -- Quality counters from Layer 1
  SELECT count(*) INTO v_rule_failures
    FROM ottoq_rule_evaluations
   WHERE depot_id = p_depot_id AND evaluated_at >= v_window_s AND evaluated_at < v_window_e AND passed = FALSE;

  SELECT count(*) INTO v_anomalies
    FROM ottoq_anomaly_observations
   WHERE depot_id = p_depot_id AND observed_at >= v_window_s AND observed_at < v_window_e AND is_anomaly = TRUE;

  SELECT count(*) INTO v_emergencies
    FROM ottoq_emergency_invocations
   WHERE depot_id = p_depot_id AND triggered_at >= v_window_s AND triggered_at < v_window_e;

  SELECT count(*) INTO v_overrides
    FROM ottoq_rule_evaluations
   WHERE depot_id = p_depot_id AND evaluated_at >= v_window_s AND evaluated_at < v_window_e AND enforcement_taken = 'overridden';

  -- SLA composite (across all OEMs at this depot)
  SELECT AVG(overall_compliance_pct), MIN(overall_compliance_pct), SUM(non_compliant_visits)
    INTO v_avg_sla, v_worst_sla, v_sla_violations
    FROM ottoq_sla_conformance_daily
   WHERE depot_id = p_depot_id AND report_date = p_date;

  INSERT INTO ottoq_depot_benchmarks_daily (
    depot_id, report_date,
    visits_completed, vehicles_served, oems_served, total_service_hours,
    avg_sla_compliance_pct, worst_sla_compliance_pct, sla_violations_count,
    total_kwh_delivered, total_revenue_usd, total_cost_usd,
    margin_pct, cost_per_visit_usd,
    rule_failures_count, anomalies_count, emergencies_count, overrides_count,
    total_carbon_offset_kg, computed_at
  ) VALUES (
    p_depot_id, p_date,
    v_visits, v_vehicles, v_oems, v_service_hours,
    v_avg_sla, v_worst_sla, COALESCE(v_sla_violations, 0),
    v_kwh, v_revenue, v_cost,
    CASE WHEN v_revenue > 0 THEN (v_revenue - v_cost) / v_revenue * 100 ELSE NULL END,
    CASE WHEN v_visits > 0 THEN v_cost / v_visits ELSE NULL END,
    v_rule_failures, v_anomalies, v_emergencies, v_overrides,
    v_carbon_offset, NOW()
  )
  ON CONFLICT (depot_id, report_date) DO UPDATE SET
    visits_completed = EXCLUDED.visits_completed,
    vehicles_served  = EXCLUDED.vehicles_served,
    oems_served      = EXCLUDED.oems_served,
    total_service_hours = EXCLUDED.total_service_hours,
    avg_sla_compliance_pct = EXCLUDED.avg_sla_compliance_pct,
    worst_sla_compliance_pct = EXCLUDED.worst_sla_compliance_pct,
    sla_violations_count = EXCLUDED.sla_violations_count,
    total_kwh_delivered = EXCLUDED.total_kwh_delivered,
    total_revenue_usd = EXCLUDED.total_revenue_usd,
    total_cost_usd = EXCLUDED.total_cost_usd,
    margin_pct = EXCLUDED.margin_pct,
    cost_per_visit_usd = EXCLUDED.cost_per_visit_usd,
    rule_failures_count = EXCLUDED.rule_failures_count,
    anomalies_count = EXCLUDED.anomalies_count,
    emergencies_count = EXCLUDED.emergencies_count,
    overrides_count = EXCLUDED.overrides_count,
    total_carbon_offset_kg = EXCLUDED.total_carbon_offset_kg,
    computed_at = NOW()
  RETURNING benchmark_id INTO v_id;
  RETURN v_id;
END;
$function$;
-- @@ function public.ottoq_block_mutation()
CREATE OR REPLACE FUNCTION public.ottoq_block_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND current_setting('ottoq.retention', true) = 'on' THEN
    RETURN OLD;  -- retention maintenance (transaction-local flag, see ottoq_retention_purge)
  END IF;
  RAISE EXCEPTION 'OTTOQ_APPEND_ONLY: % rejected on table %.', TG_OP, TG_TABLE_NAME
    USING ERRCODE = 'P0001';
END;
$function$;
-- @@ function public.ottoq_record_feature_value(p_feature_name text, p_entity_type text, p_entity_id uuid, p_value_numeric numeric, p_value_integer bigint, p_value_boolean boolean, p_value_text text, p_value_timestamp timestamp with time zone, p_value_json jsonb, p_valid_from timestamp with time zone, p_observation_time timestamp with time zone, p_source text, p_source_event_id uuid, p_computed_by text, p_fleet_operator_id uuid, p_depot_id uuid, p_quality_score numeric, p_is_imputed boolean, p_emit_event boolean)
CREATE OR REPLACE FUNCTION public.ottoq_record_feature_value(p_feature_name text, p_entity_type text, p_entity_id uuid DEFAULT NULL::uuid, p_value_numeric numeric DEFAULT NULL::numeric, p_value_integer bigint DEFAULT NULL::bigint, p_value_boolean boolean DEFAULT NULL::boolean, p_value_text text DEFAULT NULL::text, p_value_timestamp timestamp with time zone DEFAULT NULL::timestamp with time zone, p_value_json jsonb DEFAULT NULL::jsonb, p_valid_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_observation_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_source text DEFAULT 'app'::text, p_source_event_id uuid DEFAULT NULL::uuid, p_computed_by text DEFAULT NULL::text, p_fleet_operator_id uuid DEFAULT NULL::uuid, p_depot_id uuid DEFAULT NULL::uuid, p_quality_score numeric DEFAULT NULL::numeric, p_is_imputed boolean DEFAULT false, p_emit_event boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_value_id    UUID := gen_random_uuid();
  v_valid_from  TIMESTAMPTZ := COALESCE(p_valid_from, NOW());
  v_feature_ver INTEGER;
BEGIN
  UPDATE ottoq_feature_values fv
     SET valid_until = v_valid_from
   WHERE fv.feature_name = p_feature_name
     AND ((fv.entity_id IS NULL AND p_entity_id IS NULL) OR fv.entity_id = p_entity_id)
     AND fv.entity_type = p_entity_type
     AND fv.valid_until IS NULL;

  SELECT version INTO v_feature_ver FROM ottoq_features WHERE feature_name = p_feature_name;
  v_feature_ver := COALESCE(v_feature_ver, 1);

  INSERT INTO ottoq_feature_values (
    value_id, feature_name, entity_type, entity_id,
    value_numeric, value_integer, value_boolean,
    value_text, value_timestamp, value_json,
    valid_from, observation_time,
    source, source_event_id, computed_by, feature_version,
    quality_score, is_imputed,
    fleet_operator_id, depot_id
  ) VALUES (
    v_value_id, p_feature_name, p_entity_type, p_entity_id,
    p_value_numeric, p_value_integer, p_value_boolean,
    p_value_text, p_value_timestamp, p_value_json,
    v_valid_from, COALESCE(p_observation_time, NOW()),
    p_source, p_source_event_id, p_computed_by, v_feature_ver,
    p_quality_score, p_is_imputed,
    p_fleet_operator_id, p_depot_id
  );

  -- Optional event emission (off by default — feature writes are high-volume)
  IF p_emit_event THEN
    PERFORM ottoq_record_event(
      p_actor_type        := 'ottoq_engine',
      p_event_type        := 'feature.recorded',
      p_entity_type       := p_entity_type,
      p_entity_id         := p_entity_id,
      p_fleet_operator_id := p_fleet_operator_id,
      p_depot_id          := p_depot_id,
      p_payload           := jsonb_build_object(
        'feature_name', p_feature_name,
        'value_id', v_value_id,
        'source', p_source,
        'quality_score', p_quality_score
      ),
      p_severity          := 'debug'
    );
  END IF;

  RETURN v_value_id;
END;
$function$;
-- @@ function public.ottoq_compute_audit_trail_completeness(p_report_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_compute_audit_trail_completeness(p_report_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_report          ottoq_audit_reports%ROWTYPE;
  v_signed_count    BIGINT;
  v_total_count     BIGINT;
  v_invalid_count   BIGINT;
  v_complete        BOOLEAN;
  v_event_id        UUID;
  v_verification    RECORD;
  v_retention_floor TIMESTAMPTZ;
  v_status          TEXT;
  c_sample_size     CONSTANT INT := 50;
BEGIN
  SELECT * INTO v_report FROM ottoq_audit_reports r WHERE r.report_id = p_report_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'audit report % not found', p_report_id;
  END IF;

  -- Retention floor = oldest event still held. Leftmost leaf of the event_seq
  -- UNIQUE btree (~4 page reads). NEVER min(occurred_at): occurred_at has only a
  -- BRIN, so that degrades to a full 8.3 GB heap scan (measured timing out 25 s).
  SELECT e.occurred_at INTO v_retention_floor
    FROM ottoq_events e ORDER BY e.event_seq ASC LIMIT 1;

  SELECT count(*),
         count(*) FILTER (WHERE signature IS NOT NULL)
    INTO v_total_count, v_signed_count
    FROM ottoq_events e
   WHERE e.occurred_at >= v_report.window_start
     AND e.occurred_at <= v_report.window_end
     AND (v_report.fleet_operator_id IS NULL OR e.fleet_operator_id = v_report.fleet_operator_id)
     AND (v_report.depot_id          IS NULL OR e.depot_id = v_report.depot_id);

  v_invalid_count := 0;
  FOR v_event_id IN
    SELECT e.event_id FROM ottoq_events e
     WHERE e.occurred_at >= v_report.window_start
       AND e.occurred_at <= v_report.window_end
       AND e.signature IS NOT NULL
       AND (v_report.fleet_operator_id IS NULL OR e.fleet_operator_id = v_report.fleet_operator_id)
       AND (v_report.depot_id          IS NULL OR e.depot_id = v_report.depot_id)
     ORDER BY e.event_seq
     LIMIT c_sample_size
  LOOP
    SELECT * INTO v_verification FROM ottoq_verify_event_signature(v_event_id);
    -- correct column names: has_signature / valid
    IF v_verification.has_signature AND NOT v_verification.valid THEN
      v_invalid_count := v_invalid_count + 1;
    END IF;
  END LOOP;

  IF v_retention_floor IS NULL THEN
    v_status := 'no_events_at_all';             v_complete := FALSE;
  ELSIF v_total_count = 0 THEN
    v_status := CASE WHEN v_report.window_start < v_retention_floor
                       THEN 'window_predates_retention'
                     ELSE 'no_events_in_window' END;
    v_complete := FALSE;
  ELSIF v_report.window_start < v_retention_floor THEN
    v_status := 'window_partially_purged';      v_complete := FALSE;
  ELSIF v_total_count <> v_signed_count THEN
    v_status := 'unsigned_events_present';      v_complete := FALSE;
  ELSIF v_invalid_count > 0 THEN
    v_status := 'invalid_signatures_in_sample'; v_complete := FALSE;
  ELSE
    v_status := 'complete';                     v_complete := TRUE;
  END IF;

  UPDATE ottoq_audit_reports
     SET audit_trail_complete = v_complete,
         exclusions =
           COALESCE(
             (SELECT jsonb_agg(elem)
                FROM jsonb_array_elements(COALESCE(exclusions, '[]'::jsonb)) AS elem
               WHERE NOT (elem ? 'audit_trail_check')),
             '[]'::jsonb)
           || jsonb_build_object(
                'audit_trail_check', jsonb_build_object(
                  'checked_at', NOW(),
                  'status', v_status,
                  'total_events', v_total_count,
                  'signed_events', v_signed_count,
                  'invalid_signatures_sampled', v_invalid_count,
                  'signature_sample_size', c_sample_size,
                  'retention_floor', v_retention_floor,
                  'window_start', v_report.window_start,
                  'window_end', v_report.window_end
                )
              )
   WHERE report_id = p_report_id;

  RETURN v_complete;
END;
$function$;
-- @@ function public.ottoq_auto_generate_incident_report()
CREATE OR REPLACE FUNCTION public.ottoq_auto_generate_incident_report()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_incident_id UUID;
  v_existing_count INT;
BEGIN
  -- Skip auto-incident-report generation for BENCHMARK depots (perf: this trigger scans the huge
  -- ottoq_events/rule_evaluations history; synthetic A/B runs don't need prod audit reports).
  -- depots is tiny so this PK-keyed EXISTS is microseconds; robust to any 'benchmark%' slug depot.
  IF NEW.depot_id IS NOT NULL AND EXISTS (
       SELECT 1 FROM depots d WHERE d.id = NEW.depot_id AND d.slug LIKE 'benchmark%') THEN
    RETURN NEW;
  END IF;

  IF NEW.severity <> 'safety_critical' THEN RETURN NEW; END IF;

  IF NEW.event_type IN (
    'incident.report_generated','incident.report_reviewed','incident.report_reopened',
    'audit.report_requested','audit.report_completed','emergency.cleared',
    'emergency.cascade_complete','emergency.action_executed','emergency.notify_actors'
  ) THEN
    RETURN NEW;
  END IF;

  IF NEW.correlation_id IS NOT NULL THEN
    SELECT count(*) INTO v_existing_count
      FROM ottoq_incident_reports
     WHERE source_correlation_id = NEW.correlation_id;
    IF v_existing_count > 0 THEN RETURN NEW; END IF;
  END IF;

  BEGIN
    v_incident_id := ottoq_generate_incident_report(
      p_triggering_event_id := NEW.event_id,
      p_window_minutes_before := 15,
      p_window_minutes_after  := 60,
      p_generated_by_actor_type := 'ottoq_engine'
    );
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  RETURN NEW;
END;
$function$;
-- @@ function public.ottoq_replay_window(p_window_start timestamp with time zone, p_window_end timestamp with time zone, p_fleet_operator_id uuid, p_depot_id uuid, p_vehicle_id uuid, p_correlation_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_replay_window(p_window_start timestamp with time zone, p_window_end timestamp with time zone, p_fleet_operator_id uuid DEFAULT NULL::uuid, p_depot_id uuid DEFAULT NULL::uuid, p_vehicle_id uuid DEFAULT NULL::uuid, p_correlation_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(out_seq bigint, out_occurred_at timestamp with time zone, out_kind text, out_subject text, out_summary text, out_severity text, out_actor_type text, out_actor_id text, out_payload jsonb, out_event_id uuid, out_correlation_id uuid)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
BEGIN
  RETURN QUERY
  SELECT * FROM (
    SELECT
      e.event_seq, e.occurred_at, 'event'::text, e.entity_type, e.event_type,
      e.severity, e.actor_type, e.actor_id, e.payload, e.event_id, e.correlation_id
    FROM ottoq_events e
    WHERE e.occurred_at BETWEEN p_window_start AND p_window_end
      AND (p_fleet_operator_id IS NULL OR e.fleet_operator_id = p_fleet_operator_id)
      AND (p_depot_id          IS NULL OR e.depot_id = p_depot_id)
      AND (p_vehicle_id        IS NULL OR e.entity_id = p_vehicle_id)
      AND (p_correlation_id    IS NULL OR e.correlation_id = p_correlation_id)

    UNION ALL
    SELECT
      NULL::bigint, re.evaluated_at, 'rule_failure'::text, re.entity_type,
      re.rule_code || ' — ' || COALESCE(re.reason,''),
      re.severity, 'ottoq_engine'::text, NULL::text,
      jsonb_build_object('rule_code', re.rule_code, 'reason', re.reason,
                         'enforcement_taken', re.enforcement_taken),
      re.linked_event_id, re.correlation_id
    FROM ottoq_rule_evaluations re
    WHERE re.evaluated_at BETWEEN p_window_start AND p_window_end AND re.passed = FALSE
      AND (p_fleet_operator_id IS NULL OR re.fleet_operator_id = p_fleet_operator_id)
      AND (p_depot_id          IS NULL OR re.depot_id = p_depot_id)
      AND (p_vehicle_id        IS NULL OR re.entity_id = p_vehicle_id)
      AND (p_correlation_id    IS NULL OR re.correlation_id = p_correlation_id)

    UNION ALL
    SELECT
      NULL::bigint, ao.observed_at, 'anomaly'::text, ao.entity_type,
      ao.detector_code || ' score=' || ROUND(ao.anomaly_score::NUMERIC, 3)::text,
      ao.severity, 'ottoq_engine'::text, NULL::text,
      jsonb_build_object('detector', ao.detector_code, 'score', ao.anomaly_score,
                         'context', ao.context),
      ao.linked_event_id, ao.correlation_id
    FROM ottoq_anomaly_observations ao
    WHERE ao.observed_at BETWEEN p_window_start AND p_window_end AND ao.is_anomaly = TRUE
      AND (p_fleet_operator_id IS NULL OR ao.fleet_operator_id = p_fleet_operator_id)
      AND (p_depot_id          IS NULL OR ao.depot_id = p_depot_id)
      AND (p_vehicle_id        IS NULL OR ao.entity_id = p_vehicle_id)
      AND (p_correlation_id    IS NULL OR ao.correlation_id = p_correlation_id)

    UNION ALL
    SELECT
      NULL::bigint, p.created_at, 'prediction'::text, p.prediction_type::text,
      format('predict %s → %s', p.prediction_type, COALESCE(p.predicted_value::text, 'n/a')),
      'info'::text, 'ottoq_engine'::text, NULL::text,
      jsonb_build_object('type', p.prediction_type, 'value', p.predicted_value,
                         'p10', p.p10, 'p50', p.p50, 'p90', p.p90,
                         'baseline', p.prediction_baseline),
      p.event_id, p.correlation_id
    FROM ottoq_predictions p
    WHERE p.created_at BETWEEN p_window_start AND p_window_end
      AND (p_fleet_operator_id IS NULL OR p.fleet_operator_id = p_fleet_operator_id)
      AND (p_depot_id          IS NULL OR p.depot_id = p_depot_id)
      AND (p_vehicle_id        IS NULL OR p.vehicle_id = p_vehicle_id)
      AND (p_correlation_id    IS NULL OR p.correlation_id = p_correlation_id)

    UNION ALL
    SELECT
      NULL::bigint, r.emitted_at, 'recommendation'::text, r.proposed_action,
      format('%s → %s (%s)', r.proposed_action, r.status, COALESCE(r.decision_reason,'')),
      CASE WHEN r.status='rejected' THEN 'warning' ELSE 'info' END, 'ottoq_engine'::text, NULL::text,
      jsonb_build_object('action', r.proposed_action, 'status', r.status,
                         'rules_blocked_by', r.rules_blocked_by, 'shadow', r.shadow_only),
      NULL::uuid, r.correlation_id
    FROM ottoq_recommendations r
    WHERE r.emitted_at BETWEEN p_window_start AND p_window_end
      AND (p_fleet_operator_id IS NULL OR r.fleet_operator_id = p_fleet_operator_id)
      AND (p_depot_id          IS NULL OR r.depot_id = p_depot_id)
      AND (p_correlation_id    IS NULL OR r.correlation_id = p_correlation_id)

    UNION ALL
    SELECT
      NULL::bigint, ei.triggered_at, 'emergency'::text, ei.protocol_code,
      'cascade triggered: ' || ei.protocol_code,
      'safety_critical'::text, ei.triggered_by_actor_type, ei.triggered_by_actor_id,
      jsonb_build_object('protocol', ei.protocol_code, 'outcome', ei.outcome,
                         'actions_count', jsonb_array_length(ei.cascade_executed)),
      ei.linked_event_id, ei.correlation_id
    FROM ottoq_emergency_invocations ei
    WHERE ei.triggered_at BETWEEN p_window_start AND p_window_end
      AND (p_depot_id IS NULL OR ei.depot_id = p_depot_id)
      AND (p_correlation_id IS NULL OR ei.correlation_id = p_correlation_id)
  ) AS combined
  ORDER BY combined.occurred_at ASC, combined.event_seq ASC NULLS LAST;
END;
$function$;
-- @@ function twin.ottoq_sim_seeded_random(p_seed bigint, p_salt text)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_seeded_random(p_seed bigint, p_salt text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_hash BIGINT;
BEGIN
  -- Combine seed + salt into a deterministic hash, normalize to [0,1)
  v_hash := abs(hashtextextended(p_seed::text || ':' || p_salt, p_seed));
  RETURN (v_hash % 1000000)::NUMERIC / 1000000.0;
END;
$function$;
-- @@ function twin.ottoq_sim_start_run(p_scenario_code text, p_sim_clock_start timestamp with time zone, p_time_scale numeric, p_random_seed bigint, p_run_by text)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_start_run(p_scenario_code text, p_sim_clock_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_time_scale numeric DEFAULT NULL::numeric, p_random_seed bigint DEFAULT NULL::bigint, p_run_by text DEFAULT 'otto_twin'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_scenario   ottoq_scenarios%ROWTYPE;
  v_run_id     UUID := gen_random_uuid();
  v_clock_start TIMESTAMPTZ;
  v_clock_end  TIMESTAMPTZ;
  v_time_scale NUMERIC;
  v_seed       BIGINT;
  v_active_id  UUID;
  v_active_by  TEXT;
  v_deployed   INT;
  v_primed     INT := 0;
BEGIN
  SELECT * INTO v_scenario FROM ottoq_scenarios
   WHERE scenario_code = p_scenario_code AND status = 'active';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OTTOQ_SCENARIO_NOT_FOUND: %', p_scenario_code USING ERRCODE = 'P0001';
  END IF;
  -- ONE WORLD, ONE MOVER. vehicles/stalls are global and unscoped, so a second
  -- ticking run would advance the same rows from a different clock. Checked
  -- before anything is written, so a refused start leaves no partial run behind.
  IF public.ottoq_policy_get(NULL, 'allow_concurrent_runs', 0) < 1 THEN
    SELECT sim_run_id, run_by INTO v_active_id, v_active_by
      FROM ottoq_sim_runs
     WHERE status = 'running'
       AND COALESCE(run_by, '') NOT IN ('production_live', 'cert_harness')
     ORDER BY started_at DESC LIMIT 1;
    IF v_active_id IS NOT NULL THEN
      RAISE EXCEPTION 'OTTOQ_RUN_ALREADY_ACTIVE: run % (started by %) is still moving THIS WORLD -- not just this depot. vehicles and stalls are global and unscoped, so ANY running non-certification run blocks a new start on ANY depot, and a second mover would advance the same rows from a different clock. Lift it deliberately with the allow_concurrent_runs dial if that is really what you want. Watch the live run instead, or stop it first.', v_active_id, COALESCE(v_active_by,'unknown') USING ERRCODE = 'P0001';
    END IF;
  END IF;

  v_clock_start := COALESCE(p_sim_clock_start, date_trunc('day', NOW()) + INTERVAL '6 hours');
  v_clock_end   := v_clock_start + (v_scenario.sim_duration_minutes || ' minutes')::INTERVAL;
  v_time_scale  := COALESCE(p_time_scale, v_scenario.default_time_scale);
  v_seed        := COALESCE(p_random_seed, v_scenario.random_seed);

  INSERT INTO ottoq_sim_runs (
    sim_run_id, scenario_id, scenario_code, started_at, last_tick_at, next_tick_due_at,
    sim_clock_start, sim_clock_current, sim_clock_end,
    time_scale, tick_interval_seconds, depot_id, random_seed, status, run_by
  ) VALUES (
    v_run_id, v_scenario.scenario_id, v_scenario.scenario_code, NOW(), NULL, NOW(),
    v_clock_start, v_clock_start, v_clock_end,
    v_time_scale, v_scenario.tick_interval_seconds, v_scenario.depot_id, v_seed, 'running', p_run_by
  );

  -- 0092: pin this transaction's event tagging to the run just created; the row is
  -- not yet visible to the lookup path a trigger would use mid-transaction.
  PERFORM set_config('ottoq.sim_run_id', v_run_id::text, true);

  -- 0107: THE RUN DRAWS ITS OWN WORLD. vehicle_need_profile is persistent state
  -- every run mutates (last_wash_at et al.); without a per-run redraw each run
  -- inherits the previous run's clocks (pair 11: one arm washed a vehicle the
  -- other did not). Deterministic per seed; runs BEFORE the fingerprint stamp
  -- so the stamp covers the drawn state.
  BEGIN
    PERFORM public.ottoq_run_boot_draw(v_run_id);
  EXCEPTION WHEN OTHERS THEN RAISE WARNING 'run boot draw failed: %', SQLERRM;
  END;

  -- 0093: fingerprint the PRE-run world (before the cold-start prime mutates it),
  -- so any two runs can prove they started equal instead of assuming it.
  BEGIN
    UPDATE ottoq_sim_runs
       SET payload = COALESCE(payload,'{}'::jsonb)
           || jsonb_build_object('world_fingerprint',
                ottoq.ottoq_world_fingerprint(v_scenario.depot_id))
     WHERE sim_run_id = v_run_id;
  EXCEPTION WHEN OTHERS THEN RAISE WARNING 'world fingerprint failed: %', SQLERRM;
  END;

  -- COLD START. A torn-down world is all-offline, and nothing in the demo tick
  -- path deploys an offline vehicle, so without this the run can never move.
  -- Guarded on the whole fleet being parked: if anything is already deployed,
  -- this run is joining a world in motion and must not disturb it.
  /* 0177: only THIS depot. Counting every vehicle in the table let one
     depot's traffic decide whether another depot's run cold-starts, and
     a run that skips its cold start begins all-parked in a world the
     tick path cannot move. Same class as 0145/0053/0054. */
  SELECT count(*) INTO v_deployed FROM vehicles
   WHERE current_state = 'deployed'::vehicle_state
     AND home_depot_id = v_scenario.depot_id;
  IF v_deployed = 0 THEN
    v_primed := twin.ottoq_sim_prime_deployment(
      v_run_id, v_clock_start,
      public.ottoq_policy_get(NULL, 'run_start_deployed_fraction', 0.55));
  END IF;

  PERFORM ottoq_record_event(
    p_actor_type    := 'ottoq_engine', p_actor_id := 'otto_twin',
    p_event_type    := 'twin.sim_run_started', p_entity_type := 'sim_run', p_entity_id := v_run_id,
    p_depot_id      := v_scenario.depot_id,
    p_payload       := jsonb_build_object(
                        'scenario_code', p_scenario_code, 'category', v_scenario.category,
                        'sim_duration_minutes', v_scenario.sim_duration_minutes,
                        'time_scale', v_time_scale, 'random_seed', v_seed,
                        'sim_clock_start', v_clock_start, 'sim_clock_end', v_clock_end,
                        'cold_start', (v_deployed = 0), 'primed_vehicles', v_primed),
    p_severity      := 'info',
    p_ingest_source := 'twin', p_data_source := 'twin', p_sim_run_id := v_run_id
  );
  -- 0323: ARM THE AGENTIC LAYER ON THE WAY IN. Across 1,147 runs nothing
  -- that started a run had ever done this, so every run booted with the
  -- proposer door shut and the UI could never show the agentic half
  -- working. Arming is part of STARTING now, at every door, so a run is
  -- armed because it was started and not because somebody remembered.
  --
  -- THE cert_harness TEST IS NOT OPTIONAL. Arming sets
  -- proposer_frame_facts=1, which changes what the decision frame carries
  -- (0265) -- the frame every canon was measured against. The arming
  -- routine refuses such a run by RAISING, so an unguarded call would
  -- abort the creation of every certification arm.
  IF COALESCE(p_run_by, '') <> 'cert_harness' THEN
    BEGIN
      PERFORM public.ottoq_agentic_arm(v_run_id, 'auto:' || COALESCE(p_run_by, 'unknown'));
      UPDATE public.ottoq_sim_runs SET payload = COALESCE(payload, '{}'::jsonb)
             || jsonb_build_object('agentic_arm', jsonb_build_object('ok', true))
       WHERE sim_run_id = v_run_id;
    EXCEPTION WHEN OTHERS THEN
      -- Receipt, never silence, and never a failed start: a run that could
      -- not be armed is still a valid run, and the reason is on the row.
      UPDATE public.ottoq_sim_runs SET payload = COALESCE(payload, '{}'::jsonb)
             || jsonb_build_object('agentic_arm',
                  jsonb_build_object('ok', false, 'error', SQLERRM))
       WHERE sim_run_id = v_run_id;
    END;
  END IF;

  RETURN v_run_id;
END;
$function$;
-- @@ function twin.ottoq_sim_advance_clock(p_sim_run_id uuid)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_advance_clock(p_sim_run_id uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_run ottoq_sim_runs%ROWTYPE;
  v_new_clock TIMESTAMPTZ;
BEGIN
  SELECT * INTO v_run FROM ottoq_sim_runs WHERE sim_run_id = p_sim_run_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'sim run % not found', p_sim_run_id; END IF;
  IF v_run.status <> 'running' THEN RETURN NULL; END IF;

  v_new_clock := v_run.sim_clock_current + (v_run.time_scale || ' minutes')::INTERVAL;

  IF v_new_clock >= v_run.sim_clock_end THEN
    UPDATE ottoq_sim_runs
       SET sim_clock_current = sim_clock_end, status = 'completed', ended_at = NOW(),
           last_tick_at = NOW(), tick_count = tick_count + 1, next_tick_due_at = NULL
     WHERE sim_run_id = p_sim_run_id;
    PERFORM ottoq_record_event(
      p_actor_type := 'ottoq_engine', p_actor_id := 'otto_twin',
      p_event_type := 'twin.sim_run_completed', p_entity_type := 'sim_run', p_entity_id := p_sim_run_id,
      p_depot_id := v_run.depot_id,
      p_payload := jsonb_build_object('scenario_code', v_run.scenario_code,
                     'tick_count', v_run.tick_count + 1, 'events_generated', v_run.events_generated),
      p_severity := 'info', p_ingest_source := 'twin',
      p_data_source := 'twin', p_sim_run_id := p_sim_run_id
    );
    RETURN NULL;
  END IF;

  UPDATE ottoq_sim_runs
     SET sim_clock_current = v_new_clock, last_tick_at = NOW(),
         next_tick_due_at = NOW() + (tick_interval_seconds || ' seconds')::INTERVAL,
         tick_count = tick_count + 1
   WHERE sim_run_id = p_sim_run_id;
  RETURN v_new_clock;
END;
$function$;
-- @@ function twin.ottoq_sim_end_run(p_sim_run_id uuid, p_status text, p_reason text)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_end_run(p_sim_run_id uuid, p_status text DEFAULT 'aborted'::text, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE v_run ottoq_sim_runs%ROWTYPE;
BEGIN
  SELECT * INTO v_run FROM ottoq_sim_runs WHERE sim_run_id = p_sim_run_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'sim run % not found', p_sim_run_id; END IF;
  UPDATE ottoq_sim_runs
     SET status = p_status, ended_at = NOW(), failure_reason = p_reason, next_tick_due_at = NULL
   WHERE sim_run_id = p_sim_run_id;
  PERFORM ottoq_record_event(
    p_actor_type := 'ottoq_engine', p_actor_id := 'otto_twin',
    p_event_type := 'twin.sim_run_ended', p_entity_type := 'sim_run', p_entity_id := p_sim_run_id,
    p_depot_id := v_run.depot_id,
    p_payload := jsonb_build_object('status', p_status, 'reason', p_reason),
    p_severity := CASE WHEN p_status = 'failed' THEN 'error' ELSE 'info' END,
    p_ingest_source := 'twin', p_data_source := 'twin', p_sim_run_id := p_sim_run_id
  );
END;
$function$;
-- @@ function twin.ottoq_sim_record_twin_event(p_sim_run_id uuid, p_actor_type text, p_event_type text, p_entity_type text, p_entity_id uuid, p_payload jsonb, p_fleet_operator_id uuid, p_depot_id uuid, p_severity text, p_correlation_id uuid, p_occurred_at timestamp with time zone)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_record_twin_event(p_sim_run_id uuid, p_actor_type text, p_event_type text, p_entity_type text, p_entity_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb, p_fleet_operator_id uuid DEFAULT NULL::uuid, p_depot_id uuid DEFAULT NULL::uuid, p_severity text DEFAULT NULL::text, p_correlation_id uuid DEFAULT NULL::uuid, p_occurred_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE v_event_id UUID;
BEGIN
  v_event_id := ottoq_record_event(
    p_actor_type := p_actor_type, p_actor_id := 'otto_twin', p_event_type := p_event_type,
    p_entity_type := p_entity_type, p_entity_id := p_entity_id, p_payload := p_payload,
    p_fleet_operator_id := p_fleet_operator_id, p_depot_id := p_depot_id,
    p_severity := p_severity, p_correlation_id := p_correlation_id,
    p_ingest_source := 'twin', p_data_source := 'twin', p_sim_run_id := p_sim_run_id
  );
  UPDATE ottoq_sim_runs SET events_generated = events_generated + 1 WHERE sim_run_id = p_sim_run_id;
  RETURN v_event_id;
END;
$function$;
-- @@ function public.ottoq_record_event(p_actor_type text, p_event_type text, p_entity_type text, p_entity_id uuid, p_payload jsonb, p_actor_id text, p_actor_metadata jsonb, p_fleet_operator_id uuid, p_depot_id uuid, p_previous_state jsonb, p_new_state jsonb, p_severity text, p_correlation_id uuid, p_parent_event_id uuid, p_related_task_id uuid, p_related_schedule_id uuid, p_related_decision_id uuid, p_outcome text, p_latency_ms integer, p_ingest_source text, p_signing_key_id text, p_data_source text, p_sim_run_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_record_event(p_actor_type text, p_event_type text, p_entity_type text, p_entity_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb, p_actor_id text DEFAULT NULL::text, p_actor_metadata jsonb DEFAULT '{}'::jsonb, p_fleet_operator_id uuid DEFAULT NULL::uuid, p_depot_id uuid DEFAULT NULL::uuid, p_previous_state jsonb DEFAULT NULL::jsonb, p_new_state jsonb DEFAULT NULL::jsonb, p_severity text DEFAULT NULL::text, p_correlation_id uuid DEFAULT NULL::uuid, p_parent_event_id uuid DEFAULT NULL::uuid, p_related_task_id uuid DEFAULT NULL::uuid, p_related_schedule_id uuid DEFAULT NULL::uuid, p_related_decision_id uuid DEFAULT NULL::uuid, p_outcome text DEFAULT NULL::text, p_latency_ms integer DEFAULT NULL::integer, p_ingest_source text DEFAULT 'app'::text, p_signing_key_id text DEFAULT 'system:v1'::text, p_data_source text DEFAULT 'production'::text, p_sim_run_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_event_id        UUID := gen_random_uuid();
  v_category        TEXT;
  v_severity        TEXT;
  v_payload_hash    TEXT;
  v_signature       TEXT;
  v_correlation_id  UUID;
  v_causation       UUID[] := '{}'::uuid[];
  v_parent          ottoq_events%ROWTYPE;
  v_occurred_at     TIMESTAMPTZ := NOW();
BEGIN
  SELECT category, default_severity INTO v_category, v_severity
    FROM ottoq_event_types_catalog WHERE event_type = p_event_type;
  IF v_category IS NULL THEN
    v_category := 'system_event';
    v_severity := 'warning';
  END IF;
  v_severity := COALESCE(p_severity, v_severity);

  v_correlation_id := COALESCE(
    p_correlation_id,
    NULLIF(current_setting('ottoq.correlation_id', TRUE), '')::UUID,
    gen_random_uuid()
  );

  IF p_parent_event_id IS NOT NULL THEN
    SELECT * INTO v_parent FROM ottoq_events WHERE event_id = p_parent_event_id;
    IF FOUND THEN
      v_causation := v_parent.causation_chain || p_parent_event_id;
    ELSE
      v_causation := ARRAY[p_parent_event_id];
    END IF;
  END IF;

  v_payload_hash := ottoq_compute_event_hash(p_payload);
  v_signature := ottoq_sign_event(
    v_event_id, v_occurred_at, p_actor_type, p_event_type,
    p_entity_type, p_entity_id, v_payload_hash, p_signing_key_id
  );

  INSERT INTO ottoq_events (
    event_id, occurred_at, recorded_at,
    actor_type, actor_id, actor_metadata,
    event_type, event_category, severity,
    entity_type, entity_id,
    fleet_operator_id, depot_id,
    payload, previous_state, new_state,
    correlation_id, parent_event_id, causation_chain,
    related_task_id, related_schedule_id, related_decision_id,
    payload_hash, signature, signature_key_id,
    outcome, latency_ms, ingest_source,
    data_source, sim_run_id, sim_clock_at
  ) VALUES (
    v_event_id, v_occurred_at, NOW(),
    p_actor_type, p_actor_id, p_actor_metadata,
    p_event_type, v_category, v_severity,
    p_entity_type, p_entity_id,
    p_fleet_operator_id,
    COALESCE(p_depot_id,
             CASE WHEN p_entity_type = 'depot'
                       AND EXISTS (SELECT 1 FROM public.depots d WHERE d.id = p_entity_id)
                  THEN p_entity_id END),
    p_payload, p_previous_state, p_new_state,
    v_correlation_id, p_parent_event_id, v_causation,
    p_related_task_id, p_related_schedule_id, p_related_decision_id,
    v_payload_hash, v_signature, p_signing_key_id,
    p_outcome, p_latency_ms, p_ingest_source,
    COALESCE(p_data_source, 'production'), p_sim_run_id, CASE WHEN p_sim_run_id IS NOT NULL THEN ottoq.ottoq_run_now() END
  );

  RETURN v_event_id;
END;
$function$;
-- @@ function public.ottoq_sample_calibrated(p_variable_name text, p_segment text, p_seed bigint, p_salt text)
CREATE OR REPLACE FUNCTION public.ottoq_sample_calibrated(p_variable_name text, p_segment text DEFAULT 'global'::text, p_seed bigint DEFAULT 42, p_salt text DEFAULT NULL::text)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_dist        ottoq_calibration_distributions%ROWTYPE;
  v_u           NUMERIC;
  v_pos         NUMERIC;
  v_idx_low     INTEGER;
  v_idx_high    INTEGER;
  v_frac        NUMERIC;
  v_val_low     NUMERIC;
  v_val_high    NUMERIC;
  v_result      NUMERIC;
  v_salt        TEXT;
BEGIN
  v_salt := COALESCE(p_salt, p_variable_name || ':' || p_segment);

  -- 1. Resolve distribution (exact segment, then 'global' fallback)
  SELECT * INTO v_dist
    FROM ottoq_calibration_distributions
   WHERE variable_name = p_variable_name
     AND segment = p_segment
   LIMIT 1;

  IF NOT FOUND THEN
    SELECT * INTO v_dist
      FROM ottoq_calibration_distributions
     WHERE variable_name = p_variable_name
       AND segment = 'global'
     LIMIT 1;
  END IF;

  IF NOT FOUND THEN
    -- No calibration data for this variable — return NULL so the caller
    -- knows to fall back (and ideally logs a calibration gap).
    RETURN NULL;
  END IF;

  -- 2. Deterministic uniform draw
  v_u := ottoq_sim_seeded_random(p_seed, v_salt);

  -- 3. Map onto the 101-point quantile grid (indices 1..101 in PG arrays)
  v_pos      := v_u * 100.0;            -- 0..100
  v_idx_low  := floor(v_pos)::INTEGER;  -- 0..100
  v_idx_high := LEAST(v_idx_low + 1, 100);
  v_frac     := v_pos - v_idx_low;

  v_val_low  := v_dist.quantile_grid[v_idx_low + 1];   -- PG arrays 1-indexed
  v_val_high := v_dist.quantile_grid[v_idx_high + 1];
  v_result   := v_val_low + (v_val_high - v_val_low) * v_frac;

  -- 4. Clamp to physical bounds
  IF v_dist.hard_min IS NOT NULL THEN v_result := GREATEST(v_result, v_dist.hard_min); END IF;
  IF v_dist.hard_max IS NOT NULL THEN v_result := LEAST(v_result, v_dist.hard_max); END IF;

  RETURN v_result;
END;
$function$;
-- @@ function public.ottoq_calibration_coverage()
CREATE OR REPLACE FUNCTION public.ottoq_calibration_coverage()
 RETURNS TABLE(out_domain text, out_dataset_code text, out_status text, out_variables bigint, out_distributions bigint, out_total_samples bigint, out_ingested_at timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
  SELECT
    d.domain, d.dataset_code, d.status,
    count(DISTINCT dist.variable_name),
    count(dist.distribution_id),
    COALESCE(sum(dist.sample_count), 0),
    d.ingested_at
  FROM ottoq_calibration_datasets d
  LEFT JOIN ottoq_calibration_distributions dist ON dist.dataset_code = d.dataset_code
  GROUP BY d.domain, d.dataset_code, d.status, d.ingested_at
  ORDER BY d.domain, d.dataset_code;
$function$;
-- @@ function public.ottoq_local_to_latlng(p_origin_lat double precision, p_origin_lng double precision, p_x_ft double precision, p_y_ft double precision)
CREATE OR REPLACE FUNCTION public.ottoq_local_to_latlng(p_origin_lat double precision, p_origin_lng double precision, p_x_ft double precision, p_y_ft double precision)
 RETURNS TABLE(out_lat numeric, out_lng numeric)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_ft_per_deg_lat DOUBLE PRECISION := 364000;
  v_ft_per_deg_lng DOUBLE PRECISION;
BEGIN
  v_ft_per_deg_lng := 364000.0 * cos(radians(p_origin_lat));
  RETURN QUERY SELECT
    (p_origin_lat + (p_y_ft / v_ft_per_deg_lat))::NUMERIC,
    (p_origin_lng + (p_x_ft / v_ft_per_deg_lng))::NUMERIC;
END;
$function$;
-- @@ function public.ottoq_sim_compute_charge_rate(p_soc_pct numeric, p_battery_temp_c numeric, p_ambient_temp_c numeric, p_charger_max_kw numeric, p_vehicle_max_kw numeric, p_battery_capacity_kwh numeric, p_battery_soh_pct numeric, p_noise_seed bigint, p_noise_salt text)
CREATE OR REPLACE FUNCTION public.ottoq_sim_compute_charge_rate(p_soc_pct numeric, p_battery_temp_c numeric, p_ambient_temp_c numeric, p_charger_max_kw numeric, p_vehicle_max_kw numeric, p_battery_capacity_kwh numeric, p_battery_soh_pct numeric DEFAULT 100, p_noise_seed bigint DEFAULT 0, p_noise_salt text DEFAULT NULL::text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_base_rate      NUMERIC;
  v_is_dcfc        BOOLEAN;
  v_curve_factor   NUMERIC := 1.0;
  v_thermal_factor NUMERIC := 1.0;
  v_soh_factor     NUMERIC;
  v_noise_factor   NUMERIC;
  v_accept         NUMERIC[];
  v_soc            NUMERIC;
  v_i              INT;
BEGIN
  v_base_rate := LEAST(p_charger_max_kw, p_vehicle_max_kw);
  IF v_base_rate <= 0 THEN RETURN 0; END IF;
  v_is_dcfc := p_charger_max_kw > 22;

  IF v_is_dcfc AND p_battery_capacity_kwh > 0 THEN
    -- 0573: what the battery accepts, in kW per usable kWh, at 0, 5, ..., 100% charge, capped by the car's and the
    -- charger's maxima. Sources and fits: docs/research/direct/2026-09-30-lane-a-service-time-calibration.md.
    v_accept := CASE
      -- Tesla Model Y Long Range (250 kW, 75 kWh usable): its own measured curve (Fastned, figshare
      -- doi:10.6084/m9.figshare.30570653.v1) to 90%, then the median tail of the 20 curves measured to 98%+
      WHEN p_vehicle_max_kw = 250 AND p_battery_capacity_kwh = 75 THEN
        ARRAY[3.062, 3.062, 2.934, 2.607, 2.428, 2.315, 2.191, 1.953, 1.758, 1.570, 1.404,
              1.244, 1.112, 1.042, 0.971, 0.878, 0.647, 0.593, 0.461, 0.375, 0.219]::numeric[]
      -- Jaguar I-PACE (104 kW, 84.7 kWh usable): its maximum to 50%, then fitted so 10-80% takes EV Database's
      -- published 45 minutes, then the median tail
      WHEN p_vehicle_max_kw = 104 AND p_battery_capacity_kwh = 84.7 THEN
        ARRAY[3.000, 3.000, 3.000, 3.000, 3.000, 3.000, 3.000, 3.000, 3.000, 3.000, 3.000,
              1.079, 0.929, 0.780, 0.631, 0.481, 0.332, 0.309, 0.278, 0.219, 0.103]::numeric[]
      -- every other battery: the median over the dataset's 99 measured curves
      ELSE
        ARRAY[1.906, 1.949, 1.992, 1.991, 1.945, 1.948, 1.855, 1.679, 1.653, 1.581, 1.543,
              1.367, 1.229, 1.121, 1.013, 0.950, 0.790, 0.702, 0.608, 0.484, 0.312]::numeric[]
    END;
    v_soc := LEAST(100, GREATEST(0, COALESCE(p_soc_pct, 100)));
    v_i := LEAST(19, floor(v_soc / 5)::int);
    v_curve_factor := LEAST(1.0, p_battery_capacity_kwh
                                 * (v_accept[v_i + 1] + (v_accept[v_i + 2] - v_accept[v_i + 1]) * (v_soc - 5 * v_i) / 5)
                                 / v_base_rate);
  ELSIF v_is_dcfc THEN
    -- no battery size given: the shape used before 0573
    IF p_soc_pct < 20 THEN
      v_curve_factor := 0.85 + (p_soc_pct / 20.0) * 0.15;
    ELSIF p_soc_pct <= 80 THEN
      v_curve_factor := 1.0 - ((p_soc_pct - 20.0) / 60.0) * 0.78;
    ELSE
      v_curve_factor := GREATEST(0.08, 0.22 - ((p_soc_pct - 80.0) / 20.0) * 0.14);
    END IF;
  ELSE
    -- L2/AC: onboard-charger limited, flat with ~88% AC->DC efficiency;
    -- taper only near full.
    v_curve_factor := CASE WHEN p_soc_pct > 95 THEN 0.88 * 0.5 ELSE 0.88 END;
  END IF;

  -- thermal derate: INL-calibrated cold behavior; heat derate unchanged
  IF p_battery_temp_c > 35 THEN
    v_thermal_factor := GREATEST(0.30, 1.0 - (p_battery_temp_c - 35) * 0.020);
  ELSIF p_battery_temp_c < 0 THEN
    v_thermal_factor := GREATEST(0.20, 0.35 + p_battery_temp_c * 0.010);  -- <=0C: 0.35 and falling
  ELSIF p_battery_temp_c < 10 THEN
    v_thermal_factor := 0.65;                                             -- 0-10C: x0.65 (INL)
  ELSIF p_battery_temp_c < 15 THEN
    v_thermal_factor := 0.65 + (p_battery_temp_c - 10) * 0.07;            -- blend 10->15C
  END IF;

  v_soh_factor := 0.70 + (p_battery_soh_pct / 100.0) * 0.30;
  v_noise_factor := 0.97 + ottoq_sim_seeded_random(
    p_noise_seed, COALESCE(p_noise_salt, '') || ':' || p_soc_pct::text) * 0.06;

  RETURN ROUND((v_base_rate * v_curve_factor * v_thermal_factor * v_soh_factor * v_noise_factor)::NUMERIC, 3);
END;
$function$;
-- @@ function twin.ottoq_sim_emit_ocpp(p_session_id uuid, p_charger_id uuid, p_vehicle_id uuid, p_sim_run_id uuid, p_sim_clock timestamp with time zone, p_direction text, p_message_type text, p_payload jsonb)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_emit_ocpp(p_session_id uuid, p_charger_id uuid, p_vehicle_id uuid, p_sim_run_id uuid, p_sim_clock timestamp with time zone, p_direction text, p_message_type text, p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_msg_id UUID := gen_random_uuid();
BEGIN
  INSERT INTO ottoq_ocpp_messages (
    message_id, ocpp_session_id, charger_id, vehicle_id, sim_run_id,
    sim_clock_at, direction, message_type, payload, data_source
  ) VALUES (
    v_msg_id, p_session_id, p_charger_id, p_vehicle_id, p_sim_run_id,
    p_sim_clock, p_direction, p_message_type, p_payload, 'twin'
  );
  RETURN v_msg_id;
END;
$function$;
-- @@ function twin.ottoq_sim_start_charge_session(p_vehicle_id uuid, p_stall_id uuid, p_sim_run_id uuid, p_target_soc numeric, p_sim_clock_now timestamp with time zone)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_start_charge_session(p_vehicle_id uuid, p_stall_id uuid, p_sim_run_id uuid, p_target_soc numeric DEFAULT NULL::numeric, p_sim_clock_now timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_session_id      UUID := gen_random_uuid();
  v_vehicle         RECORD;
  v_stall           RECORD;
  v_charger         ottoq_ocpp_chargers%ROWTYPE;
  v_clock           TIMESTAMPTZ;
  v_target_soc      NUMERIC;
  v_charge_kind     TEXT;
  v_state           vehicle_state;
  v_ambient_temp    NUMERIC;
  v_battery_temp    NUMERIC;
  v_init_rate       NUMERIC;
BEGIN
  v_clock := COALESCE(p_sim_clock_now, NOW());

  SELECT id, fleet_operator_id, current_soc, target_soc, battery_capacity_kwh, current_stall_id,
         inlet_max_kw, max_charge_rate_kw, current_depot_id,
         (config->>'battery_soh_pct')::NUMERIC AS soh, display_name
    INTO v_vehicle FROM vehicles WHERE id = p_vehicle_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'vehicle % not found', p_vehicle_id; END IF;

  SELECT s.id, s.depot_id, s.ocpp_charger_id, s.connector_max_kw, s.stall_type
    INTO v_stall FROM stalls s WHERE s.id = p_stall_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'stall % not found', p_stall_id; END IF;
  IF v_stall.ocpp_charger_id IS NULL THEN RAISE EXCEPTION 'stall % has no associated charger', p_stall_id; END IF;

  SELECT * INTO v_charger FROM ottoq_ocpp_chargers WHERE charger_id = v_stall.ocpp_charger_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'charger for stall % not found', p_stall_id; END IF;

  -- 0510 (G241): the air a car charges in is the depot's, as its weather reads it, not a per-car draw from the whole
  -- year. The battery's own offset below still varies by car.
  v_ambient_temp := twin.ottoq_sim_site_ambient_c(p_sim_run_id, v_clock);
  v_ambient_temp := COALESCE(v_ambient_temp, 20);
  v_battery_temp := v_ambient_temp + 5 + ottoq_sim_seeded_random(42, 'btemp:' || p_vehicle_id::text) * 10;

  v_target_soc := LEAST(COALESCE(p_target_soc, v_vehicle.target_soc, public.ottoq_default_target_soc()), public.ottoq_target_soc_cap(v_stall.stall_type::TEXT, COALESCE(p_sim_clock_now, NOW()), p_sim_run_id));
  v_charge_kind := CASE WHEN v_charger.max_kw > 50 THEN 'dcfc' ELSE 'l2' END;
  v_state := (CASE WHEN v_charger.max_kw > 50 THEN 'charging_dcfc' ELSE 'charging_l2' END)::vehicle_state;

  v_init_rate := ottoq_sim_compute_charge_rate(
    p_soc_pct := v_vehicle.current_soc, p_battery_temp_c := v_battery_temp,
    p_ambient_temp_c := v_ambient_temp, p_charger_max_kw := v_charger.max_kw,
    p_vehicle_max_kw := v_vehicle.inlet_max_kw, p_battery_capacity_kwh := v_vehicle.battery_capacity_kwh,
    p_battery_soh_pct := COALESCE(v_vehicle.soh, 95),
    p_noise_seed := abs(hashtextextended(COALESCE((SELECT random_seed::text FROM ottoq_sim_runs WHERE sim_run_id = p_sim_run_id), '42'), 42)),
    p_noise_salt := p_vehicle_id::text || ':' || twin.ottoq_sim_clock_salt(p_sim_run_id, v_clock));

  -- ═══════════ 0356: THE SHIELD SEES POWER BEGIN ═══════════
  -- Five block-enforcement rules declare charge_session_start -- EN.001 grid
  -- capacity, EN.002 stall power ceiling, EN.004 demand response, EN.005 grid
  -- event hardstop, HW.002 charger state -- and until this probe existed not one
  -- of them had ever been evaluated, because nothing probed here. This is the
  -- moment power actually begins, which makes it the gate rather than a forecast.
  --
  -- MEASURED, NOT ENFORCED: the probe records and does NOT refuse the session,
  -- even on would_block. CLAUDE.md 2.9a -- measured first, enforced after a
  -- flagship round. Promotion reads ottoq_shield_probe.would_block.
  --
  -- IT SITS BEFORE THE INSERT ON PURPOSE. EN.001 reads
  -- ottoq_depot_current_demand_kw(depot, now_ts); after the insert that sum
  -- already contains this session and the check double-counts its own load.
  --
  -- entity_id IS p_stall_id, NOT v_session_id: the session id is gen_random_uuid()
  -- and differs between determinism-pair arms, and ottoq_hash_rule_evaluations
  -- digests entity_id (0139's class, fifth instance). A stall is arm-stable.
  -- now_ts IS v_clock, the SIM clock: wall clock makes every charger read stale
  -- against HW.002's 90-second threshold and refuses the whole depot.
  -- Never allowed to abort the session.
  DECLARE
    v_shield_blocks INT := 0;
    v_shield_codes  TEXT[];
  BEGIN
    BEGIN
      PERFORM set_config('ottoq.sim_run_id', p_sim_run_id::text, true);
      SELECT count(*) FILTER (WHERE sp.would_block),
             array_agg(sp.rule_code) FILTER (WHERE sp.would_block)
        INTO v_shield_blocks, v_shield_codes
        FROM public.ottoq_shield_probe(
          p_action_context    := 'charge_session_start',
          p_entity_type       := 'stall',
          p_entity_id         := p_stall_id,
          p_context           := jsonb_build_object(
                                   'depot_id',     v_stall.depot_id::text,
                                   'stall_id',      p_stall_id::text,
                                   'charger_id',    v_charger.charger_id::text,
                                   'requested_kw',  LEAST(v_charger.max_kw, v_vehicle.inlet_max_kw),
                                   'now_ts',        v_clock::text)
                                 || twin.ottoq_sim_dc_managed_context(p_sim_run_id, v_clock, v_stall.stall_type::text),  -- 0729
          p_fleet_operator_id := v_vehicle.fleet_operator_id,
          p_depot_id          := v_stall.depot_id) sp;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'charge_session_start shield probe: %', SQLERRM;
      v_shield_blocks := 0;
    END;
    IF COALESCE(v_shield_blocks, 0) > 0 THEN
      PERFORM ottoq_record_event(
        p_actor_type := 'ottoq_engine', p_actor_id := 'twin_charge_orchestrator',
        p_event_type := 'ottoq.charge_start_refused',
        p_entity_type := 'stall', p_entity_id := p_stall_id,
        p_fleet_operator_id := v_vehicle.fleet_operator_id, p_depot_id := v_stall.depot_id,
        p_payload := jsonb_build_object(
          'vehicle_id', p_vehicle_id, 'charger_id', v_charger.charger_id,
          'blocking_rules', to_jsonb(v_shield_codes), 'block_count', v_shield_blocks,
          'requested_kw', LEAST(v_charger.max_kw, v_vehicle.inlet_max_kw),
          'enforced', (public.ottoq_policy_get(p_sim_run_id,
                          'shield_enforce_charge_session_start', 1) >= 1)),
        p_severity := 'critical', p_ingest_source := 'twin', p_data_source := 'twin',
        p_sim_run_id := p_sim_run_id);
      IF public.ottoq_policy_get(p_sim_run_id,
           'shield_enforce_charge_session_start', 1) >= 1 THEN
        RETURN NULL;
      END IF;
    END IF;
  END;
  -- 0733 (G448): under a shared DC pool a new fast charge's first reading is what the pool has spare for it, at most its
  -- own rate (dial dc_power_first_reading); off, the helper returns v_init_rate unchanged. Energy is not touched: the
  -- charge step meters each interval at the rate it computes then.
  v_init_rate := twin.ottoq_sim_dc_first_reading_kw(p_sim_run_id, v_clock, v_stall.stall_type::text, v_init_rate);
  INSERT INTO ocpp_sessions (
    id, depot_id, stall_id, vehicle_id, sim_run_id,
    charge_point_id, transaction_id, evse_id, connector_id,
    status, started_at, soc_start,
    max_rate_limit_kw, ambient_temp_c, id_token,
    last_meter_value, peak_power_kw, meter_values_count
  ) VALUES (
    v_session_id, v_stall.depot_id, p_stall_id, p_vehicle_id, p_sim_run_id,
    v_charger.ocpp_identifier,
    'TXN-' || to_char(v_clock AT TIME ZONE 'UTC', 'YYYYMMDDHH24MISS') || '-' || substr(v_session_id::text, 1, 8),
    1, 1,
    'active', v_clock, v_vehicle.current_soc,
    LEAST(v_charger.max_kw, v_vehicle.inlet_max_kw), v_ambient_temp,
    'TWIN-' || substr(v_vehicle.id::text, 1, 8),
    jsonb_build_object('at', v_clock, 'power_kw', ROUND(v_init_rate::numeric, 2),
      'soc_pct', ROUND(v_vehicle.current_soc::numeric, 1), 'battery_temp_c', ROUND(v_battery_temp::numeric, 1)),
    ROUND(v_init_rate::numeric, 2), 1
  );

  PERFORM ottoq_sim_emit_ocpp(v_session_id, v_charger.charger_id, p_vehicle_id, p_sim_run_id, v_clock,
    'cs_to_csms', 'StatusNotification', jsonb_build_object('connectorId', 1, 'connectorStatus', 'Occupied', 'evseId', 1, 'timestamp', v_clock));
  -- 0694 (G412): what an OCPP 2.0.1 station sends. Authorize carries the token and nothing else; the transaction opens
  -- as TransactionEvent Started (seqNo 0) with the register at zero and the car's charge; the car's target and the air
  -- ride in customData
  PERFORM ottoq_sim_emit_ocpp(v_session_id, v_charger.charger_id, p_vehicle_id, p_sim_run_id, v_clock,
    'cs_to_csms', 'Authorize', jsonb_build_object('idToken', jsonb_build_object('idToken', 'TWIN-' || substr(p_vehicle_id::text, 1, 8), 'type', 'ISO14443')));
  PERFORM ottoq_sim_emit_ocpp(v_session_id, v_charger.charger_id, p_vehicle_id, p_sim_run_id, v_clock,
    'cs_to_csms', 'TransactionEvent', twin.ottoq_ocpp201_tx_event(
      'Started', 'CablePluggedIn', 0, (SELECT s.transaction_id FROM ocpp_sessions s WHERE s.id = v_session_id),
      v_clock, 'Charging',
      twin.ottoq_ocpp201_samples(ARRAY[
        twin.ottoq_ocpp201_sample('Energy.Active.Import.Register', 0, 'kWh'),
        twin.ottoq_ocpp201_sample('SoC', v_vehicle.current_soc, 'Percent')]),
      jsonb_build_object('target_soc_pct', v_target_soc, 'ambient_temp_c', v_ambient_temp),
      'TWIN-' || substr(p_vehicle_id::text, 1, 8)));

  UPDATE ottoq_ocpp_chargers SET station_state = 'Occupied', station_state_changed_at = v_clock WHERE charger_id = v_charger.charger_id;
  UPDATE stalls SET current_vehicle_id = p_vehicle_id WHERE id = p_stall_id;
  UPDATE vehicles SET current_state = v_state, current_stall_id = p_stall_id, current_depot_id = v_stall.depot_id, last_state_change = v_clock WHERE id = p_vehicle_id;

  -- ═══════════ THE ARM REACHES IN ═══════════
  -- StartTransaction is not the plug going in any more than StopTransaction was
  -- it coming out. On a robot-served DCFC stall the arm now has to unstow,
  -- approach, align, insert and latch before this car is connected, and OTTO-Q
  -- must refuse to move it for that whole window. Opening the cycle also writes
  -- the tether, so there is no instant where the robot is moving and the car
  -- reads movable. Never allowed to abort the session.
  -- ...BUT NOT FOR A CAR THAT NEEDS NOTHING. A session opened for a vehicle
  -- already at its target completes on the next tick with 0.00 kWh delivered,
  -- and the demate behind it abandons this mate mid-approach. The live run of
  -- 2026-08-13 produced 25 demates against 20 latches that way -- five
  -- disconnects from a connector that was never inserted. The arm only reaches
  -- when there is charge to move.
  IF v_stall.stall_type = 'dcfc'::stall_type
     AND COALESCE(v_vehicle.current_soc, 0) < v_target_soc THEN
    BEGIN
      PERFORM twin.ottoq_arm_begin_cycle(p_sim_run_id, p_vehicle_id, p_stall_id,
                                         v_session_id, 'mate', v_clock);
    EXCEPTION WHEN OTHERS THEN RAISE WARNING 'arm mate begin: %', SQLERRM;
    END;
  END IF;

  PERFORM ottoq_record_event(
    p_actor_type := 'ottoq_engine', p_actor_id := 'twin_charge_orchestrator',
    p_event_type := 'charge.session_started', p_entity_type := 'ocpp_session', p_entity_id := v_session_id,
    p_fleet_operator_id := v_vehicle.fleet_operator_id, p_depot_id := v_stall.depot_id,
    p_payload := jsonb_build_object('vehicle_display_name', v_vehicle.display_name, 'charger', v_charger.ocpp_identifier,
      'charge_kind', v_charge_kind, 'soc_start', v_vehicle.current_soc, 'soc_target', v_target_soc,
      'max_rate_kw', LEAST(v_charger.max_kw, v_vehicle.inlet_max_kw), 'initial_rate_kw', ROUND(v_init_rate::numeric,1),
      'ambient_temp_c', v_ambient_temp, 'battery_temp_c', v_battery_temp, 'battery_soh_pct', v_vehicle.soh),
    p_severity := 'info', p_ingest_source := 'twin', p_data_source := 'twin', p_sim_run_id := p_sim_run_id);

  -- T3 RENDER CONTRACT: the taxi TO this charger. Emitted with the origin the
  -- vehicle still holds, so the renderer can interpolate the drive instead of
  -- teleporting the car into the stall. Never allowed to abort the session.
  BEGIN
    PERFORM ottoq_itin_travel_leg(p_sim_run_id, v_stall.depot_id, p_vehicle_id,
                                  v_vehicle.current_stall_id, p_stall_id, v_clock,
                                  'taxi_to_charger', 'twin_charge_orchestrator');
  EXCEPTION WHEN OTHERS THEN RAISE WARNING 'travel leg (charge): %', SQLERRM;
  END;

  PERFORM ottoq_itin_leg_open(p_sim_run_id, v_stall.depot_id, p_vehicle_id, v_clock,
    CASE WHEN v_charger.max_kw > 50 THEN 'charge_dcfc' ELSE 'charge_l2' END,
    p_stall_id,
    v_clock + (ottoq_estimate_charge_minutes(
      v_vehicle.current_soc, v_target_soc, v_charger.max_kw, v_vehicle.inlet_max_kw,
      v_vehicle.battery_capacity_kwh, v_battery_temp, COALESCE(v_vehicle.soh, 95),
      GREATEST(0.2, ottoq_profile_rate_mult(p_sim_run_id, 'charge_time'))) || ' minutes')::interval,
    jsonb_build_object('kind', 'charge_curve', 'start_soc', v_vehicle.current_soc, 'target_soc', v_target_soc,
      'charger_kw', v_charger.max_kw, 'vehicle_kw', v_vehicle.inlet_max_kw,
      'pack_kwh', v_vehicle.battery_capacity_kwh, 'battery_temp_c', ROUND(v_battery_temp::numeric, 1),
      'soh_pct', COALESCE(v_vehicle.soh, 95)),
    'twin_charge_orchestrator');

  RETURN v_session_id;
END;
$function$;
-- @@ function twin.ottoq_sim_stop_charge_session(p_session_id uuid, p_reason text, p_sim_clock_now timestamp with time zone, p_fault_message text, p_sim_run_id uuid)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_stop_charge_session(p_session_id uuid, p_reason text DEFAULT 'completed'::text, p_sim_clock_now timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fault_message text DEFAULT NULL::text, p_sim_run_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_session ocpp_sessions%ROWTYPE;
  v_clock TIMESTAMPTZ;
  v_duration_s NUMERIC; v_avg_power NUMERIC; v_vehicle RECORD;
  v_new_status ocpp_session_status;
  v_requeue boolean := false; v_temp_hold jsonb; v_temp_stall uuid; v_fault_depot uuid;
  v_repair_min numeric;
  -- 0011-TETHER: DCFC stalls are robot-served. StopTransaction is NOT the unplug.
  v_is_dcfc boolean := false; v_tether boolean := false;
  v_demate_s numeric := 11.5;   -- robot disconnect time, one named knob (see below)
BEGIN
  v_clock := COALESCE(p_sim_clock_now, NOW());
  SELECT * INTO v_session FROM ocpp_sessions WHERE id = p_session_id;
  IF NOT FOUND THEN RETURN; END IF;
  IF v_session.status <> 'active' THEN
    -- Session already closed elsewhere. Do NOT repeat the accounting, but DO
    -- make sure the physical resources were actually released (this is the
    -- path that used to strand chargers as Occupied on empty stalls).
    UPDATE ottoq_ocpp_chargers c
       SET station_state = 'Available', station_state_changed_at = v_clock
     WHERE c.charger_id IN (SELECT ocpp_charger_id FROM stalls WHERE id = v_session.stall_id)
       AND c.station_state = 'Occupied'
       AND NOT EXISTS (SELECT 1 FROM ocpp_sessions s2
                        WHERE s2.stall_id = v_session.stall_id AND s2.status = 'active');
    -- 0011-TETHER: a tethered car IS the "vehicle that does not point back" -- the robot
    -- is still holding it and vehicles.current_stall_id is already NULL. Without this
    -- guard the strand-cleaner below would hand the plug away mid-demate. The tether
    -- RECORD (not a clock) is the test: ottoq_release_expired_tethers is the single
    -- releaser and it clears the record and the stall together, so deferring to it
    -- cannot strand the stall.
    UPDATE stalls s SET current_vehicle_id = NULL
     WHERE s.id = v_session.stall_id
       AND s.current_vehicle_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM vehicles v
                        WHERE v.id = s.current_vehicle_id AND v.current_stall_id = s.id)
       AND NOT EXISTS (SELECT 1 FROM vehicles tv
                        WHERE tv.id = s.current_vehicle_id
                          AND tv.robotic_tether_stall_id = s.id
                          AND tv.robotic_tether_until IS NOT NULL);
    RETURN;
  END IF;

  v_duration_s := EXTRACT(EPOCH FROM (v_clock - v_session.started_at));
  v_avg_power := CASE WHEN v_duration_s > 0 THEN
    (v_session.energy_delivered_kwh * 3600.0 / v_duration_s) ELSE 0 END;
  SELECT id, fleet_operator_id, current_soc, display_name, COALESCE(target_soc, public.ottoq_default_target_soc()) AS target_soc
    INTO v_vehicle FROM vehicles WHERE id = v_session.vehicle_id;

  v_new_status := (CASE
    WHEN p_reason = 'completed' THEN 'completed'
    WHEN p_reason LIKE 'fault%' THEN 'faulted'
    ELSE 'cancelled' END)::ocpp_session_status;

  UPDATE ocpp_sessions SET
    status = v_new_status, ended_at = v_clock, soc_end = v_vehicle.current_soc,
    avg_power_kw = v_avg_power, stopped_reason = p_reason,
    last_fault_message = p_fault_message, updated_at = NOW()
   WHERE id = p_session_id;

  -- 0694 (G412): the transaction ends as an OCPP 2.0.1 station ends it, TransactionEvent Ended, with the register, the
  -- car's charge, the time it charged, and a trigger and stopped reason from the spec's lists; the twin's own reason
  -- rides in customData
  PERFORM ottoq_sim_emit_ocpp(p_session_id, NULL, v_session.vehicle_id, p_sim_run_id, v_clock,
    'cs_to_csms', 'TransactionEvent', twin.ottoq_ocpp201_tx_event(
      'Ended', (twin.ottoq_ocpp201_ended_reasons(p_reason)).trigger_reason, twin.ottoq_ocpp201_next_seq(p_session_id),
      v_session.transaction_id, v_clock, 'Idle',
      twin.ottoq_ocpp201_samples(ARRAY[
        twin.ottoq_ocpp201_sample('Energy.Active.Import.Register', v_session.energy_delivered_kwh, 'kWh'),
        twin.ottoq_ocpp201_sample('SoC', v_vehicle.current_soc, 'Percent')]),
      jsonb_build_object('twin_reason', p_reason, 'duration_seconds', v_duration_s),
      NULL, (twin.ottoq_ocpp201_ended_reasons(p_reason)).stopped_reason, round(v_duration_s)::int));
  PERFORM ottoq_sim_emit_ocpp(p_session_id, NULL, v_session.vehicle_id, p_sim_run_id, v_clock,
    'cs_to_csms', 'StatusNotification', jsonb_build_object(
      'connectorId',1,'connectorStatus','Available','evseId',1,'timestamp',v_clock));

  -- feed-agent: the fault card dealt for this session carries the drawn
  -- repair duration (fitted repair_days grid x staffed-depot x fault mode)
  IF p_reason LIKE 'fault%' AND p_sim_run_id IS NOT NULL THEN
    SELECT (meta->>'repair_minutes')::numeric INTO v_repair_min
      FROM ottoq_variability_cards
     WHERE sim_run_id = p_sim_run_id AND var_key = 'charger_fault'
       AND scope_instance = p_session_id::text
       AND bucket_key = 'session:' || p_session_id::text;
  END IF;

  UPDATE ottoq_ocpp_chargers c SET
    -- 0550 (G281): only a repair clears a fault. A stop that is not a fault leaves a Faulted charger Faulted, and
    -- leaves its stamp alone, because twin.ottoq_sim_recover_chargers reads the stamp as the start of the repair.
    -- Before 0550 a car that charged on through an injected fault put its charger back in service when it finished.
    station_state = CASE WHEN p_reason LIKE 'fault%' THEN 'Faulted'
                         WHEN c.station_state = 'Faulted' THEN 'Faulted' ELSE 'Available' END,
    station_state_changed_at = CASE WHEN p_reason NOT LIKE 'fault%' AND c.station_state = 'Faulted'
                                    THEN c.station_state_changed_at ELSE v_clock END,
    last_fault_code = CASE WHEN p_reason LIKE 'fault%' THEN p_reason ELSE c.last_fault_code END,
    last_fault_at = CASE WHEN p_reason LIKE 'fault%' THEN v_clock ELSE c.last_fault_at END,
    last_fault_payload = CASE WHEN p_reason LIKE 'fault%' THEN
      jsonb_build_object('reason',p_reason,'message',p_fault_message,'session_id',p_session_id,
                         'repair_minutes', v_repair_min)
      ELSE c.last_fault_payload END
   WHERE charger_id IN (SELECT ocpp_charger_id FROM stalls WHERE id = v_session.stall_id);

  -- S3a AUTO RE-ROUTE: fault interrupted the charge with the vehicle still under target →
  -- re-queue so OTTO-Q reassigns a healthy charger; otherwise proceed to disposition.
  -- 0011-TETHER moved this ABOVE the stall release, because the release now depends on it.
  -- Nothing about the expression itself changed.
  v_requeue := (p_reason LIKE 'fault%' AND v_vehicle.current_soc < v_vehicle.target_soc - 5);

  -- ═══════════════════ 0011-TETHER: STOPTRANSACTION IS NOT THE UNPLUG ═══════════════════
  -- DCFC stalls are served by the OTTO-CHARGE ARM. When the session closes the car is
  -- still physically on the end of a cable and the robot needs 11.5 s to demate
  -- (unlatch 2.0 + extract 3.0 + retract 6.5, from armStateMachine.ts in
  -- ottoyarddepot-sim -- keep the two in step). So the plug is NOT handed to the next
  -- vehicle here; ottoq_release_expired_tethers frees it once the window passes.
  --
  -- WHY THE REQUEUE PATH IS EXCLUDED: on a fault-with-low-SoC the block below physically
  -- relocates the car to a booked temp stall. Holding the DCFC stall as well would leave
  -- one vehicle occupying two stalls, which is exactly what the overlap guard exists to
  -- prevent. That path therefore keeps releasing the stall, unchanged from today.
  SELECT (s.stall_type = 'dcfc'::stall_type) INTO v_is_dcfc
    FROM stalls s WHERE s.id = v_session.stall_id;
  -- ...AND ONLY IF THE ARM ACTUALLY LATCHED. A session that opened no mate --
  -- because the car was already at target -- has nothing to disconnect from, and
  -- a demate cycle here would be the arm withdrawing a plug it never inserted.
  -- v_tether governs the stall release, the tether write AND the demate cycle
  -- below, so this one conjunct covers all three: a car that was never connected
  -- is released to move immediately, which is exactly right.
  v_tether := COALESCE(v_is_dcfc, false) AND NOT v_requeue
              AND EXISTS (SELECT 1 FROM twin.arm_cycles c
                           WHERE c.session_id = v_session.id
                             AND c.direction = 'mate'
                             AND c.outcome = 'latched');

  -- ONE KNOB, NOT TWO LITERALS. The disconnect time was hardcoded here as
  -- interval '11.5 seconds', duplicating the value in armStateMachine.ts
  -- (unlatch 2.0 + extract 3.0 + retract 6.5) in the ottoyarddepot-sim repo with nothing
  -- linking them -- retune the arm and the orchestration silently disagrees about how
  -- long the car is mated. It is now the named policy 'robotic_demate_seconds',
  -- overridable per run or per depot, with 11.5 as the default so behaviour is
  -- unchanged until someone deliberately changes it. The renderer remains the physical
  -- source of truth; this is the value OTTO-Q reserves the plug for.
  v_demate_s := GREATEST(0, COALESCE(
    (public.ottoq_arm_timings(p_sim_run_id)->>'demate_seconds')::numeric, 11.5));

  BEGIN
    -- 0489 (G224): the session's own stall, not a lookup that can tie across two bookings.
    PERFORM 1 FROM public.ottoq_probe_task_completion_at(
      p_sim_run_id := p_sim_run_id,
      p_depot_id   := (SELECT depot_id FROM stalls WHERE id = v_session.stall_id),
      p_vehicle_id := v_session.vehicle_id,
      p_svc        := 'charge',
      p_started_at := v_session.started_at,
      p_ends_at    := v_clock,
      p_stall_id   := v_session.stall_id);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'ottoq_sim_stop_charge_session: task_completion probe FAILED SAFELY %: %',
      SQLSTATE, SQLERRM;
  END;
  IF NOT v_tether THEN
    UPDATE stalls SET current_vehicle_id = NULL WHERE id = v_session.stall_id;
  END IF;

  -- The fault-requeue path physically relocates this car to a temp stall. Any
  -- charge lease it is holding points at the DCFC stall it is leaving, and a
  -- stale lease would both freeze the car and misreport which stall the robot
  -- has. Drop it, and close whatever cycle was open on that plinth.
  IF v_requeue THEN
    -- ═══════ THROUGH THE FRONT DOOR, NOT AROUND IT ═══════
    -- This is the founder's malfunction case exactly: the charger has died under
    -- a car that still needs charge, so the arm must let go and the car must be
    -- relocated to a temporary stall. It used to clear the tether inline and mark
    -- the cycle 'abandoned' -- which says the world stopped underneath it rather
    -- than that the charger failed and the arm was ordered to release. That
    -- charged the arm's reliability record with somebody else's fault, emitted no
    -- safety event, and never set the disposition flag a supervisor needs.
    --
    -- Must stay AHEAD of the relocation below: since the arm interlock trigger
    -- exists, moving the car with a live tether would be refused outright.
    PERFORM twin.ottoq_arm_emergency_release(
      v_session.vehicle_id,
      'charger fault: ' || COALESCE(NULLIF(p_fault_message, ''), p_reason, 'unspecified'),
      'twin_charger_fault', p_sim_run_id, v_clock);

    -- Belt, for a cycle left open on this plinth with no tether behind it. Scoped
    -- to THIS vehicle: the old predicate was stall-only and would have abandoned
    -- another car's cycle on the same plinth.
    UPDATE twin.arm_cycles SET ended_at = v_clock, outcome = COALESCE(outcome, 'abandoned')
     WHERE stall_id = v_session.stall_id AND vehicle_id = v_session.vehicle_id
       AND ended_at IS NULL;
  END IF;
  IF v_requeue THEN
    -- DOCTRINE (Chase 2026-07-28): a vehicle is NEVER queued at the gate. A charger
      -- dying mid-charge is temp-staging case 3(a): give it a booked temp stall and let
      -- OTTO-Q re-route it to a healthy charger from there.
      SELECT s.depot_id INTO v_fault_depot FROM stalls s WHERE s.id = v_session.stall_id;
      v_temp_hold := ottoq_book_hold_stall(p_sim_run_id, v_fault_depot, v_session.vehicle_id,
                                           v_clock, v_clock + interval '30 minutes');
      IF COALESCE((v_temp_hold->>'booked')::boolean, false) THEN
        SELECT b.stall_id INTO v_temp_stall FROM ottoq_stall_bookings b
         WHERE b.booking_id = (v_temp_hold->>'booking_id')::uuid;
        UPDATE vehicles SET current_state = 'staged_awaiting_service'::vehicle_state,
               current_stall_id = v_temp_stall, last_state_change = v_clock,
               -- 0474 (G209): a step, so the deploy gate sees the car and routes it by its open work
               config = jsonb_set(COALESCE(config, '{}'::jsonb), '{svc_step}', to_jsonb('need_deploy'::text))
         WHERE id = v_session.vehicle_id;
        UPDATE stalls SET current_vehicle_id = v_session.vehicle_id, status = 'occupied'
         WHERE id = v_temp_stall;
      ELSE
        -- Staging genuinely full: still not the gate. Hold state without a stall and
        -- let the next tick place it; this is the only degraded path and it is visible.
        UPDATE vehicles SET current_state = 'staged_awaiting_service'::vehicle_state,
               current_stall_id = NULL, last_state_change = v_clock,
               -- 0474 (G209): as above
               config = jsonb_set(COALESCE(config, '{}'::jsonb), '{svc_step}', to_jsonb('need_deploy'::text))
         WHERE id = v_session.vehicle_id;
      END IF;
  ELSE
    -- 0011-TETHER: the tether is written in the SAME statement that nulls current_stall_id.
    -- That ordering is load-bearing: trg_sync_stall_occupancy is an AFTER UPDATE trigger on
    -- vehicles that frees the old stall whenever current_stall_id changes, and it reads NEW.
    -- Setting the tether in a later statement would let the trigger release the plug first.
    UPDATE vehicles SET current_state = 'charge_complete_holding'::vehicle_state,
                        -- KEEP THE STALL WHILE THE ARM UNLATCHES. Nulling this here is what
                        -- deadlocked the world tick against ottoq_arm_interlock_guard. The car
                        -- is physically still in the stall until the demate tether expires, and
                        -- ottoq_release_expired_tethers clears both the stall and this pointer
                        -- when it does. Because this no longer CHANGES current_stall_id on the
                        -- tethered path, trg_sync_stall_occupancy does not fire, so the original
                        -- 0011-TETHER hazard (the plug being freed before the tether is written)
                        -- cannot occur either.
                        current_stall_id = CASE WHEN v_tether
                          THEN v_session.stall_id ELSE NULL END, last_state_change = v_clock,
                        robotic_tether_until = CASE WHEN v_tether
                          THEN v_clock + make_interval(secs => v_demate_s) ELSE robotic_tether_until END,
                        robotic_tether_stall_id = CASE WHEN v_tether
                          THEN v_session.stall_id ELSE robotic_tether_stall_id END,
                        robotic_tether_direction = CASE WHEN v_tether
                          THEN 'demate' ELSE robotic_tether_direction END,
                        robotic_tether_phase = CASE WHEN v_tether
                          THEN 'unlatch' ELSE robotic_tether_phase END
     WHERE id = v_session.vehicle_id;
  END IF;

  -- ═══════════ THE ARM LETS GO ═══════════
  -- The demate window already existed as a deadline; this gives it a lifecycle
  -- with the same shape as the inbound one, so the cockpit and OTTO-Q read the
  -- arm the same way in both directions. Never allowed to abort the close.
  IF v_tether THEN
    BEGIN
      PERFORM twin.ottoq_arm_begin_cycle(p_sim_run_id, v_session.vehicle_id,
                                         v_session.stall_id, p_session_id, 'demate', v_clock);
    EXCEPTION WHEN OTHERS THEN RAISE WARNING 'arm demate begin: %', SQLERRM;
    END;
  END IF;

  -- A2-B2: close the charge leg; deviation_s = actual vs physics-planned end.
  PERFORM ottoq_itin_leg_close(p_sim_run_id, v_session.vehicle_id,
    ARRAY['charge_dcfc','charge_l2'], v_clock, 'done');

  -- 0484 (G217): the session is over, so this charger is no longer this car's. Its charge booking ends when the plug
  -- is free (now, or once the arm has demated a latched DCFC) and its reservation goes with it. Both used to run to
  -- their own expiry, so a car that had finished, or had been moved off a faulted charger, held it from staging.
  UPDATE ottoq_stall_bookings b
     SET state          = CASE WHEN v_new_status::text <> 'completed'
                                    AND ottoq.ottoq_occupancy_cut_short(
                                      EXTRACT(epoch FROM (upper(b.during) - lower(b.during)))::numeric,
                                      EXTRACT(epoch FROM (LEAST(upper(b.during), f.free_at) - lower(b.during)))::numeric)
                               THEN 'interrupted' ELSE 'done' END,
         released_at    = f.free_at,
         release_reason = 'charge_session_' || v_new_status::text,
         during         = tstzrange(lower(b.during),
                                    GREATEST(lower(b.during) + interval '1 second', LEAST(upper(b.during), f.free_at)), '[)')
    FROM (SELECT v_clock + CASE WHEN v_tether THEN make_interval(secs => v_demate_s)
                                ELSE interval '0 seconds' END AS free_at) f
   WHERE b.sim_run_id = p_sim_run_id
     AND b.stall_id   = v_session.stall_id
     AND b.vehicle_id = v_session.vehicle_id
     AND b.purpose IN ('charge_dcfc','charge_l2')
     AND b.state = 'active'
     AND lower(b.during) <= v_clock;
  UPDATE stalls
     SET reserved_by = NULL, reserved_at = NULL, reservation_expires_at = NULL
   WHERE id = v_session.stall_id AND reserved_by = v_session.vehicle_id;

  PERFORM ottoq_record_event(
    p_actor_type := 'ottoq_engine', p_actor_id := 'twin_charge_orchestrator',
    p_event_type := CASE WHEN p_reason LIKE 'fault%' THEN 'charge.session_faulted'
                                                     ELSE 'charge.session_completed' END,
    p_entity_type := 'ocpp_session', p_entity_id := p_session_id,
    p_fleet_operator_id := v_vehicle.fleet_operator_id, p_depot_id := v_session.depot_id,
    p_payload := jsonb_build_object('reason',p_reason,'fault_message',p_fault_message,
      'vehicle',v_vehicle.display_name,'soc_start',v_session.soc_start,
      'soc_end',v_vehicle.current_soc,'energy_kwh',v_session.energy_delivered_kwh,
      'duration_s',v_duration_s,'avg_power_kw',ROUND(v_avg_power::numeric,2),
      'repair_minutes', v_repair_min,
      'auto_rerouted', v_requeue),
    p_severity := CASE WHEN p_reason LIKE 'fault%' THEN 'warning' ELSE 'info' END,
    p_ingest_source := 'twin', p_data_source := 'twin', p_sim_run_id := p_sim_run_id);
END;
$function$;
-- @@ function twin.ottoq_sim_advance_charge_sessions(p_sim_run_id uuid, p_sim_clock_now timestamp with time zone)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_advance_charge_sessions(p_sim_run_id uuid, p_sim_clock_now timestamp with time zone)
 RETURNS TABLE(out_session_id uuid, out_action text, out_new_soc numeric, out_charge_rate_kw numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_session       RECORD;
  v_vehicle       RECORD;
  v_charger       RECORD;
  v_elapsed_min   NUMERIC;
  v_rate_kw       NUMERIC;
  v_kwh_delta     NUMERIC;
  v_new_soc       NUMERIC;
  v_target_soc    NUMERIC;
  v_battery_temp  NUMERIC;
  v_ambient_temp  NUMERIC;
  v_fault_mode    TEXT;
  v_fault_card    JSONB;
  v_last_update   TIMESTAMPTZ;
  v_seed          BIGINT;
  v_share_on      BOOLEAN := false;            -- 0726
  v_share         JSONB := '{}'::jsonb;        -- 0726
BEGIN
  v_seed := abs(hashtextextended(COALESCE((SELECT random_seed::text FROM ottoq_sim_runs WHERE sim_run_id = p_sim_run_id), '42'), 42));

  -- VEHICLE-FIRST DOCTRINE: charging is NEVER held back. Every active session charges
  -- at its full physical rate; peak shaving is the BESS's job (see ottoq_energy_orchestrate).

  -- ═══════ REAP THE ORPHANS FIRST ═══════
  -- Scoping the loop below to this run is correct, and on its own it would
  -- strand every active session whose run has ended: nothing else closes them,
  -- and they would hold their chargers Occupied forever. The unfiltered loop was
  -- accidentally the only reaper.
  --
  -- TERMINAL STATES ARE ENUMERATED. The vocabulary is initializing / running /
  -- paused / completed / failed / aborted; reaping anything merely "not running"
  -- would cancel the live sessions of a PAUSED run, so an operator pausing the
  -- cockpit would return to an empty depot. An unrecognised future status is
  -- left alone rather than destroyed.
  --
  -- Closed by direct UPDATE rather than through ottoq_sim_stop_charge_session,
  -- which is PHYSICS — it writes a robotic tether, opens a demate arm cycle and
  -- emits StopTransaction. A session whose world has ended is not demating, it
  -- is being reaped; dressing that up as a physical event is how one run's arm
  -- records came to describe another run's vehicles.
  WITH orphan AS (
    SELECT s.id, s.stall_id
      FROM ocpp_sessions s
      LEFT JOIN ottoq_sim_runs r ON r.sim_run_id = s.sim_run_id
     WHERE s.status = 'active'
       AND s.id_token LIKE 'TWIN-%'
       AND s.sim_run_id IS DISTINCT FROM p_sim_run_id
       AND (r.sim_run_id IS NULL
            OR r.status IN ('completed', 'failed', 'aborted'))
  ), closed AS (
    UPDATE ocpp_sessions s
       SET status = 'cancelled'::ocpp_session_status,
           ended_at = COALESCE(s.ended_at, p_sim_clock_now),
           stopped_reason = 'orphaned_run',
           updated_at = NOW()
      FROM orphan o WHERE s.id = o.id
    RETURNING s.stall_id
  )
  UPDATE ottoq_ocpp_chargers c
     SET station_state = 'Available', station_state_changed_at = p_sim_clock_now
   WHERE c.charger_id IN (SELECT ocpp_charger_id FROM stalls WHERE id IN (SELECT stall_id FROM closed))
     AND c.station_state = 'Occupied';

  -- 0726: A SHARED DC POWER POOL, WHEN THE TEST DAY BUILDS ONE (dial dc_power_sharing, default 0). The cabinets of a
  -- shared-cabinet site divide their power between the cars on them; the doctrine above is unchanged by it, because a
  -- share is the hardware's limit, never a decision about a car, and a shared charge still runs to its target. Off, this
  -- reads one dial and nothing else changes.
  v_share_on := COALESCE(public.ottoq_policy_get(p_sim_run_id, 'dc_power_sharing', 0), 0) >= 1;
  IF v_share_on THEN
    BEGIN
      v_share := twin.ottoq_sim_dc_pool_plan(p_sim_run_id, p_sim_clock_now, v_seed);
      IF COALESCE((v_share->>'binds')::boolean, false) THEN
        PERFORM ottoq_record_event(
          p_actor_type:='ottoq_engine', p_actor_id:='twin_dc_pool',
          p_event_type:='twin.dc_pool_shared', p_entity_type:='depot',
          p_entity_id:=(SELECT r.depot_id FROM ottoq_sim_runs r WHERE r.sim_run_id = p_sim_run_id),
          p_payload:=v_share - 'shares',
          p_severity:='info', p_ingest_source:='twin', p_data_source:='twin', p_sim_run_id:=p_sim_run_id);
      END IF;
      v_share := COALESCE(v_share->'shares', '{}'::jsonb);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '0726 dc pool plan: % %', SQLSTATE, SQLERRM;
      v_share := '{}'::jsonb;
    END;
  END IF;

  FOR v_session IN
    SELECT s.*, st.ocpp_charger_id, st.stall_type
      FROM ocpp_sessions s
      JOIN stalls st ON st.id = s.stall_id
     WHERE s.status = 'active'
       AND s.id_token LIKE 'TWIN-%'
       -- THIS RUN'S SESSIONS ONLY. Everything below uses p_sim_run_id for the
       -- seed, the variability profile, the fault deck and every recorded event;
       -- selecting other runs' sessions here made all of that describe vehicles
       -- this run never touched, and advanced them against a clock that could be
       -- days away from their own.
       AND s.sim_run_id IS NOT DISTINCT FROM p_sim_run_id
     ORDER BY s.vehicle_id   -- 0050: run-stable cursor order (fleet/stall identity, never heap order)
  LOOP
    SELECT v.current_soc, v.battery_capacity_kwh, v.inlet_max_kw, v.fleet_operator_id,
           v.target_soc, (v.config->>'battery_soh_pct')::NUMERIC AS soh, v.display_name,
           (v.config->>'charge_curve_scalar')::NUMERIC AS curve_scalar
      INTO v_vehicle FROM vehicles v WHERE id = v_session.vehicle_id;

    SELECT max_kw, ocpp_identifier INTO v_charger
      FROM ottoq_ocpp_chargers WHERE charger_id = v_session.ocpp_charger_id;

    v_last_update := COALESCE((v_session.last_meter_value->>'at')::timestamptz, v_session.started_at);
    v_elapsed_min := EXTRACT(EPOCH FROM (p_sim_clock_now - v_last_update)) / 60.0;
    IF v_elapsed_min <= 0 THEN CONTINUE; END IF;
    v_elapsed_min := LEAST(v_elapsed_min, 90);

    v_target_soc := LEAST(COALESCE(v_vehicle.target_soc, public.ottoq_default_target_soc()), public.ottoq_target_soc_cap(v_session.stall_type::TEXT, v_session.started_at, p_sim_run_id));
    v_ambient_temp := COALESCE(v_session.ambient_temp_c, 22);
    v_battery_temp := v_ambient_temp + 5
      + ottoq_sim_seeded_random(v_seed, 'btemp:' || v_session.vehicle_id::text || ':' || twin.ottoq_sim_clock_salt(p_sim_run_id, v_session.started_at)) * 8
      + LEAST(15, EXTRACT(EPOCH FROM (p_sim_clock_now - v_session.started_at)) / 600.0 * 5);

    v_rate_kw := ottoq_sim_compute_charge_rate(
      p_soc_pct := v_vehicle.current_soc, p_battery_temp_c := v_battery_temp,
      p_ambient_temp_c := v_ambient_temp, p_charger_max_kw := v_charger.max_kw,
      p_vehicle_max_kw := v_vehicle.inlet_max_kw, p_battery_capacity_kwh := v_vehicle.battery_capacity_kwh,
      p_battery_soh_pct := COALESCE(v_vehicle.soh, 95), p_noise_seed := v_seed,
      p_noise_salt := v_session.vehicle_id::text || ':' || twin.ottoq_sim_clock_salt(p_sim_run_id, v_session.started_at) || ':' || twin.ottoq_sim_clock_salt(p_sim_run_id, p_sim_clock_now));

    -- charge_time variability only (calibrated platform curve); NO energy throttle.
    v_rate_kw := v_rate_kw / GREATEST(0.2, ottoq_profile_rate_mult(p_sim_run_id, 'charge_time'));
    -- per-vehicle charge-curve scalar (condition card drawn at run boot)
    v_rate_kw := v_rate_kw * COALESCE(v_vehicle.curve_scalar, 1.0);
    -- 0726: under a shared DC pool a fast charge draws no more than its share this tick; its target is unchanged
    IF v_share_on AND v_session.stall_type::text = 'dcfc' AND v_share ? v_session.id::text THEN
      v_rate_kw := LEAST(v_rate_kw, (v_share->>v_session.id::text)::numeric);
    END IF;

    v_kwh_delta := v_rate_kw * (v_elapsed_min / 60.0);

    -- ═══════ THE PACK CANNOT TAKE MORE THAN IT HAS ROOM FOR ═══════
    -- Without this, the full window is metered at the full rate and the SoC
    -- derivation below silently discards everything past target: 1407.8 kWh of
    -- 3346.8 kWh metered across the first 68 sessions, 42%, worst case a 90 kWh
    -- pack billed 136.8 kWh in one 30-minute tick.
    --
    -- Bounded on CUMULATIVE energy since soc_start, which is the exact quantity
    -- the SoC expression below integrates, so the two agree by construction and
    -- its LEAST(v_target_soc, ...) becomes a guard that can no longer bind.
    -- A car already at or above target gets a bound of 0 and meters nothing,
    -- which is the "already full" case closing itself.
    IF COALESCE(v_vehicle.battery_capacity_kwh, 0) > 0 THEN
      v_kwh_delta := LEAST(
        v_kwh_delta,
        GREATEST(0,
          ((v_target_soc - COALESCE(v_session.soc_start, v_vehicle.current_soc, 0)) / 100.0)
            * v_vehicle.battery_capacity_kwh
          - COALESCE(v_session.energy_delivered_kwh, 0)));
    END IF;

    -- ═══════════ SoC IS DERIVED FROM CUMULATIVE ENERGY, NOT INCREMENTED ═══════════
    -- THE DEFECT. This read `v_vehicle.current_soc + (v_kwh_delta / capacity) * 100`,
    -- i.e. it incremented the value STORED on the vehicle. public.vehicles.current_soc
    -- is an INTEGER column, so ROUND(38.17, 1) was written back as 38, and the next tick
    -- read 38 and added the same fraction again. Any session whose per-tick gain was
    -- under half a point could never move at all.
    -- MEASURED on run 128c12f6, three live DCFC sessions at an ~8 s tick:
    --   DCFC-03  106 kW / 135 kWh -> 0.175 pts/tick -> frozen at 46% (15.4 kWh absorbed)
    --   DCFC-09   68 kW /  90 kWh -> 0.167 pts/tick -> frozen at 38% (11.7 kWh absorbed)
    --   DCFC-08  170 kW /  90 kWh -> 0.42  pts/tick -> moving, and losing ~40% of every
    --                                                  tick's energy to the same rounding
    -- Because the charge curve TAPERS, every session eventually falls under the
    -- threshold and sticks. No vehicle could ever reach target, so no charge could ever
    -- complete, so the depot could never turn a vehicle around.
    --
    -- THE FIX. Derive SoC from the session's cumulative delivered energy against
    -- soc_start. The cumulative total is monotonic, so it crosses each whole point no
    -- matter how small the per-tick slice is, and no energy is lost to rounding. Storing
    -- a whole number is fine; ACCUMULATING in one was not.
    -- Falls back to the incremental form if capacity is missing, so a bad row cannot
    -- turn this into a division error mid-tick.
    IF COALESCE(v_vehicle.battery_capacity_kwh, 0) > 0 THEN
      -- Floored at the battery's existing charge: a charge session may raise SoC
      -- or leave it alone, never lower it. LEAST still prevents overshoot.
      v_new_soc := GREATEST(
        COALESCE(v_vehicle.current_soc, 0),
        LEAST(v_target_soc,
          COALESCE(v_session.soc_start, v_vehicle.current_soc)
            + ((COALESCE(v_session.energy_delivered_kwh, 0) + v_kwh_delta)
               / v_vehicle.battery_capacity_kwh) * 100.0));
    ELSE
      -- No battery capacity on the row, so no gain can be derived. Leave the
      -- pack exactly as it is rather than clamping it down to the target.
      v_new_soc := v_vehicle.current_soc;
    END IF;

    v_fault_card := ottoq_twin_deal_fault_card(p_sim_run_id, v_session.id, v_session.soc_start, v_target_soc, p_sim_clock_now);

    IF (v_fault_card->>'will_fault')::boolean
       AND v_new_soc >= (v_fault_card->>'trigger_soc')::numeric
       AND v_new_soc < v_target_soc - 0.5 THEN
      v_fault_mode := v_fault_card->>'fault_mode';

      -- 0694 (G412): the reading before the fault, as an OCPP 2.0.1 station sends it; the warning rides in customData
      PERFORM ottoq_sim_emit_ocpp(v_session.id, v_session.ocpp_charger_id, v_session.vehicle_id,
        p_sim_run_id, p_sim_clock_now, 'cs_to_csms', 'TransactionEvent', twin.ottoq_ocpp201_tx_event(
          'Updated', 'MeterValuePeriodic', twin.ottoq_ocpp201_next_seq(v_session.id), v_session.transaction_id,
          p_sim_clock_now, 'Charging',
          twin.ottoq_ocpp201_samples(ARRAY[
            twin.ottoq_ocpp201_sample('Power.Active.Import', v_rate_kw, 'kW'),
            twin.ottoq_ocpp201_sample('SoC', v_new_soc, 'Percent')]),
          jsonb_build_object('battery_temp_c', v_battery_temp, 'fault_imminent', true)));

      UPDATE vehicles SET current_soc = ROUND(v_new_soc::numeric, 1),
                          current_soc_updated_at = p_sim_clock_now, current_soc_source = 'oem_telemetry'
       WHERE id = v_session.vehicle_id;

      UPDATE ocpp_sessions SET energy_delivered_kwh = energy_delivered_kwh + v_kwh_delta,
             fault_count = fault_count + 1, last_fault_message = v_fault_mode, updated_at = p_sim_clock_now
       WHERE id = v_session.id;

      PERFORM ottoq_sim_stop_charge_session(p_session_id := v_session.id, p_reason := v_fault_mode,
        p_sim_clock_now := p_sim_clock_now,
        p_fault_message := 'Calibrated fault injection per ChargerHelp mix: ' || v_fault_mode,
        p_sim_run_id := p_sim_run_id);

      out_session_id := v_session.id; out_action := 'faulted:' || v_fault_mode;
      out_new_soc := v_new_soc; out_charge_rate_kw := v_rate_kw; RETURN NEXT; CONTINUE;
    END IF;

    -- 0694 (G412): each tick's reading as an OCPP 2.0.1 station sends it, TransactionEvent Updated with the power, the
    -- car's charge, the tick's energy and the register; the battery's temperature (2.0.1 has no such measurand) rides
    -- in customData
    PERFORM ottoq_sim_emit_ocpp(v_session.id, v_session.ocpp_charger_id, v_session.vehicle_id,
      p_sim_run_id, p_sim_clock_now, 'cs_to_csms', 'TransactionEvent', twin.ottoq_ocpp201_tx_event(
        'Updated', 'MeterValuePeriodic', twin.ottoq_ocpp201_next_seq(v_session.id), v_session.transaction_id,
        p_sim_clock_now, 'Charging',
        twin.ottoq_ocpp201_samples(ARRAY[
          twin.ottoq_ocpp201_sample('Power.Active.Import', v_rate_kw, 'kW'),
          twin.ottoq_ocpp201_sample('SoC', v_new_soc, 'Percent'),
          twin.ottoq_ocpp201_sample('Energy.Active.Import.Interval', v_kwh_delta, 'kWh'),
          twin.ottoq_ocpp201_sample('Energy.Active.Import.Register',
                                    COALESCE(v_session.energy_delivered_kwh, 0) + v_kwh_delta, 'kWh')]),
        jsonb_build_object('battery_temp_c', v_battery_temp)));

    UPDATE vehicles SET current_soc = ROUND(v_new_soc::numeric, 1),
           current_soc_updated_at = p_sim_clock_now, current_soc_source = 'oem_telemetry'
     WHERE id = v_session.vehicle_id;

    UPDATE ocpp_sessions
       SET energy_delivered_kwh = COALESCE(energy_delivered_kwh, 0) + v_kwh_delta,
           peak_power_kw = GREATEST(COALESCE(peak_power_kw, 0), v_rate_kw),
           connector_temp_c_max = GREATEST(COALESCE(connector_temp_c_max, v_battery_temp), v_battery_temp),
           meter_values_count = COALESCE(meter_values_count, 0) + 1,
           last_meter_value = jsonb_build_object('at', p_sim_clock_now, 'power_kw', ROUND(v_rate_kw::numeric, 2),
             'soc_pct', ROUND(v_new_soc::numeric, 1), 'battery_temp_c', ROUND(v_battery_temp::numeric, 1)),
           updated_at = p_sim_clock_now
     WHERE id = v_session.id;

    IF v_new_soc >= v_target_soc - 0.5 THEN
      PERFORM ottoq_sim_stop_charge_session(p_session_id := v_session.id, p_reason := 'completed',
        p_sim_clock_now := p_sim_clock_now, p_sim_run_id := p_sim_run_id);
      -- CHEMISTRY: a session that actually finished at/above 99% IS the periodic balance
      -- charge — stamp it so NMC packs resume their protective 90% nightly target.
      IF v_new_soc >= 99 THEN
        BEGIN PERFORM ottoq_record_balance_charge(v_session.vehicle_id, p_sim_clock_now);
        EXCEPTION WHEN OTHERS THEN RAISE WARNING 'balance stamp: %', SQLERRM; END;
      END IF;
      out_session_id := v_session.id; out_action := 'completed';
      out_new_soc := v_new_soc; out_charge_rate_kw := v_rate_kw; RETURN NEXT; CONTINUE;
    END IF;

    out_session_id := v_session.id; out_action := 'advanced';
    out_new_soc := v_new_soc; out_charge_rate_kw := v_rate_kw; RETURN NEXT;
  END LOOP;
END;
$function$;
-- @@ function twin.ottoq_sim_compute_discharge_rate(p_speed_kmh numeric, p_ambient_temp_c numeric, p_battery_capacity_kwh numeric, p_active_fraction numeric, p_vehicle_class text, p_noise_seed bigint, p_noise_salt text)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_compute_discharge_rate(p_speed_kmh numeric, p_ambient_temp_c numeric, p_battery_capacity_kwh numeric, p_active_fraction numeric, p_vehicle_class text DEFAULT NULL::text, p_noise_seed bigint DEFAULT 0, p_noise_salt text DEFAULT NULL::text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_base_drive_kw    NUMERIC;
  v_hvac_kw          NUMERIC;
  v_accessory_kw     NUMERIC := 0.3;  -- AV compute + sensors always-on
  v_thermal_factor   NUMERIC := 1.0;
  v_noise_factor     NUMERIC;
BEGIN
  -- Base drive consumption — rough EPA-ish curve, scales with speed
  -- ~3 mi/kWh at city, ~3.5 at highway → 0.28-0.35 kWh/mi.
  -- Power = energy per distance × speed.
  --   At 30 km/h:  0.33 kWh/mi × 18.6 mi/h = 6.1 kW
  --   At 80 km/h:  0.29 kWh/mi × 49.7 mi/h = 14.4 kW
  --   At 110 km/h: 0.35 kWh/mi × 68.4 mi/h = 23.9 kW
  v_base_drive_kw := 0.28 * (p_speed_kmh / 1.609) + 0.0002 * power(p_speed_kmh, 2);

  -- HVAC load — peaks at temperature extremes
  v_hvac_kw := GREATEST(0,
    0.5 + 0.15 * GREATEST(0, abs(COALESCE(p_ambient_temp_c, 22) - 22) - 5)
  );
  -- Cap HVAC at ~5 kW
  v_hvac_kw := LEAST(v_hvac_kw, 5);

  -- Battery efficiency drops at temperature extremes (cold ohmic losses)
  IF p_ambient_temp_c < 5 THEN
    v_thermal_factor := 1.0 + (5 - p_ambient_temp_c) * 0.02;  -- up to +50% in deep cold
  ELSIF p_ambient_temp_c > 35 THEN
    v_thermal_factor := 1.0 + (p_ambient_temp_c - 35) * 0.015;
  END IF;

  -- Random noise per reading
  v_noise_factor := 0.92 + ottoq_sim_seeded_random(p_noise_seed,
    COALESCE(p_noise_salt, 'discharge:' || p_speed_kmh::text)) * 0.16;

  -- Weighted by active fraction
  RETURN ROUND(
    ((v_base_drive_kw * p_active_fraction + v_hvac_kw + v_accessory_kw)
       * v_thermal_factor * v_noise_factor)::NUMERIC,
    3
  );
END;
$function$;
-- @@ function twin.ottoq_sim_emit_telemetry(p_vehicle_id uuid, p_sim_run_id uuid, p_sim_clock timestamp with time zone, p_soc_pct numeric, p_battery_temp_c numeric, p_speed_kmh numeric, p_instant_power_kw numeric, p_state text, p_dtc_codes text[], p_force_integrity text)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_emit_telemetry(p_vehicle_id uuid, p_sim_run_id uuid, p_sim_clock timestamp with time zone, p_soc_pct numeric, p_battery_temp_c numeric, p_speed_kmh numeric, p_instant_power_kw numeric, p_state text, p_dtc_codes text[] DEFAULT NULL::text[], p_force_integrity text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_id               UUID := gen_random_uuid();
  v_integrity_roll   NUMERIC;
  v_integrity        TEXT;
  v_dropped_reason   TEXT;
  v_signal           NUMERIC;
  v_seed             BIGINT;
  v_tire_p           NUMERIC[];
  v_ambient_temp     NUMERIC;
  v_fleet_op_id      UUID;
  v_lat              DOUBLE PRECISION;   -- 0317
  v_lng              DOUBLE PRECISION;   -- 0317
BEGIN
  SELECT fleet_operator_id INTO v_fleet_op_id FROM vehicles WHERE id = p_vehicle_id;
  v_seed := abs(hashtextextended(COALESCE((SELECT random_seed::text FROM ottoq_sim_runs WHERE sim_run_id = p_sim_run_id), '42') || p_vehicle_id::text, 42));

  -- Telemetry integrity dice — 85% full / 12% partial / 3% dropped (baseline).
  -- A.10: telemetry_dropout knob scales the dropped + partial bands.
  v_integrity_roll := ottoq_sim_seeded_random(v_seed,
    'integrity:' || p_sim_clock::text);

  DECLARE v_dm NUMERIC := ottoq_profile_rate_mult(p_sim_run_id, 'telemetry_dropout');
  BEGIN
    IF p_force_integrity IS NOT NULL THEN
      v_integrity := p_force_integrity;
    ELSIF v_integrity_roll < 0.03 * v_dm THEN
      v_integrity := 'dropped';
      v_dropped_reason := CASE
        FLOOR(ottoq_sim_seeded_random(v_seed, 'dropreason:' || p_sim_clock::text) * 4)::int
        WHEN 0 THEN 'rf_dropout'
        WHEN 1 THEN 'cellular_handoff'
        WHEN 2 THEN 'oem_api_5xx'
        ELSE        'vehicle_compute_busy'
      END;
    ELSIF v_integrity_roll < 0.15 * v_dm THEN
      v_integrity := 'partial';
    ELSE
      v_integrity := 'full';
    END IF;
  END;

  -- Signal strength — correlated with integrity outcome
  v_signal := CASE v_integrity
    WHEN 'full'    THEN 65 + ottoq_sim_seeded_random(v_seed, 'sig:'||p_sim_clock::text) * 35
    WHEN 'partial' THEN 25 + ottoq_sim_seeded_random(v_seed, 'sig:'||p_sim_clock::text) * 35
    ELSE                0 + ottoq_sim_seeded_random(v_seed, 'sig:'||p_sim_clock::text) * 25
  END;

  -- Tire pressures — small thermal-cycle drift around 35 PSI
  v_tire_p := ARRAY[
    34 + ottoq_sim_seeded_random(v_seed, 'tire0:'||p_sim_clock::text) * 4,
    34 + ottoq_sim_seeded_random(v_seed, 'tire1:'||p_sim_clock::text) * 4,
    34 + ottoq_sim_seeded_random(v_seed, 'tire2:'||p_sim_clock::text) * 4,
    34 + ottoq_sim_seeded_random(v_seed, 'tire3:'||p_sim_clock::text) * 4
  ];

  -- 0510 (G241): the depot's air temperature, as its weather reads it
  v_ambient_temp := twin.ottoq_sim_site_ambient_c(p_sim_run_id, p_sim_clock);

  -- Dropped packets carry only the dropout record
  IF v_integrity = 'dropped' THEN
    INSERT INTO ottoq_telemetry_packets (
      packet_id, vehicle_id, sim_run_id, fleet_operator_id,
      packet_at, sim_clock_at, vehicle_state,
      packet_integrity, dropped_reason, signal_strength_pct, data_source
    ) VALUES (
      v_id, p_vehicle_id, p_sim_run_id, v_fleet_op_id,
      NOW(), p_sim_clock, p_state,
      v_integrity, v_dropped_reason, v_signal, 'twin'
    );
    RETURN v_id;
  END IF;

  -- 0317: persist WHERE the asset is, not only how charged it is. Computed
  -- ONCE here rather than twice inside the VALUES list, because this is the
  -- twin's hottest write path. NULL means "not on a trip" -- a parked vehicle
  -- is at a stall, and stall geometry lives in ottoq_site_structures.
  SELECT pp.lat, pp.lng INTO v_lat, v_lng
    FROM public.ottoq_vehicle_position(
           p_vehicle_id,
           (SELECT COALESCE(vv.home_depot_id, rr.depot_id)
              FROM public.ottoq_sim_runs rr
              LEFT JOIN public.vehicles vv ON vv.id = p_vehicle_id
             WHERE rr.sim_run_id = p_sim_run_id),
           p_sim_run_id, p_sim_clock) pp;

  INSERT INTO ottoq_telemetry_packets (
    packet_id, vehicle_id, sim_run_id, fleet_operator_id,
    packet_at, sim_clock_at,
    soc_pct, soc_source, battery_temp_c, ambient_temp_c,
    tire_pressures_psi, speed_kmh, current_lat, current_lng,
    instant_power_kw, vehicle_state,
    dtc_codes, signal_strength_pct, packet_integrity, data_source
  ) VALUES (
    v_id, p_vehicle_id, p_sim_run_id, v_fleet_op_id,
    NOW(), p_sim_clock,
    p_soc_pct, 'oem_telemetry', p_battery_temp_c, v_ambient_temp,
    v_tire_p, p_speed_kmh, v_lat, v_lng,
    p_instant_power_kw, p_state,
    p_dtc_codes, v_signal, v_integrity, 'twin'
  );

  RETURN v_id;
END;
$function$;
-- @@ function twin.ottoq_sim_dispatch_vehicle(p_vehicle_id uuid, p_sim_run_id uuid, p_sim_clock_now timestamp with time zone)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_dispatch_vehicle(p_vehicle_id uuid, p_sim_run_id uuid, p_sim_clock_now timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_dispatch_id     UUID := gen_random_uuid();
  v_vehicle         RECORD;
  v_planned_min     NUMERIC;
  v_seed            BIGINT;
  v_door            BOOLEAN := false;  -- 0693: the car's operator reported the departure through the v2 door
BEGIN
  SELECT current_soc, fleet_operator_id, current_state INTO v_vehicle
    FROM vehicles WHERE id = p_vehicle_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'vehicle % not found', p_vehicle_id;
  END IF;

  -- ═══════════════════ 0019: THE DOOR, NOT JUST THE QUEUE ═══════════════════
  -- ottoq.ottoq_plan_dispatch_tick already declines to SELECT a flagged vehicle.
  -- This is the same rule stated where the dispatch row is actually written, so
  -- that no present or future caller of this function can route around it. Under
  -- normal operation the planner filters first and this branch is never taken;
  -- if it is ever taken, the event below says so out loud rather than silently.
  IF public.ottoq_rider_flag_due(p_vehicle_id, p_sim_run_id, p_sim_clock_now) THEN
    BEGIN
      PERFORM ottoq_record_event(
        p_actor_type    := 'ottoq_engine',
        p_actor_id      := 'rider_flag_hold',
        p_event_type    := 'twin.dispatch_refused_rider_flag',
        p_entity_type   := 'vehicle',
        p_entity_id     := p_vehicle_id,
        p_payload       := jsonb_build_object(
          'reason', 'vehicle owes a due rider-flagged cleaning',
          'doctrine', 'always_hold_no_vehicle_leaves_owing_known_work',
          'sim_clock', p_sim_clock_now),
        p_severity      := 'warning',
        p_ingest_source := 'twin', p_data_source := 'twin',
        p_sim_run_id    := p_sim_run_id);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    RETURN NULL;
  END IF;

  -- ═══════════════ 0544 (CLAUDE.md rule 9): THE SECOND DOOR — NO CAR LEAVES UNFINISHED ═══════════════
  -- The deploy plan already offers only a car that is departure-clear (0543). This asks the same question, at the same
  -- clock, where the dispatch row is actually written, so that no present or future caller can send a car out with a
  -- service open or its charge short of its target. Under the plan's filter this branch is never taken; if it is, the
  -- event says so, the car stays where it is, and the next tick's recheck sends it back to what it needs.
  IF NOT COALESCE(public.ottoq_departure_clear(p_vehicle_id, p_sim_run_id, p_sim_clock_now, true), false) THEN
    BEGIN
      PERFORM ottoq_record_event(
        p_actor_type    := 'ottoq_engine',
        p_actor_id      := 'departure_door',
        p_event_type    := 'twin.dispatch_refused_unfinished',
        p_entity_type   := 'vehicle',
        p_entity_id     := p_vehicle_id,
        p_payload       := jsonb_build_object(
          'reason', 'the car is not finished: a service is open or its charge is short of its target',
          'soc', v_vehicle.current_soc,
          'target_soc', public.ottoq_effective_target_soc_at(p_vehicle_id, p_sim_clock_now),
          'open', (SELECT COALESCE(jsonb_agg(DISTINCT a->>'svc'), '[]'::jsonb)
                     FROM ottoq_visit_needs vn CROSS JOIN LATERAL jsonb_array_elements(vn.atoms) a
                    WHERE vn.vehicle_id = p_vehicle_id
                      AND COALESCE(vn.sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid)
                        = COALESCE(p_sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid)
                      AND vn.status IN ('open', 'in_progress')
                      AND COALESCE(a->>'status', 'pending') NOT IN ('done', 'cancelled')),
          'doctrine', 'no_car_leaves_with_a_service_still_needed',
          'sim_clock', p_sim_clock_now),
        p_severity      := 'warning',
        p_ingest_source := 'twin', p_data_source := 'twin',
        p_sim_run_id    := p_sim_run_id);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    RETURN NULL;
  END IF;

  v_seed := abs(hashtextextended(p_vehicle_id::text || twin.ottoq_sim_clock_salt(p_sim_run_id, p_sim_clock_now), 42));

  -- Sample trip duration from NYC TLC trip_duration_minutes distribution
  -- (For deployment durations longer than typical taxi trips, scale up.)
  v_planned_min := COALESCE(
    ottoq_sample_calibrated('trip_duration_minutes', 'global', v_seed, 'dispatch'),
    30
  );
  -- AV deployments are continuous shifts of multiple trips. Scale up.
  v_planned_min := v_planned_min * (2 + ottoq_sim_seeded_random(v_seed, 'multiplier') * 6)
                 * ottoq_profile_rate_mult(p_sim_run_id, 'trip_duration');   -- A.10 trip_duration knob (×)

  INSERT INTO ottoq_vehicle_dispatches (
    dispatch_id, vehicle_id, sim_run_id, fleet_operator_id,
    dispatched_at, scheduled_return_at,
    planned_duration_min, soc_at_dispatch_pct, status
  ) VALUES (
    v_dispatch_id, p_vehicle_id, p_sim_run_id, v_vehicle.fleet_operator_id,
    p_sim_clock_now,
    p_sim_clock_now + (v_planned_min || ' minutes')::INTERVAL,
    v_planned_min, v_vehicle.current_soc, 'active'
  );

  -- T3 RENDER CONTRACT: the taxi OUT to the gate. Emitted before the state write
  -- while current_stall_id still holds the origin. Never aborts the dispatch.
  BEGIN
    PERFORM ottoq_itin_travel_leg(
      p_sim_run_id,
      (SELECT home_depot_id FROM vehicles WHERE id = p_vehicle_id),
      p_vehicle_id,
      (SELECT current_stall_id FROM vehicles WHERE id = p_vehicle_id),
      (SELECT s.id FROM stalls s
        WHERE s.depot_id = (SELECT home_depot_id FROM vehicles WHERE id = p_vehicle_id)
          AND s.stall_type = 'staging'::stall_type
        ORDER BY s.relative_x DESC, s.id LIMIT 1),   -- exit is west/high-x per lane doctrine
      p_sim_clock_now, 'taxi_to_gate', 'twin_dispatcher');
  EXCEPTION WHEN OTHERS THEN RAISE WARNING 'travel leg (dispatch): %', SQLERRM;
  END;

  UPDATE vehicles
     SET current_state = 'deployed'::vehicle_state,
           -- feed-agent service_manifest: clear at deployment so the NEXT
           -- visit rolls a fresh per-visit manifest (frozen-manifest fix)
           config = (COALESCE(config, '{}'::jsonb) - 'service_manifest' - 'service_manifest_meta'),
         last_state_change = p_sim_clock_now,
         current_stall_id = NULL
   WHERE id = p_vehicle_id;

  -- the visit is over: close its itinerary, supersede unserviced needs and
  -- release any stall this car was still holding (AP-1b / B5)
  -- 0693: at twin_operator_departures 1 the car's operator reports the departure through the v2 door, whose
  -- com.ottoyard.vehicle.departed makes this same release (contract rule 8); a car no operator speaks for, or a
  -- report that could not be sent, keeps the release here
  IF ottoq_policy_get(p_sim_run_id, 'twin_operator_departures', 0) >= 1 THEN
    BEGIN v_door := twin.ottoq_twin_operator_depart(p_sim_run_id, p_sim_clock_now, p_vehicle_id);
    EXCEPTION WHEN OTHERS THEN RAISE WARNING 'operator departure: %', SQLERRM; v_door := false;
    END;
  END IF;
  IF NOT v_door THEN
  BEGIN PERFORM ottoq_release_visit_artifacts(p_vehicle_id, p_sim_run_id, p_sim_clock_now, 'redeployed');
  EXCEPTION WHEN OTHERS THEN RAISE WARNING 'release visit artifacts: %', SQLERRM; END;
  END IF;

  PERFORM ottoq_record_event(
    p_actor_type    := 'oem_dispatch_webhook',
    p_actor_id      := 'twin_dispatch_sim',
    p_event_type    := 'twin.vehicle_arrived',  -- reusing arrival type for dispatch logging
    p_entity_type   := 'vehicle',
    p_entity_id     := p_vehicle_id,
    p_fleet_operator_id := v_vehicle.fleet_operator_id,
    p_payload       := jsonb_build_object(
      'dispatch_id', v_dispatch_id,
      'planned_duration_min', v_planned_min,
      'soc_at_dispatch', v_vehicle.current_soc,
      'mode', 'deployment_start'
    ),
    p_severity      := 'info',
    p_ingest_source := 'twin',
    p_data_source   := 'twin',
    p_sim_run_id    := p_sim_run_id
  );

  RETURN v_dispatch_id;
END;
$function$;
-- @@ function twin.ottoq_sim_sample_lognormal_ms(p_mean_ms integer, p_p99_ms integer, p_seed bigint, p_salt text)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_sample_lognormal_ms(p_mean_ms integer, p_p99_ms integer, p_seed bigint, p_salt text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_u1     NUMERIC;
  v_u2     NUMERIC;
  v_z      NUMERIC;          -- standard normal
  v_mu     NUMERIC;          -- lognormal mu
  v_sigma  NUMERIC;          -- lognormal sigma
  v_x      NUMERIC;          -- sampled lognormal
BEGIN
  -- Solve mu, sigma from mean and p99
  --   E[X] = exp(mu + sigma^2/2)
  --   p99(X) = exp(mu + 2.326*sigma)
  -- Use simple inversion: sigma ~ ln(p99/mean) / 1.826
  v_sigma := GREATEST(0.2, LN(GREATEST(p_p99_ms::numeric, p_mean_ms::numeric * 1.5) / p_mean_ms::numeric) / 1.826);
  v_mu    := LN(p_mean_ms::numeric) - (v_sigma * v_sigma / 2.0);

  v_u1 := GREATEST(1e-9, ottoq_sim_seeded_random(p_seed, p_salt || '_u1'));
  v_u2 := ottoq_sim_seeded_random(p_seed, p_salt || '_u2');

  -- Box-Muller transform
  v_z := SQRT(-2.0 * LN(v_u1)) * COS(2.0 * PI() * v_u2);

  v_x := EXP(v_mu + v_sigma * v_z);
  RETURN GREATEST(10, LEAST(60000, ROUND(v_x)::integer));   -- clamp [10ms, 60s]
END;
$function$;
-- @@ function twin.ottoq_sim_build_arrival_payload(p_oem text, p_vehicle record, p_sim_clock_now timestamp with time zone, p_arrival_soc numeric, p_dispatch_id uuid, p_seed bigint, p_complete boolean)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_build_arrival_payload(p_oem text, p_vehicle record, p_sim_clock_now timestamp with time zone, p_arrival_soc numeric, p_dispatch_id uuid, p_seed bigint, p_complete boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_payload JSONB;
  v_drop_optional BOOLEAN := NOT p_complete;
  v_odo NUMERIC := COALESCE((p_vehicle.config->>'lifetime_miles')::numeric, 0)
                  + COALESCE((SELECT SUM(miles_driven) FROM ottoq_vehicle_dispatches
                              WHERE vehicle_id = p_vehicle.id AND status = 'completed'
                                AND COALESCE(sim_run_id,'00000000-0000-0000-0000-000000000000'::uuid)
                                  = COALESCE((SELECT d0.sim_run_id FROM ottoq_vehicle_dispatches d0
                                               WHERE d0.dispatch_id = p_dispatch_id),
                                             '00000000-0000-0000-0000-000000000000'::uuid)), 0);
BEGIN
  IF p_oem = 'waymo' THEN
    v_payload := jsonb_build_object(
      'vehicle_id',   p_vehicle.av_api_vehicle_id,
      'arrival_at',   to_char(p_sim_clock_now AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'gate_id',      'OTTOYARD-NASH-GATE-INGRESS',
      'soc_pct',      ROUND(p_arrival_soc::numeric, 1)
    );
    IF NOT v_drop_optional THEN
      v_payload := v_payload
        || jsonb_build_object(
             'estimated_service_minutes',
               FLOOR(15 + ottoq_sim_seeded_random(p_seed, 'svc') * 30)::int,
             'flags',
               CASE WHEN (p_vehicle.config->>'flagged_issue')::boolean
                 THEN jsonb_build_array(p_vehicle.config->>'flagged_issue_type')
                 ELSE '[]'::jsonb END,
             'odometer_mi',  ROUND(v_odo::numeric, 1),
             'heading_deg',  FLOOR(ottoq_sim_seeded_random(p_seed, 'hdg') * 360)::int,
             'health_status', CASE
               WHEN (p_vehicle.config->>'battery_soh_pct')::numeric > 90 THEN 'green'
               WHEN (p_vehicle.config->>'battery_soh_pct')::numeric > 85 THEN 'yellow'
               ELSE 'amber' END);
    END IF;

  ELSIF p_oem = 'tesla' THEN
    v_payload := jsonb_build_object(
      'id',                  p_vehicle.av_api_vehicle_id,
      'arrival_timestamp',   EXTRACT(EPOCH FROM p_sim_clock_now)::bigint,
      'gate',                'NASH-A',
      'soc',                 ROUND(p_arrival_soc::numeric, 0)
    );
    IF NOT v_drop_optional THEN
      v_payload := v_payload
        || jsonb_build_object(
             'est_charge_min', FLOOR(20 + ottoq_sim_seeded_random(p_seed, 'tsl_chg') * 40)::int,
             'alerts',
               CASE WHEN (p_vehicle.config->>'flagged_issue')::boolean
                 THEN jsonb_build_array(p_vehicle.config->>'flagged_issue_type')
                 ELSE '[]'::jsonb END,
             'odo_km',         ROUND((v_odo * 1.60934)::numeric, 1),
             'drive_state',    'parked',
             'vehicle_state',  'online');
    END IF;

  ELSIF p_oem = 'zoox' THEN
    v_payload := jsonb_build_object(
      'vehicle_uuid',     p_vehicle.id::text,
      'gate_arrival_ts',  to_char(p_sim_clock_now AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
      'gate_node',        'ottoyard_nashville_gate_a',
      'soc_pct',          ROUND(p_arrival_soc::numeric, 2)
    );
    IF NOT v_drop_optional THEN
      v_payload := v_payload
        || jsonb_build_object(
             'telemetry_burst', jsonb_build_object(
                'battery_temp_c', ROUND((28 + ottoq_sim_seeded_random(p_seed,'zx_bt') * 12)::numeric, 1),
                'motor_temp_c',   ROUND((35 + ottoq_sim_seeded_random(p_seed,'zx_mt') * 20)::numeric, 1),
                'cabin_temp_c',   ROUND((19 + ottoq_sim_seeded_random(p_seed,'zx_ct') * 6)::numeric, 1)
              ),
             'next_dispatch_eta_min',
               FLOOR(45 + ottoq_sim_seeded_random(p_seed, 'zx_eta') * 120)::int,
             'cargo_state',  'empty',
             'sensor_health', CASE
               WHEN ottoq_sim_seeded_random(p_seed, 'zx_sh') > 0.05 THEN 'nominal'
               ELSE 'degraded_lidar_3' END);
    END IF;
  END IF;

  v_payload := v_payload
    || jsonb_build_object('_internal_dispatch_id', p_dispatch_id::text,
                          '_schema_version',       (SELECT payload_schema_version FROM ottoq_oem_webhook_patterns WHERE oem_name = p_oem));

  RETURN v_payload;
END;
$function$;
-- @@ function twin.ottoq_sim_emit_arrival_webhook(p_vehicle_id uuid, p_sim_run_id uuid, p_sim_clock_now timestamp with time zone, p_dispatch_id uuid, p_arrival_soc numeric)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_emit_arrival_webhook(p_vehicle_id uuid, p_sim_run_id uuid, p_sim_clock_now timestamp with time zone, p_dispatch_id uuid, p_arrival_soc numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_vehicle           RECORD;
  v_oem               TEXT;
  v_pattern           ottoq_oem_webhook_patterns%ROWTYPE;
  v_seed              BIGINT;
  v_webhook_id        UUID := gen_random_uuid();
  v_payload           JSONB;
  v_payload_complete  BOOLEAN;
  v_missing_fields    TEXT[];
  v_attempt           INTEGER := 1;
  v_max_retries       INTEGER;
  v_latency_ms        INTEGER;
  v_total_latency_ms  INTEGER := 0;
  v_roll_auth         NUMERIC;
  v_roll_rate         NUMERIC;
  v_roll_timeout      NUMERIC;
  v_roll_5xx          NUMERIC;
  v_roll_dup          NUMERIC;
  v_roll_ooo          NUMERIC;
  v_roll_complete     NUMERIC;
  v_delivery          TEXT;
  v_http_status       INTEGER;
  v_validation        TEXT;
  v_is_duplicate      BOOLEAN := FALSE;
  v_is_ooo            BOOLEAN := FALSE;
  v_failed_first      BOOLEAN := FALSE;
  v_backoff_ms        INTEGER[];
  v_jitter_pct        NUMERIC;
BEGIN
  SELECT v.*, fo.fleet_operator_id, fo.av_platform, fo.av_api_vehicle_id, fo.make, fo.config
    INTO v_vehicle
    FROM vehicles v
   CROSS JOIN LATERAL (SELECT v.fleet_operator_id, v.platform::text AS av_platform,
                              v.av_api_vehicle_id, v.make, v.config) fo
   WHERE v.id = p_vehicle_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'vehicle % not found', p_vehicle_id;
  END IF;

  v_oem := LOWER(v_vehicle.av_platform);
  SELECT * INTO v_pattern FROM ottoq_oem_webhook_patterns WHERE oem_name = v_oem AND active = TRUE;
  IF NOT FOUND THEN
    -- No pattern → drop silently (real OEM not yet onboarded)
    RETURN NULL;
  END IF;

  -- LIVE DELIVERY ROUTE: a real signed HTTP POST when this OEM is onboarded live.
  IF v_pattern.live_delivery_enabled
     AND v_pattern.live_endpoint_url IS NOT NULL
     AND v_pattern.live_endpoint_url LIKE 'https://%' THEN
    v_payload := ottoq_sim_build_arrival_payload(v_oem, v_vehicle, p_sim_clock_now, p_arrival_soc, p_dispatch_id,
                   abs(hashtextextended(p_vehicle_id::text || twin.ottoq_sim_clock_salt(p_sim_run_id, p_sim_clock_now) || 'arrival', 42)), TRUE);
    PERFORM ottoq_oem_deliver_live(v_webhook_id, p_sim_run_id, p_vehicle_id, v_pattern.fleet_operator_id,
                   v_oem, v_pattern.live_endpoint_url, v_payload, v_pattern.signing_secret_ref, p_sim_clock_now);
    RETURN v_webhook_id;
  END IF;

  v_seed         := abs(hashtextextended(p_vehicle_id::text || twin.ottoq_sim_clock_salt(p_sim_run_id, p_sim_clock_now) || 'arrival', 42));
  v_max_retries  := COALESCE((v_pattern.retry_policy->>'max_retries')::int, 3);
  v_backoff_ms   := ARRAY(SELECT (jsonb_array_elements_text(v_pattern.retry_policy->'backoff_ms'))::int);
  v_jitter_pct   := COALESCE((v_pattern.retry_policy->>'jitter_pct')::numeric, 15);

  -- ----- Payload completeness roll -----
  v_roll_complete   := ottoq_sim_seeded_random(v_seed, 'complete');
  v_payload_complete := v_roll_complete < v_pattern.payload_completeness_pct;

  IF NOT v_payload_complete THEN
    -- Pick 1-2 optional fields to omit
    v_missing_fields := ARRAY(
      SELECT jsonb_array_elements_text(v_pattern.optional_fields)
      ORDER BY ottoq_sim_seeded_random(v_seed, 'miss_' || jsonb_array_elements_text(v_pattern.optional_fields))
      LIMIT 1 + FLOOR(ottoq_sim_seeded_random(v_seed, 'miss_n') * 2)::int
    );
  END IF;

  v_payload := ottoq_sim_build_arrival_payload(
    v_oem, v_vehicle, p_sim_clock_now, p_arrival_soc, p_dispatch_id, v_seed, v_payload_complete);

  -- ----- Out-of-order delivery roll -----
  v_roll_ooo := ottoq_sim_seeded_random(v_seed, 'ooo');
  v_is_ooo   := v_roll_ooo < v_pattern.out_of_order_pct;

  -- ----- Attempt loop (handles retries) -----
  LOOP
    v_latency_ms := ottoq_sim_sample_lognormal_ms(
      v_pattern.latency_mean_ms, v_pattern.latency_p99_ms, v_seed,
      'lat_' || v_attempt::text);
    v_total_latency_ms := v_total_latency_ms + v_latency_ms;

    v_roll_timeout := ottoq_sim_seeded_random(v_seed, 'timeout_' || v_attempt::text);
    v_roll_auth    := ottoq_sim_seeded_random(v_seed, 'auth_'    || v_attempt::text);
    v_roll_rate    := ottoq_sim_seeded_random(v_seed, 'rate_'    || v_attempt::text);
    v_roll_5xx     := ottoq_sim_seeded_random(v_seed, '5xx_'     || v_attempt::text);

    -- Failure mode cascade
    IF v_roll_timeout < v_pattern.network_timeout_pct THEN
      v_delivery := 'timed_out';   v_http_status := NULL;
    ELSIF v_roll_auth < v_pattern.auth_failure_pct THEN
      v_delivery := 'auth_failed'; v_http_status := 401;
    ELSIF v_roll_rate < v_pattern.rate_limit_pct THEN
      v_delivery := 'rate_limited';v_http_status := 429;
    ELSIF v_roll_5xx < v_pattern.server_error_5xx_pct THEN
      v_delivery := 'server_error';v_http_status := 502;
    ELSE
      v_delivery := 'delivered';   v_http_status := 200;
    END IF;

    -- Log this attempt (whether success or fail)
    INSERT INTO ottoq_oem_webhook_log (
      webhook_id, sim_run_id, vehicle_id, fleet_operator_id,
      oem_name, webhook_type, http_method, endpoint_url,
      payload, payload_complete, payload_missing_fields,
      attempt_num, is_retry, is_duplicate, is_out_of_order, parent_webhook_id,
      latency_ms, http_status, delivery_status, delivery_mode,
      validation_result, sim_clock_emitted_at, sim_clock_delivered_at,
      data_source
    ) VALUES (
      CASE WHEN v_attempt = 1 THEN v_webhook_id ELSE gen_random_uuid() END,
      p_sim_run_id, p_vehicle_id, v_pattern.fleet_operator_id,
      v_oem, 'arrival', 'POST', v_pattern.webhook_endpoint,
      v_payload, v_payload_complete, v_missing_fields,
      v_attempt, v_attempt > 1, FALSE, v_is_ooo,
      CASE WHEN v_attempt > 1 THEN v_webhook_id ELSE NULL END,
      v_latency_ms, v_http_status, v_delivery, 'simulated',
      CASE
        WHEN v_delivery = 'delivered' AND v_payload_complete THEN 'accepted'
        WHEN v_delivery = 'delivered' AND NOT v_payload_complete THEN 'accepted_partial'
        WHEN v_delivery = 'auth_failed' THEN 'rejected_auth'
        WHEN v_delivery IN ('rate_limited','server_error','timed_out') THEN 'pending_retry'
        ELSE 'rejected_other'
      END,
      p_sim_clock_now + (v_total_latency_ms - v_latency_ms || ' milliseconds')::interval,
      CASE WHEN v_delivery = 'delivered'
           THEN p_sim_clock_now + (v_total_latency_ms || ' milliseconds')::interval
           ELSE NULL END,
      'twin'
    );

    EXIT WHEN v_delivery = 'delivered';
    EXIT WHEN v_delivery = 'auth_failed';     -- auth fail terminates
    EXIT WHEN v_attempt >= v_max_retries;     -- exhausted retries

    -- Apply backoff
    IF array_length(v_backoff_ms, 1) >= v_attempt THEN
      v_total_latency_ms := v_total_latency_ms + v_backoff_ms[v_attempt]
                          + FLOOR(v_backoff_ms[v_attempt] * v_jitter_pct / 100.0
                                  * (ottoq_sim_seeded_random(v_seed, 'jit_' || v_attempt::text) - 0.5) * 2)::int;
    END IF;

    v_attempt := v_attempt + 1;
    v_failed_first := TRUE;
  END LOOP;

  -- ----- Duplicate send roll (only on success) -----
  IF v_delivery = 'delivered' THEN
    v_roll_dup := ottoq_sim_seeded_random(v_seed, 'dup');
    IF v_roll_dup < v_pattern.duplicate_send_pct THEN
      v_is_duplicate := TRUE;
      INSERT INTO ottoq_oem_webhook_log (
        webhook_id, sim_run_id, vehicle_id, fleet_operator_id,
        oem_name, webhook_type, http_method, endpoint_url,
        payload, payload_complete,
        attempt_num, is_retry, is_duplicate, parent_webhook_id,
        latency_ms, http_status, delivery_status, delivery_mode,
        validation_result, sim_clock_emitted_at, sim_clock_delivered_at,
        data_source
      ) VALUES (
        gen_random_uuid(),
        p_sim_run_id, p_vehicle_id, v_pattern.fleet_operator_id,
        v_oem, 'arrival', 'POST', v_pattern.webhook_endpoint,
        v_payload, v_payload_complete,
        1, FALSE, TRUE, v_webhook_id,
        ottoq_sim_sample_lognormal_ms(v_pattern.latency_mean_ms, v_pattern.latency_p99_ms, v_seed, 'dup_lat'),
        200, 'delivered', 'simulated',
        'rejected_duplicate',
        p_sim_clock_now + (FLOOR(2000 + ottoq_sim_seeded_random(v_seed, 'dup_off') * 8000) || ' milliseconds')::interval,
        p_sim_clock_now + (FLOOR(2000 + ottoq_sim_seeded_random(v_seed, 'dup_off') * 8000) + 200 || ' milliseconds')::interval,
        'twin'
      );
    END IF;
  END IF;

  -- Emit canonical twin event for forensic replay
  PERFORM ottoq_record_event(
    p_actor_type    := 'oem_dispatch_webhook',
    p_actor_id      := v_oem || '_arrival_mock',
    p_event_type    := 'twin.oem_webhook_emitted',
    p_entity_type   := 'vehicle',
    p_entity_id     := p_vehicle_id,
    p_fleet_operator_id := v_pattern.fleet_operator_id,
    p_payload       := jsonb_build_object(
      'webhook_id',        v_webhook_id,
      'oem',               v_oem,
      'delivery_status',   v_delivery,
      'attempts',          v_attempt,
      'total_latency_ms',  v_total_latency_ms,
      'payload_complete',  v_payload_complete,
      'is_duplicate',      v_is_duplicate,
      'is_out_of_order',   v_is_ooo,
      'soc_at_arrival',    p_arrival_soc
    ),
    p_severity      := CASE WHEN v_delivery = 'delivered' THEN 'info' ELSE 'warning' END,
    p_ingest_source := 'twin',
    p_data_source   := 'twin',
    p_sim_run_id    := p_sim_run_id
  );

  RETURN v_webhook_id;
END;
$function$;
-- @@ function twin.ottoq_sim_advance_deployed_telemetry(p_sim_run_id uuid, p_sim_clock_now timestamp with time zone, p_tick_minutes numeric)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_advance_deployed_telemetry(p_sim_run_id uuid, p_sim_clock_now timestamp with time zone, p_tick_minutes numeric)
 RETURNS TABLE(out_vehicle_id uuid, out_action text, out_new_soc numeric, out_new_state text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_ret_should boolean; v_ret_trigger text; v_ret_urgency text; v_ret_ev jsonb;
  v_ret_deferrable boolean; v_book jsonb; v_eta_min numeric;
  v_eta_computed numeric;   -- 0318: NULL means the computation refused
  v_dispatch        RECORD;
  v_active_frac     NUMERIC;
  v_avg_speed       NUMERIC;
  v_discharge_kw    NUMERIC;
  v_kwh_consumed    NUMERIC;
  v_miles           NUMERIC;
  v_new_soc         NUMERIC;
  v_seed            BIGINT;
  v_salt            TEXT;
  v_dtc             TEXT;
  v_incident        RECORD;
  v_ambient         NUMERIC;
  v_battery_temp    NUMERIC;
  v_should_return   BOOLEAN;
  v_min_soc_thresh  NUMERIC;
  v_incident_id     UUID;
  v_webhook_id      UUID;
  v_eta_card       JSONB;
  v_progress       NUMERIC;
  v_ws             RECORD;    -- 0212: the work side's answer
  v_recall_id      UUID;      -- 0212: the decision a refusal names
  v_out_drain_pct_h NUMERIC;  -- 0486: SoC points per hour a car is out, beyond what it drives
  v_publish BOOLEAN;  -- 0692: the run's twin_operator_publish flag
BEGIN
  v_seed := abs(hashtextextended(COALESCE((SELECT random_seed::text FROM ottoq_sim_runs WHERE sim_run_id = p_sim_run_id), '42') || twin.ottoq_sim_clock_salt(p_sim_run_id, p_sim_clock_now), 42));
  -- 0486 (G219): THE DRAIN IS DRIVEN, NOT STAMPED. The scenario's arrival drain (a negative soc_on_arrival shift,
  -- never a positive one, since driving refills nothing) and the climate drain used to land in one step at the
  -- gate, so every reading before the gate was about 33 points high on busy_day. They are now SoC points per
  -- hour the car is out, drawn as power below, so the battery falls while the car drives.
  v_out_drain_pct_h := GREATEST(0, -COALESCE((SELECT (vp.knobs #>> '{soc_on_arrival,shift}')::numeric
                                                FROM ottoq_variability_profiles vp
                                               WHERE vp.sim_run_id = p_sim_run_id), 0))
                       + GREATEST(0, COALESCE(ottoq_twin_arrival_soc_drain(p_sim_run_id, p_sim_clock_now), 0));

  -- 0692: at twin_operator_publish 1 each car's operator sends its telemetry through the v2 door
  v_publish := ottoq_policy_get(p_sim_run_id, 'twin_operator_publish', 0) >= 1;

  FOR v_dispatch IN
    SELECT d.*, v.battery_capacity_kwh, v.current_soc AS v_soc,
           v.min_soc_threshold, v.current_state AS v_state,
           v.display_name, v.fleet_operator_id AS v_fleet_op,
           (v.config->>'consumption_scalar')::numeric AS v_cons_scalar
      FROM ottoq_vehicle_dispatches d
      JOIN vehicles v ON v.id = d.vehicle_id
     WHERE d.status IN ('active','returning')
       AND (p_sim_run_id IS NULL OR d.sim_run_id = p_sim_run_id)
     ORDER BY d.vehicle_id   -- 0050: run-stable cursor order (fleet/stall identity, never heap order)
  LOOP
    v_salt := v_dispatch.vehicle_id::text || ':' || twin.ottoq_sim_clock_salt(p_sim_run_id, p_sim_clock_now);
    v_min_soc_thresh := COALESCE(v_dispatch.min_soc_threshold, 20);

    v_active_frac := LEAST(1.0, (0.40 + ottoq_sim_seeded_random(v_seed, 'active:' || v_salt) * 0.45)
                     * ottoq_profile_rate_mult(p_sim_run_id, 'idle_fraction'));
    v_avg_speed   := 20 + ottoq_sim_seeded_random(v_seed, 'speed:' || v_salt) * 70;

    v_ambient := COALESCE(
      twin.ottoq_sim_site_ambient_c(p_sim_run_id, p_sim_clock_now),   -- 0510 (G241): the depot's air, not a per-car draw
      22);

    v_discharge_kw := ottoq_sim_compute_discharge_rate(
      v_avg_speed, v_ambient, v_dispatch.battery_capacity_kwh,
      v_active_frac, NULL, v_seed, 'disch:'||v_salt);
    v_discharge_kw := ottoq_apply_profile(p_sim_run_id, 'soh_spread', v_discharge_kw, v_discharge_kw * 0.85);
    -- per-vehicle consumption scalar (condition card drawn at run boot)
    v_discharge_kw := v_discharge_kw * COALESCE(v_dispatch.v_cons_scalar, 1.0);
    -- 0486 (G219): the out-drain as power, so it lands in the cumulative energy the SoC below is derived from.
    v_discharge_kw := v_discharge_kw + (v_out_drain_pct_h / 100.0) * COALESCE(v_dispatch.battery_capacity_kwh, 0);
    v_kwh_consumed := v_discharge_kw * (p_tick_minutes / 60.0);
    v_miles := (v_avg_speed * v_active_frac * p_tick_minutes / 60.0) * 0.621371;

    -- ═══════ DRAIN IS DERIVED FROM CUMULATIVE ENERGY, NOT DECREMENTED ═══════
    -- SAME DEFECT AS THE CHARGE SIDE, AND MORE DAMAGING. This read
    -- `v_dispatch.v_soc - ...`, i.e. it decremented the value STORED on the vehicle,
    -- and public.vehicles.current_soc is an INTEGER. At the live tick rate a deployed
    -- car burns well under half a SoC point per tick, so ROUND() wrote the same whole
    -- number back every time and the vehicle never lost any charge at all.
    -- MEASURED on run 128c12f6: over 94 sim-seconds, five deployed vehicles had
    -- current_soc_updated_at advancing every tick -- the code was running and writing --
    -- while current_soc sat unchanged at 97/95/90/89/97.
    -- CONSEQUENCE: robotaxis that never discharge never need to come back, so the depot
    -- receives no organic return demand. That silently contradicts the whole point of
    -- unscripted arrivals.
    -- FIX: derive from the dispatch's own cumulative energy against soc_at_dispatch_pct
    -- (both already exist and are numeric). Monotonic, so it crosses each whole point no
    -- matter how thin the per-tick slice is. Falls back to the old expression when the
    -- dispatch has no recorded starting SoC, so nothing regresses.
    IF v_dispatch.soc_at_dispatch_pct IS NOT NULL
       AND COALESCE(v_dispatch.battery_capacity_kwh, 0) > 0 THEN
      v_new_soc := GREATEST(0,
        v_dispatch.soc_at_dispatch_pct
          - ((COALESCE(v_dispatch.energy_consumed_kwh, 0) + v_kwh_consumed)
             / v_dispatch.battery_capacity_kwh) * 100.0);
    ELSE
      v_new_soc := GREATEST(0,
        v_dispatch.v_soc - (v_kwh_consumed / v_dispatch.battery_capacity_kwh) * 100.0);
    END IF;

    v_battery_temp := v_ambient + 4 + v_active_frac * 6
      + ottoq_sim_seeded_random(v_seed, 'btemp:'||v_salt) * 4;

    v_dtc := ottoq_sim_maybe_spawn_dtc(v_seed, v_salt, p_tick_minutes, v_active_frac,
                                       ottoq_profile_rate_mult(p_sim_run_id, 'dtc'));

    v_incident := NULL;
    IF v_miles > 0 THEN
      SELECT * INTO v_incident FROM ottoq_sim_maybe_incident(v_seed, v_salt, v_miles,
                                       ottoq_profile_rate_mult(p_sim_run_id, 'incident') * ottoq_twin_incident_weather_mult(p_sim_run_id, p_sim_clock_now),
                                       ottoq_apply_profile(p_sim_run_id, 'incident_severity', 0, 0),
                                       ottoq_profile_rate_mult(p_sim_run_id, 'breakdown_rate'));
    END IF;

    IF v_incident.out_kind IS NOT NULL THEN
      v_incident_id := gen_random_uuid();
      INSERT INTO ottoq_vehicle_incidents (
        incident_id, vehicle_id, sim_run_id, occurred_at,
        incident_type, severity,
        speed_kmh_at_event, soc_pct_at_event,
        description, requires_tow, resolution_status
      ) VALUES (
        v_incident_id, v_dispatch.vehicle_id, p_sim_run_id, p_sim_clock_now,
        v_incident.out_kind, v_incident.out_sev,
        v_avg_speed, v_new_soc,
        'Auto-generated by deployment simulator (DMV-calibrated rate)',
        v_incident.out_requires_tow, 'open');

      PERFORM ottoq_record_event(
        p_actor_type    := 'av_vehicle',
        p_actor_id      := v_dispatch.vehicle_id::text,
        p_event_type    := CASE WHEN v_incident.out_sev IN ('major','safety_critical')
                                THEN 'anomaly.critical_detected'
                                ELSE 'anomaly.detected' END,
        p_entity_type   := 'vehicle',
        p_entity_id     := v_dispatch.vehicle_id,
        p_fleet_operator_id := v_dispatch.v_fleet_op,
        p_payload       := jsonb_build_object(
          'incident_type', v_incident.out_kind,
          'severity', v_incident.out_sev,
          'requires_tow', v_incident.out_requires_tow,
          'soc_at_event', v_new_soc,
          'speed_at_event', v_avg_speed),
        p_severity      := CASE
                             WHEN v_incident.out_sev = 'major' THEN 'critical'
                             WHEN v_incident.out_sev = 'moderate' THEN 'warning'
                             ELSE 'info' END,
        p_ingest_source := 'twin',
        p_data_source   := 'twin',
        p_sim_run_id    := p_sim_run_id);

      IF v_incident.out_requires_tow THEN
        UPDATE vehicles SET current_state = 'tow_requested'::vehicle_state,
                            last_state_change = p_sim_clock_now,
                            current_soc = ROUND(v_new_soc::numeric,1),
                            current_soc_updated_at = p_sim_clock_now
         WHERE id = v_dispatch.vehicle_id;
        UPDATE ottoq_vehicle_dispatches SET status = 'aborted',
                                            actual_return_at = p_sim_clock_now
         WHERE dispatch_id = v_dispatch.dispatch_id;
        out_vehicle_id := v_dispatch.vehicle_id;
        out_action := 'incident:' || v_incident.out_kind;
        out_new_soc := v_new_soc; out_new_state := 'tow_requested';
        RETURN NEXT;
        CONTINUE;
      END IF;
    END IF;

    IF v_dispatch.status = 'active' THEN
      v_eta_card := ottoq_twin_deal_eta_card(p_sim_run_id, v_dispatch.dispatch_id, (p_sim_clock_now::date - DATE '2020-01-01')::int);
      IF (v_eta_card->>'will_delay')::boolean AND NOT COALESCE((v_eta_card->>'applied')::boolean, false) THEN
        v_progress := CASE WHEN v_dispatch.scheduled_return_at > v_dispatch.dispatched_at
          THEN EXTRACT(EPOCH FROM (p_sim_clock_now - v_dispatch.dispatched_at))
               / NULLIF(EXTRACT(EPOCH FROM (v_dispatch.scheduled_return_at - v_dispatch.dispatched_at)),0)
          ELSE 1 END;
        IF v_progress >= (v_eta_card->>'trigger_progress')::numeric THEN
          -- 0009 (DEFECT 2a). This is the FIRST of the two writers that move
          -- scheduled_return_at away from the dispatch-time plan, and until now it moved it
          -- SILENTLY -- from the row alone you could not tell the column had stopped being
          -- the plan. The move itself is legitimate (a real modelled delay) and is left
          -- byte-for-byte; what is added is the RECORD of it. The plan itself is now safe in
          -- its own generated column, planned_return_at, which nothing may overwrite.
          -- CLOCK DOMAIN: p_sim_clock_now is the SIM clock. So is scheduled_return_at.
          UPDATE ottoq_vehicle_dispatches
             SET scheduled_return_at = scheduled_return_at + ((v_eta_card->>'delay_min') || ' minutes')::interval,
                 eta_refreshed_at    = p_sim_clock_now,
                 eta_source          = 'twin_eta_delay_card:' || COALESCE(v_eta_card->>'cause','unknown')
           WHERE dispatch_id = v_dispatch.dispatch_id;
          v_dispatch.scheduled_return_at := v_dispatch.scheduled_return_at + ((v_eta_card->>'delay_min') || ' minutes')::interval;
          UPDATE ottoq_variability_cards SET meta = meta || '{"applied":true}'::jsonb
           WHERE sim_run_id=p_sim_run_id AND var_key='eta_delay' AND scope_instance=v_dispatch.dispatch_id::text;
          BEGIN
            PERFORM ottoq_record_event(
              p_actor_type:='av_vehicle', p_actor_id:=v_dispatch.vehicle_id::text,
              p_event_type:='fleet.arrival_delayed', p_entity_type:='vehicle', p_entity_id:=v_dispatch.vehicle_id,
              p_fleet_operator_id:=v_dispatch.v_fleet_op,
              p_payload:=jsonb_build_object('cause', v_eta_card->>'cause', 'delay_min', (v_eta_card->>'delay_min')::numeric,
                'new_eta', v_dispatch.scheduled_return_at),
              p_severity:='warning', p_ingest_source:='twin', p_data_source:='twin', p_sim_run_id:=p_sim_run_id);
          EXCEPTION WHEN OTHERS THEN NULL; END;
        END IF;
      END IF;
    END IF;

    -- Persist the running total the SoC above is derived from. energy_consumed_kwh is an
    -- existing numeric column that NOTHING else assigns (verified across this function
    -- and the whole schema), so this introduces no double counting.
    UPDATE ottoq_vehicle_dispatches
       SET energy_consumed_kwh = COALESCE(energy_consumed_kwh, 0) + v_kwh_consumed,
           -- 0690 (G406): the tick's miles accrue beside its energy, the v_miles the incident roll reads. The close
           -- used to count each telemetry packet as one minute of driving, and a car sends one packet a tick.
           miles_driven        = COALESCE(miles_driven, 0) + v_miles
     WHERE dispatch_id = v_dispatch.dispatch_id;

    UPDATE vehicles
       SET current_soc = ROUND(v_new_soc::numeric, 1),
           current_soc_updated_at = p_sim_clock_now,
           current_soc_source = 'estimated',
           last_state_change = p_sim_clock_now
     WHERE id = v_dispatch.vehicle_id;

    IF v_publish THEN
      PERFORM twin.ottoq_twin_operator_publish(
        p_sim_run_id, p_sim_clock_now, v_dispatch.vehicle_id,
        v_new_soc, v_battery_temp, v_avg_speed * v_active_frac,
        v_discharge_kw, v_dispatch.v_state::text, v_dtc);
    ELSE
    PERFORM ottoq_sim_emit_telemetry(
      v_dispatch.vehicle_id, p_sim_run_id, p_sim_clock_now,
      v_new_soc, v_battery_temp, v_avg_speed * v_active_frac,
      v_discharge_kw, v_dispatch.v_state::text,
      CASE WHEN v_dtc IS NOT NULL THEN ARRAY[v_dtc] ELSE NULL END);
    END IF;

    -- AP-3: need-driven return decision (evaluator scoped to the real run)
    SELECT er.should_return, er.return_trigger, er.urgency, er.is_deferrable, er.evidence
      INTO v_ret_should, v_ret_trigger, v_ret_urgency, v_ret_deferrable, v_ret_ev
      FROM ottoq_evaluate_return_need(
             v_dispatch.vehicle_id, v_dispatch.sim_run_id, p_sim_clock_now,
             p_tick_minutes, v_new_soc) er;
    -- 0321 (DEFECT 1, db/checks/0240 SecA): refresh the forecast for a vehicle
    -- that is STILL WORKING. Before this, 36 of 36 `active` dispatches carried a
    -- NULL ETA because the only write lived in the branch that also flips status
    -- to 'returning' -- so the forecast could not exist before the decision it is
    -- meant to inform (CLAUDE.md 2.7 asks for a recall_time).
    -- PLACED HERE, not in the 'active' block at L156, because this is AFTER the
    -- tick emitted its own telemetry packet: ottoq_computed_eta_minutes averages
    -- speed over packets with sim_clock_at <= the clock, and at L156 the newest
    -- observation does not exist yet.
    IF v_dispatch.status = 'active' THEN
      PERFORM public.ottoq_refresh_return_eta(
                v_dispatch.vehicle_id, p_sim_run_id, p_sim_clock_now);
    END IF;
    v_should_return := COALESCE(v_ret_should, false);

    -- 0212 (G7): ASK THE WORK SIDE BEFORE THE HANDSHAKE.
    -- CLAUDE.md 2.7: refusal is first-class and triggers re-solve, never an
    -- error. A non-deferrable recall is not offered for refusal.
    IF v_should_return AND v_dispatch.status = 'active' THEN
      SELECT * INTO v_ws FROM public.ottoq_work_side_accepts(
        v_dispatch.vehicle_id, p_sim_run_id, p_sim_clock_now,
        v_ret_trigger, v_ret_urgency, COALESCE(v_ret_deferrable, false));

      IF NOT v_ws.accepted THEN
        IF v_ws.is_new THEN
          SELECT rd.recall_id INTO v_recall_id
            FROM public.ottoq_recall_decisions rd
           WHERE rd.sim_run_id = p_sim_run_id
             AND rd.vehicle_id = v_dispatch.vehicle_id
             AND rd.decided_at_sim = p_sim_clock_now
           ORDER BY rd.decision_seq DESC LIMIT 1;

          -- A refusal that cannot name the decision it refuses is not evidence,
          -- so it is not written and the recall proceeds. Reachable only under
          -- ottoq.dryrun, where the wrapper writes no decision row.
          IF v_recall_id IS NOT NULL THEN
            INSERT INTO public.ottoq_recall_refusals
              (recall_id, sim_run_id, vehicle_id, depot_id, refused_at_sim,
               refused_by, reason_code, retry_after_min, recall_trigger,
               recall_urgency, was_deferrable, evidence, content_hash, data_source)
            VALUES
              (v_recall_id, p_sim_run_id, v_dispatch.vehicle_id,
               (SELECT v.home_depot_id FROM public.vehicles v WHERE v.id = v_dispatch.vehicle_id),
               p_sim_clock_now, 'ottow_dispatcher', v_ws.reason_code,
               v_ws.retry_after_min, v_ret_trigger, v_ret_urgency,
               COALESCE(v_ret_deferrable, false),
               jsonb_build_object('soc', v_new_soc, 'recall_evidence', v_ret_ev),
               md5(v_dispatch.vehicle_id::text || '|'
                   || to_char(p_sim_clock_now AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US') || '|'
                   || v_ws.reason_code || '|' || COALESCE(v_ret_trigger, '-') || '|'
                   || COALESCE(v_ret_urgency, '-') || '|' || v_ws.retry_after_min::text),
               CASE WHEN (SELECT r.run_by FROM public.ottoq_sim_runs r
                           WHERE r.sim_run_id = p_sim_run_id) = 'production_live'
                    THEN 'production' ELSE 'twin' END);

            PERFORM ottoq_record_event(
              p_actor_type    := 'ottow_dispatcher',
              p_actor_id      := 'work_side',
              p_event_type    := 'recall_refused',
              p_entity_type   := 'vehicle',
              p_entity_id     := v_dispatch.vehicle_id,
              p_fleet_operator_id := v_dispatch.v_fleet_op,
              p_depot_id      := (SELECT v.home_depot_id FROM public.vehicles v
                                   WHERE v.id = v_dispatch.vehicle_id),
              p_severity      := 'warning',
              p_payload       := jsonb_build_object(
                                   'reason_code', v_ws.reason_code,
                                   'retry_after_min', v_ws.retry_after_min,
                                   'recall_trigger', v_ret_trigger,
                                   'recall_urgency', v_ret_urgency,
                                   'deferrable', COALESCE(v_ret_deferrable, false)),
              p_sim_run_id    := p_sim_run_id);

            v_should_return := false;
          END IF;
        ELSE
          -- still inside a standing refusal's hold: suppress without a new row
          v_should_return := false;
        END IF;
      END IF;
    END IF;

    IF v_should_return AND v_dispatch.status = 'active' THEN
      -- AP-4: THE RETURN HANDSHAKE. Telemetry was just emitted (the vehicle's "return to
      -- depot" notification). OTTO-Q now books the appointment BEFORE the state flip:
      -- builds the workflow, reserves the stall, communicates the selection back.
      -- 0318: compute ONCE, then label honestly from the same value. The
      -- fallback inlines the dial rather than calling ottoq_return_eta_minutes,
      -- which would re-run the computation that just returned NULL.
      v_eta_computed := public.ottoq_computed_eta_minutes(
                          v_dispatch.vehicle_id,
                          (SELECT COALESCE(vv.home_depot_id, rr.depot_id)
                             FROM public.ottoq_sim_runs rr
                             LEFT JOIN public.vehicles vv ON vv.id = v_dispatch.vehicle_id
                            WHERE rr.sim_run_id = p_sim_run_id),
                          p_sim_run_id, p_sim_clock_now);
      v_eta_min := COALESCE(v_eta_computed,
                            GREATEST(1, COALESCE(ottoq_policy_get(p_sim_run_id,'return_eta_minutes',30), 30)));
      BEGIN
        v_book := ottoq_book_appointment(
                  v_dispatch.vehicle_id, p_sim_run_id, p_sim_clock_now,
                  v_ret_trigger, v_ret_urgency, COALESCE(v_ret_deferrable, false),
                  v_eta_min, v_new_soc, NULL);
      EXCEPTION WHEN OTHERS THEN
        -- one bad vehicle must never abort the whole telemetry step (tick hot path)
        v_book := jsonb_build_object('secured', false, 'reason', 'booking_error');
      END;

      -- Gate departure on securing a resource. Non-deferrable needs (reserve breach, fault)
      -- depart immediately regardless; a deferrable need with no free stall keeps the car
      -- deployed and earning, retrying next tick. That deferral is bounded by the SoC ladder:
      -- as charge drains, the trigger escalates to a non-deferrable low_soc_reserve return
      -- before any safety margin is at risk.
      IF COALESCE((v_book->>'secured')::boolean, false) OR NOT COALESCE(v_ret_deferrable, false) THEN
        UPDATE ottoq_vehicle_dispatches
           SET status = 'returning',
               return_trigger = COALESCE(v_ret_trigger, 'need_unspecified'),
               returning_started_at = p_sim_clock_now,
               return_eta_minutes   = v_eta_min,
               scheduled_return_at  = p_sim_clock_now + (v_eta_min || ' minutes')::interval,
               -- 0009 (DEFECT 2a). The SECOND writer, and the destructive one: it does not
               -- adjust the plan, it REPLACES it. Measured 2026-08-05 on live data: 116 of 116
               -- dispatch rows that reached this branch ended with
               -- scheduled_return_at = returning_started_at + EXACTLY 30 min, one distinct
               -- ETA value across the whole table. Grading that against the arrival it itself
               -- caused is circular; there was no training signal. The write is left standing
               -- (twelve other live functions READ this column as "current best arrival
               -- estimate"), but the plan is now preserved independently in planned_return_at,
               -- and the refresh is stamped, so plan / live-ETA / actual are three separate
               -- observable facts. CLOCK DOMAIN: every timestamp written here is the SIM
               -- clock. created_at is the ONLY wall-clock column on this table.
               eta_refreshed_at     = p_sim_clock_now,
               eta_source           = CASE WHEN v_eta_computed IS NOT NULL
                                      THEN 'computed:distance_over_speed'
                                      ELSE 'policy_constant:return_eta_minutes' END,
               return_evidence = COALESCE(v_ret_ev, '{}'::jsonb) || jsonb_build_object(
                 'decided_at', p_sim_clock_now,
                 'soc_at_decision', v_new_soc,
                 'reserve', v_min_soc_thresh,
                 'eta_minutes_is_a_parameter', (v_eta_computed IS NULL),
                 -- 0009: the divergence, computed at the exact moment of the refresh, so a
                 -- later reader never has to reconstruct what the plan had been.
                 'eta_source', CASE WHEN v_eta_computed IS NOT NULL
                                 THEN 'computed:distance_over_speed'
                                 ELSE 'policy_constant:return_eta_minutes' END,
                 'planned_return_at', planned_return_at,
                 'live_return_at', p_sim_clock_now + (v_eta_min || ' minutes')::interval,
                 'plan_minus_live_min', ROUND((EXTRACT(EPOCH FROM (planned_return_at
                     - (p_sim_clock_now + (v_eta_min || ' minutes')::interval))) / 60.0)::numeric, 1),
                 'appointment', v_book)
         WHERE dispatch_id = v_dispatch.dispatch_id;
        UPDATE vehicles SET current_state = 'en_route_to_depot'::vehicle_state,
                            last_state_change = p_sim_clock_now
         WHERE id = v_dispatch.vehicle_id;
        out_action := CASE WHEN COALESCE((v_book->>'secured')::boolean, false)
                           THEN 'returning:booked=' || COALESCE(v_book->>'stall_type','?')
                           ELSE 'returning:unbooked_nondeferrable' END;
      ELSE
        out_action := 'deferred:no_capacity';
      END IF;
    ELSIF v_dispatch.status = 'returning'
          AND p_sim_clock_now >= COALESCE(
                v_dispatch.returning_started_at
                  + (COALESCE(v_dispatch.return_eta_minutes, 30) || ' minutes')::interval,
                v_dispatch.scheduled_return_at + INTERVAL '5 minutes') THEN
      v_webhook_id := ottoq_sim_emit_arrival_webhook(
        v_dispatch.vehicle_id, p_sim_run_id, p_sim_clock_now,
        v_dispatch.dispatch_id, v_new_soc);

      UPDATE ottoq_vehicle_dispatches
         SET status = 'completed',
             actual_return_at = p_sim_clock_now,
             actual_duration_min = EXTRACT(EPOCH FROM (p_sim_clock_now - dispatched_at)) / 60.0,
             arrival_jitter_min = EXTRACT(EPOCH FROM (p_sim_clock_now - COALESCE(
                 returning_started_at + (COALESCE(return_eta_minutes,30) || ' minutes')::interval,
                 scheduled_return_at))) / 60.0,
             soc_at_return_pct = v_new_soc,
             miles_driven = COALESCE(miles_driven, 0)  -- 0690 (G406): the miles accrued tick by tick
       WHERE dispatch_id = v_dispatch.dispatch_id;
      UPDATE vehicles SET current_state = 'arrived_at_gate'::vehicle_state,
                          current_soc = GREATEST(2, LEAST(100, v_new_soc)),  -- 0486 (G219): the drain landed on the way in
                          last_state_change = p_sim_clock_now
       WHERE id = v_dispatch.vehicle_id;
      out_action := 'arrived:webhook=' || COALESCE(LEFT(v_webhook_id::text, 8), 'null');
    ELSE
      out_action := 'advancing';
    END IF;

    out_vehicle_id := v_dispatch.vehicle_id;
    out_new_soc := v_new_soc;
    out_new_state := (SELECT current_state::text FROM vehicles WHERE id = v_dispatch.vehicle_id);
    RETURN NEXT;
  END LOOP;
END;
$function$;
-- @@ function twin.ottoq_sim_solar_elevation_deg(p_at_utc timestamp with time zone, p_lat numeric, p_lng numeric)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_solar_elevation_deg(p_at_utc timestamp with time zone, p_lat numeric, p_lng numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_n            INTEGER;          -- day-of-year (1-366)
  v_decl_deg     NUMERIC;          -- solar declination
  v_lst_hours    NUMERIC;          -- local solar time, decimal hours
  v_hour_ang_deg NUMERIC;
  v_lat_rad      NUMERIC;
  v_decl_rad     NUMERIC;
  v_hra_rad      NUMERIC;
  v_sin_elev     NUMERIC;
  v_elev_rad     NUMERIC;
BEGIN
  v_n        := EXTRACT(DOY FROM p_at_utc);
  v_decl_deg := 23.45 * SIN(RADIANS(360.0/365.0 * (v_n + 284)));

  -- Local solar time ≈ UTC hour + lng/15 + EoT (we ignore EoT for ±15 min)
  v_lst_hours := EXTRACT(EPOCH FROM p_at_utc) / 3600.0;
  v_lst_hours := (v_lst_hours + p_lng / 15.0) - FLOOR((v_lst_hours + p_lng / 15.0) / 24) * 24;

  v_hour_ang_deg := 15.0 * (v_lst_hours - 12.0);

  v_lat_rad  := RADIANS(p_lat);
  v_decl_rad := RADIANS(v_decl_deg);
  v_hra_rad  := RADIANS(v_hour_ang_deg);

  v_sin_elev := SIN(v_lat_rad) * SIN(v_decl_rad)
              + COS(v_lat_rad) * COS(v_decl_rad) * COS(v_hra_rad);

  v_elev_rad := ASIN(GREATEST(-1.0, LEAST(1.0, v_sin_elev)));
  RETURN DEGREES(v_elev_rad);
END;
$function$;
-- @@ function twin.ottoq_sim_clear_sky_ghi_wm2(p_elev_deg numeric)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_clear_sky_ghi_wm2(p_elev_deg numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_air_mass   NUMERIC;
  v_solar_const NUMERIC := 1361.0;        -- TOA solar constant W/m²
  v_ghi        NUMERIC;
BEGIN
  IF p_elev_deg <= 0 THEN
    RETURN 0;                              -- below horizon
  END IF;

  -- Air mass (Kasten-Young for low elevations)
  v_air_mass := 1.0 / (SIN(RADIANS(p_elev_deg))
                       + 0.50572 * POWER(GREATEST(p_elev_deg + 6.07995, 0.01), -1.6364));

  -- Atmospheric attenuation × cos(zenith) = sin(elevation)
  v_ghi := v_solar_const
         * POWER(0.7, POWER(v_air_mass, 0.678))
         * SIN(RADIANS(p_elev_deg));

  RETURN GREATEST(0, v_ghi);
END;
$function$;
-- @@ function twin.ottoq_sim_cloud_attenuated_ghi(p_clear_sky_ghi numeric, p_cloud_pct numeric)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_cloud_attenuated_ghi(p_clear_sky_ghi numeric, p_cloud_pct numeric)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
  SELECT GREATEST(0,
    p_clear_sky_ghi * (1.0 - 0.75 * POWER(LEAST(p_cloud_pct, 100) / 100.0, 3.4)));
$function$;
-- @@ function twin.ottoq_sim_poa_irradiance(p_ghi_wm2 numeric, p_elev_deg numeric, p_panel_tilt_deg numeric, p_panel_azimuth numeric, p_solar_azimuth numeric)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_poa_irradiance(p_ghi_wm2 numeric, p_elev_deg numeric, p_panel_tilt_deg numeric, p_panel_azimuth numeric, p_solar_azimuth numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_zenith_deg   NUMERIC;
  v_aoi_cos      NUMERIC;          -- cos of angle of incidence
BEGIN
  IF p_elev_deg <= 0 OR p_ghi_wm2 <= 0 THEN
    RETURN 0;
  END IF;
  v_zenith_deg := 90.0 - p_elev_deg;

  -- Simplified isotropic AOI: cos(AOI) = cos(zenith)*cos(tilt) + sin(zenith)*sin(tilt)*cos(azim_diff)
  v_aoi_cos := COS(RADIANS(v_zenith_deg)) * COS(RADIANS(p_panel_tilt_deg))
             + SIN(RADIANS(v_zenith_deg)) * SIN(RADIANS(p_panel_tilt_deg))
               * COS(RADIANS(p_solar_azimuth - p_panel_azimuth));

  -- POA = GHI × max(cos_AOI, 0) / cos(zenith)  — simplified (ignore diffuse)
  IF v_aoi_cos <= 0 OR COS(RADIANS(v_zenith_deg)) < 0.05 THEN
    RETURN 0;
  END IF;

  RETURN p_ghi_wm2 * (v_aoi_cos / COS(RADIANS(v_zenith_deg)));
END;
$function$;
-- @@ function twin.ottoq_sim_cell_temp_c(p_ambient_c numeric, p_poa_wm2 numeric, p_wind_kmh numeric)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_cell_temp_c(p_ambient_c numeric, p_poa_wm2 numeric, p_wind_kmh numeric DEFAULT 5)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
  -- T_cell = T_amb + (NOCT - 20) × POA / 800 × wind_factor
  -- NOCT = 45°C typical; wind reduces cell temp slightly
  SELECT p_ambient_c
       + (45.0 - 20.0) * (p_poa_wm2 / 800.0)
         * GREATEST(0.65, 1.0 - 0.02 * LEAST(p_wind_kmh, 20));
$function$;
-- @@ function twin.ottoq_sim_pv_dc_power_kw(p_nameplate_dc_kw numeric, p_poa_wm2 numeric, p_cell_temp_c numeric, p_soiling numeric, p_temp_coeff numeric)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_pv_dc_power_kw(p_nameplate_dc_kw numeric, p_poa_wm2 numeric, p_cell_temp_c numeric, p_soiling numeric, p_temp_coeff numeric DEFAULT '-0.0040'::numeric)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
  SELECT GREATEST(0,
    p_nameplate_dc_kw
      * (p_poa_wm2 / 1000.0)
      * (1.0 + p_temp_coeff * (p_cell_temp_c - 25.0))
      * p_soiling);
$function$;
-- @@ function twin.ottoq_sim_sample_cloud_pct(p_seed bigint, p_salt text, p_hour_of_day integer)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_sample_cloud_pct(p_seed bigint, p_salt text, p_hour_of_day integer)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_u1      NUMERIC;
  v_u2      NUMERIC;
  v_beta    NUMERIC;
  v_hour_factor NUMERIC;
BEGIN
  -- Beta(α=2, β=2) gives a symmetric distribution around 50% — Nashville annual mean
  -- Realized via ratio-of-uniforms approximation
  v_u1 := GREATEST(1e-9, ottoq_sim_seeded_random(p_seed, p_salt || '_c1'));
  v_u2 := GREATEST(1e-9, ottoq_sim_seeded_random(p_seed, p_salt || '_c2'));

  -- Two-uniform Beta-like sampler
  v_beta := POWER(v_u1, 1.0/2.0);
  v_beta := v_beta / (v_beta + POWER(v_u2, 1.0/2.0));

  -- Diurnal bias: afternoon cloud development +10%, dawn -10%
  v_hour_factor := CASE
    WHEN p_hour_of_day BETWEEN 13 AND 18 THEN  0.10
    WHEN p_hour_of_day BETWEEN  4 AND  8 THEN -0.10
    ELSE 0
  END;

  RETURN GREATEST(0, LEAST(100, (v_beta + v_hour_factor) * 100));
END;
$function$;
-- @@ function twin.ottoq_sim_advance_weather_and_solar(p_depot_id uuid, p_sim_run_id uuid, p_sim_clock_now timestamp with time zone)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_advance_weather_and_solar(p_depot_id uuid, p_sim_run_id uuid, p_sim_clock_now timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_seed             BIGINT;
  v_salt             TEXT;
  v_depot            RECORD;
  v_lat              NUMERIC;
  v_lng              NUMERIC;
  v_elev_deg         NUMERIC;
  v_azim_deg         NUMERIC;
  v_clear_ghi        NUMERIC;
  v_cloud_pct        NUMERIC;
  v_ambient_c        NUMERIC;
  v_wind_kmh         NUMERIC;
  v_wind_dir_deg     NUMERIC;
  v_humidity_pct     NUMERIC;
  v_precip_state     TEXT;
  v_precip_mm        NUMERIC;
  v_prev_precip      TEXT;
  v_actual_ghi       NUMERIC;
  v_dni              NUMERIC;
  v_dhi              NUMERIC;
  v_poa_avg          NUMERIC;
  v_label            TEXT;
  v_weather_id       UUID := gen_random_uuid();
  v_is_day           BOOLEAN;
  v_hour_of_day      INTEGER;
  v_canopy           RECORD;
  v_canopy_poa       NUMERIC;
  v_cell_temp        NUMERIC;
  v_new_soiling      NUMERIC;
  v_prev_soiling     NUMERIC;
  v_dc_kw            NUMERIC;
  v_ac_kw            NUMERIC;
  v_clipped          BOOLEAN;
  v_blip             BOOLEAN;
  v_inv_eff          NUMERIC := 0.96;
BEGIN
  -- Depot location
  SELECT origin_lat, origin_lng INTO v_lat, v_lng
    FROM depots WHERE id = p_depot_id;
  IF NOT FOUND THEN
    -- Fall back to Nashville flagship
    v_lat := 36.1397; v_lng := -86.7728;
  END IF;

  v_seed        := abs(hashtextextended(p_depot_id::text || twin.ottoq_sim_clock_salt(p_sim_run_id, p_sim_clock_now) || 'wx', 17));
  v_salt        := to_char(p_sim_clock_now, 'YYYYMMDD-HH24MISS');
  v_hour_of_day := EXTRACT(HOUR FROM p_sim_clock_now AT TIME ZONE 'America/Chicago')::int;

  -- Sun geometry
  v_elev_deg := ottoq_sim_solar_elevation_deg(p_sim_clock_now, v_lat, v_lng);
  -- Azimuth (simplified — symmetric around solar noon, south-positive)
  v_azim_deg := 180 + 15.0 * (v_hour_of_day - 12);
  v_is_day   := v_elev_deg > 0;

  -- Clear-sky GHI
  v_clear_ghi := ottoq_sim_clear_sky_ghi_wm2(v_elev_deg);

  -- Sample atmospheric state
  v_cloud_pct := COALESCE(ottoq_twin_deal(p_sim_run_id, 'cloud_cover_pct', 'global', p_sim_clock_now, (p_sim_clock_now::date - DATE '2020-01-01'), 0), ottoq_sim_sample_cloud_pct(v_seed, v_salt, v_hour_of_day));
  -- A.8: shape through the run's variability profile (cloud has no calibration
  -- row, so pass explicit mean 50 so Chaos spread widens around the real center),
  -- then re-clamp to a valid 0-100 range.
  v_cloud_pct := GREATEST(0, LEAST(100,
    ottoq_apply_profile(p_sim_run_id, 'cloud_cover_pct', v_cloud_pct, 50)));

  -- per-DAY ambient regime via the lifespan card engine: one draw per sim-day from the real
  -- NOAA distribution, HELD across the day; the diurnal swing below adds intra-day variation.
  v_ambient_c := COALESCE(
    ottoq_twin_deal(p_sim_run_id, 'ambient_temp_c', 'global', p_sim_clock_now,
      (p_sim_clock_now::date - DATE '2020-01-01'), 0,
      'month:' || to_char(p_sim_clock_now AT TIME ZONE 'America/Chicago', 'MM')),
    22);

  -- Feed-agent ambient_temp_c: AR(1) day-to-day persistence (NOAA-computed
  -- phi=0.72). Blend the fresh marginal draw with yesterday's realized
  -- anomaly; variance-preserving; card value updated so tomorrow chains off
  -- realized state. Idempotent via the ar1 meta flag.
  DECLARE
    v_plan_t jsonb := ottoq_feed_plan('ambient_temp_c');
    v_phi numeric; v_mu numeric; v_mu_y numeric; v_yest numeric;
    v_mo text; v_mo_y text; v_blend numeric; v_meta_flag text;
    v_day_n int := (p_sim_clock_now::date - DATE '2020-01-01');
  BEGIN
    IF v_plan_t IS NOT NULL THEN
      SELECT meta->>'ar1' INTO v_meta_flag FROM ottoq_variability_cards
       WHERE sim_run_id = p_sim_run_id AND var_key = 'ambient_temp_c'
         AND scope_instance = 'global' AND bucket_key = 'day:' || v_day_n;
      IF v_meta_flag IS NULL THEN
        v_phi  := COALESCE((v_plan_t->>'ar1_phi')::numeric, 0.72);
        v_mo   := to_char(p_sim_clock_now AT TIME ZONE 'America/Chicago', 'MM');
        v_mo_y := to_char((p_sim_clock_now - interval '1 day') AT TIME ZONE 'America/Chicago', 'MM');
        v_mu   := (v_plan_t->'monthly'->v_mo->>'mean_c')::numeric;
        v_mu_y := COALESCE((v_plan_t->'monthly'->v_mo_y->>'mean_c')::numeric, v_mu);
        SELECT value INTO v_yest FROM ottoq_variability_cards
         WHERE sim_run_id = p_sim_run_id AND var_key = 'ambient_temp_c'
           AND scope_instance = 'global' AND bucket_key = 'day:' || (v_day_n - 1);
        IF v_yest IS NOT NULL AND v_mu IS NOT NULL THEN
          v_blend := v_mu + v_phi * (v_yest - v_mu_y)
                   + sqrt(1 - v_phi * v_phi) * (v_ambient_c - v_mu);
          v_blend := LEAST(GREATEST(v_blend, (v_plan_t->'monthly'->v_mo->>'record_lo')::numeric),
                            (v_plan_t->'monthly'->v_mo->>'record_hi')::numeric);
          UPDATE ottoq_variability_cards
             SET value = round(v_blend, 2),
                 meta = COALESCE(meta, '{}'::jsonb) || jsonb_build_object('ar1', true, 'raw_draw', round(v_ambient_c, 2))
           WHERE sim_run_id = p_sim_run_id AND var_key = 'ambient_temp_c'
             AND scope_instance = 'global' AND bucket_key = 'day:' || v_day_n;
          v_ambient_c := v_blend;
        ELSE
          UPDATE ottoq_variability_cards
             SET meta = COALESCE(meta, '{}'::jsonb) || jsonb_build_object('ar1', true)
           WHERE sim_run_id = p_sim_run_id AND var_key = 'ambient_temp_c'
             AND scope_instance = 'global' AND bucket_key = 'day:' || v_day_n;
        END IF;
      END IF;
    END IF;
  END;

  -- Add diurnal temperature swing: ±5°C peak-to-peak around the calibrated mean
  v_ambient_c := v_ambient_c
               + COALESCE((ottoq_feed_plan('ambient_temp_c')->'monthly'
                   ->to_char(p_sim_clock_now AT TIME ZONE 'America/Chicago', 'MM')->>'diurnal_half_c')::numeric, 5.0)
                 * COS(RADIANS(15.0 * (v_hour_of_day - 14)));   -- peak 2 PM, trough 2 AM (0436: was SIN, which peaked at 8 PM)

  /* A.8, as 0449 (G180) re-centred it: shape ambient through the run's profile around this month's normal for
     this hour (the feed plan's mean_c plus the diurnal term above), not the all-year calibration mean (17.5 C),
     which pushed every September hour up by 0.4 x (T - 17.5) under busy_day's spread 1.4. Then hold the value
     inside the month's record, unless the profile declares its own ambient knobs: a deliberate heat or cold
     scenario keeps its shift/floor/ceiling; variance widening alone never makes a day the record lacks. */
  DECLARE
    v_mo_t   jsonb := ottoq_feed_plan('ambient_temp_c') -> 'monthly'
                        -> to_char(p_sim_clock_now AT TIME ZONE 'America/Chicago', 'MM');
    v_clim_c numeric;
    v_amb_kn jsonb;
  BEGIN
    v_clim_c := (v_mo_t ->> 'mean_c')::numeric
              + COALESCE((v_mo_t ->> 'diurnal_half_c')::numeric, 5.0) * COS(RADIANS(15.0 * (v_hour_of_day - 14)));
    v_ambient_c := ottoq_apply_profile(p_sim_run_id, 'ambient_temp_c', v_ambient_c, v_clim_c);
    SELECT knobs -> 'ambient_temp_c' INTO v_amb_kn FROM ottoq_variability_profiles WHERE sim_run_id = p_sim_run_id;
    IF v_mo_t IS NOT NULL AND COALESCE(v_amb_kn, '{}'::jsonb) = '{}'::jsonb THEN
      v_ambient_c := LEAST(GREATEST(v_ambient_c, (v_mo_t ->> 'record_lo')::numeric),
                           (v_mo_t ->> 'record_hi')::numeric);
    END IF;
  END;

  v_wind_kmh := COALESCE(
    ottoq_twin_deal(p_sim_run_id, 'wind_speed_kmh', 'global', p_sim_clock_now, (p_sim_clock_now::date - DATE '2020-01-01'), 0),
    ottoq_sample_calibrated('wind_speed_kmh', 'global', v_seed, 'wind:' || v_salt),
    7);
  -- A.8: shape wind (calibration mean 7.63); clamp non-negative.
  v_wind_kmh := GREATEST(0, ottoq_apply_profile(p_sim_run_id, 'wind_speed_kmh', v_wind_kmh));
  v_wind_dir_deg := ottoq_sim_seeded_random(v_seed, 'wd') * 360;
  -- (A.10 humidity shaping applied just below, after the base clamp)
  v_humidity_pct := 40 + ottoq_sim_seeded_random(v_seed, 'rh') * 50
                  + (v_cloud_pct - 50) * 0.2;
  v_humidity_pct := GREATEST(10, LEAST(100,
    ottoq_apply_profile(p_sim_run_id, 'humidity_pct', v_humidity_pct, 65)));

  -- Get prev precip state
  SELECT precip_state INTO v_prev_precip
    FROM ottoq_weather_snapshots
   WHERE COALESCE(sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid)
       = COALESCE(p_sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid)  /* 0134 */
     AND depot_id = p_depot_id
     AND sim_clock_at < p_sim_clock_now
   ORDER BY sim_clock_at DESC, snapshot_id DESC LIMIT 1;
  v_prev_precip := COALESCE(v_prev_precip, 'dry');

  SELECT * INTO v_precip_state, v_precip_mm
    FROM ottoq_sim_sample_precip_state(v_seed, v_salt, v_prev_precip, v_cloud_pct,
           ottoq_profile_rate_mult(p_sim_run_id, 'precip'),
           p_sim_run_id, p_sim_clock_now);   -- feed-agent: daily-budget disaggregation

  -- rain implies overcast: raise cloud before GHI attenuation (computed below)
  IF v_precip_mm > 0 THEN
    v_cloud_pct := GREATEST(v_cloud_pct, 75);
  END IF;

  -- Actual GHI after cloud attenuation
  v_actual_ghi := ottoq_sim_cloud_attenuated_ghi(v_clear_ghi, v_cloud_pct);
  v_dni        := v_actual_ghi * 0.7;     -- approximation
  v_dhi        := v_actual_ghi * 0.3;

  -- POA (depot-level average, south-facing 30° tilt) for snapshot record
  v_poa_avg := ottoq_sim_poa_irradiance(v_actual_ghi, v_elev_deg, 30, 180, v_azim_deg);

  -- Conditions label
  v_label := CASE
    WHEN v_precip_state IN ('storm','heavy_rain') THEN 'storm'
    WHEN v_precip_state IN ('rain','drizzle')     THEN 'rain'
    WHEN v_cloud_pct > 80                          THEN 'overcast'
    WHEN v_cloud_pct > 40                          THEN 'partly_cloudy'
    WHEN v_humidity_pct > 90 AND v_ambient_c < 15  THEN 'foggy'
    ELSE                                                 'clear' END;

  -- Insert weather snapshot
  INSERT INTO ottoq_weather_snapshots (
    snapshot_id, depot_id, sim_run_id, sim_clock_at,
    solar_elevation_deg, solar_azimuth_deg, air_mass,
    ambient_temp_c, cloud_cover_pct, wind_speed_kmh, wind_direction_deg,
    relative_humidity_pct, precip_mm_per_hr, precip_state,
    ghi_wm2, dni_wm2, dhi_wm2, poa_wm2,
    conditions_label, is_daytime, data_source
  ) VALUES (
    v_weather_id, p_depot_id, p_sim_run_id, p_sim_clock_now,
    ROUND(v_elev_deg::numeric, 2), ROUND(v_azim_deg::numeric, 2),
    CASE WHEN v_elev_deg > 0 THEN ROUND((1.0 / SIN(RADIANS(v_elev_deg)))::numeric, 2) ELSE NULL END,
    ROUND(v_ambient_c::numeric, 1), ROUND(v_cloud_pct::numeric, 1),
    ROUND(v_wind_kmh::numeric, 1), ROUND(v_wind_dir_deg::numeric, 0),
    ROUND(v_humidity_pct::numeric, 1), ROUND(v_precip_mm::numeric, 2), v_precip_state,
    ROUND(v_actual_ghi::numeric, 1), ROUND(v_dni::numeric, 1), ROUND(v_dhi::numeric, 1),
    ROUND(v_poa_avg::numeric, 1),
    v_label, v_is_day, 'twin');

  -- Emit anomaly if storm or extreme temp
  IF v_label = 'storm' OR v_ambient_c > 38 OR v_ambient_c < -10 THEN
    PERFORM ottoq_record_event(
      p_actor_type    := 'external_sensor',
      p_actor_id      := 'twin_weather_generator',
      p_event_type    := 'twin.weather_anomaly',
      p_entity_type   := 'depot',
      p_entity_id     := p_depot_id,
      p_payload       := jsonb_build_object(
        'label', v_label, 'temp_c', v_ambient_c, 'precip_mm_hr', v_precip_mm,
        'wind_kmh', v_wind_kmh, 'cloud_pct', v_cloud_pct),
      p_severity      := 'warning',
      p_ingest_source := 'twin',
      p_data_source   := 'twin',
      p_sim_run_id    := p_sim_run_id);
  END IF;

  -- ----- Now compute per-canopy solar output -----
  FOR v_canopy IN SELECT * FROM ottoq_canopy_state WHERE depot_id = p_depot_id LOOP

    -- Soiling: drifts down ~0.05% per hour on dry days, resets toward 1.0 after rain
    -- 0479 (G214): this run's own soiling, never the depot row another run left behind
    v_prev_soiling := twin.ottoq_sim_canopy_soiling(p_sim_run_id, p_depot_id, v_canopy.canopy_code, p_sim_clock_now);
    IF v_precip_mm >= 1.0 THEN
      v_new_soiling := LEAST(1.00, v_prev_soiling + 0.03);
    ELSE
      v_new_soiling := GREATEST(0.85,
        v_prev_soiling - 0.0005 * (1 + ottoq_sim_seeded_random(v_seed, 'so:' || v_canopy.canopy_code)));
    END IF;
    -- A.10: solar_soiling knob — shape the soiling derate (mean 1.0 = clean), clamp valid range
    v_new_soiling := GREATEST(0.40, LEAST(1.00,
      ottoq_apply_profile(p_sim_run_id, 'solar_soiling', v_new_soiling, 1.0)));

    v_canopy_poa := ottoq_sim_poa_irradiance(
      v_actual_ghi, v_elev_deg, v_canopy.tilt_deg, v_canopy.azimuth_deg, v_azim_deg);
    v_cell_temp  := ottoq_sim_cell_temp_c(v_ambient_c, v_canopy_poa, v_wind_kmh);

    v_dc_kw := ottoq_sim_pv_dc_power_kw(
      v_canopy.nameplate_dc_kw, v_canopy_poa, v_cell_temp, v_new_soiling);

    -- Inverter blip — rare random momentary fault
    v_blip := ottoq_sim_seeded_random(v_seed, 'blip:' || v_canopy.canopy_code) < 0.005;

    IF v_blip THEN
      v_ac_kw   := 0;
      v_clipped := FALSE;
    ELSE
      v_ac_kw   := v_dc_kw * v_inv_eff;
      v_clipped := v_ac_kw > v_canopy.nameplate_ac_kw;
      IF v_clipped THEN v_ac_kw := v_canopy.nameplate_ac_kw; END IF;
    END IF;

    INSERT INTO ottoq_solar_output (
      output_id, depot_id, sim_run_id, weather_snapshot_id,
      canopy_structure_id, canopy_code, sim_clock_at,
      irradiance_poa_wm2, ambient_temp_c, cell_temp_c, soiling_factor,
      nameplate_dc_kw, nameplate_ac_kw,
      dc_power_kw, ac_power_kw, inverter_efficiency,
      inverter_clipped, inverter_blip, data_source
    ) VALUES (
      gen_random_uuid(), p_depot_id, p_sim_run_id, v_weather_id,
      v_canopy.structure_id, v_canopy.canopy_code, p_sim_clock_now,
      ROUND(v_canopy_poa::numeric, 1),
      ROUND(v_ambient_c::numeric, 1),
      ROUND(v_cell_temp::numeric, 1),
      ROUND(v_new_soiling::numeric, 4),
      v_canopy.nameplate_dc_kw, v_canopy.nameplate_ac_kw,
      ROUND(v_dc_kw::numeric, 2), ROUND(v_ac_kw::numeric, 2), v_inv_eff,
      v_clipped, v_blip, 'twin');

    -- Persist soiling state
    UPDATE ottoq_canopy_state
       SET current_soiling = v_new_soiling,
           last_rain_clean_at = CASE WHEN v_precip_mm >= 1.0 THEN p_sim_clock_now
                                      ELSE last_rain_clean_at END,
           last_updated_at = NOW()
     WHERE canopy_code = v_canopy.canopy_code;

    IF v_blip THEN
      PERFORM ottoq_record_event(
        p_actor_type    := 'solar_controller',
        p_actor_id      := 'twin_solar_canopy_' || v_canopy.canopy_code,
        p_event_type    := 'twin.solar_inverter_blip',
        p_entity_type   := 'structure',
        p_entity_id     := v_canopy.structure_id,
        p_payload       := jsonb_build_object(
          'canopy_code', v_canopy.canopy_code,
          'dc_kw_at_fault', v_dc_kw,
          'lost_ac_kw', v_dc_kw * v_inv_eff),
        p_severity      := 'warning',
        p_ingest_source := 'twin',
        p_data_source   := 'twin',
        p_sim_run_id    := p_sim_run_id);
    END IF;
  END LOOP;

  -- Lightweight tick event (debug-severity, doesn't pollute info log)
  PERFORM ottoq_record_event(
    p_actor_type    := 'external_sensor',
    p_actor_id      := 'twin_weather_generator',
    p_event_type    := 'twin.weather_tick',
    p_entity_type   := 'depot',
    p_entity_id     := p_depot_id,
    p_payload       := jsonb_build_object(
      'weather_snapshot_id', v_weather_id,
      'label',     v_label,
      'temp_c',    ROUND(v_ambient_c::numeric, 1),
      'cloud_pct', ROUND(v_cloud_pct::numeric, 1),
      'ghi_wm2',   ROUND(v_actual_ghi::numeric, 1),
      'precip',    v_precip_state),
    p_severity      := 'debug',
    p_ingest_source := 'twin',
    p_data_source   := 'twin',
    p_sim_run_id    := p_sim_run_id);

  RETURN v_weather_id;
END;
$function$;
-- @@ function twin.ottoq_sim_bess_compute_max_power_kw(p_bess_id uuid, p_direction text, p_temp_c numeric)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_bess_compute_max_power_kw(p_bess_id uuid, p_direction text, p_temp_c numeric DEFAULT NULL::numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v               ottoq_bess_units%ROWTYPE;
  v_nameplate     NUMERIC;
  v_soc_factor    NUMERIC := 1.0;
  v_soh_factor    NUMERIC;
  v_temp_factor   NUMERIC := 1.0;
  v_temp          NUMERIC;
BEGIN
  SELECT * INTO v FROM ottoq_bess_units WHERE bess_id = p_bess_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  v_temp := COALESCE(p_temp_c, v.current_temperature_c, 25);

  IF p_direction = 'charge' THEN
    v_nameplate := v.max_charge_kw;
    -- Taper as we approach ceiling
    IF v.current_soc_pct > 90 THEN
      v_soc_factor := GREATEST(0, (v.soc_max_ceiling_pct - v.current_soc_pct)
                                   / (v.soc_max_ceiling_pct - 90));
    END IF;
  ELSE
    v_nameplate := v.max_discharge_kw;
    -- Taper as we approach floor
    IF v.current_soc_pct < 15 THEN
      v_soc_factor := GREATEST(0, (v.current_soc_pct - v.soc_min_floor_pct)
                                   / (15 - v.soc_min_floor_pct));
    END IF;
  END IF;

  v_soh_factor := COALESCE(v.current_soh_pct, 100) / 100.0;

  -- Thermal derate
  IF v_temp > 45 THEN
    v_temp_factor := GREATEST(0.3, 1.0 - (v_temp - 45) * 0.02);
  ELSIF v_temp < 5 THEN
    v_temp_factor := GREATEST(0.3, 1.0 - (5 - v_temp) * 0.025);
  END IF;

  RETURN GREATEST(0, v_nameplate * v_soc_factor * v_soh_factor * v_temp_factor);
END;
$function$;
-- @@ function twin.ottoq_sim_bess_apply_degradation(p_bess_id uuid, p_tick_minutes numeric, p_kwh_throughput numeric, p_seed bigint)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_bess_apply_degradation(p_bess_id uuid, p_tick_minutes numeric, p_kwh_throughput numeric, p_seed bigint)
 RETURNS numeric
 LANGUAGE plpgsql
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_capacity       NUMERIC;
  v_fce_delta      NUMERIC;
  v_cycle_fade     NUMERIC;
  v_cal_fade       NUMERIC;
  v_noise          NUMERIC;
  v_delta_soh      NUMERIC;
BEGIN
  SELECT capacity_kwh INTO v_capacity FROM ottoq_bess_units WHERE bess_id = p_bess_id;
  IF v_capacity IS NULL OR v_capacity = 0 THEN RETURN 0; END IF;

  -- FCE = full-cycle equivalent (kWh throughput / (2 × capacity))
  v_fce_delta := p_kwh_throughput / (2.0 * v_capacity);

  -- Cycle fade: 0.005% per FCE × small noise
  v_noise      := 0.9 + ottoq_sim_seeded_random(p_seed, 'soh') * 0.2;
  v_cycle_fade := -0.00005 * v_fce_delta * v_noise * 100;     -- in % units

  -- Calendar fade: 0.5%/yr → per-minute = 0.5/525600
  v_cal_fade   := -(0.5 / 525600.0) * p_tick_minutes;

  v_delta_soh  := v_cycle_fade + v_cal_fade;

  -- Apply to unit
  UPDATE ottoq_bess_units
     SET current_soh_pct      = GREATEST(60, current_soh_pct + v_delta_soh),
         current_cycle_count  = current_cycle_count + v_fce_delta,
         lifetime_kwh_charged = lifetime_kwh_charged
                              + GREATEST(0, p_kwh_throughput / 2.0),       -- half is charge
         lifetime_kwh_discharged = lifetime_kwh_discharged
                                  + GREATEST(0, p_kwh_throughput / 2.0),
         updated_at = NOW()
   WHERE bess_id = p_bess_id;

  RETURN v_delta_soh;
END;
$function$;
-- @@ function twin.ottoq_sim_bess_step(p_bess_id uuid, p_sim_run_id uuid, p_sim_clock_now timestamp with time zone, p_tick_minutes numeric, p_target_power_kw numeric, p_ambient_temp_c numeric, p_dispatch_reason text)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_bess_step(p_bess_id uuid, p_sim_run_id uuid, p_sim_clock_now timestamp with time zone, p_tick_minutes numeric, p_target_power_kw numeric, p_ambient_temp_c numeric DEFAULT NULL::numeric, p_dispatch_reason text DEFAULT 'manual'::text)
 RETURNS TABLE(out_actual_power_kw numeric, out_soc_pct_new numeric, out_temp_c_new numeric, out_soh_pct_new numeric, out_thermal_derated boolean, out_soc_limited boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v              ottoq_bess_units%ROWTYPE;
  v_seed         BIGINT;
  v_max_kw       NUMERIC;
  v_actual_kw    NUMERIC;
  v_kwh_delta    NUMERIC;
  v_one_way_eff  NUMERIC;
  v_thermal_derated BOOLEAN := FALSE;
  v_soc_limited     BOOLEAN := FALSE;
  v_new_soc_kwh  NUMERIC;
  v_new_soc_pct  NUMERIC;
  v_aux_load     NUMERIC;
  v_aux_noise    NUMERIC;
  v_new_temp     NUMERIC;
  v_target_temp  NUMERIC;
  v_thermal_lag  NUMERIC;                    -- 0450: 1 - exp(-tick_minutes / 5), set below (was 0.18 per tick)
  v_kwh_through  NUMERIC;
  v_delta_soh    NUMERIC;
  v_ambient      NUMERIC;
  v_thermal_noise NUMERIC;
  v_bms_margin   NUMERIC;
  v_passive_c    NUMERIC;                    -- 0450 (G183): the old target, before the coolant loop
  v_lift_c       NUMERIC;                    -- 0450: cooling lift the loop was sized for
  v_lift_h       NUMERIC;                    -- 0450: heating lift
  v_setpoint_c   NUMERIC;
  v_duty         NUMERIC := 0;
BEGIN
  SELECT * INTO v FROM ottoq_bess_units WHERE bess_id = p_bess_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'bess % not found', p_bess_id;
  END IF;

  v_seed   := abs(hashtextextended(p_bess_id::text || twin.ottoq_sim_clock_salt(p_sim_run_id, p_sim_clock_now), 23));
  v_ambient := COALESCE(p_ambient_temp_c, v.current_temperature_c, 22);
  v_one_way_eff := SQRT(COALESCE(v.roundtrip_efficiency_pct, 0.96));   -- per-direction

  -- BMS safety margin: 95-100% of theoretical max (jittered)
  v_bms_margin := 0.95 + ottoq_sim_seeded_random(v_seed, 'bms') * 0.05;

  IF p_target_power_kw > 0 THEN
    v_max_kw    := ottoq_sim_bess_compute_max_power_kw(p_bess_id, 'charge', v.current_temperature_c) * v_bms_margin;
    v_actual_kw := LEAST(p_target_power_kw, v_max_kw);
    IF v.current_temperature_c > 45 OR v.current_temperature_c < 5 THEN
      v_thermal_derated := TRUE;
    END IF;
    IF v.current_soc_pct >= v.soc_max_ceiling_pct - 0.05 THEN
      v_actual_kw    := 0;
      v_soc_limited  := TRUE;
    END IF;
  ELSIF p_target_power_kw < 0 THEN
    v_max_kw    := ottoq_sim_bess_compute_max_power_kw(p_bess_id, 'discharge', v.current_temperature_c) * v_bms_margin;
    v_actual_kw := -LEAST(ABS(p_target_power_kw), v_max_kw);
    IF v.current_temperature_c > 45 OR v.current_temperature_c < 5 THEN
      v_thermal_derated := TRUE;
    END IF;
    IF v.current_soc_pct <= v.soc_min_floor_pct + 0.05 THEN
      v_actual_kw    := 0;
      v_soc_limited  := TRUE;
    END IF;
  ELSE
    v_actual_kw := 0;
  END IF;

  -- Apply round-trip efficiency
  -- Charging: kWh stored = power_in × eff
  -- Discharging: kWh removed from pack = |power_out| / eff (need to pull more from pack to deliver)
  v_kwh_delta := CASE
    WHEN v_actual_kw > 0 THEN v_actual_kw * (p_tick_minutes / 60.0) * v_one_way_eff
    WHEN v_actual_kw < 0 THEN v_actual_kw * (p_tick_minutes / 60.0) / v_one_way_eff
    ELSE 0 END;

  -- Auxiliary load (BMS + HVAC + comms) — always pulls from pack
  v_aux_noise  := 0.85 + ottoq_sim_seeded_random(v_seed, 'aux') * 0.30;
  /* 0450 (G183): the coolant loop. The passive target is the old model; the loop holds the setpoint while the lift
     it needs is within the lift it was sized for (rated power at the rated ambient), and pays for it in
     proportion to duty. Computed here because the pack pays the loop in this tick's energy. */
  v_setpoint_c := COALESCE(v.hvac_setpoint_c, 25);
  v_passive_c  := v_ambient + 3.0 + (ABS(v_actual_kw) / v.max_charge_kw) * 12.0;
  v_lift_c     := GREATEST(1.0, COALESCE(v.hvac_rated_ambient_c, 50) + 15.0 - v_setpoint_c);
  v_lift_h     := GREATEST(1.0, v_setpoint_c - (COALESCE(v.hvac_rated_min_ambient_c, -30) + 3.0));
  v_duty       := CASE WHEN v_passive_c > v_setpoint_c THEN LEAST(1.0, (v_passive_c - v_setpoint_c) / v_lift_c)
                       ELSE LEAST(1.0, (v_setpoint_c - v_passive_c) / v_lift_h) END;
  v_aux_load   := v.auxiliary_load_kw * v_aux_noise
                + v_duty * COALESCE(v.hvac_rated_kw, 0.01 * GREATEST(v.max_charge_kw, v.max_discharge_kw));
  v_kwh_delta  := v_kwh_delta - (v_aux_load * (p_tick_minutes / 60.0));

  v_new_soc_kwh := v.current_soc_kwh + v_kwh_delta;
  v_new_soc_kwh := GREATEST(0, LEAST(v.capacity_kwh, v_new_soc_kwh));
  v_new_soc_pct := v_new_soc_kwh / v.capacity_kwh * 100.0;

  -- Thermal model: heat from |P| × (1 - one_way_eff)
  -- 0450 (G183): the loop holds the setpoint up to its lift; the cells follow only the excess beyond it.
  v_target_temp := CASE WHEN v_passive_c > v_setpoint_c THEN GREATEST(v_setpoint_c, v_passive_c - v_lift_c)
                        ELSE LEAST(v_setpoint_c, v_passive_c + v_lift_h) END;
  -- 0450: tick-invariant lag with the 5-minute time constant the original comment named
  v_thermal_lag := 1 - exp(-GREATEST(COALESCE(p_tick_minutes, 1), 0) / 5.0);
  v_thermal_noise := (ottoq_sim_seeded_random(v_seed, 'noise') - 0.5) * 3.0;
  v_new_temp := v.current_temperature_c
              + (v_target_temp - v.current_temperature_c) * v_thermal_lag
              + v_thermal_noise;

  -- Throughput in kWh (for SOH calc)
  v_kwh_through := ABS(v_actual_kw) * (p_tick_minutes / 60.0);
  v_delta_soh := ottoq_sim_bess_apply_degradation(p_bess_id, p_tick_minutes, v_kwh_through, v_seed);

  -- Persist unit state
  UPDATE ottoq_bess_units
     SET current_soc_kwh           = ROUND(v_new_soc_kwh::numeric, 2),
         current_soc_pct           = ROUND(v_new_soc_pct::numeric, 2),
         current_temperature_c     = ROUND(v_new_temp::numeric, 2),
         current_power_kw          = ROUND(v_actual_kw::numeric, 2),
         current_state             = CASE
                                       WHEN v_actual_kw > 0  THEN 'charging'
                                       WHEN v_actual_kw < 0  THEN 'discharging'
                                       --: 0397 / G96. WAS 'idle'. The comment this replaces said
                                      --: "'idle' is the unit-level vocabulary" and that was the
                                      --: whole defect: the INSERT twelve lines below writes
                                      --: 'standby' from this same v_actual_kw, and 'standby' is
                                      --: what the bess_status enum and the bess rows of
                                      --: ottoq_state_transitions both use. 'idle' appeared in no
                                      --: matrix row, so a bess_state_change probe reading this
                                      --: column would have refused every transition into or out
                                      --: of rest -- a critical/block rule taking the BESS offline
                                      --: on the first tick. One state, one word. db/checks/0298.
                                      ELSE 'standby' END,
         current_state_updated_at  = p_sim_clock_now,
         last_heartbeat_at         = p_sim_clock_now,
         updated_at                = NOW()
   WHERE bess_id = p_bess_id;

  -- Snapshot to time-series
  INSERT INTO bess_snapshots (
    id, depot_id, system_id, timestamp, soc_percent,
    capacity_kwh, usable_capacity_kwh, current_output_kw,
    max_discharge_kw, max_charge_kw,
    grid_import_kw, grid_export_kw,
    temperature_c, health_percent, cycle_count, status
  ) VALUES (
    gen_random_uuid(), v.depot_id, v.bess_id, p_sim_clock_now, ROUND(v_new_soc_pct::numeric, 2),
    v.capacity_kwh,
    v.capacity_kwh * (v.soc_max_ceiling_pct - v.soc_min_floor_pct) / 100,
    ROUND(v_actual_kw::numeric, 2),
    v.max_discharge_kw, v.max_charge_kw,
    0, 0,                                                   -- grid linkage in A.5.4
    ROUND(v_new_temp::numeric, 2),
    ROUND(LEAST(100, v.current_soh_pct + v_delta_soh)::numeric, 3),
    ROUND((v.current_cycle_count + (v_kwh_through / (2 * v.capacity_kwh)))::numeric, 4),
    (CASE WHEN v_actual_kw > 0 THEN 'charging'
          WHEN v_actual_kw < 0 THEN 'discharging'
          ELSE 'standby' END)::bess_status
  );

  -- Emit events for noteworthy conditions
  IF v_thermal_derated THEN
    PERFORM ottoq_record_event(
      p_actor_type    := 'bess_controller',
      p_actor_id      := v.bess_identifier,
      p_event_type    := 'twin.bess_thermal_derate',
      p_entity_type   := 'depot',
      p_entity_id     := v.depot_id,
      p_payload       := jsonb_build_object(
        'temp_c', v.current_temperature_c,
        'requested_kw', p_target_power_kw,
        'actual_kw', v_actual_kw),
      p_severity      := 'warning',
      p_ingest_source := 'twin',
      p_data_source   := 'twin',
      p_sim_run_id    := p_sim_run_id);
  END IF;

  IF v_soc_limited THEN
    PERFORM ottoq_record_event(
      p_actor_type    := 'bess_controller',
      p_actor_id      := v.bess_identifier,
      p_event_type    := 'twin.bess_soc_limit',
      p_entity_type   := 'depot',
      p_entity_id     := v.depot_id,
      p_payload       := jsonb_build_object(
        'soc_pct', v.current_soc_pct,
        'direction', CASE WHEN p_target_power_kw > 0 THEN 'charge' ELSE 'discharge' END),
      p_severity      := 'warning',
      p_ingest_source := 'twin',
      p_data_source   := 'twin',
      p_sim_run_id    := p_sim_run_id);
  END IF;

  PERFORM ottoq_record_event(
    p_actor_type    := 'bess_controller',
    p_actor_id      := v.bess_identifier,
    p_event_type    := 'twin.bess_dispatch',
    p_entity_type   := 'depot',
    p_entity_id     := v.depot_id,
    p_payload       := jsonb_build_object(
      'target_kw',      p_target_power_kw,
      'actual_kw',      v_actual_kw,
      'soc_pct_after',  ROUND(v_new_soc_pct::numeric, 2),
      'soh_pct_after',  ROUND(LEAST(100, v.current_soh_pct + v_delta_soh)::numeric, 3),
      'temp_c_after',   ROUND(v_new_temp::numeric, 2),
      'reason',         p_dispatch_reason),
    p_severity      := 'info',
    p_ingest_source := 'twin',
    p_data_source   := 'twin',
    p_sim_run_id    := p_sim_run_id);

  out_actual_power_kw := ROUND(v_actual_kw::numeric, 2);
  out_soc_pct_new     := ROUND(v_new_soc_pct::numeric, 2);
  out_temp_c_new      := ROUND(v_new_temp::numeric, 2);
  out_soh_pct_new     := ROUND(LEAST(100, v.current_soh_pct + v_delta_soh)::numeric, 3);
  out_thermal_derated := v_thermal_derated;
  out_soc_limited     := v_soc_limited;
  RETURN NEXT;
END;
$function$;
-- @@ function twin.ottoq_sim_bess_default_target_kw(p_bess_id uuid, p_sim_clock_now timestamp with time zone, p_solar_ac_kw numeric)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_bess_default_target_kw(p_bess_id uuid, p_sim_clock_now timestamp with time zone, p_solar_ac_kw numeric DEFAULT 0)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v     ottoq_bess_units%ROWTYPE;
  v_hr  INTEGER;
BEGIN
  SELECT * INTO v FROM ottoq_bess_units WHERE bess_id = p_bess_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  v_hr := EXTRACT(HOUR FROM p_sim_clock_now AT TIME ZONE 'America/Chicago')::int;

  -- Discharge in peak hours when SOC healthy
  IF v_hr BETWEEN 14 AND 19 AND v.current_soc_pct > 30 THEN
    RETURN -1 * LEAST(v.max_discharge_kw * 0.7, v.max_discharge_kw);
  END IF;

  -- Charge from solar surplus
  IF p_solar_ac_kw > 200 AND v.current_soc_pct < 90 THEN
    RETURN LEAST(p_solar_ac_kw * 0.6, v.max_charge_kw * 0.8);
  END IF;

  -- Off-peak top-up at night
  IF v_hr BETWEEN 0 AND 5 AND v.current_soc_pct < 70 THEN
    RETURN v.max_charge_kw * 0.5;
  END IF;

  RETURN 0;
END;
$function$;
-- @@ function twin.ottoq_sim_advance_bess(p_depot_id uuid, p_sim_run_id uuid, p_sim_clock_now timestamp with time zone, p_tick_minutes numeric)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_advance_bess(p_depot_id uuid, p_sim_run_id uuid, p_sim_clock_now timestamp with time zone, p_tick_minutes numeric)
 RETURNS TABLE(out_bess_id uuid, out_target_kw numeric, out_actual_kw numeric, out_soc_pct numeric, out_temp_c numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_bess           RECORD;
  v_solar_kw       NUMERIC;
  v_ambient        NUMERIC;
  v_target_kw      NUMERIC;
  v_step           RECORD;
BEGIN
  -- Pull latest solar + ambient (within last tick window)
  SELECT COALESCE(SUM(ac_power_kw), 0) INTO v_solar_kw
    FROM ottoq_solar_output
   WHERE COALESCE(sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid)
       = COALESCE(p_sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid)  /* 0134 */
     AND depot_id = p_depot_id
     AND sim_clock_at >= p_sim_clock_now - (p_tick_minutes || ' minutes')::interval
     AND sim_clock_at <= p_sim_clock_now;

  SELECT ambient_temp_c INTO v_ambient
    FROM ottoq_weather_snapshots
   WHERE COALESCE(sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid)
       = COALESCE(p_sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid)  /* 0134 */
     AND depot_id = p_depot_id AND sim_clock_at <= p_sim_clock_now
   ORDER BY sim_clock_at DESC, ambient_temp_c DESC, snapshot_id DESC LIMIT 1;
  v_ambient := COALESCE(v_ambient, 22);

  FOR v_bess IN SELECT bess_id, bess_identifier FROM ottoq_bess_units WHERE depot_id = p_depot_id LOOP
    -- OTTO-Q energy control: OBEY OTTO-Q's battery order if present (sign corrected: OTTO-Q +=discharge).
    v_target_kw := NULL;
    SELECT -setpoint_kw INTO v_target_kw FROM ottoq_energy_commands
      WHERE sim_run_id = p_sim_run_id AND depot_id = p_depot_id AND command_type = 'bess_setpoint_kw'
        AND status IN ('executed','pending') ORDER BY issued_at DESC, created_at DESC, command_id DESC  /* 0134 */ LIMIT 1;
    IF v_target_kw IS NULL THEN  -- no OTTO-Q order (baseline/dumb run) → autonomous default
      v_target_kw := ottoq_sim_bess_default_target_kw(v_bess.bess_id, p_sim_clock_now, v_solar_kw,
                       (SELECT COALESCE(s.total_ev_charging_kw,0) + COALESCE(s.building_load_kw,0) + COALESCE(s.lighting_load_kw,0)
                          FROM site_energy_snapshots s
                         WHERE s.sim_run_id = p_sim_run_id AND s.timestamp <= p_sim_clock_now
                         ORDER BY s.timestamp DESC, s.id DESC  /* 0134 */ LIMIT 1),
                       (SELECT MAX(s2.grid_import_kw) FROM site_energy_snapshots s2
                         WHERE s2.sim_run_id = p_sim_run_id AND s2.timestamp <= p_sim_clock_now))
                   * ottoq_profile_rate_mult(p_sim_run_id, 'bess_aggressiveness');   -- A.10 knob (×)
    END IF;
    SELECT * INTO v_step FROM ottoq_sim_bess_step(
      v_bess.bess_id, p_sim_run_id, p_sim_clock_now, p_tick_minutes,
      v_target_kw, v_ambient, 'default_policy');
    out_bess_id    := v_bess.bess_id;
    out_target_kw  := v_target_kw;
    out_actual_kw  := v_step.out_actual_power_kw;
    out_soc_pct    := v_step.out_soc_pct_new;
    out_temp_c     := v_step.out_temp_c_new;
    RETURN NEXT;
  END LOOP;
END;
$function$;
-- @@ function twin.ottoq_sim_sample_carbon_intensity(p_seed bigint, p_salt text, p_hour integer)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_sample_carbon_intensity(p_seed bigint, p_salt text, p_hour integer)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_solar_fraction NUMERIC;
  v_nuclear        NUMERIC := 0.40;
  v_gas            NUMERIC := 0.25;
  v_coal           NUMERIC := 0.20;
  v_hydro          NUMERIC := 0.10;
  v_solar          NUMERIC := 0.05;
  v_noise          NUMERIC;
BEGIN
  -- Solar fraction peaks midday
  v_solar_fraction := CASE
    WHEN p_hour BETWEEN 9 AND 16 THEN 0.05 + 0.10 * (1 - ABS(p_hour - 12.5) / 4.0)
    ELSE 0.0 END;
  v_solar := GREATEST(0.02, v_solar_fraction);
  v_coal  := 0.20 - v_solar_fraction * 0.7;             -- solar mostly displaces coal
  v_gas   := 0.25 - v_solar_fraction * 0.3;

  v_noise := (ottoq_sim_seeded_random(p_seed, p_salt || '_carbon') - 0.5) * 30;

  -- gCO2/kWh weighted:
  --   nuclear: 12, gas: 490, coal: 820, hydro: 24, solar: 45
  RETURN GREATEST(150,
    v_nuclear * 12
    + v_gas    * 490
    + v_coal   * 820
    + v_hydro  * 24
    + v_solar  * 45
    + v_noise);
END;
$function$;
-- @@ function twin.ottoq_sim_current_tariff(p_depot_id uuid, p_sim_clock_now timestamp with time zone)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_current_tariff(p_depot_id uuid, p_sim_clock_now timestamp with time zone)
 RETURNS TABLE(out_label text, out_rate_usd_kwh numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_hour    INTEGER;
  v_dow     INTEGER;
  v_month   INTEGER;
  v_season  TEXT;
BEGIN
  v_hour := EXTRACT(HOUR FROM p_sim_clock_now AT TIME ZONE 'America/Chicago')::int;
  v_dow  := EXTRACT(DOW  FROM p_sim_clock_now AT TIME ZONE 'America/Chicago')::int;
  v_month := EXTRACT(MONTH FROM p_sim_clock_now AT TIME ZONE 'America/Chicago')::int;

  v_season := CASE
    WHEN v_month BETWEEN 6 AND 9  THEN 'summer'
    WHEN v_month BETWEEN 12 AND 12 OR v_month BETWEEN 1 AND 2 THEN 'winter'
    ELSE 'shoulder' END;

  SELECT label, rate_usd_per_kwh
    INTO out_label, out_rate_usd_kwh
    FROM ottoq_tariff_windows
   WHERE depot_id = p_depot_id
     AND active
     AND v_hour >= hour_start AND v_hour < hour_end
     AND (season = v_season OR season = 'all')
   ORDER BY rate_usd_per_kwh DESC                       -- super-peak wins over peak
   LIMIT 1;
  IF NOT FOUND THEN
    out_label := 'unknown';
    out_rate_usd_kwh := 0.10;
  END IF;
  RETURN NEXT;
END;
$function$;
-- @@ function twin.ottoq_sim_maybe_ignite_dr_call(p_depot_id uuid, p_sim_run_id uuid, p_sim_clock_now timestamp with time zone, p_ambient_temp_c numeric, p_seed bigint)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_maybe_ignite_dr_call(p_depot_id uuid, p_sim_run_id uuid, p_sim_clock_now timestamp with time zone, p_ambient_temp_c numeric, p_seed bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_hour     INTEGER;
  v_roll     NUMERIC;
  v_prob     NUMERIC := 0;
  v_existing UUID;
  v_call_id  UUID;
  v_dur_min  NUMERIC;
  v_cap_kw   NUMERIC;
  v_red_kw   NUMERIC;   -- 0433
  v_base_kw  NUMERIC;   -- 0433
  v_base_src TEXT;      -- 0433
  v_tick_min NUMERIC;   -- 0433
  v_zero     CONSTANT uuid := '00000000-0000-0000-0000-000000000000';
BEGIN
  -- Don't ignite if already active
  SELECT dr_call_id INTO v_existing
    FROM ottoq_dr_calls
   WHERE depot_id = p_depot_id AND call_status = 'active'
     AND expires_at > p_sim_clock_now LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RETURN v_existing;
  END IF;

  v_hour := EXTRACT(HOUR FROM p_sim_clock_now AT TIME ZONE 'America/Chicago')::int;

  -- Probability model: hot afternoon peak hours
  IF p_ambient_temp_c >= 32 AND v_hour BETWEEN 14 AND 19 THEN
    v_prob := 0.030 + (p_ambient_temp_c - 32) * 0.012;
  ELSIF p_ambient_temp_c >= 30 AND v_hour BETWEEN 15 AND 18 THEN
    v_prob := 0.010;
  ELSIF p_ambient_temp_c <= -5 AND v_hour BETWEEN 6 AND 9 THEN
    -- Winter morning event
    v_prob := 0.015;
  END IF;

  -- A.8: scale DR-ignition probability by the run's variability profile
  v_prob := v_prob * ottoq_profile_rate_mult(p_sim_run_id, 'dr_ignition');

  -- 0433 (C): A HAZARD, NOT A PER-TICK COIN. The probability above is read as per 30 sim-minutes -- the cadence
  -- the canon runs at, so a cert tick draws exactly what it drew before -- and elapsed over the sim time THIS tick
  -- advanced, which the advancer publishes before the world steps (0420's source, same reasoning). A tick that
  -- advanced no time carries no hazard. ASSUMPTION: the author calibrated at the 30-minute cadence.
  IF COALESCE(ottoq_policy_get(p_sim_run_id, 'dr_hazard_per_sim_time', 1), 1) >= 1 AND v_prob > 0 THEN
    SELECT COALESCE(NULLIF(r.payload->>'tick_minutes_actual','')::numeric,
                    (r.tick_interval_seconds * r.time_scale) / 60.0, 30)
      INTO v_tick_min FROM ottoq_sim_runs r WHERE r.sim_run_id = p_sim_run_id;
    v_tick_min := COALESCE(v_tick_min, 30);
    IF v_tick_min <= 0 THEN RETURN NULL; END IF;
    v_prob := 1 - power(1 - LEAST(v_prob, 0.999), v_tick_min / 30.0);
  END IF;

  v_roll := ottoq_sim_seeded_random(p_seed, 'dr_ignite');
  IF v_roll >= v_prob THEN RETURN NULL; END IF;

  -- Sample duration (90-240 min, Weibull-shaped via U^0.75)
  v_dur_min := 90 + POWER(ottoq_sim_seeded_random(p_seed, 'dr_dur'), 0.75) * 150;
  -- Sample required load cap (50-400 kW reduction)
  v_cap_kw  := 50 + ottoq_sim_seeded_random(p_seed, 'dr_cap') * 350;

  -- 0433 (A): THE DRAW IS A REDUCTION, AS THE LINE ABOVE HAS ALWAYS SAID. Every reader of required_load_cap_kw
  -- treats it as a cap on grid import, so store the cap: a prior-hour baseline minus the reduction. The draw is
  -- untouched (same salts, same sample) -- only its meaning is honoured.
  IF COALESCE(ottoq_policy_get(p_sim_run_id, 'dr_cap_from_baseline', 1), 1) >= 1 THEN
    v_red_kw := v_cap_kw;
    SELECT avg(e.grid_import_kw) INTO v_base_kw
      FROM site_energy_snapshots e
     WHERE e.depot_id = p_depot_id
       AND COALESCE(e.sim_run_id, v_zero) = COALESCE(p_sim_run_id, v_zero)
       AND e.timestamp >  p_sim_clock_now - interval '60 minutes'
       AND e.timestamp <= p_sim_clock_now;
    v_base_src := 'prior_60_sim_min_mean_grid_import';
    IF v_base_kw IS NULL THEN
      SELECT e.grid_import_kw INTO v_base_kw
        FROM site_energy_snapshots e
       WHERE e.depot_id = p_depot_id
         AND COALESCE(e.sim_run_id, v_zero) = COALESCE(p_sim_run_id, v_zero)
         AND e.timestamp <= p_sim_clock_now
       ORDER BY e.timestamp DESC, e.id LIMIT 1;
      v_base_src := 'latest_snapshot_grid_import';
    END IF;
    IF v_base_kw IS NULL THEN
      -- No site history at all: keep the pre-0433 value rather than invent a baseline, and say so.
      v_base_src := 'none_pre_0433_reading_kept';
    ELSE
      v_cap_kw := GREATEST(0, v_base_kw - v_red_kw);
    END IF;
  END IF;

  v_call_id := gen_random_uuid();
  INSERT INTO ottoq_dr_calls (
    dr_call_id, depot_id, sim_run_id, issued_at, expires_at,
    duration_minutes, required_load_cap_kw, reason, program, call_status
  ) VALUES (
    v_call_id, p_depot_id, p_sim_run_id, p_sim_clock_now,
    p_sim_clock_now + (v_dur_min || ' minutes')::interval,
    v_dur_min, v_cap_kw,
    CASE WHEN p_ambient_temp_c >= 32 THEN 'heat_demand_response'
         WHEN p_ambient_temp_c <= -5 THEN 'cold_winter_morning'
         ELSE 'contingency' END,
    'TVA_VOLUNTARY', 'active');

  PERFORM ottoq_record_event(
    p_actor_type    := 'external_sensor',
    p_actor_id      := 'tva_dr_program',
    p_event_type    := 'twin.dr_call_issued',
    p_entity_type   := 'depot',
    p_entity_id     := p_depot_id,
    p_payload       := jsonb_build_object(
      'dr_call_id', v_call_id,
      'duration_min', v_dur_min,
      'required_cap_kw', v_cap_kw,
      'required_reduction_kw', v_red_kw,        -- 0433
      'baseline_kw', round(v_base_kw, 1),       -- 0433
      'baseline_source', v_base_src,            -- 0433
      'tick_minutes', v_tick_min,               -- 0433
      'reason', CASE WHEN p_ambient_temp_c >= 32 THEN 'heat'
                     WHEN p_ambient_temp_c <= -5 THEN 'cold'
                     ELSE 'contingency' END,
      'temp_c', p_ambient_temp_c),
    p_severity      := 'warning',
    p_ingest_source := 'twin',
    p_data_source   := 'twin',
    p_sim_run_id    := p_sim_run_id);

  RETURN v_call_id;
END;
$function$;
-- @@ function twin.ottoq_sim_advance_grid(p_depot_id uuid, p_sim_run_id uuid, p_sim_clock_now timestamp with time zone)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_advance_grid(p_depot_id uuid, p_sim_run_id uuid, p_sim_clock_now timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_seed           BIGINT;
  v_salt           TEXT;
  v_hour           INTEGER;
  v_dow            INTEGER;
  v_demand_mw      NUMERIC;
  v_lmp            NUMERIC;
  v_carbon         NUMERIC;
  v_tariff         RECORD;
  v_volt           RECORD;
  v_freq           RECORD;
  v_ambient        NUMERIC;
  v_dr_call_id     UUID;
  v_dr_call        ottoq_dr_calls%ROWTYPE;
  v_snap_id        UUID := gen_random_uuid();
  v_supply_mw      NUMERIC;
  v_reserve_pct    NUMERIC;
  v_shape          NUMERIC;
  v_dr_cap         NUMERIC;
  v_local_load_kw  NUMERIC;
  v_eng_cap        NUMERIC;
  v_load_util      NUMERIC;
  v_load_bo_mult   NUMERIC;
BEGIN
  v_seed  := abs(hashtextextended(p_depot_id::text || twin.ottoq_sim_clock_salt(p_sim_run_id, p_sim_clock_now) || 'grid', 31));
  v_salt  := to_char(p_sim_clock_now, 'YYYYMMDD-HH24');
  v_hour  := EXTRACT(HOUR FROM p_sim_clock_now AT TIME ZONE 'America/Chicago')::int;
  v_dow   := EXTRACT(DOW  FROM p_sim_clock_now AT TIME ZONE 'America/Chicago')::int;

  SELECT ambient_temp_c INTO v_ambient
    FROM ottoq_weather_snapshots
   WHERE COALESCE(sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid)
       = COALESCE(p_sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid)  /* 0134 */
     AND depot_id = p_depot_id AND sim_clock_at <= p_sim_clock_now
   ORDER BY sim_clock_at DESC, ambient_temp_c DESC, snapshot_id DESC LIMIT 1;
  v_ambient := COALESCE(v_ambient, 22);

  SELECT (profile_data->>(v_hour::text))::numeric INTO v_shape
    FROM ottoq_calibration_profiles
   WHERE profile_name = 'hourly_grid_demand_shape' LIMIT 1;
  v_shape := COALESCE(v_shape, 1.0);
  v_demand_mw := LEAST(40000, GREATEST(10000, COALESCE(
    ottoq_twin_deal(p_sim_run_id, 'grid_demand_mw', 'grid', p_sim_clock_now,
      (p_sim_clock_now::date - DATE '2020-01-01'), 0),
    21000))) * v_shape
    * ottoq_profile_rate_mult(p_sim_run_id, 'grid_demand_mw');
  v_demand_mw := v_demand_mw * (1
    + COALESCE((ottoq_twin_climate_stress(p_sim_run_id, (p_sim_clock_now::date - DATE '2020-01-01'))->>'heat_stress')::numeric,0) * 0.15
    + COALESCE((ottoq_twin_climate_stress(p_sim_run_id, (p_sim_clock_now::date - DATE '2020-01-01'))->>'cold_stress')::numeric,0) * 0.12);

  v_reserve_pct := 0.12 + ottoq_sim_seeded_random(v_seed, 'rm') * 0.10
                 - GREATEST(0, v_ambient - 32) * 0.005;
  v_supply_mw   := v_demand_mw * (1 + v_reserve_pct);

  v_lmp    := ottoq_sim_sample_lmp_usd_mwh(v_seed, v_salt, v_hour, v_ambient, v_dow, p_sim_run_id);
  v_lmp    := GREATEST(8, ottoq_apply_profile(p_sim_run_id, 'lmp_usd_mwh', v_lmp, 45));
  v_carbon := ottoq_sim_sample_carbon_intensity(v_seed, v_salt, v_hour);
  v_carbon := GREATEST(50, ottoq_apply_profile(p_sim_run_id, 'carbon_intensity', v_carbon, 380));

  SELECT * INTO v_tariff FROM ottoq_sim_current_tariff(p_depot_id, p_sim_clock_now);

  -- FID-B: local feeder load-responsiveness (SAME engineering cap EN.001 enforces)
  v_local_load_kw := ottoq_sim_compute_charger_load_kw(p_depot_id, p_sim_clock_now);
  SELECT dcfc_max_concurrent_kw * (1 - COALESCE(dcfc_safety_margin_pct, 10.0)/100.0)
    INTO v_eng_cap FROM depots WHERE id = p_depot_id;
  v_load_util := CASE WHEN COALESCE(v_eng_cap, 0) > 0 THEN v_local_load_kw / v_eng_cap ELSE 0 END;
  v_load_bo_mult := LEAST(3.0, 1 + GREATEST(0, v_load_util - 0.70) * 6.0);

  SELECT * INTO v_volt FROM ottoq_sim_sample_voltage_event(v_seed, v_salt,
    ottoq_profile_rate_mult(p_sim_run_id, 'brownout_rate') * v_load_bo_mult);
  SELECT * INTO v_freq FROM ottoq_sim_sample_frequency_hz(v_seed, v_salt,
    ottoq_profile_rate_mult(p_sim_run_id, 'freq_excursion_rate'));

  v_dr_call_id := ottoq_sim_maybe_ignite_dr_call(p_depot_id, p_sim_run_id, p_sim_clock_now,
                                                 v_ambient, v_seed);
  IF v_dr_call_id IS NOT NULL THEN
    SELECT * INTO v_dr_call FROM ottoq_dr_calls WHERE dr_call_id = v_dr_call_id;
    v_dr_cap := v_dr_call.required_load_cap_kw;
  END IF;

  UPDATE ottoq_dr_calls
     SET call_status = 'cleared', cleared_at = p_sim_clock_now
   WHERE depot_id = p_depot_id AND call_status = 'active'
     AND expires_at <= p_sim_clock_now;

  INSERT INTO ottoq_grid_snapshots (
    snapshot_id, depot_id, sim_run_id, sim_clock_at,
    region_demand_mw, region_supply_mw, reserve_margin_pct,
    generation_mix, carbon_intensity_gco2_per_kwh,
    voltage_v, frequency_hz, voltage_status, frequency_status,
    lmp_usd_per_mwh, current_tariff_label, current_rate_usd_per_kwh,
    active_dr_call_id, dr_required_load_cap_kw,
    data_source
  ) VALUES (
    v_snap_id, p_depot_id, p_sim_run_id, p_sim_clock_now,
    ROUND(v_demand_mw::numeric, 0), ROUND(v_supply_mw::numeric, 0),
    ROUND(v_reserve_pct::numeric, 4),
    jsonb_build_object('nuclear', 0.40, 'gas', 0.25, 'coal', 0.20, 'hydro', 0.10, 'solar', 0.05),
    ROUND(v_carbon::numeric, 1),
    ROUND(v_volt.out_voltage_v::numeric, 1),
    ROUND(v_freq.out_freq_hz::numeric, 3),
    v_volt.out_status,
    v_freq.out_status,
    ROUND(v_lmp::numeric, 2),
    v_tariff.out_label,
    ROUND(v_tariff.out_rate_usd_kwh::numeric, 4),
    v_dr_call_id, v_dr_cap,
    'twin');

  IF v_volt.out_status IN ('sag','brownout','swell') THEN
    PERFORM ottoq_record_event(
      p_actor_type    := 'external_sensor',
      p_actor_id      := 'grid_meter',
      p_event_type    := CASE v_volt.out_status
                           WHEN 'sag' THEN 'twin.grid_voltage_sag'
                           WHEN 'brownout' THEN 'twin.grid_brownout'
                           ELSE 'twin.grid_voltage_sag' END,
      p_entity_type   := 'depot',
      p_entity_id     := p_depot_id,
      p_payload       := jsonb_build_object(
        'voltage_v', v_volt.out_voltage_v,
        'status',    v_volt.out_status,
        'lmp_usd_mwh', v_lmp,
        'demand_mw', v_demand_mw,
        'local_load_kw', ROUND(v_local_load_kw::numeric, 1),
        'local_load_util', ROUND(v_load_util::numeric, 3),
        'load_brownout_mult', ROUND(v_load_bo_mult::numeric, 2)),
      p_severity      := CASE v_volt.out_status WHEN 'brownout' THEN 'critical' ELSE 'warning' END,
      p_ingest_source := 'twin',
      p_data_source   := 'twin',
      p_sim_run_id    := p_sim_run_id);
  END IF;

  IF v_freq.out_status = 'excursion' THEN
    PERFORM ottoq_record_event(
      p_actor_type    := 'external_sensor',
      p_actor_id      := 'grid_meter',
      p_event_type    := 'twin.grid_frequency_excursion',
      p_entity_type   := 'depot',
      p_entity_id     := p_depot_id,
      p_payload       := jsonb_build_object(
        'frequency_hz', v_freq.out_freq_hz,
        'deviation_hz', ABS(v_freq.out_freq_hz - 60.0)),
      p_severity      := 'warning',
      p_ingest_source := 'twin',
      p_data_source   := 'twin',
      p_sim_run_id    := p_sim_run_id);
  END IF;

  RETURN v_snap_id;
END;
$function$;
-- @@ function twin.ottoq_sim_compute_building_load_kw(p_depot_id uuid, p_sim_clock_now timestamp with time zone, p_ambient_c numeric, p_seed bigint, p_salt text)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_compute_building_load_kw(p_depot_id uuid, p_sim_clock_now timestamp with time zone, p_ambient_c numeric, p_seed bigint, p_salt text)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_hour      INTEGER;
  v_dow       INTEGER;
  v_hvac_kw   NUMERIC;
  v_lighting_kw NUMERIC;
  v_service_kw NUMERIC;
  v_wash_kw   NUMERIC;
  v_base_kw   NUMERIC := 6;
  v_noise     NUMERIC;
BEGIN
  v_hour := EXTRACT(HOUR FROM p_sim_clock_now AT TIME ZONE 'America/Chicago')::int;
  v_dow  := EXTRACT(DOW  FROM p_sim_clock_now AT TIME ZONE 'America/Chicago')::int;

  -- HVAC: U-shaped vs ambient (heating cold + cooling hot), modulated by hour
  v_hvac_kw := 14 + 1.2 * GREATEST(0, p_ambient_c - 22)        -- AC ramp
                  + 1.5 * GREATEST(0, 18 - p_ambient_c);        -- heat ramp
  IF v_hour BETWEEN 22 AND 5 THEN
    v_hvac_kw := v_hvac_kw * 0.55;                              -- setback at night
  END IF;

  -- Lighting: perimeter on at night, interior modulates with hour
  v_lighting_kw := CASE
    WHEN v_hour BETWEEN 20 AND 23 OR v_hour BETWEEN 0 AND 5 THEN 16
    WHEN v_hour BETWEEN 6 AND 8 OR v_hour BETWEEN 18 AND 19    THEN 9
    ELSE 4 END;

  -- Service bays: peak during business hours
  v_service_kw := CASE
    WHEN v_hour BETWEEN 7 AND 19 THEN 25 + ottoq_sim_seeded_random(p_seed, p_salt || '_svc') * 60
    ELSE                                  ottoq_sim_seeded_random(p_seed, p_salt || '_svc') * 8 END;

  -- Wash bays: midday peak
  v_wash_kw := CASE
    WHEN v_hour BETWEEN 9 AND 17 THEN ottoq_sim_seeded_random(p_seed, p_salt || '_wash') * 95
    ELSE                              ottoq_sim_seeded_random(p_seed, p_salt || '_wash') * 15 END;

  v_noise := 0.9 + ottoq_sim_seeded_random(p_seed, p_salt || '_bld_n') * 0.2;
  RETURN (v_base_kw + v_hvac_kw + v_lighting_kw + v_service_kw + v_wash_kw) * v_noise;
END;
$function$;
-- @@ function twin.ottoq_sim_compute_charger_load_kw(p_depot_id uuid, p_sim_clock_now timestamp with time zone)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_compute_charger_load_kw(p_depot_id uuid, p_sim_clock_now timestamp with time zone)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
  /* 0155: THE METER MUST SEE THE POWER THAT FLOWED. status='active'
     excluded a session that ENDED during this very tick, and
     ottoq_depot_running_run(depot) is NULL off-sim so "= NULL" matched
     nothing. The time predicate already means "drawing at this instant";
     status only excludes what never delivered. */
  /* 0223: the run key is derived ONCE, in a MATERIALIZED CTE, instead of once
     per candidate row. Measured before the change: 8,966,506 evaluations of
     ottoq_depot_running_run in a single 12-tick pair, 108.8 s, 8,756 per call
     of this function — of a value that does not vary within the call.
     It sat on the right of a comparison whose left side carries a Var, so it
     was a per-row filter expression, and it carries a SET clause so it is not
     inlinable. Same answer by the definition of STABLE; the sum is unchanged.
     MATERIALIZED is load-bearing: without it the planner may fold the CTE back
     into the filter and restore the per-row call. See db/checks/0130. */
  WITH r AS MATERIALIZED (
    SELECT COALESCE(ottoq_depot_running_run(p_depot_id),
                    '00000000-0000-0000-0000-000000000000'::uuid) AS run_key
  )
  SELECT COALESCE(SUM(((cs.last_meter_value->>'power_kw'))::numeric), 0)
    FROM ocpp_sessions cs CROSS JOIN r
   WHERE cs.depot_id = p_depot_id
     AND cs.status IN ('active'::ocpp_session_status, 'completed'::ocpp_session_status)
     AND cs.started_at <= p_sim_clock_now
     AND (cs.ended_at IS NULL OR cs.ended_at >= p_sim_clock_now)
     AND COALESCE(cs.sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) = r.run_key;
$function$;
-- @@ function twin.ottoq_sim_advance_site_energy(p_depot_id uuid, p_sim_run_id uuid, p_sim_clock_now timestamp with time zone, p_tick_minutes numeric)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_advance_site_energy(p_depot_id uuid, p_sim_run_id uuid, p_sim_clock_now timestamp with time zone, p_tick_minutes numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_seed             BIGINT;
  v_salt             TEXT;
  v_solar_ac_kw      NUMERIC := 0;
  v_bess_kw          NUMERIC := 0;
  v_chargers_kw      NUMERIC;
  v_building_kw      NUMERIC;
  v_grid_kw          NUMERIC;
  v_ambient          NUMERIC := 22;
  v_dcfc_cap_kw      NUMERIC;
  v_service_cap_kw   NUMERIC;
  v_dcfc_load_kw     NUMERIC := 0;
  v_dr_cap_kw        NUMERIC;
  v_dr_call_id       UUID;
  v_tariff_label     TEXT;
  v_tariff_rate      NUMERIC;
  v_snap_id          UUID := gen_random_uuid();
  v_peak_15min       NUMERIC;
BEGIN
  v_seed := abs(hashtextextended(p_depot_id::text || twin.ottoq_sim_clock_salt(p_sim_run_id, p_sim_clock_now) || 'site', 11));
  v_salt := to_char(p_sim_clock_now, 'YYYYMMDD-HH24MISS');
  SELECT d.dcfc_max_concurrent_kw, d.service_max_kw INTO v_dcfc_cap_kw, v_service_cap_kw
    FROM public.depots d WHERE d.id = p_depot_id;

  /* 0133: neither run-scoped nor tiebroken; several runs share one sim_clock_at.
     Ordered on the value actually selected, so the result is total either way. */
  SELECT ambient_temp_c INTO v_ambient
    FROM ottoq_weather_snapshots
   WHERE depot_id = p_depot_id AND sim_clock_at <= p_sim_clock_now
     AND COALESCE(sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid)
       = COALESCE(p_sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid)
   ORDER BY sim_clock_at DESC, ambient_temp_c DESC LIMIT 1;
  v_ambient := COALESCE(v_ambient, 22);

  /* 0133: 860 solar rows from 215 DISTINCT runs shared sim 2026-09-01 08:00 on the
     flagship depot, and this SUM added all of them -- inflating solar, deflating grid
     import. Zero-uuid idiom (0020/0124) so production (sim_run_id NULL) is unchanged. */
  WITH latest AS (
    SELECT MAX(sim_clock_at) AS t FROM ottoq_solar_output
     WHERE depot_id = p_depot_id AND sim_clock_at <= p_sim_clock_now
       AND COALESCE(sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid)
         = COALESCE(p_sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid)
  )
  SELECT COALESCE(SUM(ac_power_kw), 0) INTO v_solar_ac_kw
    FROM ottoq_solar_output, latest
   WHERE depot_id = p_depot_id AND sim_clock_at = latest.t
     AND COALESCE(sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid)
       = COALESCE(p_sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid);

  SELECT COALESCE(SUM(current_power_kw), 0) INTO v_bess_kw
    FROM ottoq_bess_units WHERE depot_id = p_depot_id;

  v_chargers_kw := ottoq_sim_compute_charger_load_kw(p_depot_id, p_sim_clock_now);
  v_building_kw := ottoq_sim_compute_building_load_kw(p_depot_id, p_sim_clock_now, v_ambient, v_seed, v_salt);

  SELECT COALESCE(SUM(((cs.last_meter_value->>'power_kw'))::numeric), 0) INTO v_dcfc_load_kw
    FROM ocpp_sessions cs
    JOIN stalls s ON s.id = cs.stall_id
   WHERE cs.depot_id = p_depot_id
     AND s.stall_type::text = 'dcfc'
     AND cs.status IN ('active'::ocpp_session_status, 'completed'::ocpp_session_status)
     AND cs.started_at <= p_sim_clock_now
     AND (cs.ended_at IS NULL OR cs.ended_at >= p_sim_clock_now)
     AND COALESCE(cs.sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid)
       = COALESCE(p_sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid);

  v_grid_kw := v_chargers_kw + v_building_kw - v_solar_ac_kw + v_bess_kw;

  SELECT dr_call_id, required_load_cap_kw INTO v_dr_call_id, v_dr_cap_kw
    FROM ottoq_dr_calls
   WHERE depot_id = p_depot_id AND call_status = 'active'
     AND expires_at > p_sim_clock_now
     AND COALESCE(sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid)
       = COALESCE(p_sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid)
   ORDER BY required_load_cap_kw ASC, dr_call_id LIMIT 1;

  SELECT out_label, out_rate_usd_kwh INTO v_tariff_label, v_tariff_rate
    FROM ottoq_sim_current_tariff(p_depot_id, p_sim_clock_now);

  -- 15-min peak from THIS run's trailing snapshots (sim_run scoped → no cross-run bleed)
  SELECT COALESCE(MAX(grid_import_kw - grid_export_kw), 0) INTO v_peak_15min
    FROM site_energy_snapshots
   WHERE depot_id = p_depot_id
     AND timestamp >= p_sim_clock_now - INTERVAL '15 minutes'
     AND timestamp <= p_sim_clock_now
     AND (CASE WHEN p_sim_run_id IS NULL THEN TRUE ELSE sim_run_id = p_sim_run_id END);
  v_peak_15min := GREATEST(v_peak_15min, v_grid_kw);

  INSERT INTO site_energy_snapshots (
    id, depot_id, timestamp,
    grid_import_kw, grid_export_kw,
    solar_generation_kw, bess_output_kw,
    total_ev_charging_kw, building_load_kw,
    lighting_load_kw,
    peak_demand_kw_15min, billing_period_peak_kw,
    current_tariff_label, current_rate_per_kwh
  ) VALUES (
    v_snap_id, p_depot_id, p_sim_clock_now,
    ROUND(GREATEST(0, v_grid_kw)::numeric, 1),
    ROUND(GREATEST(0, -v_grid_kw)::numeric, 1),
    ROUND(v_solar_ac_kw::numeric, 1),
    ROUND(-v_bess_kw::numeric, 1),
    ROUND(v_chargers_kw::numeric, 1),
    ROUND(v_building_kw::numeric, 1),
    ROUND(0::numeric, 1),
    ROUND(v_peak_15min::numeric, 1),
    ROUND(GREATEST(v_peak_15min,
       (SELECT COALESCE(MAX(billing_period_peak_kw), 0)
          FROM site_energy_snapshots
         WHERE depot_id = p_depot_id
           AND timestamp >= date_trunc('month', p_sim_clock_now)
           AND (CASE WHEN p_sim_run_id IS NULL THEN TRUE ELSE sim_run_id = p_sim_run_id END)))::numeric, 1),
    (CASE
       WHEN v_tariff_label IN ('peak','super_peak')                THEN 'on_peak'
       WHEN v_tariff_label IN ('off_peak','mid_peak','on_peak',
                               'super_off_peak')                   THEN v_tariff_label
       ELSE 'mid_peak'
     END)::tariff_label,
    v_tariff_rate);

  IF v_dcfc_load_kw > v_dcfc_cap_kw THEN
    PERFORM ottoq_record_event(
      p_actor_type:='ottoq_engine', p_actor_id:='site_energy_balance',
      p_event_type:='twin.dcfc_cap_exceeded', p_entity_type:='depot', p_entity_id:=p_depot_id,
      p_payload:=jsonb_build_object('dcfc_kw', v_dcfc_load_kw, 'cap_kw', v_dcfc_cap_kw),
      p_severity:='critical', p_ingest_source:='twin', p_data_source:='twin', p_sim_run_id:=p_sim_run_id);
  ELSIF v_dcfc_load_kw > v_dcfc_cap_kw * 0.90 THEN
    PERFORM ottoq_record_event(
      p_actor_type:='ottoq_engine', p_actor_id:='site_energy_balance',
      p_event_type:='twin.dcfc_cap_approached', p_entity_type:='depot', p_entity_id:=p_depot_id,
      p_payload:=jsonb_build_object('dcfc_kw', v_dcfc_load_kw, 'cap_kw', v_dcfc_cap_kw,
                                    'utilization_pct', ROUND(v_dcfc_load_kw/v_dcfc_cap_kw*100, 1)),
      p_severity:='warning', p_ingest_source:='twin', p_data_source:='twin', p_sim_run_id:=p_sim_run_id);
  END IF;

  IF v_grid_kw > v_service_cap_kw THEN
    PERFORM ottoq_record_event(
      p_actor_type:='ottoq_engine', p_actor_id:='site_energy_balance',
      p_event_type:='twin.service_cap_exceeded', p_entity_type:='depot', p_entity_id:=p_depot_id,
      p_payload:=jsonb_build_object('grid_kw', v_grid_kw, 'cap_kw', v_service_cap_kw),
      p_severity:='critical', p_ingest_source:='twin', p_data_source:='twin', p_sim_run_id:=p_sim_run_id);
  ELSIF v_grid_kw > v_service_cap_kw * 0.90 THEN
    PERFORM ottoq_record_event(
      p_actor_type:='ottoq_engine', p_actor_id:='site_energy_balance',
      p_event_type:='twin.service_cap_approached', p_entity_type:='depot', p_entity_id:=p_depot_id,
      p_payload:=jsonb_build_object('grid_kw', v_grid_kw, 'cap_kw', v_service_cap_kw),
      p_severity:='warning', p_ingest_source:='twin', p_data_source:='twin', p_sim_run_id:=p_sim_run_id);
  END IF;

  IF v_dr_call_id IS NOT NULL THEN
    PERFORM ottoq_record_event(
      p_actor_type:='ottoq_engine', p_actor_id:='site_energy_balance',
      p_event_type:='twin.dr_compliance', p_entity_type:='depot', p_entity_id:=p_depot_id,
      p_payload:=jsonb_build_object('dr_call_id', v_dr_call_id, 'required_cap_kw', v_dr_cap_kw,
        'actual_grid_kw', v_grid_kw, 'compliant', v_grid_kw <= v_dr_cap_kw,
        'overage_kw', GREATEST(0, v_grid_kw - v_dr_cap_kw)),
      p_severity:=CASE WHEN v_grid_kw > v_dr_cap_kw THEN 'warning' ELSE 'info' END,
      p_ingest_source:='twin', p_data_source:='twin', p_sim_run_id:=p_sim_run_id);
  END IF;

  RETURN v_snap_id;
END;
$function$;
-- @@ function twin.ottoq_sim_advance_all_energy(p_depot_id uuid, p_sim_run_id uuid, p_sim_clock_now timestamp with time zone, p_tick_minutes numeric)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_advance_all_energy(p_depot_id uuid, p_sim_run_id uuid, p_sim_clock_now timestamp with time zone, p_tick_minutes numeric)
 RETURNS TABLE(out_weather_id uuid, out_grid_id uuid, out_bess_count integer, out_site_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_weather  UUID;
  v_grid     UUID;
  v_bess_n   INTEGER;
  v_site     UUID;
BEGIN
  v_weather := ottoq_sim_advance_weather_and_solar(p_depot_id, p_sim_run_id, p_sim_clock_now);
  v_grid    := ottoq_sim_advance_grid             (p_depot_id, p_sim_run_id, p_sim_clock_now);
  SELECT COUNT(*) INTO v_bess_n
    FROM ottoq_sim_advance_bess(p_depot_id, p_sim_run_id, p_sim_clock_now, p_tick_minutes);
  v_site    := ottoq_sim_advance_site_energy(p_depot_id, p_sim_run_id, p_sim_clock_now, p_tick_minutes);

  IF v_site IS NOT NULL AND p_sim_run_id IS NOT NULL THEN
    UPDATE site_energy_snapshots SET sim_run_id = p_sim_run_id WHERE id = v_site;
  END IF;

  out_weather_id := v_weather;
  out_grid_id    := v_grid;
  out_bess_count := v_bess_n;
  out_site_id    := v_site;
  RETURN NEXT;
END;
$function$;
-- @@ function twin.ottoq_sim_auto_dispatch_tick(p_sim_run_id uuid, p_sim_clock_now timestamp with time zone, p_tick_minutes numeric)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_auto_dispatch_tick(p_sim_run_id uuid, p_sim_clock_now timestamp with time zone, p_tick_minutes numeric)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_run ottoq_sim_runs%ROWTYPE; v_scenario ottoq_sim_scenarios%ROWTYPE;
  v_hour INTEGER; v_dispatch_mult NUMERIC := 1.0; v_target_deployed_pct NUMERIC := 0.90;
  v_total_fleet INTEGER; v_currently_deployed INTEGER; v_desired_deployed INTEGER;
  v_to_dispatch INTEGER; v_vehicle RECORD; v_count INTEGER := 0; v_seed BIGINT;
  v_recall_on boolean; v_win_start int; v_win_end int; v_hyst int; v_holdout_pct int;
  v_to_recall int; v_cap int; v_recalled int := 0;
  v_sec RECORD; v_eta numeric;
  v_release_cap int; v_valved int := 0; v_forced boolean;
  v_plan jsonb;
  -- 2026-08-11: the tick's OWN elapsed sim-minutes, resolved once and handed to BOTH
  -- phases of ottoq_plan_dispatch_tick. The recall phase already received it; the
  -- deploy phase did not, so the callee fell back to its 30-minute DEFAULT and any
  -- tick-length scaling on the release cap was inert by construction.
  v_tick_min numeric;
BEGIN
  SELECT * INTO v_run FROM ottoq_sim_runs WHERE sim_run_id = p_sim_run_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  -- Byte-for-byte the expression the recall call below already used. Kept as one
  -- variable so the two phases can never disagree about how long this tick was.
  v_tick_min := COALESCE((v_run.payload->>'tick_minutes_actual')::numeric,
                         (v_run.tick_interval_seconds::numeric * COALESCE(v_run.time_scale,1))/60.0,
                         30);

  -- ══════════════ 0019: THE IN-DEPOT PATH FOR A RIDER FLAG ══════════════
  -- A flag that comes due while the car is PARKED can never reach
  -- public.ottoq_evaluate_return_need, because that function reads an ACTIVE
  -- dispatch and returns should_return=false when there is none. A parked car
  -- does not need recalling -- it needs the atom put on the visit it is already
  -- having. This runs BEFORE the deploy cursor below, so a flag that matures
  -- this tick becomes must_do work this tick and the same tick's dispatcher
  -- then declines to send the car out. Self-silencing: it must never cost the
  -- depot a dispatch.
  BEGIN
    PERFORM ottoq.ottoq_rider_flag_indepot_sweep(p_sim_run_id, v_run.depot_id, p_sim_clock_now);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'rider flag in-depot sweep failed safely: % %', SQLSTATE, SQLERRM;
  END;

  SELECT s.* INTO v_scenario FROM ottoq_sim_scenarios s
   WHERE s.scenario_code = COALESCE(v_run.scenario_code, 'normal_day') LIMIT 1;
  IF v_scenario.scenario_code IS NULL THEN
    SELECT * INTO v_scenario FROM ottoq_sim_scenarios WHERE scenario_code = 'normal_day';
  END IF;
  v_dispatch_mult       := COALESCE((v_scenario.fleet_overrides->>'dispatch_rate_multiplier')::numeric, 1.0);
  v_target_deployed_pct := COALESCE((v_scenario.fleet_overrides->>'target_deployed_fraction')::numeric, 0.90);

  v_hour := EXTRACT(HOUR FROM p_sim_clock_now AT TIME ZONE 'America/Chicago')::int;
  v_seed := abs(hashtextextended(COALESCE(v_run.random_seed, 42)::text || twin.ottoq_sim_clock_salt(p_sim_run_id, p_sim_clock_now) || 'disp', 7));   -- 0051: run-relative salt, never the absolute clock

  SELECT COUNT(*) INTO v_total_fleet FROM vehicles
   WHERE category = 'autonomous' AND home_depot_id = v_run.depot_id;
  SELECT COUNT(*) INTO v_currently_deployed
    FROM ottoq_vehicle_dispatches
   WHERE sim_run_id = p_sim_run_id AND status IN ('active', 'returning');

  v_desired_deployed := FLOOR(v_total_fleet * ottoq_deploy_target_fraction(
      v_hour, ottoq_policy_get(p_sim_run_id,'deploy_peak_fraction', v_target_deployed_pct)) * v_dispatch_mult);

  v_to_dispatch := GREATEST(0, v_desired_deployed - v_currently_deployed);

  -- (1) DEPLOY toward the target. OTTO-Q ranks and paces; the twin departs them.
  IF v_to_dispatch > 0 THEN
    v_plan := ottoq_plan_dispatch_tick(
                'deploy_plan', p_sim_run_id, v_run.depot_id, p_sim_clock_now,
                p_hour := v_hour, p_seed := v_seed, p_to_dispatch := v_to_dispatch,
                p_tick_minutes_actual := v_tick_min);
    v_release_cap := COALESCE((v_plan->>'cap')::int, 1);
    v_forced      := COALESCE((v_plan->>'forced')::boolean, false);

    FOR v_vehicle IN
      SELECT t.value::uuid AS id
        FROM jsonb_array_elements_text(COALESCE(v_plan->'release','[]'::jsonb)) WITH ORDINALITY AS t(value, ord)
       ORDER BY t.ord
    LOOP
      -- 0019: count a dispatch only when one actually happened. The refusal in
      -- twin.ottoq_sim_dispatch_vehicle returns NULL, and an emit event that
      -- counted refusals as departures would be a false number.
      IF ottoq_sim_dispatch_vehicle(v_vehicle.id, p_sim_run_id, p_sim_clock_now) IS NOT NULL THEN
        v_count := v_count + 1;
      END IF;
    END LOOP;

    IF jsonb_array_length(COALESCE(v_plan->'hold','[]'::jsonb)) > 0 THEN
      v_valved := COALESCE((ottoq_plan_dispatch_tick(
                    'deploy_hold', p_sim_run_id, v_run.depot_id, p_sim_clock_now,
                    p_vehicles := v_plan->'hold', p_forced := v_forced)->>'held')::int, 0);
    END IF;

    IF v_valved > 0 THEN
      PERFORM ottoq_record_event(
        p_actor_type := 'ottoq_engine', p_actor_id := 'rush_valve',
        p_event_type := 'twin.rush_valve_hold', p_entity_type := 'system',
        p_payload := jsonb_build_object('held', v_valved, 'released', v_count,
          'cap', v_release_cap, 'forced', v_forced, 'hour_cst', v_hour),
        p_severity := 'info', p_ingest_source := 'twin', p_data_source := 'twin',
        p_sim_run_id := p_sim_run_id);
    END IF;

    IF v_count > 0 THEN
      PERFORM ottoq_record_event(
        p_actor_type := 'ottoq_engine', p_actor_id := 'twin_auto_dispatcher',
        p_event_type := 'twin.auto_dispatch_emit', p_entity_type := 'system',
        p_payload := jsonb_build_object('count', v_count, 'hour_cst', v_hour, 'scenario', v_scenario.scenario_code,
          'total_fleet', v_total_fleet, 'desired', v_desired_deployed, 'deployed', v_currently_deployed),
        p_severity := 'info', p_ingest_source := 'twin', p_data_source := 'twin', p_sim_run_id := p_sim_run_id);
    END IF;
  END IF;

  -- (2) OVERNIGHT SURPLUS RECALL. Twin measures the surplus (a demand fact) and
  -- applies the world writes; OTTO-Q ranks it and secures the appointments.
  v_recall_on   := ottoq_policy_get(p_sim_run_id,'overnight_recall_enabled',1) > 0;
  v_win_start   := ottoq_policy_get(p_sim_run_id,'overnight_recall_start_hour',22)::int;
  v_win_end     := ottoq_policy_get(p_sim_run_id,'overnight_recall_end_hour',3)::int;
  v_hyst        := ottoq_policy_get(p_sim_run_id,'overnight_recall_hysteresis',2)::int;
  v_holdout_pct := ottoq_policy_get(p_sim_run_id,'overnight_holdout_pct',1)::int;

  IF v_recall_on AND (v_hour >= v_win_start OR v_hour < 6) THEN
    v_to_recall := GREATEST(0, v_currently_deployed - v_desired_deployed - v_hyst);
    IF v_to_recall > 0 THEN
      v_plan := ottoq_plan_dispatch_tick(
                  'recall', p_sim_run_id, v_run.depot_id, p_sim_clock_now,
                  p_hour := v_hour, p_to_recall := v_to_recall, p_holdout_pct := v_holdout_pct,
                  p_win_start := v_win_start, p_win_end := v_win_end,
                  p_tick_minutes_actual := v_tick_min);
      v_cap := COALESCE((v_plan->>'cap')::int, 0);

      FOR v_sec IN
        SELECT t.value AS d
          FROM jsonb_array_elements(COALESCE(v_plan->'secured','[]'::jsonb)) WITH ORDINALITY AS t(value, ord)
         ORDER BY t.ord
      LOOP
        v_eta := (v_sec.d->>'eta_minutes')::numeric;
        UPDATE ottoq_vehicle_dispatches
           SET status='returning', return_trigger='surplus_to_demand',
               returning_started_at = p_sim_clock_now,
               return_eta_minutes = v_eta,
               -- 0321: this ETA came from the SECURED BOOKING
               -- (v_plan->'secured'->>'eta_minutes'), not from a recompute. It is
               -- what the stall was actually held for, so it is recorded rather
               -- than overruled -- and now it says so.
               eta_refreshed_at = p_sim_clock_now,
               eta_source = 'booking_plan:secured',
               scheduled_return_at = p_sim_clock_now + (v_eta || ' minutes')::interval,
               return_evidence = jsonb_build_object('decided_at',p_sim_clock_now,
                 'soc_at_decision',(v_sec.d->>'soc_at_decision')::int,'hour_cst',v_hour,
                 'reason','overnight_surplus_to_demand','appointment',v_sec.d->'appointment',
                 'desired_deployed',v_desired_deployed,'currently_deployed',v_currently_deployed)
         WHERE dispatch_id = (v_sec.d->>'dispatch_id')::uuid;
        UPDATE vehicles SET current_state='en_route_to_depot'::vehicle_state, last_state_change=p_sim_clock_now
         WHERE id = (v_sec.d->>'vehicle_id')::uuid;
        v_recalled := v_recalled + 1;
      END LOOP;

      IF v_recalled > 0 THEN
        PERFORM ottoq_record_event(
          p_actor_type:='ottoq_engine', p_actor_id:='overnight_recall',
          p_event_type:='twin.overnight_surplus_recall', p_entity_type:='system',
          p_payload:=jsonb_build_object('recalled',v_recalled,'hour_cst',v_hour,
            'desired',v_desired_deployed,'deployed_before',v_currently_deployed,'cap',v_cap,
            'holdout_active', NOT (v_hour >= v_win_end AND v_hour < v_win_start)),
          p_severity:='info', p_ingest_source:='twin', p_data_source:='twin', p_sim_run_id:=p_sim_run_id);
      END IF;
    END IF;
  END IF;

  RETURN v_count;
END;
$function$;
-- @@ function twin.ottoq_sim_auto_charge_assign_tick(p_sim_run_id uuid, p_sim_clock_now timestamp with time zone)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_auto_charge_assign_tick(p_sim_run_id uuid, p_sim_clock_now timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_vehicle    RECORD;
  v_stall_id   UUID;
  v_count      INTEGER := 0;
  v_session_id UUID;
  v_target_soc NUMERIC;
  v_seed       BIGINT;
BEGIN
  v_seed := abs(hashtextextended(COALESCE((SELECT random_seed::text FROM ottoq_sim_runs WHERE sim_run_id = p_sim_run_id), '42') || twin.ottoq_sim_clock_salt(p_sim_run_id, p_sim_clock_now) || 'assign', 13));   -- 0051: run-relative salt, never the absolute clock

  FOR v_vehicle IN
    SELECT id, current_soc, target_soc, fleet_operator_id, inlet_type, home_depot_id
      FROM vehicles
     WHERE current_state = 'arrived_at_gate'
       AND category = 'autonomous'
       AND current_soc < 85
     ORDER BY current_soc ASC, id                      -- lowest SOC first (most urgent); 0051: run-stable id tiebreak, never heap order
  LOOP
    v_stall_id := NULL;                                -- FIX 3: never inherit the previous vehicle's stall

    -- DCFC if low SOC; L2 otherwise
    IF v_vehicle.current_soc < 50 THEN
      SELECT s.id INTO v_stall_id
        FROM stalls s
        LEFT JOIN ocpp_sessions cs
               ON cs.stall_id = s.id
              AND cs.status = 'active'::ocpp_session_status   -- FIX 1: real label, index-usable
              AND cs.sim_run_id = p_sim_run_id                -- FIX 2: run-scoped
              AND (cs.ended_at IS NULL OR cs.ended_at > p_sim_clock_now)
       WHERE s.depot_id = v_vehicle.home_depot_id
         AND s.stall_type = 'dcfc'::stall_type
         AND s.current_vehicle_id IS NULL                     -- physically empty too
         AND cs.id IS NULL
       ORDER BY ottoq_sim_seeded_random(v_seed, 'dcfc:' || s.id::text)
       LIMIT 1;
    END IF;

    IF v_stall_id IS NULL THEN
      SELECT s.id INTO v_stall_id
        FROM stalls s
        LEFT JOIN ocpp_sessions cs
               ON cs.stall_id = s.id
              AND cs.status = 'active'::ocpp_session_status
              AND cs.sim_run_id = p_sim_run_id
              AND (cs.ended_at IS NULL OR cs.ended_at > p_sim_clock_now)
       WHERE s.depot_id = v_vehicle.home_depot_id
         AND s.stall_type = 'l2'::stall_type
         AND s.current_vehicle_id IS NULL
         AND cs.id IS NULL
       ORDER BY ottoq_sim_seeded_random(v_seed, 'l2:' || s.id::text)
       LIMIT 1;
    END IF;

    -- Couldn't find a free stall — leave vehicle queued at gate. THIS IS THE POINT:
    -- a naive assigner must feel charger scarcity, which it never did before.
    IF v_stall_id IS NULL THEN CONTINUE; END IF;

    -- 0539 (CLAUDE.md rule 9): the car charges to its own target. The A.10 `target_soc` profile knob shifted it,
    -- clamped to 50-100%: a scenario lowering the owner's target. No variability profile carried it (0 of 19).
    v_target_soc := COALESCE(v_vehicle.target_soc, public.ottoq_default_target_soc());

    BEGIN
      v_session_id := ottoq_sim_start_charge_session(
        v_vehicle.id, v_stall_id, p_sim_run_id, v_target_soc, p_sim_clock_now);
    EXCEPTION WHEN OTHERS THEN
      CONTINUE;        -- lost a race, or uniq_ocpp_active_session_per_stall fired; skip this tick
    END;

    IF v_session_id IS NULL THEN CONTINUE; END IF;

    v_count := v_count + 1;

    PERFORM ottoq_record_event(
      p_actor_type    := 'ottoq_engine',
      p_actor_id      := 'twin_auto_charge_assigner',
      p_event_type    := 'twin.auto_charge_assign',
      p_entity_type   := 'vehicle',
      p_entity_id     := v_vehicle.id,
      p_payload       := jsonb_build_object(
        'session_id', v_session_id, 'soc_at_assign', v_vehicle.current_soc,
        'target_soc', v_target_soc),
      p_severity      := 'info',
      p_ingest_source := 'twin',
      p_data_source   := 'twin',
      p_sim_run_id    := p_sim_run_id);
  END LOOP;

  RETURN v_count;
END;
$function$;
-- @@ function public.ottoq_sim_advance_tick(p_sim_run_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_sim_advance_tick(p_sim_run_id uuid)
 RETURNS TABLE(out_sim_clock_after timestamp with time zone, out_tick_minutes numeric, out_dispatched integer, out_telemetry_emitted integer, out_charge_assigned integer, out_charge_advanced integer, out_completed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE w RECORD; d RECORD;
BEGIN
  -- 0196: transaction-local flags are TICK-local by contract. Under pg_cron a tick
  -- is its own transaction and these die with it; under the certification pair
  -- both arms and every tick share one transaction, so a grant stamped in arm A
  -- authorised stall vacates in arm B (db/checks/0111). Clear them here so every
  -- driver sees the same world at every tick boundary.
  PERFORM set_config('ottoq.reassign_ok', '', true);
  PERFORM set_config('ottoq.skip_wash_bump', '', true); /* 0196 */
  -- 0654: with twin_operator_door on, the twin's operators answer the directives the last tick issued before the world
  -- moves. Here (a pair, a sweep, a jump) that is the caller's transaction; the metronome gives it its own.
  IF ottoq_policy_get(p_sim_run_id, 'twin_operator_door', 0) >= 1 THEN
    PERFORM twin.ottoq_twin_operator_step(p_sim_run_id);
  END IF;
  SELECT * INTO w FROM ottoq_sim_advance_tick_world(p_sim_run_id);
  IF w.out_completed AND w.out_sim_clock_after IS NULL THEN
    -- 0102: a run that completes naturally gets the SAME teardown as a stopped one.
    -- Finalized HERE -- after the world function has returned and every phase loop
    -- closed -- because mid-world teardown (0101's seam) trips on in-flight state.
    -- GUC pinned per 0092 so teardown events carry this run.
    BEGIN
      PERFORM set_config('ottoq.sim_run_id', p_sim_run_id::text, true);
      PERFORM ottoq_sim_release_depot(p_sim_run_id, 'sim_clock_end_reached');
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'advance_tick completion teardown FAILED: % %', SQLSTATE, SQLERRM;
    END;
    out_completed:=TRUE; RETURN NEXT; RETURN;
  END IF;
  -- 0360 (G76): release reservations whose holder can no longer use them,
  -- and those expired on the SIM clock, BEFORE this tick decides. The depot
  -- was measured at 155 of 158 stalls reserved and 21 occupied, so every
  -- proposer saw ~1% of a site that was 87% free. Never allowed to abort the
  -- tick: the function returns ok:false rather than raising, and this handler
  -- is the second line of that same defence.
  BEGIN
    PERFORM public.ottoq_release_unusable_reservations(p_sim_run_id);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING '0360 release_unusable_reservations: % %', SQLSTATE, SQLERRM;
  END;
  SELECT * INTO d FROM ottoq_sim_decide_and_dispatch(p_sim_run_id);
  -- 0735 (G449, G450): with twin_answer_in_tick on, the twin carries out in this tick the commands this tick's decide
  -- gave, and plugs in a car seated on a charger; off, they wait for the next tick's world step, as they always did.
  IF NOT COALESCE(w.out_completed, false) AND w.out_sim_clock_after IS NOT NULL
     AND COALESCE(ottoq_policy_get(p_sim_run_id, 'twin_answer_in_tick', 0), 0) >= 1 THEN
    PERFORM twin.ottoq_sim_answer_in_tick(p_sim_run_id, w.out_sim_clock_after);
  END IF;
  -- 0736 (G383): with ready_promise_record on, each visit first seen this tick is promised a ready time, and the
  -- promise recorded; it decides nothing. Off, nothing is recorded.
  IF NOT COALESCE(w.out_completed, false) AND w.out_sim_clock_after IS NOT NULL
     AND COALESCE(ottoq_policy_get(p_sim_run_id, 'ready_promise_record', 0), 0) >= 1 THEN
    PERFORM twin.ottoq_sim_record_ready_promises(p_sim_run_id, w.out_sim_clock_after);
  END IF;
  out_sim_clock_after:=w.out_sim_clock_after; out_tick_minutes:=w.out_tick_minutes;
  out_dispatched:=d.out_dispatched; out_telemetry_emitted:=w.out_telemetry_emitted;
  out_charge_assigned:=d.out_charge_assigned; out_charge_advanced:=w.out_charge_advanced;
  out_completed:=w.out_completed;
  -- 0103: the LIVE completion seam. advance_tick_world writes status='completed'
  -- mid-function and still returns a non-NULL clock, so the early branch above
  -- never fires; decide_and_dispatch has also already run (and may have issued
  -- commands post-completion -- the finalizer expires them). Finalize HERE, after
  -- the full tick. GUC pinned per 0092 so teardown events carry this run.
  IF w.out_completed THEN
    BEGIN
      PERFORM set_config('ottoq.sim_run_id', p_sim_run_id::text, true);
      PERFORM ottoq_sim_release_depot(p_sim_run_id, 'sim_clock_end_reached');
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'advance_tick completion teardown FAILED: % %', SQLSTATE, SQLERRM;
    END;
  END IF;
  RETURN NEXT;
END;
$function$;
-- @@ function public.ottoq_sim_advance_due_runs(p_max_runs integer)
CREATE OR REPLACE FUNCTION public.ottoq_sim_advance_due_runs(p_max_runs integer DEFAULT 10)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_run     RECORD;
  v_total   INTEGER := 0;
BEGIN
  FOR v_run IN
    SELECT sim_run_id FROM ottoq_sim_runs
     WHERE status = 'running'
       AND next_tick_due_at <= NOW()
     ORDER BY next_tick_due_at ASC
     LIMIT p_max_runs
  LOOP
    PERFORM ottoq_sim_advance_tick(v_run.sim_run_id);
    v_total := v_total + 1;
  END LOOP;
  RETURN v_total;
END;
$function$;
-- @@ function public.ottoq_apply_profile(p_sim_run_id uuid, p_var text, p_raw numeric, p_mean numeric)
CREATE OR REPLACE FUNCTION public.ottoq_apply_profile(p_sim_run_id uuid, p_var text, p_raw numeric, p_mean numeric DEFAULT NULL::numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_knobs    JSONB;
  v_knob     JSONB;
  v_gspread  NUMERIC;
  v_spread   NUMERIC;
  v_shift    NUMERIC;
  v_floor    NUMERIC;
  v_ceiling  NUMERIC;
  v_mean     NUMERIC;
  v_out      NUMERIC;
BEGIN
  IF p_sim_run_id IS NULL OR p_raw IS NULL THEN
    RETURN p_raw;
  END IF;

  SELECT knobs INTO v_knobs
    FROM ottoq_variability_profiles
   WHERE sim_run_id = p_sim_run_id;

  -- No profile → identity (behaves exactly like today)
  IF v_knobs IS NULL THEN
    RETURN p_raw;
  END IF;

  v_knob    := COALESCE(v_knobs -> p_var, '{}'::jsonb);
  v_gspread := COALESCE((v_knobs #>> '{_global,spread_mult}')::numeric, 1);
  v_spread  := COALESCE((v_knob ->> 'spread')::numeric, 1) * v_gspread;
  v_shift   := COALESCE((v_knob ->> 'shift')::numeric, 0);
  v_floor   := (v_knob ->> 'floor')::numeric;     -- may be NULL
  v_ceiling := (v_knob ->> 'ceiling')::numeric;   -- may be NULL

  -- Fast path: fully neutral knob
  IF v_spread = 1 AND v_shift = 0 AND v_floor IS NULL AND v_ceiling IS NULL THEN
    RETURN p_raw;
  END IF;

  -- Center for variance widening
  v_mean := p_mean;
  IF v_mean IS NULL THEN
    SELECT mean_value INTO v_mean
      FROM ottoq_calibration_distributions
     WHERE variable_name = p_var AND segment = 'global'
     LIMIT 1;
  END IF;
  v_mean := COALESCE(v_mean, p_raw);

  v_out := v_mean + (p_raw - v_mean) * v_spread + v_shift;

  IF v_floor   IS NOT NULL THEN v_out := GREATEST(v_out, v_floor);   END IF;
  IF v_ceiling IS NOT NULL THEN v_out := LEAST(v_out, v_ceiling);    END IF;

  RETURN v_out;
END;
$function$;
-- @@ function public.ottoq_profile_rate_mult(p_sim_run_id uuid, p_event text)
CREATE OR REPLACE FUNCTION public.ottoq_profile_rate_mult(p_sim_run_id uuid, p_event text)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_knobs  JSONB;
  v_global NUMERIC;
  v_rate   NUMERIC;
BEGIN
  IF p_sim_run_id IS NULL THEN RETURN 1; END IF;

  SELECT knobs INTO v_knobs
    FROM ottoq_variability_profiles
   WHERE sim_run_id = p_sim_run_id;
  IF v_knobs IS NULL THEN RETURN 1; END IF;

  v_global := COALESCE((v_knobs #>> '{_global,rate_mult}')::numeric, 1);
  v_rate   := COALESCE((v_knobs #>> ARRAY['_rates', p_event])::numeric, 1);
  RETURN v_rate * v_global;
END;
$function$;
-- @@ function public.ottoq_sample_shaped(p_sim_run_id uuid, p_var text, p_segment text, p_seed bigint, p_salt text)
CREATE OR REPLACE FUNCTION public.ottoq_sample_shaped(p_sim_run_id uuid, p_var text, p_segment text, p_seed bigint, p_salt text)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_raw NUMERIC;
BEGIN
  v_raw := ottoq_sample_calibrated(p_var, p_segment, p_seed, p_salt);
  IF v_raw IS NULL THEN RETURN NULL; END IF;
  RETURN ottoq_apply_profile(p_sim_run_id, p_var, v_raw);
END;
$function$;
-- @@ function public.ottoq_variability_instantiate(p_sim_run_id uuid, p_template_name text)
CREATE OR REPLACE FUNCTION public.ottoq_variability_instantiate(p_sim_run_id uuid, p_template_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_knobs JSONB;
  v_id    UUID;
BEGIN
  SELECT knobs INTO v_knobs FROM ottoq_variability_profiles
   WHERE name = p_template_name;
  IF v_knobs IS NULL THEN
    SELECT knobs INTO v_knobs FROM ottoq_variability_profiles WHERE name = '__default__';
  END IF;
  v_knobs := COALESCE(v_knobs, '{}'::jsonb);

  INSERT INTO ottoq_variability_profiles (sim_run_id, name, knobs, notes)
  VALUES (p_sim_run_id, NULL, v_knobs, 'instantiated from ' || p_template_name)
  ON CONFLICT (sim_run_id) DO UPDATE SET knobs = EXCLUDED.knobs, updated_at = NOW()
  RETURNING profile_id INTO v_id;

  RETURN v_id;
END;
$function$;
-- @@ function twin.ottoq_sim_maybe_spawn_dtc(p_seed bigint, p_salt text, p_tick_minutes numeric, p_active_fraction numeric, p_rate_mult numeric)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_maybe_spawn_dtc(p_seed bigint, p_salt text, p_tick_minutes numeric, p_active_fraction numeric, p_rate_mult numeric DEFAULT 1)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  -- Calibrate: CA DMV median ~5000 mi per disengagement-equivalent event.
  -- At 50 km/h avg, that's ~5000 mi / 31 mph = 161 hours of driving = ~9700
  -- active-drive-minutes per event. So per active-drive minute, p ≈ 1/9700.
  v_per_active_min NUMERIC := 0.0001;
  v_effective_p    NUMERIC;
  v_roll           NUMERIC;
  v_pick           NUMERIC;
BEGIN
  v_effective_p := v_per_active_min * p_tick_minutes * p_active_fraction * COALESCE(p_rate_mult, 1);
  v_roll := ottoq_sim_seeded_random(p_seed, 'dtc_roll:' || p_salt);
  IF v_roll >= v_effective_p THEN RETURN NULL; END IF;

  -- Sample from DTC catalog weighted by category mix calibrated to DMV
  -- cause distribution (perception 28, planning 25, hardware 18, software 14,
  -- weather_road 10, operator 5).
  v_pick := ottoq_sim_seeded_random(p_seed, 'dtc_pick:' || p_salt);
  RETURN (
    SELECT dtc_code FROM ottoq_dtc_catalog
     WHERE category = CASE
       WHEN v_pick < 0.28 THEN 'perception'
       WHEN v_pick < 0.53 THEN 'planning'
       WHEN v_pick < 0.71 THEN 'hardware'
       WHEN v_pick < 0.85 THEN 'software'
       WHEN v_pick < 0.95 THEN 'weather_road'
       ELSE                    'operator'
     END
     ORDER BY ottoq_sim_seeded_random(p_seed, 'dtc_idx:' || p_salt || dtc_code)
     LIMIT 1
  );
END;
$function$;
-- @@ function public.ottoq_twin_depot_layout(p_depot_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_twin_depot_layout(p_depot_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_out JSONB;
BEGIN
  SELECT jsonb_build_object(
    'depot', (
      SELECT jsonb_build_object(
        'id', d.id, 'name', d.name,
        'origin_lat', d.origin_lat, 'origin_lng', d.origin_lng
      ) FROM depots d WHERE d.id = p_depot_id
    ),
    'structures', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'code', s.structure_code, 'kind', s.structure_kind, 'title', s.title,
        'x_ft', s.origin_x_ft, 'y_ft', s.origin_y_ft,
        'width_ft', s.width_ft, 'length_ft', s.length_ft,
        'height_ft', s.height_ft, 'rotation_deg', s.rotation_deg
      ) ORDER BY s.structure_code)
      FROM ottoq_site_structures s WHERE s.depot_id = p_depot_id
    ), '[]'::jsonb),
    'stalls', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', st.id, 'code', st.stall_code, 'type', st.stall_type,
        'zone', st.zone, 'canopy', st.canopy_code, 'covered', st.covered,
        'x', st.relative_x, 'y', st.relative_y, 'heading', st.heading_degrees,
        'connector_kw', st.connector_max_kw
      ) ORDER BY st.stall_code)
      FROM stalls st WHERE st.depot_id = p_depot_id
    ), '[]'::jsonb)
  ) INTO v_out;

  RETURN v_out;
END;
$function$;
-- @@ function public.ottoq_twin_snapshot(p_sim_run_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_twin_snapshot(p_sim_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_run     ottoq_sim_runs%ROWTYPE;
  v_depot   UUID;
  v_clock   TIMESTAMPTZ;
  v_out     JSONB;
BEGIN
  SELECT * INTO v_run FROM ottoq_sim_runs WHERE sim_run_id = p_sim_run_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'sim_run not found', 'sim_run_id', p_sim_run_id);
  END IF;
  v_depot := v_run.depot_id;
  v_clock := v_run.sim_clock_current;

  SELECT jsonb_build_object(

    'run', jsonb_build_object(
      'sim_run_id',  v_run.sim_run_id,
      'scenario',    v_run.scenario_code,
      'status',      v_run.status,
      'sim_clock',   v_clock,
      'tick_count',  v_run.tick_count,
      'time_scale',  v_run.time_scale,
      'seed',        v_run.random_seed::text,
      -- PLAYBACK CONTRACT for the renderer.
      -- 'live'  => 1 real second advances the sim clock by speed_x sim seconds (true 1:1 at 1x)
      -- 'fixed' => historical tick_interval_seconds * time_scale behaviour (certs/benchmarks)
      'playback_mode', COALESCE(v_run.payload->>'playback_mode','fixed'),
      'speed_x',       COALESCE((v_run.payload->>'speed_x')::numeric, 1.0),
      -- T5: MEASURED, not configured. NULL until >=2 ticks are logged.
      'clock_measured', (
         SELECT jsonb_build_object(
                  'ratio',            f.ratio,
                  'target',           f.target_ratio,
                  'ticks',            f.ticks_measured,
                  'p50_tick_ms',      f.p50_tick_ms,
                  'p95_tick_ms',      f.p95_tick_ms,
                  'max_speed',        f.max_sustainable_speed,
                  'within_tolerance', f.within_tolerance,
                  'verdict',          f.verdict)
           FROM ottoq_clock_fidelity(v_run.sim_run_id, 20) f),
      -- present ONLY while a fast-forward is in flight; drives the planning pause + progress
      'jump',             v_run.payload->'jump',
      -- pacing inputs: elapsed-since-last-tick and clock skew
      'last_tick_at',     v_run.last_tick_at,
      'next_tick_due_at', v_run.next_tick_due_at,
      'server_now',       now()
    ),

    -- T3 RENDER CONTRACT: timed legs. The renderer INTERPOLATES these; it must
    -- never invent motion the contract did not specify.
    'legs', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'leg_id',      l.leg_id,
        'vehicle_id',  l.vehicle_id,
        'seq',         l.seq,
        'leg_type',    l.leg_type,
        'intent',      l.duration_basis->>'intent',
        'kind',        COALESCE(l.duration_basis->>'kind','dwell'),
        'from_stall',  l.from_stall_id,
        'to_stall',    l.to_stall_id,
        'from_x',      fs.relative_x, 'from_y', fs.relative_y,
        'to_x',        ts.relative_x, 'to_y',   ts.relative_y,
        'start_sim',   l.planned_start_sim,
        'end_sim',     l.planned_end_sim,
        'duration_s',  l.planned_duration_s,
        'status',      l.status,
        'geometry',    COALESCE(l.duration_basis->>'geometry','n/a'))
        ORDER BY l.vehicle_id, l.seq)
        FROM ottoq_itinerary_legs l
        LEFT JOIN stalls fs ON fs.id = l.from_stall_id
        LEFT JOIN stalls ts ON ts.id = l.to_stall_id
       WHERE l.sim_run_id = v_run.sim_run_id
         AND (
           CASE WHEN COALESCE(l.duration_basis->>'kind','dwell') = 'travel'
                -- TRAVEL: covered until CLOSED. ottoq_itin_close_travel_legs bounds
                -- it (arrived / superseded / stale), so a drive that overruns its
                -- estimate stays covered instead of falling off a time cliff.
                THEN l.status NOT IN ('done','amended','skipped')
                -- DWELL: durations are authoritative, keep the time window.
                ELSE l.status <> 'done'
                     AND l.planned_end_sim   >= v_clock - interval '10 minutes'
                     AND l.planned_start_sim <= v_clock + interval '10 minutes'
           END)
    ), '[]'::jsonb),

    -- #173 (D): server half of the CONTRACT COVERAGE ratio. The renderer knows
    -- how many cars are physically taxiing; only it can close the ratio. Publish
    -- the denominator so coverage is measurable instead of assumed.
    'legs_meta', jsonb_build_object(
      'open_travel_legs', (
        SELECT count(*) FROM ottoq_itinerary_legs l2
         WHERE l2.sim_run_id = v_run.sim_run_id
           AND l2.duration_basis->>'kind' = 'travel'
           AND l2.status NOT IN ('done','amended','skipped')),
      'vehicles_with_open_leg', (
        SELECT count(DISTINCT l3.vehicle_id) FROM ottoq_itinerary_legs l3
         WHERE l3.sim_run_id = v_run.sim_run_id
           AND l3.duration_basis->>'kind' = 'travel'
           AND l3.status NOT IN ('done','amended','skipped')),
      'closed_this_run', (
        SELECT count(*) FROM ottoq_itinerary_legs l4
         WHERE l4.sim_run_id = v_run.sim_run_id
           AND l4.duration_basis->>'kind' = 'travel'
           AND l4.status = 'done'),
      'median_deviation_s', (
        SELECT round(percentile_cont(0.5) WITHIN GROUP (ORDER BY l5.deviation_s)::numeric, 1)
          FROM ottoq_itinerary_legs l5
         WHERE l5.sim_run_id = v_run.sim_run_id
           AND l5.duration_basis->>'kind' = 'travel'
           AND l5.deviation_s IS NOT NULL)),

    'fleet', jsonb_build_object(
      'counts', (
        SELECT jsonb_object_agg(state, n) FROM (
          SELECT current_state::text AS state, COUNT(*) AS n
            FROM vehicles WHERE category = 'autonomous' AND home_depot_id = v_depot
           GROUP BY current_state
        ) c
      ),
      'total', (SELECT COUNT(*) FROM vehicles WHERE category = 'autonomous' AND home_depot_id = v_depot),
      'vehicles', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', v.id, 'av_id', v.av_api_vehicle_id, 'make', v.make,
          'platform', v.platform, 'state', v.current_state,
          'soc', ROUND(v.current_soc::numeric, 1), 'stall_id', v.current_stall_id,
          -- 0762 (G480): a car in a wash, detail or service bay carries its seat there: when it entered the bay (the
          -- bay door changes its state) and when the twin's timer ends its work (config.service_ends_at, which 0746
          -- times by the work). Both are on the sim clock. The renderer plays the bay's robot inside this window.
          -- The timer goes through public.ottoq_try_timestamptz, so a malformed one is null and cannot end the
          -- snapshot. NULL for a car in no bay.
          'bay_seat', CASE WHEN v.current_state::text IN ('in_wash_bay', 'in_detail_bay', 'in_service_bay')
                           THEN jsonb_build_object(
                                  'since', v.last_state_change,
                                  'ends_at', public.ottoq_try_timestamptz(v.config ->> 'service_ends_at'))
                      END,
          -- VISIT WORKFLOW. What OTTO-Q decided this car needs THIS visit, and
          -- how far through it the car is. NULL when there is no open visit for
          -- this run — the renderer must show that as "no workflow published",
          -- never as an empty checklist meaning "nothing needed".
          -- Selection mirrors ottoq_mark_visit_atoms_done (open/in_progress,
          -- newest first) and is additionally scoped to THIS run so a snapshot
          -- of a finished run can never borrow a live run's workflow.
          'visit', vn.card
        ) ORDER BY v.av_api_vehicle_id)
        FROM vehicles v
        LEFT JOIN LATERAL (
          SELECT jsonb_build_object(
            'visit_id',       n.visit_id,
            'visit_status',   n.status,
            'archetype',      n.archetype,
            'urgency',        n.urgency,
            'arrived_at',     n.arrived_at,
            'target_soc',     n.target_soc,
            -- SoC the car ENTERED on, stamped by the needs generator.
            'soc_at_arrival', CASE WHEN n.meta->>'soc_at_arrival' ~ '^-?[0-9]+(\.[0-9]+)?$'
                                   THEN (n.meta->>'soc_at_arrival')::numeric END,
            -- OTTO-Q's OWN charge estimate, lifted from the charge atom, not a
            -- re-derivation. NULL when this visit has no charge atom.
            'est_charge_min', (
              SELECT CASE WHEN ca.value->>'est_min' ~ '^[0-9]+(\.[0-9]+)?$'
                          THEN round((ca.value->>'est_min')::numeric)::int END
                FROM jsonb_array_elements(COALESCE(n.atoms,'[]'::jsonb)) ca
               WHERE ca.value->>'svc' = 'charge'
               LIMIT 1),
            -- THE BULLET LIST, in the order OTTO-Q wrote it. An atom with no
            -- status key reads 'pending' — the same COALESCE decide_tick uses.
            -- est_min is regex-guarded before its cast so one malformed atom
            -- cannot abort the whole snapshot.
            'atoms', COALESCE((
              SELECT jsonb_agg(jsonb_build_object(
                       'svc',     a.value->>'svc',
                       'status',  lower(COALESCE(a.value->>'status','pending')),
                       'must_do', COALESCE((a.value->>'must_do')::boolean, false),
                       -- 0512 (G236): who performed it (charger_sensors; absent for a technician), whether it waits
                       -- on the triage check's verdict, and the verdict once given
                       'performed_by', a.value->>'performed_by',
                       'awaiting_triage', COALESCE((a.value->>'confirm_required')::boolean, false)
                                          AND lower(COALESCE(a.value->>'status','pending')) = 'pending',
                       'triage_verdict', a.value->>'triage_verdict',
                       'est_min', CASE WHEN a.value->>'est_min' ~ '^[0-9]+(\.[0-9]+)?$'
                                       THEN (a.value->>'est_min')::numeric END,
                       -- 0758: when the work started and ends and when it was done (the sim clock, as the engine wrote
                       -- them), and the stall whose cleaning arm does it, so the renderer plays the arm on the twin's own
                       -- times. Each is null when absent; a value that is not a JSON string reads null.
                       'started_at', CASE WHEN jsonb_typeof(a.value->'started_at') = 'string' THEN a.value->'started_at' END,
                       'ends_at', CASE WHEN jsonb_typeof(a.value->'ends_at') = 'string' THEN a.value->'ends_at' END,
                       'done_at', CASE WHEN jsonb_typeof(a.value->'done_at') = 'string' THEN a.value->'done_at' END,
                       'robot_stall_id', a.value->>'robot_stall_id')
                     ORDER BY a.ord)
                FROM jsonb_array_elements(COALESCE(n.atoms,'[]'::jsonb))
                     WITH ORDINALITY AS a(value, ord)
            ), '[]'::jsonb)
          ) AS card
            FROM ottoq_visit_needs n
           WHERE n.vehicle_id = v.id
             AND n.sim_run_id = v_run.sim_run_id
             AND n.status IN ('open','in_progress')
           ORDER BY n.created_at DESC
           LIMIT 1
        ) vn ON TRUE
        WHERE v.category = 'autonomous' AND v.home_depot_id = v_depot
      ), '[]'::jsonb)
    ),

    -- Live stall status only (geometry comes from layout, cached once)
    -- 0011-TETHER: 'tethered' is what lets the cockpit draw a CONNECTED CABLE. The car is
    -- no longer charging and no longer points at the stall, so without this flag the
    -- renderer has nothing to distinguish "robot still mated" from "stall simply busy".
    -- 'tether_until' is the sim-clock demate deadline, so the arm retract can be animated
    -- against the same clock the legs use. The LEFT JOIN is filtered on v_clock, so an
    -- expired tether reads as false even in the beat before the sweep clears it.
    -- The status filter gains an OR: a tethered stall must stay in the payload even if
    -- something flips its status to 'available' mid-window, or the cable would vanish.
    'stalls_status', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', st.id,
        -- 0612: a stall whose charger is Faulted reads 'faulted' until the drawn repair ends, so the twin draws it down
        -- and its assignment pool drops it. The engine's own candidate source refuses it already (0372).
        'status', CASE WHEN oc.station_state = 'Faulted' THEN 'faulted' ELSE st.status::text END,
        'vehicle_id', st.current_vehicle_id,
        'charger_state', oc.station_state,
        'fault_code', CASE WHEN oc.station_state = 'Faulted' THEN oc.last_fault_code END,
        'fault_until', CASE WHEN oc.station_state = 'Faulted' THEN oc.station_state_changed_at
                              + ((oc.last_fault_payload ->> 'repair_minutes')::numeric || ' minutes')::interval END,
        -- WHO the stall is held for, so the renderer can drive the car to the
        -- stall OTTO-Q actually chose instead of picking one itself. Without
        -- this the cockpit knew only that a stall was 'reserved' and fell back
        -- to its own nearest-the-gate pool, which is the south perimeter — so a
        -- car parked on the ring while a short-term spot sat held for it.
        -- Scoped to LIVE reservations against the SIM clock, which is the clock
        -- ottoq_reserve_stall stamps the expiry in. An expired hold is not an
        -- instruction.
        'reserved_by', CASE WHEN st.reservation_expires_at IS NULL
                                OR st.reservation_expires_at > v_clock
                           THEN st.reserved_by END,
        'reserved_until', st.reservation_expires_at,
        'tethered', (tv.id IS NOT NULL),
        'tether_until', tv.robotic_tether_until,
        -- WHICH WAY the robot is going, and where it has got to. 'tethered' alone
        -- cannot distinguish an arm reaching in from an arm pulling out, and the
        -- renderer has to animate those in opposite directions.
        'tether_direction', tv.robotic_tether_direction,
        'tether_phase', tv.robotic_tether_phase
      ))
      FROM stalls st
      LEFT JOIN public.ottoq_ocpp_chargers oc ON oc.charger_id = st.ocpp_charger_id   -- 0612
      LEFT JOIN vehicles tv
        ON tv.robotic_tether_stall_id = st.id
       AND tv.robotic_tether_until IS NOT NULL
       AND tv.robotic_tether_until > v_clock
      WHERE st.depot_id = v_depot
        AND (st.status::text <> 'available'       -- only occupied/charging/faulted (light payload)
             OR oc.station_state = 'Faulted'      -- 0612: ...plus any stall whose charger is down
             OR tv.id IS NOT NULL                 -- ...plus any stall a robot is still holding
             OR (st.reserved_by IS NOT NULL       -- ...plus any stall HELD for an inbound car,
                 AND (st.reservation_expires_at IS NULL
                      OR st.reservation_expires_at > v_clock)))  -- which is usually still 'available'
    ), '[]'::jsonb),

    'energy', (
      SELECT jsonb_build_object(
        'grid_import_kw', se.grid_import_kw, 'grid_export_kw', se.grid_export_kw,
        'solar_kw', se.solar_generation_kw, 'bess_output_kw', se.bess_output_kw,
        'ev_charging_kw', se.total_ev_charging_kw, 'building_kw', se.building_load_kw,
        'peak_15min_kw', se.peak_demand_kw_15min,
        'tariff', se.current_tariff_label, 'rate_per_kwh', se.current_rate_per_kwh,
        'at', se.timestamp
      )
      FROM site_energy_snapshots se WHERE se.depot_id = v_depot
        AND se.sim_run_id = v_run.sim_run_id
        AND se.timestamp <= v_clock
        AND se.timestamp >= v_run.sim_clock_start   -- scope to THIS run's sim-time window
      ORDER BY se.timestamp DESC LIMIT 1
    ),

    'bess', (
      SELECT jsonb_build_object(
        'soc_pct', b.current_soc_pct, 'power_kw', b.current_power_kw,
        'state', b.current_state, 'temp_c', b.current_temperature_c,
        'soh_pct', b.current_soh_pct
      )
      FROM ottoq_bess_units b WHERE b.depot_id = v_depot LIMIT 1
    ),

    'weather', (
      SELECT jsonb_build_object(
        'temp_c', w.ambient_temp_c, 'cloud_pct', w.cloud_cover_pct,
        'conditions', w.conditions_label, 'precip', w.precip_state,
        'ghi_wm2', w.ghi_wm2, 'wind_kmh', w.wind_speed_kmh,
        'solar_elev_deg', w.solar_elevation_deg, 'at', w.sim_clock_at,
        'humidity_pct', w.relative_humidity_pct
      )
      FROM ottoq_weather_snapshots w WHERE w.sim_run_id = p_sim_run_id
      ORDER BY w.sim_clock_at DESC, w.snapshot_id DESC  /* 0134 */ LIMIT 1
    ),

    'grid', (
      SELECT jsonb_build_object(
        'lmp_usd_mwh', g.lmp_usd_per_mwh, 'tariff', g.current_tariff_label,
        'carbon_gco2_kwh', g.carbon_intensity_gco2_per_kwh,
        'voltage_status', g.voltage_status, 'frequency_hz', g.frequency_hz,
        'reserve_margin_pct', g.reserve_margin_pct,
        'dr_active', (g.active_dr_call_id IS NOT NULL),
        'dr_cap_kw', g.dr_required_load_cap_kw, 'at', g.sim_clock_at
      )
      FROM ottoq_grid_snapshots g WHERE g.sim_run_id = p_sim_run_id
      ORDER BY g.sim_clock_at DESC LIMIT 1
    ),

    'counters', jsonb_build_object(
      'dispatches_active', (SELECT COUNT(*) FROM ottoq_vehicle_dispatches
                             WHERE sim_run_id = p_sim_run_id AND status IN ('active','returning')),
      'dispatches_total',  (SELECT COUNT(*) FROM ottoq_vehicle_dispatches WHERE sim_run_id = p_sim_run_id),
      'telemetry_packets', (SELECT COUNT(*) FROM ottoq_telemetry_packets WHERE sim_run_id = p_sim_run_id),
      'charge_sessions',   (SELECT COUNT(*) FROM ocpp_sessions cs WHERE cs.sim_run_id = p_sim_run_id),
      'events_total',      (SELECT COUNT(*) FROM ottoq_events WHERE sim_run_id = p_sim_run_id),
      'open_incidents',    (SELECT COUNT(*) FROM ottoq_vehicle_incidents
                             WHERE sim_run_id = p_sim_run_id AND resolution_status = 'open')
    ),

    'recent_events', COALESCE((
      SELECT jsonb_agg(e) FROM (
        SELECT jsonb_build_object(
          'type', event_type, 'severity', severity,
          'at', occurred_at, 'entity', entity_type,
          'payload', payload
        ) AS e
        FROM ottoq_events
        WHERE sim_run_id = p_sim_run_id
          AND event_type NOT IN (
            'twin.bess_dispatch','twin.weather_tick','twin.solar_tick','twin.grid_tick',
            'twin.sim_tick_advanced','twin.telemetry_emitted','twin.bess_soh_degradation'
          )
        ORDER BY occurred_at DESC LIMIT 15
      ) sub
    ), '[]'::jsonb),

    -- THE ARM CONTRACT. armStateMachine.ts in ottoyarddepot-sim used to DEFINE
    -- these numbers; it now READS them here, so retuning the arm is one edit to
    -- ottoq_policy_params and both worlds move together. demate_seconds is what
    -- OTTO-Q reserves the plug for; connect_seconds is the inbound mate window.
    -- SCALE AND UNITS, so a renderer never has to guess them. See
    -- the_site_geometry_contract_has_one_home.
    'geometry', public.ottoq_site_geometry(p_sim_run_id),
    'arm', jsonb_build_object(
      'timings', public.ottoq_arm_timings(p_sim_run_id),
      -- REGISTRATION ACCURACY. Millimetres between where the arm believed the
      -- inlet was and where it actually was, and how often that was close
      -- enough on the first reach. Empty reads as "nothing measured", never as
      -- a perfect score.
      'accuracy', twin.ottoq_arm_accuracy(p_sim_run_id),
      -- THE INBOUND HALF, which the cockpit could not see at all before: the arm
      -- reaching, aligning, inserting and latching, plus any retry it is on.
      -- Open cycles only — a closed one is history and belongs in the event log.
      'cycles', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'cycle_id', ac.cycle_id, 'stall_id', ac.stall_id, 'vehicle_id', ac.vehicle_id,
          'direction', ac.direction, 'phase', ac.phase,
          'phase_deadline', ac.phase_deadline, 'started_at', ac.started_at,
          'retry_count', ac.retry_count))
          FROM twin.arm_cycles ac
         WHERE ac.sim_run_id = p_sim_run_id AND ac.ended_at IS NULL
      ), '[]'::jsonb)),

    'variability', COALESCE((
      SELECT knobs FROM ottoq_variability_profiles WHERE sim_run_id = p_sim_run_id
    ), '{}'::jsonb)

  ) INTO v_out;

  RETURN v_out;
END;
$function$;
-- @@ function twin.ottoq_sim_sample_voltage_event(p_seed bigint, p_salt text, p_rate_mult numeric)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_sample_voltage_event(p_seed bigint, p_salt text, p_rate_mult numeric DEFAULT 1)
 RETURNS TABLE(out_status text, out_voltage_v numeric)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_roll NUMERIC;
  v_m    NUMERIC := COALESCE(p_rate_mult, 1);
BEGIN
  v_roll := ottoq_sim_seeded_random(p_seed, p_salt || '_volt');

  IF v_roll < 0.000008 * v_m THEN          -- ~1-2 per year per hour-bucket (× knob)
    out_status := 'brownout';
    out_voltage_v := 380 + ottoq_sim_seeded_random(p_seed, p_salt || '_v') * 40;
  ELSIF v_roll < 0.0002 * v_m THEN          -- ~1-3 per month (× knob)
    out_status := 'sag';
    out_voltage_v := 440 + ottoq_sim_seeded_random(p_seed, p_salt || '_v') * 30;
  ELSIF v_roll < 0.0004 * v_m THEN
    out_status := 'swell';
    out_voltage_v := 500 + ottoq_sim_seeded_random(p_seed, p_salt || '_v') * 20;
  ELSE
    out_status := 'nominal';
    out_voltage_v := 478 + ottoq_sim_seeded_random(p_seed, p_salt || '_v') * 5;
  END IF;
  RETURN NEXT;
END;
$function$;
-- @@ function twin.ottoq_sim_sample_frequency_hz(p_seed bigint, p_salt text, p_rate_mult numeric)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_sample_frequency_hz(p_seed bigint, p_salt text, p_rate_mult numeric DEFAULT 1)
 RETURNS TABLE(out_status text, out_freq_hz numeric)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_roll NUMERIC;
  v_freq NUMERIC;
BEGIN
  v_roll := ottoq_sim_seeded_random(p_seed, p_salt || '_freq_roll');
  v_freq := 60.0 + (ottoq_sim_seeded_random(p_seed, p_salt || '_freq') - 0.5) * 0.05;

  IF v_roll < 0.0005 * COALESCE(p_rate_mult, 1) THEN   -- ~once a week excursion (× knob)
    v_freq := v_freq + (CASE WHEN ottoq_sim_seeded_random(p_seed, p_salt||'_dir') > 0.5
                              THEN 1 ELSE -1 END) * (0.10 + ottoq_sim_seeded_random(p_seed, p_salt||'_mag') * 0.15);
    out_status := 'excursion';
  ELSE
    out_status := 'nominal';
  END IF;
  out_freq_hz := ROUND(v_freq::numeric, 3);
  RETURN NEXT;
END;
$function$;
-- @@ function twin.ottoq_sim_lane_capacity(p_sim_run_id uuid, p_lane_staff_key text, p_physical integer)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_lane_capacity(p_sim_run_id uuid, p_lane_staff_key text, p_physical integer)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_knobs   JSONB;
  v_master  NUMERIC;
  v_lane    NUMERIC;
BEGIN
  IF p_sim_run_id IS NULL THEN RETURN p_physical; END IF;
  SELECT knobs INTO v_knobs FROM ottoq_variability_profiles WHERE sim_run_id = p_sim_run_id;
  IF v_knobs IS NULL THEN RETURN p_physical; END IF;
  v_master := COALESCE((v_knobs #>> ARRAY['_rates','staffing_level'])::numeric, 1);
  v_lane   := COALESCE((v_knobs #>> ARRAY['_rates', p_lane_staff_key])::numeric, 1);
  -- Any positive staffing keeps at least ONE lane open (understaffing slows the
  -- flow + grows staging; it never fully gridlocks). Zero staffing = closed.
  IF v_master * v_lane <= 0 THEN RETURN 0; END IF;
  RETURN GREATEST(1, FLOOR(p_physical * v_master * v_lane))::int;
END;
$function$;
-- @@ function twin.ottoq_sim_service_minutes(p_sim_run_id uuid, p_time_key text, p_base_min numeric)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_service_minutes(p_sim_run_id uuid, p_time_key text, p_base_min numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE v_knobs JSONB; v_m NUMERIC;
BEGIN
  IF p_sim_run_id IS NULL THEN RETURN p_base_min; END IF;
  SELECT knobs INTO v_knobs FROM ottoq_variability_profiles WHERE sim_run_id = p_sim_run_id;
  v_m := COALESCE((v_knobs #>> ARRAY['_rates', p_time_key])::numeric, 1);
  RETURN GREATEST(1, p_base_min * v_m);
END;
$function$;
-- @@ function twin.ottoq_sim_advance_service_flow(p_sim_run_id uuid, p_sim_clock_now timestamp with time zone, p_tick_minutes numeric, p_depot_id uuid)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_advance_service_flow(p_sim_run_id uuid, p_sim_clock_now timestamp with time zone, p_tick_minutes numeric, p_depot_id uuid DEFAULT '11111111-1111-1111-1111-111111111111'::uuid)
 RETURNS TABLE(out_washing integer, out_servicing integer, out_staged integer, out_ready integer, out_overflow integer)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_wash_cap    INT;  v_svc_cap     INT;  v_deploy_cap  INT;
  v_wash_dur    NUMERIC; v_detail_dur NUMERIC; v_svc_dur NUMERIC;
  v_in_wash     INT;  v_in_svc      INT;  v_admitted    INT;
  v_order       TEXT;  v_rec         RECORD;  v_needs_svc   BOOLEAN;  v_overflow    INT := 0;
  v_hour        INT;  v_fleet       INT;  v_deployed    INT;  v_target      INT;
  v_pressure    BOOLEAN := FALSE;  v_fasttracked INT := 0;  v_recharged   INT := 0;
  v_floor       NUMERIC;  v_end_ts      TIMESTAMPTZ;  v_feed_sim BOOLEAN := TRUE;
  -- DEPARTURE READINESS GATE (2026-08-02)
  v_ncand       INT := 0;  v_gate_on BOOLEAN := TRUE;
  v_patience_dep NUMERIC;  v_hardcap NUMERIC;  v_relcap INT;
  v_held        INT := 0;  v_esc_gate INT := 0;  v_override INT := 0;
  -- 0009 (DEFECT 1) HONEST COMPLETION CREDIT. Four working sets and three counters.
  -- v_bay_caps    = what this bay is PHYSICALLY ABLE to do (unchanged from the pre-image).
  -- v_outstanding = what THIS VEHICLE actually still had open on THIS visit, read before
  --                 the atoms are marked done.
  -- v_flag_svcs   = the technician flag that admitted it, where the flag names the work.
  -- v_credit      = v_bay_caps INTERSECT (v_outstanding UNION v_flag_svcs)  <-- the fix.
  v_bay_caps    TEXT[];  v_outstanding TEXT[];  v_flag_svcs TEXT[];  v_credit TEXT[];
  v_credited    INT := 0;  v_suppressed  INT := 0;  v_credit_none INT := 0;
BEGIN
  v_wash_cap   := ottoq_sim_lane_capacity(p_sim_run_id, 'cleaning_staff', 3);
  v_svc_cap    := ottoq_sim_lane_capacity(p_sim_run_id, 'service_staff', 2);
  v_deploy_cap := ottoq_sim_lane_capacity(p_sim_run_id, 'deploy_staff', 20);
  v_wash_dur   := ottoq_sim_service_minutes(p_sim_run_id, 'wash_time', 9);
  v_detail_dur := ottoq_sim_service_minutes(p_sim_run_id, 'detail_time', 25);
  v_svc_dur    := ottoq_sim_service_minutes(p_sim_run_id, 'maintenance_time', 40);
  v_floor      := ottoq_policy_get(p_sim_run_id, 'deploy_floor_soc', 80);
  SELECT COALESCE(d.feed_mode,'sim')='sim' INTO v_feed_sim FROM depots d WHERE d.id = p_depot_id;
  v_feed_sim := COALESCE(v_feed_sim, TRUE);

  SELECT COALESCE((knobs #>> ARRAY['_policy','scheduling_algorithm']), 'calibrated')
    INTO v_order FROM ottoq_variability_profiles WHERE sim_run_id = p_sim_run_id;
  v_order := COALESCE(v_order, 'calibrated');

  -- ───── STEP 0: re-charge stranded under-floor vehicles (deadlock breaker) ─────
  FOR v_rec IN
    SELECT v.id FROM vehicles v
     WHERE v.home_depot_id = p_depot_id AND v.category='autonomous'
       AND v.current_state IN ('charge_complete_holding','staged_awaiting_service','staged_for_departure')
       AND v.current_soc < v_floor
       -- 0557 (G291): not a car with an open vehicle fault. It is staged for its repair, and relabelling it need_charge
       -- would put it in the charge line first.
       AND NOT public.ottoq_vehicle_fault_open(v.config)
       AND EXISTS (SELECT 1 FROM ottoq_visit_needs n, jsonb_array_elements(n.atoms) a
              WHERE n.vehicle_id = v.id AND n.sim_run_id = p_sim_run_id
                AND a->>'svc' = 'charge' AND COALESCE(a->>'status','open') <> 'done')
       AND NOT EXISTS (SELECT 1 FROM ottoq_vehicle_dispatches d
              WHERE d.vehicle_id = v.id AND d.sim_run_id = p_sim_run_id AND d.status IN ('active','returning'))
     ORDER BY v.id   -- 0050: run-stable cursor order (fleet/stall identity, never heap order)
  LOOP
    -- DOCTRINE (Chase 2026-07-28): never bounce a vehicle to the gate.
    -- SPLIT 2026-07-29: the CHOICE (re-queue for charge + pick/hold/reserve the temp
    -- stall) moved to ottoq_replan_stranded_undercharge. The twin only executes the
    -- returned plan: the flag write and the physical occupancy write.
    DECLARE v_dec jsonb; v_s uuid;
    BEGIN
      v_dec := ottoq_replan_stranded_undercharge(v_rec.id, p_sim_run_id, p_depot_id, p_sim_clock_now);

      UPDATE vehicles
         SET current_state = 'staged_awaiting_service'::vehicle_state,
             -- 0546 (G272): stamp the clock only for a car this moves INTO staging. A car already staged keeps
             -- its stamp, so the stamp says when it began to wait. Re-stamping it every tick made every waiting
             -- car below the floor read as just arrived to each queue that orders by it (the charge cursor,
             -- FIFO, the depot queue, the in-place starter).
             last_state_change = CASE WHEN current_state = 'staged_awaiting_service'::vehicle_state
                                      THEN last_state_change ELSE p_sim_clock_now END,
             config = jsonb_set(config, '{svc_step}',
                                to_jsonb(COALESCE(v_dec->>'svc_step', 'need_charge')))
       WHERE id = v_rec.id;

      v_s := NULLIF(v_dec->>'stall_id', '')::uuid;
      -- ASK THE ARM FIRST. 'charge_complete_holding' is one of this loop's
      -- candidate states and it is also the demate window, so a car can be
      -- re-placed here with the arm still attached to it.
      IF v_s IS NOT NULL
         AND twin.ottoq_arm_refuse_move(v_rec.id, 'service_flow.stranded_recharge',
                                        v_s, p_sim_run_id, p_sim_clock_now) THEN
        v_s := NULL;
      END IF;
      IF v_s IS NOT NULL THEN
        -- ONE STALL PER VEHICLE, RELEASE BEFORE CLAIM. See the migration header.
        UPDATE stalls SET current_vehicle_id = NULL,
               status = CASE WHEN status = 'occupied' THEN 'available' ELSE status END
         WHERE current_vehicle_id = v_rec.id AND id <> v_s;
        UPDATE vehicles SET current_stall_id = v_s WHERE id = v_rec.id;
        UPDATE stalls SET current_vehicle_id = v_rec.id, status = 'occupied'
         WHERE id = v_s;
      END IF;
    END;
    v_recharged := v_recharged + 1;
  END LOOP;
  IF v_recharged > 0 THEN
    PERFORM ottoq_record_event(p_actor_type := 'ottoq_engine', p_actor_id := 'service_flow', p_event_type := 'twin.recharge_stranded',
      p_entity_type := 'depot', p_entity_id := p_depot_id,
      p_payload := jsonb_build_object('recharged', v_recharged, 'floor', v_floor),
      p_severity := 'warning', p_ingest_source := 'twin', p_data_source := 'twin', p_sim_run_id := p_sim_run_id);
  END IF;

  -- 0746 (G460): with wash_lane_physics on, the world times each new wash or detail seat by the work, from the
  -- minute the car entered the bay, before STEP 1 reads its timer. Off, this returns at once and nothing changes.
  IF v_feed_sim THEN PERFORM twin.ottoq_sim_time_bay_work(p_sim_run_id, p_depot_id, p_sim_clock_now); END IF;
  -- ───── STEP 1: complete in-progress services (elapsed timer OR null-timer stuck) ─────
  FOR v_rec IN
    SELECT id, current_state, config,
           last_state_change AS bay_seat_at, current_stall_id AS bay_stall_id   -- 0750 (G464): the seat, for its leg
      FROM vehicles
     WHERE home_depot_id = p_depot_id
       AND current_state IN ('in_wash_bay','in_detail_bay','in_service_bay')
       AND ( COALESCE((config->>'service_done')::boolean, FALSE)
          OR ( v_feed_sim AND (
                 (config->>'service_ends_at') IS NULL
              OR (config->>'service_ends_at')::timestamptz <= p_sim_clock_now ) ) )
     ORDER BY id   -- 0050: run-stable cursor order (fleet/stall identity, never heap order)
  LOOP
    v_end_ts := COALESCE((v_rec.config->>'service_ends_at')::timestamptz, p_sim_clock_now);
    -- T3 RENDER CONTRACT: the drive OUT of the bay to staging. Origin left NULL so the
    -- emitter resolves it from leg history to the bay the entry leg targeted, closing
    -- the route. Destination is a render target only; staged_awaiting_service holds no
    -- stall. Never allowed to abort the transition.
    BEGIN
      PERFORM ottoq_itin_travel_leg(p_sim_run_id, p_depot_id, v_rec.id, NULL,
        (SELECT s.id FROM stalls s
          WHERE s.depot_id = p_depot_id AND s.stall_type = 'staging'::stall_type
          ORDER BY (s.current_vehicle_id IS NOT NULL), s.stall_code
          OFFSET (abs(hashtext(v_rec.id::text)) % 20) LIMIT 1),
        p_sim_clock_now,
        CASE WHEN v_rec.current_state IN ('in_wash_bay','in_detail_bay')
             THEN 'exit_wash_to_staging' ELSE 'exit_service_to_staging' END,
        'twin_service_flow');
    EXCEPTION WHEN OTHERS THEN RAISE WARNING 'travel leg (bay exit): %', SQLERRM;
    END;
    IF v_rec.current_state IN ('in_wash_bay','in_detail_bay') THEN
      v_needs_svc := public.ottoq_flag_needs_service(v_rec.config);   -- 0556 (G289): the gate's own flag is a note, not work
      UPDATE vehicles SET current_state = 'staged_awaiting_service'::vehicle_state, last_state_change = p_sim_clock_now,
             config = jsonb_set(jsonb_set(config, '{svc_step}', to_jsonb(CASE WHEN v_needs_svc THEN 'need_service' ELSE 'need_deploy' END)), '{service_ends_at}', 'null'::jsonb) - 'service_done' - 'awaiting_external_completion' - 'bay_need'
                    -- 0556 (G289): the bay did the work the gate held the car for, so the gate's flag goes too (0546 (b))
                    - (CASE WHEN config->>'flagged_issue_type' IN ('deploy_gate_stuck', 'deploy_gate_hard_cap')
                            THEN ARRAY['flagged_issue', 'flagged_issue_type'] ELSE ARRAY[]::text[] END)
       WHERE id = v_rec.id;
    ELSE
      UPDATE vehicles SET current_state = 'staged_awaiting_service'::vehicle_state, last_state_change = p_sim_clock_now,
             config = jsonb_set(jsonb_set(config, '{svc_step}', to_jsonb('need_deploy'::text)), '{service_ends_at}', 'null'::jsonb) - 'service_done' - 'awaiting_external_completion' - 'bay_need'
                    -- 0475 (G208): the technician seat is what the flag asked for, and the gate raises it again if the car is stuck again
                    - 'flagged_issue' - 'flagged_issue_type'
       WHERE id = v_rec.id;
    END IF;
    PERFORM ottoq_itin_leg_close(p_sim_run_id, v_rec.id, ARRAY['wash','detail','service'], v_end_ts);

    -- ═══════ 0009 FIX (DEFECT 1) — CREDIT ONLY THE WORK THIS VEHICLE ACTUALLY HAD ═══════
    -- WAS: every bay exit credited a FIXED array regardless of why the car was in the bay,
    -- so a vehicle in for ONE job was recorded as having had up to FOUR. The exact pre-image
    -- line is quoted in this file's header, not here, so §POST can grep the live body for it.
    -- Registered as GAP 5 by 0005 and left open; this is that pass.
    --
    -- STEP A — the bay's CAPABILITY set. Byte-for-byte the three arrays from the pre-image.
    -- 0009 does not retune what a bay can do; it only stops claiming the bay did all of it.
    v_bay_caps := CASE WHEN v_rec.current_state = 'in_wash_bay' THEN ARRAY['exterior_wash','sensor_clean']
                       WHEN v_rec.current_state = 'in_detail_bay' THEN ARRAY['interior_deep_clean','exterior_wash','interior_tidy']
                       ELSE ARRAY['mechanical_pm','sensor_calibration','fault_repair','cosmetic_repair'] END;

    -- STEP B — what the vehicle ACTUALLY had outstanding, from its own visit record.
    -- ORDER IS LOAD-BEARING: this must be read BEFORE ottoq_mark_visit_atoms_done below,
    -- which flips these same atoms to 'done'. Read it after and the answer is always empty.
    -- The visit selector is IDENTICAL to ottoq_mark_visit_atoms_done's own (vehicle +
    -- status open/in_progress + newest created_at), so the wear ledger and the visit ledger
    -- can never disagree about WHICH visit they are discussing. "Outstanding" uses the
    -- depot's own existing definition, already live in STEP 2 of this same function:
    --     COALESCE(status,'pending') NOT IN ('done','cancelled','skipped')
    -- No new vocabulary is invented anywhere in this block.
    SELECT COALESCE(array_agg(DISTINCT a->>'svc'), ARRAY[]::text[])
      INTO v_outstanding
      FROM ottoq_visit_needs n, jsonb_array_elements(n.atoms) a
     WHERE n.visit_id = (SELECT n2.visit_id FROM ottoq_visit_needs n2
                          WHERE n2.vehicle_id = v_rec.id
                            AND n2.status IN ('open','in_progress') AND COALESCE(n2.sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE(p_sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) /* 0123 */
                          ORDER BY n2.created_at DESC, n2.visit_key DESC LIMIT 1)
       AND COALESCE(a->>'status','pending') NOT IN ('done','cancelled','skipped');
    v_outstanding := COALESCE(v_outstanding, ARRAY[]::text[]);

    -- STEP C — THE TECHNICIAN FLAG IS REAL WORK TOO, AND IGNORING IT WOULD BE A NEW LIE.
    -- STEP 2 of this function admits a vehicle to the wash/detail lane on
    -- `flagged_issue_type` ALONE, with no atom required. Atoms-only credit would leave that
    -- car's body soil never reset -- and post-0008 ONLY an exterior_wash may reset it -- so
    -- the depot would wash it, still grade it dirty, and wash it again, forever. ONE mapping,
    -- and only where the flag NAMES the work: 'wash_due' -> exterior_wash.
    -- 'minor_cosmetic' is deliberately NOT mapped (GAP 1): a detail does not repair cosmetic
    -- damage, and inventing that equivalence would be the same disease this file removes.
    v_flag_svcs := CASE WHEN v_rec.config->>'flagged_issue_type' = 'wash_due'
                        THEN ARRAY['exterior_wash'] ELSE ARRAY[]::text[] END;
    -- 0458 (G191): THE NEED A CAR WAS SEATED FOR IS REAL WORK TOO, for the same reason the
    -- technician flag is. The needs card seats a car for a need read from its live condition,
    -- which can arise after the visit was derived and so be on no manifest: 736406cf's AV-062
    -- was seated 462 times for an overdue wash its visit never listed, credited nothing each
    -- time, and was re-seated. Credited only while bound to the timer this car is exiting on,
    -- so a stale need from an earlier seat cannot ride on a later one; the bay's own
    -- capability set still decides what can be credited at all.
    IF NULLIF(v_rec.config->'bay_need'->>'svc', '') IS NOT NULL
       AND v_rec.config->'bay_need'->>'ends_at' IS NOT DISTINCT FROM v_rec.config->>'service_ends_at' THEN
      v_flag_svcs := v_flag_svcs || ARRAY[v_rec.config->'bay_need'->>'svc'];
    END IF;

    -- STEP D — THE CREDIT SET: what this bay CAN do  ∩  what this vehicle ACTUALLY had.
    -- If a vehicle genuinely had all four due it still gets all four: the bug being fixed is
    -- unconditionality, not breadth.
    v_credit := ARRAY(SELECT t.svc FROM unnest(v_bay_caps) AS t(svc)
                       WHERE t.svc = ANY(v_outstanding || v_flag_svcs));
    -- 0750 (G464): with bay_exit_closes_its_leg on, a seat that closed no active leg above closes the planned bay leg of
    -- each service it credited, or records one, so it ends in a done leg and its service record. Off, this returns at
    -- once. A failure is a warning, never the tick's.
    BEGIN
      PERFORM public.ottoq_close_bay_seat_legs(p_sim_run_id, p_depot_id, v_rec.id, v_rec.current_state::text,
                                               v_rec.bay_seat_at, v_end_ts, v_rec.bay_stall_id, v_credit);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '0750 bay exit leg (vehicle %): % %', v_rec.id, SQLSTATE, SQLERRM;
    END;

    PERFORM ottoq_mark_visit_atoms_done(v_rec.id,
      CASE WHEN v_rec.current_state = 'in_wash_bay' THEN ARRAY['exterior_wash','sensor_clean']
           WHEN v_rec.current_state = 'in_detail_bay' THEN ARRAY['interior_deep_clean','exterior_wash','interior_tidy']
           ELSE ARRAY['mechanical_pm','sensor_calibration','fault_repair','cosmetic_repair'] END, v_end_ts);
    -- wear truth follows completion (mark_serviced was dead: soil/PM/calibration never reset)
    -- 0009: the fixed array is gone. One call per service the vehicle REALLY had -- the same
    -- one-real-atom-per-call shape 0005 §3 uses on the non-bay path, and the same shape the
    -- real-telemetry seam public.ottoq_ingest_service_complete uses (FOREACH over the codes
    -- the OEM actually reported). An empty credit set yields zero rows from unnest, so the
    -- PERFORM makes NO call at all: total, never an error, never able to abort decide_tick.
    -- ottoq_mark_visit_atoms_done above is left BYTE-FOR-BYTE UNCHANGED on purpose. It is
    -- already correctly intersected -- it only touches atoms that exist on the visit -- so it
    -- was never part of this defect, and narrowing it would be scope creep.
    PERFORM ottoq_wear_mark_serviced(v_rec.id, p_sim_run_id, s, v_end_ts)
      FROM unnest(v_credit) AS s;
    -- 0555 (G290): the repair closes the car's vehicle fault. Only a service-bay exit that credits fault_repair does this,
    -- so an open fault cannot be lost any other way (a run's seed aside), and the departure test holds the car until then.
    IF 'fault_repair' = ANY (v_credit) AND public.ottoq_vehicle_fault_open(v_rec.config) THEN
      UPDATE vehicles SET config = config - 'exception' WHERE id = v_rec.id;
    END IF;
    v_credited    := v_credited + COALESCE(array_length(v_credit, 1), 0);
    v_suppressed  := v_suppressed + COALESCE(array_length(v_bay_caps, 1), 0)
                                  - COALESCE(array_length(v_credit, 1), 0);
    IF COALESCE(array_length(v_credit, 1), 0) = 0 THEN v_credit_none := v_credit_none + 1; END IF;
    PERFORM ottoq_record_event(p_actor_type := 'av_vehicle', p_actor_id := v_rec.id::text, p_event_type := 'twin.service_completed',
      p_entity_type := 'vehicle', p_entity_id := v_rec.id, p_payload := jsonb_build_object('from', v_rec.current_state, 'self_healed', (v_rec.config->>'service_ends_at') IS NULL,
        -- 0009 RUNTIME PROOF, carried on an event that was already being written, so the
        -- write-rate budget (~852-960 B/event) is not disturbed by a new event type.
        'bay_capable', to_jsonb(v_bay_caps), 'credited', to_jsonb(v_credit),
        'suppressed_n', COALESCE(array_length(v_bay_caps,1),0) - COALESCE(array_length(v_credit,1),0),
        -- 0475 (G208): the technician flag this service-bay seat cleared, if any
        'flag_cleared', CASE WHEN v_rec.current_state = 'in_service_bay' AND COALESCE((v_rec.config->>'flagged_issue')::boolean, false)
                             THEN COALESCE(v_rec.config->>'flagged_issue_type', 'untyped') END,
        -- 0555 (G290): the vehicle fault this repair closed, if any
        'fault_repaired', CASE WHEN 'fault_repair' = ANY (v_credit) AND public.ottoq_vehicle_fault_open(v_rec.config)
                               THEN v_rec.config->'exception' END),
      p_severity := 'debug', p_ingest_source := 'twin', p_data_source := 'twin', p_sim_run_id := p_sim_run_id);
  END LOOP;

  -- 0009: ONE summary event per CALL, and only when a bay exit credited NOTHING -- i.e. a
  -- vehicle sat in a bay yet no outstanding work and no naming flag could be found for it.
  -- That is a gap a human should see, not something to paper over with a false credit.
  -- Silent in the normal case, so the event budget is unchanged on the happy path.
  IF v_credit_none > 0 THEN
    PERFORM ottoq_record_event(p_actor_type := 'ottoq_engine', p_actor_id := 'service_flow',
      p_event_type := 'twin.bay_credit_none', p_entity_type := 'depot', p_entity_id := p_depot_id,
      p_payload := jsonb_build_object('exits_crediting_nothing', v_credit_none,
        'services_credited', v_credited, 'services_suppressed', v_suppressed,
        'note', 'a bay exit found no outstanding work and no naming flag; nothing was credited, which is the honest answer -- investigate why the car was admitted'),
      p_severity := 'warning', p_ingest_source := 'twin', p_data_source := 'twin', p_sim_run_id := p_sim_run_id);
  END IF;

  -- ───── STEP 1.5: deploy-pressure fast-track past OPTIONAL wash ─────
  v_hour     := EXTRACT(HOUR FROM p_sim_clock_now AT TIME ZONE 'America/Chicago')::int;
  v_fleet    := (SELECT COUNT(*) FROM vehicles WHERE category='autonomous' AND home_depot_id=p_depot_id);
  v_deployed := (SELECT COUNT(*) FROM ottoq_vehicle_dispatches WHERE sim_run_id=p_sim_run_id AND status IN ('active','returning'));
  v_target   := public.ottoq_deploy_target_now(p_sim_run_id, p_depot_id, p_sim_clock_now);  -- 0434: the dispatcher's target, not a fixed 0.90
  v_pressure := v_deployed < v_target;
  IF v_pressure THEN
    FOR v_rec IN
      SELECT v.id FROM vehicles v
       WHERE v.home_depot_id = p_depot_id AND v.category='autonomous'
         AND v.current_state = 'charge_complete_holding' AND v.current_soc >= v_floor
         AND NOT EXISTS (SELECT 1 FROM ottoq_visit_needs n, jsonb_array_elements(n.atoms) a
             WHERE n.vehicle_id = v.id AND n.sim_run_id = p_sim_run_id
               AND (a->>'must_do')::boolean = TRUE AND a->>'svc' NOT IN ('charge','readiness_check')
               AND COALESCE(a->>'status','open') <> 'done')
     ORDER BY v.id   -- 0050: run-stable cursor order (fleet/stall identity, never heap order)
    LOOP
      UPDATE vehicles SET current_state = 'staged_awaiting_service'::vehicle_state, last_state_change = p_sim_clock_now,
             config = jsonb_set(config, '{svc_step}', to_jsonb('need_deploy'::text)) WHERE id = v_rec.id;
      v_fasttracked := v_fasttracked + 1;
    END LOOP;
    IF v_fasttracked > 0 THEN
      PERFORM ottoq_record_event(p_actor_type := 'ottoq_engine', p_actor_id := 'service_flow', p_event_type := 'twin.deploy_pressure_fasttrack',
        p_entity_type := 'depot', p_entity_id := p_depot_id,
        p_payload := jsonb_build_object('fasttracked', v_fasttracked, 'deployed', v_deployed, 'target', v_target, 'hour_cst', v_hour),
        p_severity := 'info', p_ingest_source := 'twin', p_data_source := 'twin', p_sim_run_id := p_sim_run_id);
    END IF;
  END IF;

  -- ───── STEP 2: admit waiting vehicles into lanes (capacity-gated, ordered) ─────
  SELECT COUNT(*) INTO v_in_wash FROM vehicles WHERE home_depot_id = p_depot_id AND current_state IN ('in_wash_bay','in_detail_bay');
  v_admitted := 0;
  FOR v_rec IN
    -- M1_need_gated_wash: admit ONLY vehicles that actually have wash/detail
    -- work outstanding. Previously any holding vehicle was admitted to fill capacity.
    -- BOOKING-AWARE (2026-08-02), same reasoning as the service cursor below: the wash
    -- lane also ignored the forward calendar and picked a bay by OFFSET n % 3. The need
    -- gate and the ordering expression are preserved EXACTLY; a booking-holder key is
    -- prepended, and the vehicle's own reserved bay is surfaced for the travel leg.
    SELECT q.id, q.config, q.booked_stall FROM (
      SELECT v.id, v.config,
             (SELECT b2.stall_id
                FROM ottoq_stall_bookings b2 JOIN stalls sb ON sb.id = b2.stall_id
               WHERE b2.sim_run_id = p_sim_run_id AND b2.vehicle_id = v.id
                 AND b2.state = 'held' AND b2.purpose IN ('wash','detail')
                 AND sb.depot_id = p_depot_id AND sb.stall_type = 'wash_bay'::stall_type
                 AND sb.status NOT IN ('maintenance','closed')
                 AND lower(b2.during) <= p_sim_clock_now AND upper(b2.during) > p_sim_clock_now
               ORDER BY lower(b2.during), b2.stall_id, b2.booking_id DESC /* 0129 */ LIMIT 1) AS booked_stall,
             CASE v_order WHEN 'soc_optimized' THEN v.current_soc WHEN 'priority_weighted' THEN -COALESCE((v.config->>'seed_idx')::numeric, 0) ELSE EXTRACT(EPOCH FROM v.last_state_change) END AS ord
        FROM vehicles v
       WHERE v.home_depot_id = p_depot_id AND v.current_state = 'charge_complete_holding'
         -- 0695: a car whose data transfer holds it on its charger goes to the wash after the transfer
         AND NOT ottoq.ottoq_uplink_transfer_holds(v.id, p_sim_run_id)
         AND (EXISTS (SELECT 1 FROM ottoq_visit_needs n, jsonb_array_elements(n.atoms) a
                       WHERE n.vehicle_id = v.id AND n.status IN ('open','in_progress') AND COALESCE(n.sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE(p_sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) /* 0124 */
                         AND a->>'svc' IN ('exterior_wash','interior_deep_clean')
                         AND COALESCE(a->>'status','pending') NOT IN ('done','cancelled','skipped'))
              OR v.config->>'flagged_issue_type' IN ('minor_cosmetic','wash_due'))
    ) q
     -- 0554 (G286): only a car whose bay is booked for now can be seated here. The rest are seated by OTTO-Q's
     -- needs card, in a bay free on the floor and on the calendar.
     WHERE q.booked_stall IS NOT NULL
     -- 0100: run-stable tiebreak; ord ties on same-tick last_state_change (heap below).
     ORDER BY (q.booked_stall IS NULL), q.ord, q.id
     -- wash_supervisor_pool: the 8-10 min exterior wash needs a supervisor as well
     -- as a free lane (founder spec: "a couple of wash bay supervisors").
     LIMIT GREATEST(0, LEAST(v_wash_cap, public.ottoq_wash_lane_staff_gate(p_sim_run_id, p_depot_id)) - v_in_wash)   -- 0746
  LOOP
    -- T3 RENDER CONTRACT: the drive to the wash building. Render-only; picks a
    -- door for the leg, claims nothing. Origin left NULL on purpose (it is NULL on
    -- every path into charge_complete_holding) so the emitter resolves it from leg history.
    BEGIN
      PERFORM ottoq_itin_travel_leg(p_sim_run_id, p_depot_id, v_rec.id, NULL,
        COALESCE(v_rec.booked_stall,
        (SELECT s.id FROM stalls s WHERE s.depot_id = p_depot_id
          AND s.stall_type = 'wash_bay'::stall_type
          ORDER BY (s.status IN ('maintenance','closed')), (s.current_vehicle_id IS NOT NULL), (EXISTS (SELECT 1 FROM ottoq_stall_bookings b3 WHERE b3.stall_id = s.id AND b3.sim_run_id = p_sim_run_id AND b3.state IN ('held','active','done') AND b3.during && tstzrange(p_sim_clock_now, p_sim_clock_now + make_interval(mins => GREATEST(v_wash_dur, v_detail_dur)::int), '[)'))), s.stall_code LIMIT 1)),
        p_sim_clock_now, 'taxi_to_wash', 'twin_service_flow');
    EXCEPTION WHEN OTHERS THEN RAISE WARNING 'travel leg (wash): %', SQLERRM;
    END;
    -- 0048 REORDER: PHYSICAL TRUTH BEFORE THE STATE FLIP. This vehicle-state
    -- UPDATE used to run BEFORE the stall handoff below. That made
    -- trg_reassignment_guard (BEFORE UPDATE ON stalls) see the vehicle already
    -- in a protected in-bay state while it was still standing on its OLD stall,
    -- so the guard vetoed the release, silently restored the old pointer, and
    -- the very next place-statement violated idx_stalls_one_vehicle_per_stall
    -- and killed the whole tick (measured: cert arm 44252690, vehicle a6e9c009,
    -- charge_complete_holding on a wash bay, admitted to its booked service
    -- bay). Handoff first -- while the state is still a holding state the guard
    -- does not protect -- then the state write. Both statements byte-identical
    -- to the pre-image; only their order changed.

    IF v_rec.booked_stall IS NOT NULL
       AND NOT twin.ottoq_arm_refuse_move(v_rec.id, 'service_flow.bay_admit',
                                          v_rec.booked_stall, p_sim_run_id, p_sim_clock_now) THEN
      -- CLAIMABILITY IS CHECKED BEFORE THE RELEASE, not after. The original guard
      -- below defends the TARGET bay from a second vehicle, which is the opposite
      -- direction from idx_stalls_one_vehicle_per_stall -- that index is
      -- UNIQUE(current_vehicle_id), i.e. one STALL per VEHICLE. Both directions now
      -- hold: the bay cannot be stolen, and the car cannot be in two places.
      -- Hoisted ahead of the release so a bay we cannot claim never leaves the car
      -- standing in no stall at all.
      IF EXISTS (SELECT 1 FROM stalls s
                  WHERE s.id = v_rec.booked_stall
                    AND (s.current_vehicle_id IS NULL OR s.current_vehicle_id = v_rec.id)) THEN
        UPDATE stalls SET current_vehicle_id = NULL,
               status = CASE WHEN status = 'occupied' THEN 'available' ELSE status END
         WHERE current_vehicle_id = v_rec.id AND id <> v_rec.booked_stall;
        UPDATE stalls SET current_vehicle_id = v_rec.id, status = 'occupied'
         WHERE id = v_rec.booked_stall
           AND (current_vehicle_id IS NULL OR current_vehicle_id = v_rec.id);
        IF FOUND THEN
          UPDATE vehicles SET current_stall_id = v_rec.booked_stall WHERE id = v_rec.id;
        END IF;
      END IF;
    END IF;
    -- 0554 (G286): the bay state only for a car standing in its bay. The claim above fails when another car stands
    -- in the bay or the charge arm still holds this one; the car then stays as it is, and this tick's wash triage
    -- routes it.
    CONTINUE WHEN NOT EXISTS (SELECT 1 FROM vehicles vb
                               WHERE vb.id = v_rec.id AND vb.current_stall_id = v_rec.booked_stall);
    UPDATE vehicles
       SET current_state = (CASE WHEN (ottoq_visit_wants_detail(v_rec.id) OR v_rec.config->>'flagged_issue_type' IN ('minor_cosmetic','wash_due')) THEN 'in_detail_bay' ELSE 'in_wash_bay' END)::vehicle_state,
           last_state_change = p_sim_clock_now,
           config = jsonb_set(jsonb_set(config, '{svc_step}', to_jsonb('washing'::text)), '{service_ends_at}', to_jsonb((p_sim_clock_now +
               ((CASE WHEN (ottoq_visit_wants_detail(v_rec.id) OR v_rec.config->>'flagged_issue_type' IN ('minor_cosmetic','wash_due'))
                      THEN v_detail_dur * COALESCE(ottoq_twin_deal(p_sim_run_id, 'detail_time', v_rec.id::text || ':' || twin.ottoq_sim_clock_salt(p_sim_run_id, p_sim_clock_now), p_sim_clock_now, (p_sim_clock_now::date - DATE '2020-01-01'), 0), 1.0)
                      ELSE v_wash_dur * COALESCE(ottoq_twin_deal(p_sim_run_id, 'wash_time', v_rec.id::text || ':' || twin.ottoq_sim_clock_salt(p_sim_run_id, p_sim_clock_now), p_sim_clock_now, (p_sim_clock_now::date - DATE '2020-01-01'), 0), 1.0) END) || ' minutes')::interval)::text))
     WHERE id = v_rec.id;
    PERFORM ottoq_itin_leg_open(p_sim_run_id, p_depot_id, v_rec.id, p_sim_clock_now,
      CASE WHEN (ottoq_visit_wants_detail(v_rec.id) OR v_rec.config->>'flagged_issue_type' IN ('minor_cosmetic','wash_due')) THEN 'detail' ELSE 'wash' END,
      NULL, (SELECT (config->>'service_ends_at')::timestamptz FROM vehicles WHERE id = v_rec.id),
      jsonb_build_object('kind', 'distribution', 'corpus', 'service_ops', 'base_min', CASE WHEN (ottoq_visit_wants_detail(v_rec.id) OR v_rec.config->>'flagged_issue_type' IN ('minor_cosmetic','wash_due')) THEN v_detail_dur ELSE v_wash_dur END),
      'service_flow');
    v_admitted := v_admitted + 1;
  END LOOP;

  -- ══════ 0468 (G201): THE SERVICE LANE IS NEED-GATED, LIKE THE WASH LANE ABOVE ══════
  -- This cursor admitted any car whose step said need_service. The seeder's boot cohort and the readmit paths write
  -- that step without service-bay work, so 4 of 5 boot seats on 317d4331 were 40 minutes on the scarcest bay that
  -- credited nothing. A car with no outstanding service-bay atom (the bay's own credit rule, by
  -- service_cadence_policy.lane, the lane 0464's gate reads), no technician flag and no live service booking goes
  -- to the deploy gate below in this same pass. The gate asks for need_service only when service-bay work is open,
  -- so this cannot loop.
  UPDATE vehicles v
     SET config = jsonb_set(COALESCE(v.config, '{}'::jsonb), '{svc_step}', to_jsonb('need_deploy'::text))
   WHERE v.home_depot_id = p_depot_id AND v.current_state = 'staged_awaiting_service'
     AND v.config->>'svc_step' = 'need_service'
     -- a technician flag is its own reason to see the service bay: STEP 1 sends a flagged car here from the
     -- wash and detail bays on the flag alone, with no atom, and that path is kept as it is
     AND NOT public.ottoq_flag_needs_service(v.config)   -- 0556 (G289): but not the readiness gate's own flag
     AND NOT EXISTS (SELECT 1 FROM ottoq_visit_needs n
                       CROSS JOIN LATERAL jsonb_array_elements(n.atoms) a
                       JOIN service_cadence_policy cp ON cp.svc = a->>'svc' AND cp.is_active AND cp.lane = 'service_bay'
                      WHERE n.vehicle_id = v.id AND n.sim_run_id = p_sim_run_id
                        AND n.status IN ('open','in_progress')
                        AND COALESCE(a->>'status','pending') NOT IN ('done','cancelled','skipped'))
     AND NOT EXISTS (SELECT 1 FROM ottoq_stall_bookings b
                      WHERE b.sim_run_id = p_sim_run_id AND b.vehicle_id = v.id
                        AND b.state = 'held' AND b.purpose = 'service'
                        AND lower(b.during) <= p_sim_clock_now AND upper(b.during) > p_sim_clock_now);

  SELECT COUNT(*) INTO v_in_svc FROM vehicles WHERE home_depot_id = p_depot_id AND current_state = 'in_service_bay';
  -- BOOKING-AWARE ADMISSION (2026-08-02). This cursor was blind to the forward calendar:
  -- it ordered purely by last_state_change and sent the car to an ARBITRARY bay
  -- (OFFSET n % 2), so a vehicle holding a live reservation got no priority and was often
  -- not even routed to the bay it had been promised. Reservations then rotted to
  -- no_show_grace_elapsed (37.3% of bay bookings). It now surfaces the vehicle's own open
  -- booking and admits booking-holders FIRST. Capacity is still staff-gated byte-for-byte:
  -- this changes WHO gets the slot and WHICH bay, never HOW MANY.
  FOR v_rec IN
    SELECT * FROM (
      SELECT v.id,
             (SELECT b2.stall_id
                FROM ottoq_stall_bookings b2 JOIN stalls sb ON sb.id = b2.stall_id
               WHERE b2.sim_run_id = p_sim_run_id AND b2.vehicle_id = v.id
                 AND b2.state = 'held' AND b2.purpose = 'service'
                 AND sb.depot_id = p_depot_id AND sb.stall_type = 'service_bay'::stall_type
                 AND sb.status NOT IN ('maintenance','closed')
                 AND lower(b2.during) <= p_sim_clock_now AND upper(b2.during) > p_sim_clock_now
               ORDER BY lower(b2.during), b2.stall_id, b2.booking_id DESC /* 0129 */ LIMIT 1) AS booked_stall,
             v.last_state_change AS lsc
        FROM vehicles v
       WHERE v.home_depot_id = p_depot_id AND v.current_state = 'staged_awaiting_service'
         AND v.config->>'svc_step' = 'need_service'
    ) q
     -- 0554 (G286): only a car whose bay is booked for now can be seated here. The rest are seated by OTTO-Q's
     -- needs card, in a bay free on the floor and on the calendar.
     WHERE q.booked_stall IS NOT NULL
     -- 0100: run-stable tiebreak; lsc ties on same-tick transitions (heap below).
     ORDER BY (q.booked_stall IS NULL), q.lsc, q.id LIMIT GREATEST(0, v_svc_cap - v_in_svc)
  LOOP
    -- T3 RENDER CONTRACT: the drive to the service bays (OFFICE-01 complex, far west).
    -- Render-only; claims no bay. Capacity remains staff-gated exactly as before.
    BEGIN
      PERFORM ottoq_itin_travel_leg(p_sim_run_id, p_depot_id, v_rec.id, NULL,
        COALESCE(v_rec.booked_stall,
        (SELECT s.id FROM stalls s WHERE s.depot_id = p_depot_id
          AND s.stall_type = 'service_bay'::stall_type
          ORDER BY (s.status IN ('maintenance','closed')), (s.current_vehicle_id IS NOT NULL), (EXISTS (SELECT 1 FROM ottoq_stall_bookings b3 WHERE b3.stall_id = s.id AND b3.sim_run_id = p_sim_run_id AND b3.state IN ('held','active','done') AND b3.during && tstzrange(p_sim_clock_now, p_sim_clock_now + make_interval(mins => v_svc_dur::int), '[)'))), s.stall_code LIMIT 1)),
        p_sim_clock_now, 'taxi_to_service', 'twin_service_flow');
    EXCEPTION WHEN OTHERS THEN RAISE WARNING 'travel leg (service): %', SQLERRM;
    END;
    -- 0048 REORDER: PHYSICAL TRUTH BEFORE THE STATE FLIP. This vehicle-state
    -- UPDATE used to run BEFORE the stall handoff below. That made
    -- trg_reassignment_guard (BEFORE UPDATE ON stalls) see the vehicle already
    -- in a protected in-bay state while it was still standing on its OLD stall,
    -- so the guard vetoed the release, silently restored the old pointer, and
    -- the very next place-statement violated idx_stalls_one_vehicle_per_stall
    -- and killed the whole tick (measured: cert arm 44252690, vehicle a6e9c009,
    -- charge_complete_holding on a wash bay, admitted to its booked service
    -- bay). Handoff first -- while the state is still a holding state the guard
    -- does not protect -- then the state write. Both statements byte-identical
    -- to the pre-image; only their order changed.

    -- HONOUR THE RESERVATION PHYSICALLY. Claiming the booked bay is what lets
    -- ottoq.ottoq_activate_present_bookings flip the row held -> active next tick -- the
    -- RUNTIME proof the reservation was kept rather than silently expired. Guarded so it
    -- can never steal a bay another vehicle is standing in, so it cannot double-book.
    IF v_rec.booked_stall IS NOT NULL
       AND NOT twin.ottoq_arm_refuse_move(v_rec.id, 'service_flow.bay_admit',
                                          v_rec.booked_stall, p_sim_run_id, p_sim_clock_now) THEN
      -- CLAIMABILITY IS CHECKED BEFORE THE RELEASE, not after. The original guard
      -- below defends the TARGET bay from a second vehicle, which is the opposite
      -- direction from idx_stalls_one_vehicle_per_stall -- that index is
      -- UNIQUE(current_vehicle_id), i.e. one STALL per VEHICLE. Both directions now
      -- hold: the bay cannot be stolen, and the car cannot be in two places.
      -- Hoisted ahead of the release so a bay we cannot claim never leaves the car
      -- standing in no stall at all.
      IF EXISTS (SELECT 1 FROM stalls s
                  WHERE s.id = v_rec.booked_stall
                    AND (s.current_vehicle_id IS NULL OR s.current_vehicle_id = v_rec.id)) THEN
        UPDATE stalls SET current_vehicle_id = NULL,
               status = CASE WHEN status = 'occupied' THEN 'available' ELSE status END
         WHERE current_vehicle_id = v_rec.id AND id <> v_rec.booked_stall;
        UPDATE stalls SET current_vehicle_id = v_rec.id, status = 'occupied'
         WHERE id = v_rec.booked_stall
           AND (current_vehicle_id IS NULL OR current_vehicle_id = v_rec.id);
        IF FOUND THEN
          UPDATE vehicles SET current_stall_id = v_rec.booked_stall WHERE id = v_rec.id;
        END IF;
      END IF;
    END IF;
    -- 0554 (G286): the bay state only for a car standing in its bay (see the wash lane).
    CONTINUE WHEN NOT EXISTS (SELECT 1 FROM vehicles vb
                               WHERE vb.id = v_rec.id AND vb.current_stall_id = v_rec.booked_stall);
    UPDATE vehicles SET current_state = 'in_service_bay'::vehicle_state, last_state_change = p_sim_clock_now,
           config = jsonb_set(jsonb_set(config, '{svc_step}', to_jsonb('servicing'::text)), '{service_ends_at}', to_jsonb((p_sim_clock_now + ((v_svc_dur * COALESCE(ottoq_twin_deal(p_sim_run_id, 'maintenance_time', v_rec.id::text || ':' || twin.ottoq_sim_clock_salt(p_sim_run_id, p_sim_clock_now), p_sim_clock_now, (p_sim_clock_now::date - DATE '2020-01-01'), 0), 1.0)) || ' minutes')::interval)::text))
     WHERE id = v_rec.id;
    PERFORM ottoq_itin_leg_open(p_sim_run_id, p_depot_id, v_rec.id, p_sim_clock_now, 'service', NULL,
      (SELECT (config->>'service_ends_at')::timestamptz FROM vehicles WHERE id = v_rec.id),
      jsonb_build_object('kind', 'distribution', 'corpus', 'service_ops', 'base_min', v_svc_dur), 'service_flow');
  END LOOP;

  -- ═════ STEP 3: RELEASE TO DEPARTURE — READINESS GATE (2026-08-02) ═════
  -- DOCTRINE (full-service visit): a visit is ATOMIC. 'staged_for_departure' must mean
  -- "this vehicle would be dispatched if asked" — nothing weaker. Before this gate the
  -- transition was UNCONDITIONAL, so vehicles at 28-29% SoC were staged as READY.
  -- That is not merely cosmetic: 'staged_for_departure' is NOT in ottoq_decide_tick's
  -- charging cursor (which reads 'arrived_at_gate' and 'staged_awaiting_service'), so
  -- staging an undercharged car REMOVED IT FROM THE CHARGE QUEUE, while
  -- ottoq_plan_dispatch_tick(deploy_plan) would refuse it anyway (soc >= 80 + no open
  -- must-do work). Dead inventory that could never leave and could never be fixed.
  --
  -- THE GATE IS THE DISPATCHER'S OWN ADMISSION PREDICATE, MOVED ONE STEP EARLIER.
  -- It is therefore never stricter than what the dispatcher accepts, so it cannot
  -- create a new deadlock class:
  --     soc >= ready_soc   AND   no open must-do work left in this run's visit
  -- ready_soc comes from the NEEDS CARD (ottoq_vehicle_needs_card.min_ready_soc_pct),
  -- not a bare SoC literal, so it follows the per-vehicle need profile; it falls back
  -- to the deploy_floor_soc policy when the card has no row for the vehicle — a TOTAL
  -- function: a missing card must never block a vehicle. The card also supplies
  -- must_do_now / fits_window / minutes_to_deploy as EVIDENCE on the hold receipt.
  -- The card is read ONCE per call for the whole candidate set: the view materialises
  -- the entire fleet regardless of its WHERE clause (measured 192 ms for a
  -- single-vehicle probe), so a per-vehicle read would cost seconds per tick.
  --
  -- NOT AN ENERGY GATE. Vehicle-first doctrine is untouched — nothing is held back for
  -- price or grid reasons. This is READINESS only: the vehicle is not finished.
  --
  -- ESCAPE HATCHES — nothing sits unseen:
  --   0. policy deploy_ready_gate_enabled = 0  → gate off, pre-2026-08-02 behaviour.
  --   1. a held vehicle is ROUTED TO THE REMEDY, never parked: svc_step := 'need_charge'
  --      (ottoq_decide_tick's charge cursor consumes staged_awaiting_service on SoC
  --      alone — no atom required) or 'need_service' (STEP 2 above consumes it).
  --      Both consumers verified in live source. The loop closes: charge →
  --      charge_complete_holding → STEP 1.5/STEP 2 → need_deploy → re-gated.
  --   2. deploy_gate_patience_min (default 45 sim-min) → config.flagged_issue +
  --      flagged_issue_type='deploy_gate_stuck' so a technician sees it, counted in a
  --      WARNING summary event.
  --   3. deploy_gate_hard_cap_min (default 240 sim-min — longer than any bounded demo)
  --      → 0542 (CLAUDE.md rule 9): NOT released. The car stays held on its remedy, flagged
  --      deploy_gate_hard_cap, with one CRITICAL twin.deploy_gate_escalated event for a
  --      person. Hatch 3 used to release it with its needs open; no path does that now.
  -- Event budget: ONE summary event per call (plus one per rare override), not one per
  -- vehicle — event-write amplification is the known tick-cost driver.
  -- 0543 (CLAUDE.md rule 9): a car staged to leave that is not finished goes back to what it needs first, and a car
  -- waiting for a charger it no longer needs comes back to this gate.
  PERFORM twin.ottoq_sim_departure_recheck(p_sim_run_id, p_sim_clock_now, p_depot_id);
  v_gate_on      := COALESCE(ottoq_policy_get(p_sim_run_id,'deploy_ready_gate_enabled',1),1) > 0;
  v_patience_dep := COALESCE(ottoq_policy_get(p_sim_run_id,'deploy_gate_patience_min',45),45);
  v_hardcap      := COALESCE(ottoq_policy_get(p_sim_run_id,'deploy_gate_hard_cap_min',240),240);
  v_relcap       := GREATEST(1, CEIL(v_deploy_cap * COALESCE(p_tick_minutes, 30) / 30.0))::int;
  v_admitted := 0;

  SELECT COUNT(*) INTO v_ncand FROM vehicles v
   WHERE v.home_depot_id = p_depot_id AND v.current_state = 'staged_awaiting_service'
     AND v.config->>'svc_step' = 'need_deploy';

  IF v_ncand > 0 THEN
    FOR v_rec IN
      WITH cand AS (
        SELECT v.id, v.current_soc, v.config, v.last_state_change
          FROM vehicles v
         WHERE v.home_depot_id = p_depot_id AND v.category = 'autonomous'
           AND v.current_state = 'staged_awaiting_service'
           AND v.config->>'svc_step' = 'need_deploy'
      ), card AS (
        SELECT c.vehicle_id, c.min_ready_soc_pct, c.must_do_now, c.fits_window, c.minutes_to_deploy
          FROM ottoq_vehicle_needs_card c
         WHERE v_gate_on
      ), ev AS (
        SELECT cd.id, cd.current_soc, cd.config, cd.last_state_change,
               GREATEST(v_floor, COALESCE(k.min_ready_soc_pct, v_floor),
                        public.ottoq_effective_target_soc_at(cd.id, p_sim_clock_now) - 1) AS ready_soc,   /* 0543 */
               COALESCE(k.must_do_now, '{}'::text[])                     AS card_must,
               k.fits_window, k.minutes_to_deploy,
               -- IDENTICAL predicate to ottoq_plan_dispatch_tick(deploy_plan)
               EXISTS (SELECT 1 FROM ottoq_visit_needs vn
                        WHERE vn.vehicle_id = cd.id AND vn.sim_run_id = p_sim_run_id
                          AND vn.status IN ('open','in_progress')
                          AND EXISTS (SELECT 1 FROM jsonb_array_elements(vn.atoms) a
                                       WHERE a->>'svc' <> 'readiness_check'   /* 0543 (CLAUDE.md rule 9): every open service, as the dispatchers ask */
                                         AND COALESCE(a->>'status','pending') NOT IN ('done','cancelled')))
                                                                          AS work_open
          FROM cand cd LEFT JOIN card k ON k.vehicle_id = cd.id
      )
      SELECT ev.*,
             ((NOT v_gate_on) OR (ev.current_soc >= ev.ready_soc AND NOT ev.work_open)) AS ready
        FROM ev
       ORDER BY (CASE WHEN (NOT v_gate_on) OR (ev.current_soc >= ev.ready_soc AND NOT ev.work_open) THEN 0 ELSE 1 END),
                ev.last_state_change, ev.id
    LOOP
      IF v_rec.ready THEN
        -- deploy_cap_per_minute: v_deploy_cap is calibrated as releases per 30-MINUTE
        -- tick; rescale to the real tick length so throughput cannot change with tick size.
        IF v_admitted < v_relcap THEN
          UPDATE vehicles SET current_state = 'staged_for_departure'::vehicle_state, last_state_change = p_sim_clock_now,
                 -- 0546 (G273): the release drops the flag this gate raised with its own stamp. A finished car
                 -- flagged "stuck" told every cockpit it needed a person, and the next bay exit sent it to the
                 -- service bay. A flag anything else raised is kept.
                 config = jsonb_set(config, '{svc_step}', to_jsonb('ready'::text)) - 'deploy_gate'
                          - (CASE WHEN config->>'flagged_issue_type' IN ('deploy_gate_stuck', 'deploy_gate_hard_cap')
                                  THEN ARRAY['flagged_issue', 'flagged_issue_type'] ELSE ARRAY[]::text[] END)
           WHERE id = v_rec.id;
          v_admitted := v_admitted + 1;
        END IF;   -- over cap: stays need_deploy, retried next tick (unchanged behaviour)
      ELSE
        DECLARE
          v_since TIMESTAMPTZ; v_reason TEXT; v_missing TEXT[]; v_held_min NUMERIC; v_remedy TEXT;
          v_open TEXT[]; v_open_svc_bay BOOLEAN; v_open_charge BOOLEAN;   -- 0464 (G196b)
        BEGIN
          /* 0447 (G182): a hold stamp is this run's or it is absent. An earlier run's stamp made a fresh hold
             read three weeks old and released the vehicle past the gate on its first tick. */
          v_since    := CASE WHEN (v_rec.config #>> '{deploy_gate,run}') = p_sim_run_id::text
                             -- 0545 (G269): from the later of the stamp and the car's last state change. A car that
                             -- went to its charger or bay and came back is timed from its return, not from its first
                             -- hold: time being served is not time held. The gate never moves last_state_change.
                             THEN GREATEST(COALESCE((v_rec.config #>> '{deploy_gate,held_since}')::timestamptz, p_sim_clock_now),
                                           COALESCE(v_rec.last_state_change, '-infinity'::timestamptz))
                             ELSE p_sim_clock_now END;
          v_held_min := GREATEST(0, EXTRACT(EPOCH FROM (p_sim_clock_now - v_since))/60.0);
          -- ══════ 0464 (G196b): THE REMEDY FOLLOWS THE WORK, AND `missing` NAMES IT ══════
          -- Any open must-do atom at a ready SoC used to mean need_service, and need_service admits to the
          -- SERVICE BAY only: 8 of 11 service-bay exits on 317d4331 credited nothing (a charge, detail and
          -- wash work). service_cadence_policy.lane already says what each bay can do. Service-bay work ->
          -- need_service; an open charge -> need_charge; anything else -> need_deploy, held here and re-read
          -- next tick (cabin, exterior and digital work runs in place; wash and detail are admitted from
          -- staging by the needs card), bounded as before by this gate's patience flag and hard cap.
          -- `missing` is the atoms that hold the gate; the card's list stays as card_must_do_now.
          SELECT COALESCE(array_agg(DISTINCT a->>'svc' ORDER BY a->>'svc'), ARRAY[]::text[]),
                 COALESCE(bool_or(cp.lane = 'service_bay'), false),
                 COALESCE(bool_or(a->>'svc' = 'charge'), false)
            INTO v_open, v_open_svc_bay, v_open_charge
            FROM ottoq_visit_needs vn
            CROSS JOIN LATERAL jsonb_array_elements(vn.atoms) a
            LEFT JOIN service_cadence_policy cp ON cp.svc = a->>'svc' AND cp.is_active
           WHERE vn.vehicle_id = v_rec.id AND vn.sim_run_id = p_sim_run_id
             AND vn.status IN ('open','in_progress')
             AND a->>'svc' <> 'readiness_check'   /* 0543: the remedy follows every open service */
             AND COALESCE(a->>'status','pending') NOT IN ('done','cancelled');
          v_reason   := CASE WHEN v_rec.current_soc < v_rec.ready_soc THEN 'soc_below_ready' ELSE 'must_do_work_open' END;
          v_remedy   := CASE WHEN v_rec.current_soc < v_rec.ready_soc THEN 'need_charge'
                             WHEN v_open_svc_bay                     THEN 'need_service'
                             WHEN v_open_charge                      THEN 'need_charge'
                             ELSE 'need_deploy' END;
          v_missing  := (CASE WHEN v_rec.current_soc < v_rec.ready_soc AND NOT ('charge' = ANY (v_open))
                              THEN ARRAY['charge'] ELSE ARRAY[]::text[] END) || v_open;

          IF v_held_min >= v_hardcap THEN
            -- 0542 (G265 (a), CLAUDE.md rule 9): hatch 3 no longer releases. Past the hard cap the car stays held on its
            -- remedy like any other hold, and the first tick past the cap escalates it to a person: one critical event,
            -- kept to one by `escalated_at` on this run's hold stamp. A car the depot cannot finish is a capacity or
            -- defect finding, never a reason to send it out with its needs open. v_override counts these cars now.
            v_override := v_override + 1;
            IF NOT ((v_rec.config #>> '{deploy_gate,run}') = p_sim_run_id::text
                    AND (v_rec.config #>> '{deploy_gate,escalated_at}') IS NOT NULL) THEN
              PERFORM ottoq_record_event(p_actor_type := 'ottoq_engine', p_actor_id := 'deploy_ready_gate',
                p_event_type := 'twin.deploy_gate_escalated', p_entity_type := 'vehicle', p_entity_id := v_rec.id,
                p_payload := jsonb_build_object('held_min', round(v_held_min,1), 'hard_cap_min', v_hardcap,
                  'reason', v_reason, 'remedy', v_remedy, 'soc', v_rec.current_soc, 'ready_soc', v_rec.ready_soc,
                  'missing', to_jsonb(v_missing),
                  'note', 'held past the hard cap with its needs open: a person must look. The car is not released (CLAUDE.md rule 9)'),
                p_severity := 'critical', p_ingest_source := 'twin', p_data_source := 'twin', p_sim_run_id := p_sim_run_id);
            END IF;
          END IF;
          UPDATE vehicles
             SET config = jsonb_set(config, '{svc_step}', to_jsonb(v_remedy))
                        || jsonb_build_object('deploy_gate', jsonb_build_object(
                             'held_since', v_since, 'run', p_sim_run_id, 'held_min', round(v_held_min,1),   /* 0447 */
                             'reason', v_reason, 'remedy', v_remedy,
                             'soc', v_rec.current_soc, 'ready_soc', v_rec.ready_soc,
                             'missing', to_jsonb(v_missing),
                             'card_must_do_now', to_jsonb(COALESCE(v_rec.card_must, ARRAY[]::text[])),
                             'fits_window', v_rec.fits_window,
                             'minutes_to_deploy', v_rec.minutes_to_deploy)
                           || CASE WHEN v_held_min >= v_hardcap   /* 0542 */
                                   THEN jsonb_build_object('escalated_at',
                                          COALESCE(CASE WHEN (v_rec.config #>> '{deploy_gate,run}') = p_sim_run_id::text
                                                        THEN v_rec.config #> '{deploy_gate,escalated_at}' END,
                                                   to_jsonb(p_sim_clock_now)))
                                   ELSE '{}'::jsonb END)
                        || CASE WHEN v_held_min >= v_hardcap
                                THEN jsonb_build_object('flagged_issue', true,
                                                        'flagged_issue_type', 'deploy_gate_hard_cap')
                                WHEN v_held_min >= v_patience_dep
                                THEN jsonb_build_object('flagged_issue', true,
                                                        'flagged_issue_type', 'deploy_gate_stuck')
                                ELSE '{}'::jsonb END
           WHERE id = v_rec.id;   -- last_state_change deliberately UNTOUCHED (queue order + patience metric)
          v_held := v_held + 1;
          IF v_held_min >= v_patience_dep THEN v_esc_gate := v_esc_gate + 1; END IF;
        END;
      END IF;
    END LOOP;

    IF v_held > 0 OR v_override > 0 THEN
      PERFORM ottoq_record_event(p_actor_type := 'ottoq_engine', p_actor_id := 'deploy_ready_gate',
        p_event_type := 'twin.deploy_gate_summary', p_entity_type := 'depot', p_entity_id := p_depot_id,
        p_payload := jsonb_build_object('candidates', v_ncand, 'released', v_admitted,
          'held', v_held, 'escalated', v_esc_gate, 'held_past_hard_cap', v_override,
          'floor', v_floor, 'patience_min', v_patience_dep, 'hard_cap_min', v_hardcap,
          'gate_enabled', v_gate_on),
        p_severity := CASE WHEN v_override > 0 THEN 'critical'
                           WHEN v_esc_gate > 0 THEN 'warning' ELSE 'info' END,
        p_ingest_source := 'twin', p_data_source := 'twin', p_sim_run_id := p_sim_run_id);
    END IF;
  END IF;

  -- 0546 (G274, CLAUDE.md rule 9): a car held on its remedy (a charger or the service bay) past the hard cap is
  -- escalated to a person as a car held at the gate is: one critical twin.deploy_gate_escalated per wait, stamped
  -- remedy_wait {run, since}. The gate judges only need_deploy cars, so a car could wait all day for a charger with no
  -- one told. The car is not moved or released: its wait is a capacity finding.
  -- 0551 (G282, G279): every car the charge cursor reads is waiting for a charger, at the gate as well as in staging, and a
  -- charge wait is read on the cursor's clock (public.ottoq_charge_wait_min), so a fault or a move does not restart it.
  -- One escalation per episode: remedy_wait.since is the episode's start (public.ottoq_charge_wait_since). A wait for the
  -- service bay is timed as before, from the car's last state change.
  DECLARE v_w RECORD; v_w_missing TEXT[];
  BEGIN
    FOR v_w IN
      SELECT q.* FROM (
        SELECT v.id, v.current_soc, v.config, v.current_state::text AS state,
               CASE WHEN v.current_state = 'arrived_at_gate' THEN 'need_charge' ELSE v.config->>'svc_step' END AS step,
               CASE WHEN v.current_state = 'arrived_at_gate' OR v.config->>'svc_step' = 'need_charge'
                    THEN public.ottoq_charge_wait_min(v.config, v.last_state_change, p_sim_clock_now, p_sim_run_id)
                    ELSE GREATEST(EXTRACT(EPOCH FROM (p_sim_clock_now - v.last_state_change)) / 60.0, 0) END AS wait_min,
               CASE WHEN v.current_state = 'arrived_at_gate' OR v.config->>'svc_step' = 'need_charge'
                    THEN public.ottoq_charge_wait_since(v.config, v.last_state_change, p_sim_run_id)
                    ELSE v.last_state_change END AS since
          FROM vehicles v
         WHERE v.home_depot_id = p_depot_id AND v.category = 'autonomous'
           AND ((v.current_state = 'staged_awaiting_service' AND v.config->>'svc_step' IN ('need_charge', 'need_service'))
                OR (v.current_state = 'arrived_at_gate'
                    AND v.current_soc < COALESCE((SELECT vn.target_soc FROM ottoq_visit_needs vn
                                                   WHERE vn.vehicle_id = v.id AND vn.status IN ('open','in_progress')
                                                     AND vn.sim_run_id = p_sim_run_id
                                                   ORDER BY vn.created_at DESC, vn.visit_key DESC LIMIT 1),
                                                 public.ottoq_default_target_soc()) - 1))
      ) q
       WHERE q.wait_min >= v_hardcap
         AND NOT (COALESCE(q.config #>> '{remedy_wait,run}', '') = p_sim_run_id::text
                  AND (q.config #>> '{remedy_wait,since}')::timestamptz IS NOT DISTINCT FROM q.since)
       ORDER BY q.since, q.id
    LOOP
      SELECT COALESCE(array_agg(DISTINCT a->>'svc' ORDER BY a->>'svc'), ARRAY[]::text[]) INTO v_w_missing
        FROM ottoq_visit_needs vn CROSS JOIN LATERAL jsonb_array_elements(vn.atoms) a
       WHERE vn.vehicle_id = v_w.id AND vn.sim_run_id = p_sim_run_id AND vn.status IN ('open','in_progress')
         AND a->>'svc' <> 'readiness_check' AND COALESCE(a->>'status','pending') NOT IN ('done','cancelled');
      IF v_w.step = 'need_charge' AND NOT ('charge' = ANY (v_w_missing)) THEN
        v_w_missing := ARRAY['charge'] || v_w_missing;
      END IF;
      PERFORM ottoq_record_event(p_actor_type := 'ottoq_engine', p_actor_id := 'deploy_ready_gate',
        p_event_type := 'twin.deploy_gate_escalated', p_entity_type := 'vehicle', p_entity_id := v_w.id,
        p_payload := jsonb_build_object('held_min', round(v_w.wait_min, 1), 'hard_cap_min', v_hardcap,
          'reason', CASE WHEN v_w.step = 'need_charge' THEN 'waiting_for_a_charger' ELSE 'waiting_for_the_service_bay' END,
          'remedy', v_w.step, 'soc', v_w.current_soc, 'missing', to_jsonb(v_w_missing),
          'at', CASE WHEN v_w.state = 'arrived_at_gate' THEN 'gate' ELSE 'staging' END, 'waiting_since', v_w.since,
          'note', 'waited past the hard cap for its remedy: a person must look. The car is not released (CLAUDE.md rule 9)'),
        p_severity := 'critical', p_ingest_source := 'twin', p_data_source := 'twin', p_sim_run_id := p_sim_run_id);
      UPDATE vehicles
         SET config = COALESCE(config, '{}'::jsonb) || jsonb_build_object('remedy_wait', jsonb_build_object(
               'run', p_sim_run_id, 'since', v_w.since, 'escalated_at', p_sim_clock_now))
       WHERE id = v_w.id;   -- last_state_change deliberately UNTOUCHED
    END LOOP;
  END;

  -- overflow now counts need_charge too: a vehicle held by the readiness gate is still
  -- waiting in staging and must not vanish from the queue telemetry.
  SELECT COUNT(*) INTO v_overflow FROM vehicles WHERE home_depot_id = p_depot_id AND current_state = 'staged_awaiting_service' AND config->>'svc_step' IN ('need_service','need_deploy','need_charge');
  IF v_overflow > 0 THEN
    DECLARE v_patience NUMERIC := GREATEST(1, 10 + ottoq_apply_profile(p_sim_run_id, 'queue_patience', 0, 0)); v_escalated INT;
    BEGIN
      SELECT COUNT(*) INTO v_escalated FROM vehicles WHERE home_depot_id = p_depot_id AND current_state = 'staged_awaiting_service'
         AND config->>'svc_step' IN ('need_service','need_deploy','need_charge') AND EXTRACT(EPOCH FROM (p_sim_clock_now - last_state_change))/60.0 > v_patience;
      PERFORM ottoq_record_event(p_actor_type := 'ottoq_engine', p_actor_id := 'service_flow', p_event_type := 'twin.staging_overflow',
        p_entity_type := 'depot', p_entity_id := p_depot_id,
        p_payload := jsonb_build_object('overflow', v_overflow, 'escalated', v_escalated, 'patience_min', ROUND(v_patience,1), 'wash_cap', v_wash_cap, 'svc_cap', v_svc_cap, 'deploy_cap', v_deploy_cap, 'gate_held', v_held),
        p_severity := CASE WHEN v_escalated > 0 THEN 'warning' ELSE 'info' END, p_ingest_source := 'twin', p_data_source := 'twin', p_sim_run_id := p_sim_run_id);
    END;
  END IF;

  out_washing   := (SELECT COUNT(*) FROM vehicles WHERE home_depot_id=p_depot_id AND current_state IN ('in_wash_bay','in_detail_bay'));
  out_servicing := (SELECT COUNT(*) FROM vehicles WHERE home_depot_id=p_depot_id AND current_state='in_service_bay');
  out_staged    := (SELECT COUNT(*) FROM vehicles WHERE home_depot_id=p_depot_id AND current_state='staged_awaiting_service');
  out_ready     := (SELECT COUNT(*) FROM vehicles WHERE home_depot_id=p_depot_id AND current_state='staged_for_departure');
  out_overflow  := v_overflow;
  RETURN NEXT;
END;
$function$;
-- @@ function twin.ottoq_sim_maybe_incident(p_seed bigint, p_salt text, p_miles_this_tick numeric, p_rate_mult numeric, p_severity_shift numeric, p_breakdown_mult numeric)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_maybe_incident(p_seed bigint, p_salt text, p_miles_this_tick numeric, p_rate_mult numeric DEFAULT 1, p_severity_shift numeric DEFAULT 0, p_breakdown_mult numeric DEFAULT 1)
 RETURNS TABLE(out_kind text, out_sev text, out_requires_tow boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  -- 0696 (G408): collisions at the rate Waymo filed with the CPUC for its California driverless deployment,
  -- 2026-04-01 to 2026-06-30: 291 collision rows over 28,143,285 miles, 10.3 per million
  -- (docs/research/direct/2026-10-10-cpuc-waymo-q2-2026-duty-cycle.md). ASSUMPTION: it stands in for every twin fleet.
  v_collision_per_mile CONSTANT numeric := 291.0 / 28143285;
  -- breakdowns, tire failures and strandings at their earlier rate (0.18 of the earlier 5e-7): no public per-mile data
  v_other_per_mile     CONSTANT numeric := 0.00000009;
  -- of the collisions: towed, NHTSA SGO 2021-01 ADS reports, 647 of Waymo's 1,211; severe, the CPUC file, 2 of 291
  -- (docs/research/direct/2026-10-10-nhtsa-crash-reports-and-temperature-curves.md)
  v_towed              CONSTANT numeric := 647.0 / 1211;
  v_severe             CONSTANT numeric := 2.0 / 291;
  v_per_mile numeric;
  v_c        numeric;
  v_roll     numeric;
  v_pick     numeric;
BEGIN
  IF p_miles_this_tick <= 0 THEN RETURN; END IF;
  v_per_mile := v_collision_per_mile + v_other_per_mile;
  v_roll := ottoq_sim_seeded_random(p_seed, 'inc_roll:' || p_salt);
  -- A.10: breakdown_rate also lifts the overall incident probability slightly
  IF v_roll >= (v_per_mile * p_miles_this_tick * COALESCE(p_rate_mult, 1) * COALESCE(p_breakdown_mult, 1)) THEN RETURN; END IF;

  -- A.10: incident_severity shifts the pick toward more severe outcomes, so the outcomes stay in order of severity
  v_pick := LEAST(1, GREATEST(0, ottoq_sim_seeded_random(p_seed, 'inc_pick:' || p_salt) + COALESCE(p_severity_shift, 0)));
  v_c := v_collision_per_mile / v_per_mile;   -- the collisions' share of what fires
  IF v_pick < v_c * (1 - v_towed) THEN
    out_kind := 'collision_minor'; out_sev := 'minor'; out_requires_tow := FALSE;
  ELSIF v_pick < v_c * (1 - v_severe) THEN
    out_kind := 'collision_moderate'; out_sev := 'moderate'; out_requires_tow := TRUE;
  ELSIF v_pick < v_c * (1 - v_severe) + (1 - v_c) * 4 / 9 THEN
    out_kind := 'breakdown_electrical'; out_sev := 'moderate'; out_requires_tow := TRUE;
  ELSIF v_pick < v_c * (1 - v_severe) + (1 - v_c) * 7 / 9 THEN
    out_kind := 'tire_failure'; out_sev := 'minor'; out_requires_tow := TRUE;
  ELSIF v_pick < v_c * (1 - v_severe) + (1 - v_c) THEN
    out_kind := 'stranded_low_soc'; out_sev := 'moderate'; out_requires_tow := TRUE;
  ELSE
    out_kind := 'collision_major'; out_sev := 'major'; out_requires_tow := TRUE;
  END IF;
  RETURN NEXT;
END;
$function$;
-- @@ function public.ottoq_twin_run_list(p_limit integer)
CREATE OR REPLACE FUNCTION public.ottoq_twin_run_list(p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET statement_timeout TO '8s'
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_out JSONB;
  -- 0466 (G198): a cost guard, not a count. A counter that reaches it is listed in counters_capped.
  c_guard CONSTANT int := 200000;
BEGIN
  SELECT COALESCE(jsonb_agg(r ORDER BY rn), '[]'::jsonb) INTO v_out
  FROM (
    SELECT sr.rn, jsonb_build_object(
      'sim_run_id',        sr.sim_run_id,
      'scenario',          sr.scenario_code,
      'status',            sr.status,
      'started_at',        sr.started_at,
      'ended_at',          sr.ended_at,
      'sim_clock_start',   sr.sim_clock_start,
      'sim_clock_current', sr.sim_clock_current,
      'tick_count',        sr.tick_count,
      'time_scale',        sr.time_scale,
      'seed',              sr.random_seed::text,
      'sim_minutes', GREATEST(0, ROUND(
        EXTRACT(EPOCH FROM (sr.sim_clock_current - sr.sim_clock_start)) / 60.0
      ))::int,
      -- counters only for the 10 NEWEST runs; every one run-scoped and exact up to c_guard (0466)
      'counters', CASE WHEN sr.rn <= 10 THEN jsonb_build_object(
        'dispatches_total',  k.dispatches_total,
        'dispatches_active', k.dispatches_active,
        'telemetry_packets', k.telemetry_packets,
        'events_total',      k.events_total,
        'incidents_open',    k.incidents_open,
        'incidents_total',   k.incidents_total,
        'faults',            k.faults,
        'charge_sessions',   k.charge_sessions
      ) ELSE NULL END,
      'counters_capped', CASE WHEN sr.rn <= 10 THEN to_jsonb(ARRAY(
        SELECT x.key FROM (VALUES ('dispatches_total', k.dispatches_total), ('telemetry_packets', k.telemetry_packets),
                                  ('events_total', k.events_total), ('incidents_total', k.incidents_total),
                                  ('faults', k.faults), ('charge_sessions', k.charge_sessions)) x(key, n)
         WHERE x.n >= c_guard ORDER BY x.key)) ELSE NULL END,
      'variability', (
        SELECT jsonb_build_object(
          'spread_mult', COALESCE((vp.knobs #>> '{_global,spread_mult}')::numeric, 1),
          'rate_mult',   COALESCE((vp.knobs #>> '{_global,rate_mult}')::numeric, 1),
          'tuned_knobs', (
            SELECT COUNT(*) FROM jsonb_object_keys(vp.knobs) AS keys(key)
             WHERE keys.key NOT LIKE '\_%'
          ),
          'notes', vp.notes
        )
        FROM ottoq_variability_profiles vp WHERE vp.sim_run_id = sr.sim_run_id
      )
    ) AS r
    FROM (
      SELECT sr0.*, row_number() OVER (ORDER BY sr0.started_at DESC NULLS LAST, sr0.sim_run_id) AS rn
      FROM ottoq_sim_runs sr0
      -- 0470 (G202): the operator's runs only. Every harness (determinism, dial, A/B pair) stamps validation_status
      -- on its arms and an operator's run never has one; a recert sweep's 18 arms had pushed every run off the list.
      WHERE sr0.validation_status IS NULL
      ORDER BY sr0.started_at DESC NULLS LAST, sr0.sim_run_id
      LIMIT GREATEST(1, LEAST(50, p_limit))
    ) sr
    LEFT JOIN LATERAL (
      SELECT
        (SELECT count(*) FROM (SELECT 1 FROM ottoq_vehicle_dispatches d WHERE d.sim_run_id = sr.sim_run_id LIMIT c_guard) q)::int AS dispatches_total,
        (SELECT count(*) FROM ottoq_vehicle_dispatches d WHERE d.sim_run_id = sr.sim_run_id AND d.status IN ('active','returning'))::int AS dispatches_active,
        (SELECT count(*) FROM (SELECT 1 FROM ottoq_telemetry_packets t WHERE t.sim_run_id = sr.sim_run_id LIMIT c_guard) q)::int AS telemetry_packets,
        (SELECT count(*) FROM (SELECT 1 FROM ottoq_events e WHERE e.sim_run_id = sr.sim_run_id LIMIT c_guard) q)::int AS events_total,
        (SELECT count(*) FROM ottoq_vehicle_incidents i WHERE i.sim_run_id = sr.sim_run_id AND i.resolution_status = 'open')::int AS incidents_open,
        (SELECT count(*) FROM (SELECT 1 FROM ottoq_vehicle_incidents i WHERE i.sim_run_id = sr.sim_run_id LIMIT c_guard) q)::int AS incidents_total,
        (SELECT count(*) FROM (SELECT 1 FROM ottoq_events e WHERE e.sim_run_id = sr.sim_run_id
                                AND (e.event_type LIKE '%fault%' OR e.event_type LIKE '%brownout%'
                                  OR e.event_type LIKE '%anomaly%' OR e.event_type LIKE '%incident%'
                                  OR e.event_type LIKE '%voltage%' OR e.event_type LIKE '%frequency%')
                                -- 0466 (G198): weather is not a fault. twin.weather_anomaly is a per-tick
                                -- weather summary and was 454 of 470 "faults" on 317d4331.
                                AND e.event_type NOT LIKE '%weather%'
                              LIMIT c_guard) q)::int AS faults,
        -- 0466 (G198): run-scoped. This compared a session's SIM start with the run's REAL start and read 0.
        (SELECT count(*) FROM (SELECT 1 FROM ocpp_sessions cs WHERE cs.sim_run_id = sr.sim_run_id LIMIT c_guard) q)::int AS charge_sessions
       WHERE sr.rn <= 10
    ) k ON true
  ) sub;

  RETURN v_out;
END;
$function$;
-- @@ function twin.ottoq_sim_seed_fleet(p_depot_id uuid, p_seed bigint)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_seed_fleet(p_depot_id uuid, p_seed bigint DEFAULT 42)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_seed BIGINT := COALESCE(p_seed, 42);
  v_hour INT := EXTRACT(HOUR FROM (NOW() AT TIME ZONE 'America/Chicago'))::int;
  v_deploy_frac NUMERIC := ottoq_deploy_target_fraction(v_hour, 0.90);
BEGIN
  -- superseded-run leftovers never actually returned: abort, don't "complete"
  -- (completed requires return_trigger + feeds turnaround metrics)
  /* 0181: two corrections to a statement whose STATUS was always right.
     (1) sim-domain guard. 0066 section 5: this had no twin guard while
     the ocpp reset beside it is twin-only by token convention, so a
     depot reseed would abort a PRODUCTION dispatch (sim_run_id IS NULL)
     for any vehicle homed here. 0 such rows exist today, so this is a
     guard placed before the exposure, not after it.
     (2) actual_return_at left alone - NOW() is a wall clock on a column
     every reader treats as sim clock, and an aborted dispatch has no
     return to timestamp. */
  UPDATE ottoq_vehicle_dispatches d
     SET status = 'aborted',
         return_trigger = COALESCE(return_trigger, 'run_reseed_abort')
    FROM vehicles v
   WHERE d.vehicle_id = v.id AND v.home_depot_id = p_depot_id
     AND d.sim_run_id IS NOT NULL
     AND d.status IN ('active','returning');

  UPDATE ocpp_sessions cs
     SET status = 'completed', ended_at = COALESCE(ended_at, NOW())
   WHERE cs.depot_id = p_depot_id AND cs.status = 'active'::ocpp_session_status
     AND cs.id_token LIKE 'TWIN-%';

  UPDATE vehicles v
     SET current_state = CASE
           -- deploy pool: the first v_deploy_frac by seeded rank → prime sends OUT
           WHEN r.rn <= FLOOR(r.total * v_deploy_frac) THEN 'staged_for_departure'::vehicle_state
           -- service cohort, weighted charge-first (a returning wave at the gate)
           WHEN r.svcroll < 0.55 THEN 'arrived_at_gate'::vehicle_state
           WHEN r.svcroll < 0.78 THEN 'charge_complete_holding'::vehicle_state
           ELSE 'staged_awaiting_service'::vehicle_state
         END,
         current_soc = CASE
           WHEN r.rn <= FLOOR(r.total * v_deploy_frac) THEN ROUND(86 + r.socroll * 13)::int
           WHEN r.svcroll < 0.55 THEN ROUND(12 + r.socroll * 35)::int   -- gate: LOW, charge-first
           WHEN r.svcroll < 0.78 THEN ROUND(88 + r.socroll * 11)::int   -- holding: high
           ELSE ROUND(78 + r.socroll * 20)::int                          -- awaiting: mid/high
         END,
         current_stall_id = NULL, current_soc_updated_at = NOW(), current_soc_source = 'oem_telemetry',
         last_state_change = NOW() - ((r.stagger * 90)::text || ' minutes')::interval,
         config = CASE
           WHEN r.rn > FLOOR(r.total * v_deploy_frac) AND r.svcroll >= 0.78
             THEN jsonb_set(COALESCE(v.config,'{}'::jsonb) - 'service_ends_at' - 'flagged_issue' - 'flagged_issue_type' - 'exception' - 'draining_item',
                            '{svc_step}', to_jsonb('need_service'::text))
           ELSE COALESCE(v.config,'{}'::jsonb) - 'svc_step' - 'service_ends_at' - 'flagged_issue' - 'flagged_issue_type' - 'exception' - 'draining_item'
         END
    FROM (
      SELECT id,
             row_number() OVER (ORDER BY ottoq_sim_seeded_random(v_seed, 'lane:'||id::text)) AS rn,
             count(*) OVER () AS total,
             ottoq_sim_seeded_random(v_seed, 'soc:'||id::text)     AS socroll,
             ottoq_sim_seeded_random(v_seed, 'stagger:'||id::text) AS stagger,
             ottoq_sim_seeded_random(v_seed, 'svc:'||id::text)     AS svcroll
        FROM vehicles WHERE home_depot_id = p_depot_id AND category = 'autonomous'
    ) r
   WHERE v.id = r.id;

  UPDATE ottoq_ocpp_chargers SET station_state = 'Available', last_heartbeat_at = NOW(), last_fault_code = NULL
   WHERE depot_id = p_depot_id;
  UPDATE stalls SET status = 'available', current_vehicle_id = NULL, reserved_by = NULL, reserved_at = NULL, reservation_expires_at = NULL
   WHERE depot_id = p_depot_id;
  RETURN;
END;
$function$;
-- @@ function public.ottoq_evaluate_rule_core(p_rule_code text, p_entity_type text, p_entity_id uuid, p_context jsonb, p_action_context text, p_fleet_operator_id uuid, p_depot_id uuid, p_triggered_by_event_id uuid, p_override_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_evaluate_rule_core(p_rule_code text, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_context jsonb DEFAULT '{}'::jsonb, p_action_context text DEFAULT NULL::text, p_fleet_operator_id uuid DEFAULT NULL::uuid, p_depot_id uuid DEFAULT NULL::uuid, p_triggered_by_event_id uuid DEFAULT NULL::uuid, p_override_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(passed boolean, reason text, enforcement_taken text, evaluation_id uuid, severity text, enforcement text, suggested_action text, rule_version integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_rule        ottoq_rules%ROWTYPE;
  v_params      JSONB;
  v_result      ottoq_rule_result;
  v_started_at  TIMESTAMPTZ := clock_timestamp();
  v_eval_id     UUID := gen_random_uuid();
  v_event_id    UUID;
  v_enforcement TEXT;
  v_severity    TEXT;
  v_taken       TEXT;
  v_correlation UUID;
  v_dynamic_sql TEXT;
  v_run         UUID;
BEGIN
  v_run := ottoq.ottoq_active_sim_run_id();

  SELECT * INTO v_rule FROM ottoq_rules
   WHERE rule_code = p_rule_code AND status IN ('active','shadow')
   ORDER BY version DESC LIMIT 1;

  IF NOT FOUND THEN
    v_event_id := ottoq_record_event(
      p_actor_type := 'ottoq_engine', p_event_type := 'system.catalog_miss',
      p_entity_type := COALESCE(p_entity_type, 'system'), p_entity_id := p_entity_id,
      p_payload := jsonb_build_object('missing_rule_code', p_rule_code), p_severity := 'warning',
      p_data_source := CASE WHEN v_run IS NULL THEN 'production' ELSE 'twin' END,
      p_sim_run_id := v_run);
    RETURN QUERY SELECT TRUE, 'rule_not_found'::text, 'allowed'::text, v_eval_id,
                        'info'::text, 'log_only'::text, NULL::text, 0;
    RETURN;
  END IF;

  v_params := ottoq_resolve_rule_parameters(p_rule_code, p_fleet_operator_id, p_depot_id, NULL);

  BEGIN
    v_dynamic_sql := format('SELECT * FROM %I($1,$2,$3,$4)', v_rule.evaluator_function);
    EXECUTE v_dynamic_sql INTO v_result USING p_entity_type, p_entity_id, p_context, v_params;
  EXCEPTION WHEN OTHERS THEN
    v_event_id := ottoq_record_event(
      p_actor_type := 'ottoq_engine', p_event_type := 'system.catalog_miss',
      p_entity_type := COALESCE(p_entity_type, 'system'), p_entity_id := p_entity_id,
      p_payload := jsonb_build_object('rule_code', p_rule_code, 'evaluator_error', SQLERRM,
                     'sqlstate', SQLSTATE, 'enforcement', v_rule.enforcement, 'severity', v_rule.severity,
                     'fail_closed', (v_rule.enforcement = 'block')),
      p_severity := 'critical',
      p_data_source := CASE WHEN v_run IS NULL THEN 'production' ELSE 'twin' END,
      p_sim_run_id := v_run);

    -- WIRE-2: a BLOCK-tier rule that THROWS fails CLOSED (the safety posture);
    -- non-block advisory rules keep log-and-pass.
    IF v_rule.enforcement = 'block' THEN
      RETURN QUERY SELECT FALSE, ('evaluator_error_failclosed: ' || SQLERRM)::text, 'blocked'::text, v_eval_id,
                          COALESCE(v_rule.severity,'critical'), v_rule.enforcement, 'fix_evaluator_or_supply_context'::text, v_rule.version;
    ELSE
      RETURN QUERY SELECT TRUE, ('evaluator_error: ' || SQLERRM)::text, 'logged'::text, v_eval_id,
                          COALESCE(v_rule.severity,'warning'), v_rule.enforcement, NULL::text, v_rule.version;
    END IF;
    RETURN;
  END;

  v_enforcement := v_rule.enforcement;
  v_severity    := COALESCE(v_result.severity_override, v_rule.severity);

  IF v_result.passed THEN
    v_taken := CASE WHEN v_enforcement = 'shadow' THEN 'shadow_pass' ELSE 'allowed' END;
  ELSE
    v_taken := CASE
      WHEN p_override_id IS NOT NULL THEN 'overridden'
      WHEN v_enforcement = 'block'    THEN 'blocked'
      WHEN v_enforcement = 'warn'     THEN 'warned'
      WHEN v_enforcement = 'log_only' THEN 'logged'
      WHEN v_enforcement = 'shadow'   THEN 'shadow_fail'
      ELSE 'logged'
    END;
  END IF;

  v_correlation := NULLIF(current_setting('ottoq.correlation_id', TRUE), '')::UUID;

  IF current_setting('ottoq.dryrun', true) = 'on' THEN
    RETURN QUERY SELECT v_result.passed, v_result.reason, v_taken, v_eval_id, v_severity, v_enforcement, v_result.suggested_action, v_rule.version;
    RETURN;
  END IF;  -- MPC fork: evaluate but do not persist

  -- THE AUDIT RECORD. 0202: it now names its run (sim_run_id := v_run; NULL is production).
  INSERT INTO ottoq_rule_evaluations (
    evaluation_id, evaluated_at, duration_ms, rule_code, rule_version,
    triggered_by_event_id, action_context, entity_type, entity_id,
    fleet_operator_id, depot_id, passed, reason, severity, enforcement, enforcement_taken,
    parameters_used, context, result_payload, override_id, correlation_id, sim_run_id
  ) VALUES (
    v_eval_id, NOW(), EXTRACT(MILLISECOND FROM (clock_timestamp() - v_started_at))::INTEGER,
    p_rule_code, v_rule.version, p_triggered_by_event_id, p_action_context,
    p_entity_type, p_entity_id, p_fleet_operator_id, p_depot_id,
    v_result.passed, v_result.reason, v_severity, v_enforcement, v_taken,
    v_params, p_context, COALESCE(v_result.payload, '{}'::jsonb), p_override_id, v_correlation, v_run
  );

  -- ══════════════════════════ 0015 ══════════════════════════
  -- 29,178 `rule.evaluated_pass` events in 3 days, every one of them a strict subset
  -- of the row we just wrote, plus a third write to stitch them together. A rule that
  -- passed is the expected case and carries no signal the evaluation row lacks. So:
  -- emit the event for a FAIL (always), or for ANY shadow-tier evaluation. Skip it for
  -- a pass on a non-shadow rule -- and skip the linked_event_id UPDATE with it. The
  -- audit trail is not thinned: ottoq_rule_evaluations still has one row per evaluation.
  IF (NOT v_result.passed) OR v_enforcement = 'shadow' THEN
    v_event_id := ottoq_record_event(
      p_actor_type := 'ottoq_engine',
      p_event_type := CASE WHEN v_result.passed THEN 'rule.evaluated_pass' ELSE 'rule.evaluated_fail' END,
      p_entity_type := COALESCE(p_entity_type, 'system'), p_entity_id := p_entity_id,
      p_fleet_operator_id := p_fleet_operator_id, p_depot_id := p_depot_id,
      p_payload := jsonb_build_object(
        'rule_code', p_rule_code, 'rule_version', v_rule.version,
        'passed', v_result.passed, 'reason', v_result.reason,
        'enforcement_taken', v_taken, 'severity', v_severity,
        'action_context', p_action_context, 'override_id', p_override_id,
        'result_payload', v_result.payload),
      p_severity := v_severity, p_parent_event_id := p_triggered_by_event_id,
      p_correlation_id := v_correlation,
      p_data_source := CASE WHEN v_run IS NULL THEN 'production' ELSE 'twin' END,
      p_sim_run_id := v_run);

    UPDATE ottoq_rule_evaluations re SET linked_event_id = v_event_id WHERE re.evaluation_id = v_eval_id;
  END IF;

  RETURN QUERY SELECT v_result.passed, v_result.reason, v_taken, v_eval_id,
                      v_severity, v_enforcement, v_result.suggested_action, v_rule.version;
END;
$function$;
-- @@ function public.ottoq_evaluate_rule(p_rule_code text, p_entity_type text, p_entity_id uuid, p_context jsonb, p_action_context text, p_fleet_operator_id uuid, p_depot_id uuid, p_triggered_by_event_id uuid, p_override_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_evaluate_rule(p_rule_code text, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_context jsonb DEFAULT '{}'::jsonb, p_action_context text DEFAULT NULL::text, p_fleet_operator_id uuid DEFAULT NULL::uuid, p_depot_id uuid DEFAULT NULL::uuid, p_triggered_by_event_id uuid DEFAULT NULL::uuid, p_override_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(passed boolean, reason text, enforcement_taken text, evaluation_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_rule_version integer;
BEGIN
  -- call the non-raising core (assign each OUT column explicitly)
  SELECT c.passed, c.reason, c.enforcement_taken, c.evaluation_id, c.rule_version
    INTO passed, reason, enforcement_taken, evaluation_id, v_rule_version
  FROM ottoq_evaluate_rule_core(
    p_rule_code, p_entity_type, p_entity_id, p_context, p_action_context,
    p_fleet_operator_id, p_depot_id, p_triggered_by_event_id, p_override_id) c;

  IF enforcement_taken = 'blocked' THEN
    RAISE EXCEPTION 'OTTOQ_RULE_BLOCKED: % — %', p_rule_code, COALESCE(reason,'no reason provided')
      USING ERRCODE = 'P0001',
            HINT = format('rule_version=%s evaluation_id=%s', v_rule_version, evaluation_id);
  END IF;

  RETURN QUERY SELECT passed, reason, enforcement_taken, evaluation_id;
END;
$function$;
-- @@ function public.ottoq_shield_probe(p_action_context text, p_entity_type text, p_entity_id uuid, p_context jsonb, p_fleet_operator_id uuid, p_depot_id uuid, p_triggered_by_event_id uuid, p_override_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_shield_probe(p_action_context text, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_context jsonb DEFAULT '{}'::jsonb, p_fleet_operator_id uuid DEFAULT NULL::uuid, p_depot_id uuid DEFAULT NULL::uuid, p_triggered_by_event_id uuid DEFAULT NULL::uuid, p_override_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(rule_code text, passed boolean, reason text, enforcement_taken text, evaluation_id uuid, severity text, enforcement text, suggested_action text, would_block boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_rc TEXT;
BEGIN
  FOR v_rc IN
    SELECT r.rule_code FROM ottoq_rules r
     WHERE r.status IN ('active','shadow')
       AND p_action_context = ANY(r.applies_to_actions)
     ORDER BY CASE r.severity
                WHEN 'safety_critical' THEN 1 WHEN 'critical' THEN 2
                WHEN 'error' THEN 3 WHEN 'warning' THEN 4 WHEN 'info' THEN 5 ELSE 6 END,
              r.rule_code
  LOOP
    RETURN QUERY
    SELECT v_rc, c.passed, c.reason, c.enforcement_taken, c.evaluation_id,
           c.severity, c.enforcement, c.suggested_action,
           -- would_block = this rule, if enforced, blocks the action (override-agnostic):
           (NOT c.passed AND c.enforcement = 'block')
    FROM ottoq_evaluate_rule_core(
      v_rc, p_entity_type, p_entity_id, p_context, p_action_context,
      p_fleet_operator_id, p_depot_id, p_triggered_by_event_id, p_override_id) c;
  END LOOP;
END;
$function$;
-- @@ function public.ottoq_build_decision_frame(p_depot_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_build_decision_frame(p_depot_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
  SELECT public.ottoq_build_decision_frame(p_depot_id, public.ottoq_current_sim_run_id());
$function$;
-- @@ function public.ottoq_capture_decision_snapshot(p_sim_run_id uuid, p_tick_seq bigint, p_depot_id uuid, p_sim_clock timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ottoq_capture_decision_snapshot(p_sim_run_id uuid, p_tick_seq bigint, p_depot_id uuid, p_sim_clock timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_existing uuid;
  v_frame    jsonb;
  v_hash     text;
  v_counts   jsonb;
  v_id       uuid;
BEGIN
  SELECT snapshot_id INTO v_existing
    FROM ottoq_decision_snapshots WHERE sim_run_id = p_sim_run_id AND tick_seq = p_tick_seq;
  IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;

  v_frame := ottoq_build_decision_frame(p_depot_id, p_sim_run_id);
  -- 0280: hash the ID-BLIND payload, not the raw frame. The raw frame carries
  -- ocpp_sessions.id (uuid_generate_v4) in the digest AND in the sessions sort
  -- key, which made two arms of a PASSING certification pair disagree on 44 of
  -- 48 ticks (db/checks/0216). The stored `frame` is unchanged and keeps full
  -- fidelity; only what gets digested is normalised.
  v_hash := encode(digest(jsonb_pretty(public.ottoq_frame_hash_payload(v_frame)),
                          'sha256'), 'hex');
  v_counts := jsonb_build_object(
    'vehicles', jsonb_array_length(COALESCE(v_frame->'vehicles','[]'::jsonb)),
    'stalls',   jsonb_array_length(COALESCE(v_frame->'stalls','[]'::jsonb)),
    'sessions', jsonb_array_length(COALESCE(v_frame->'sessions','[]'::jsonb))
  );

  INSERT INTO ottoq_decision_snapshots (sim_run_id, tick_seq, depot_id, sim_clock,
                                        content_hash, frame, frame_counts, hash_algo)
  VALUES (p_sim_run_id, p_tick_seq, p_depot_id, p_sim_clock, v_hash, v_frame, v_counts, 2)
  ON CONFLICT (sim_run_id, tick_seq) DO NOTHING
  RETURNING snapshot_id INTO v_id;

  IF v_id IS NULL THEN
    SELECT snapshot_id INTO v_id FROM ottoq_decision_snapshots
     WHERE sim_run_id = p_sim_run_id AND tick_seq = p_tick_seq;
  END IF;
  RETURN v_id;
END;
$function$;
-- @@ function public.ottoq_assert_snapshot_integrity(p_snapshot_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_assert_snapshot_integrity(p_snapshot_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_row        ottoq_decision_snapshots%ROWTYPE;
  v_recomputed text;
BEGIN
  SELECT * INTO v_row FROM ottoq_decision_snapshots WHERE snapshot_id = p_snapshot_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OTTOQ_SNAPSHOT_MISSING: %', p_snapshot_id USING ERRCODE = 'P0001';
  END IF;

  -- 0280: verify under the algorithm that WROTE this row. NULL is the original
  -- raw-frame digest and is left verifiable exactly as it was; 2 is the id-blind
  -- payload. An unknown value is refused rather than guessed -- a verifier that
  -- falls back on an unrecognised algorithm is not a verifier.
  IF v_row.hash_algo IS NULL THEN
    v_recomputed := encode(digest(jsonb_pretty(v_row.frame), 'sha256'), 'hex');
  ELSIF v_row.hash_algo = 2 THEN
    v_recomputed := encode(digest(jsonb_pretty(public.ottoq_frame_hash_payload(v_row.frame)),
                                  'sha256'), 'hex');
  ELSE
    RAISE EXCEPTION 'OTTOQ_SNAPSHOT_UNKNOWN_ALGO: snapshot % declares hash_algo %',
                    p_snapshot_id, v_row.hash_algo USING ERRCODE = 'P0001';
  END IF;

  IF v_recomputed <> v_row.content_hash THEN
    RAISE EXCEPTION 'OTTOQ_SNAPSHOT_TAMPERED: % expected % got %',
                    p_snapshot_id, v_row.content_hash, v_recomputed USING ERRCODE = 'P0001';
  END IF;
  RETURN TRUE;
END;
$function$;
-- @@ function public.ottoq_depot_current_demand_kw(p_depot_id uuid, p_now timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ottoq_depot_current_demand_kw(p_depot_id uuid, p_now timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
  SELECT ottoq_sim_compute_charger_load_kw(p_depot_id, COALESCE(p_now, now()));
$function$;
-- @@ function public.ottoq_mirror_grid_event_to_ottoq(p_depot_id uuid, p_kind text, p_effective_at timestamp with time zone, p_expires_at timestamp with time zone, p_payload jsonb, p_clear boolean)
CREATE OR REPLACE FUNCTION public.ottoq_mirror_grid_event_to_ottoq(p_depot_id uuid, p_kind text, p_effective_at timestamp with time zone, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_payload jsonb DEFAULT '{}'::jsonb, p_clear boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_event_type TEXT;
  v_severity   TEXT;
  v_id         UUID;
BEGIN
  -- Map twin vocabulary -> certified-evaluator vocabulary.
  v_event_type := CASE p_kind
    WHEN 'grid_brownout'            THEN 'brownout'
    WHEN 'grid_voltage_sag'         THEN 'undervoltage'
    WHEN 'grid_frequency_excursion' THEN 'grid_trip'
    WHEN 'demand_response_called'   THEN 'demand_response_called'
    ELSE p_kind  -- already-canonical types pass through (brownout/undervoltage/overvoltage/grid_trip)
  END;
  v_severity := CASE WHEN v_event_type = 'demand_response_called' THEN 'critical' ELSE 'safety_critical' END;

  IF p_clear THEN
    -- Clear the most-recent open event of this type for the depot.
    UPDATE ottoq_grid_events
       SET cleared_at = p_effective_at
     WHERE depot_id = p_depot_id AND event_type = v_event_type AND cleared_at IS NULL
       AND grid_event_id = (
         SELECT grid_event_id FROM ottoq_grid_events
          WHERE depot_id = p_depot_id AND event_type = v_event_type AND cleared_at IS NULL
          ORDER BY effective_at DESC LIMIT 1)
     RETURNING grid_event_id INTO v_id;
    RETURN v_id;
  END IF;

  INSERT INTO ottoq_grid_events (depot_id, event_type, severity, effective_at, expires_at, source, payload)
  VALUES (p_depot_id, v_event_type, v_severity, p_effective_at, p_expires_at, 'twin_mirror',
          p_payload || jsonb_build_object('twin_kind', p_kind))
  RETURNING grid_event_id INTO v_id;
  RETURN v_id;
END;
$function$;
-- @@ function public.ottoq_mirror_dr_call(p_dr_call_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_mirror_dr_call(p_dr_call_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE d ottoq_dr_calls%ROWTYPE; v_id uuid;
BEGIN
  SELECT * INTO d FROM ottoq_dr_calls WHERE dr_call_id = p_dr_call_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF d.cleared_at IS NOT NULL OR d.call_status NOT IN ('active','issued') THEN
    -- clear the mirror
    RETURN ottoq_mirror_grid_event_to_ottoq(d.depot_id, 'demand_response_called', COALESCE(d.cleared_at, d.expires_at, NOW()), NULL,
             jsonb_build_object('dr_call_id', d.dr_call_id), TRUE);
  END IF;
  v_id := ottoq_mirror_grid_event_to_ottoq(d.depot_id, 'demand_response_called', d.issued_at, d.expires_at,
            jsonb_build_object('dr_call_id', d.dr_call_id, 'target_kw', d.required_load_cap_kw,
                               'program', d.program, 'reason', d.reason), FALSE);
  RETURN v_id;
END;
$function$;
-- @@ function public.ottoq_role_rank(p_role text)
CREATE OR REPLACE FUNCTION public.ottoq_role_rank(p_role text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
  SELECT CASE p_role
    WHEN 'command_center_operator' THEN 3
    WHEN 'depot_supervisor'        THEN 2
    WHEN 'depot_tech'              THEN 1
    ELSE 0 END;
$function$;
-- @@ function public.ottoq_l1_override_authorized(p_rule_code text, p_actor_type text, p_actor_id text, p_justification text, p_entity_type text, p_entity_id uuid, p_depot_id uuid, p_fleet_operator_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_l1_override_authorized(p_rule_code text, p_actor_type text, p_actor_id text, p_justification text, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_depot_id uuid DEFAULT NULL::uuid, p_fleet_operator_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_rule ottoq_rules%ROWTYPE;
  v_id   uuid;
  v_who  RECORD;
  v_actor_type text;
  v_actor_id   text;
  v_identity   text;
BEGIN
  SELECT * INTO v_who FROM public.ottoq_caller_identity();

  -- 0198. Who is asking, decided by the server.
  IF v_who.trust = 'anonymous' THEN
    RAISE EXCEPTION 'OTTOQ_OVERRIDE_UNAUTHENTICATED: an anonymous caller cannot authorize an override'
      USING ERRCODE = '42501';
  ELSIF v_who.trust = 'system' THEN
    -- A trusted system caller (cron, migration, edge function) names the
    -- human it is acting for. That is recorded as system-declared.
    v_actor_type := p_actor_type;
    v_actor_id   := p_actor_id;
    v_identity   := 'system:' || COALESCE(v_who.jwt_role, 'db:' || v_who.db_session_user);
  ELSE
    -- An operator's rank is looked up, never declared.
    v_actor_type := public.ottoq_staff_rule_role(v_who.auth_uid);
    IF v_actor_type IS NULL THEN
      RAISE EXCEPTION 'OTTOQ_OVERRIDE_NO_STAFF_IDENTITY: authenticated user % is not active staff with override authority', v_who.auth_uid
        USING ERRCODE = 'P0001';
    END IF;
    v_actor_id := v_who.auth_uid::text;
    v_identity := 'staff_users';
  END IF;

  SELECT * INTO v_rule FROM ottoq_rules
   WHERE rule_code = p_rule_code AND status IN ('active','shadow')
   ORDER BY version DESC LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OTTOQ_OVERRIDE_UNKNOWN_RULE: %', p_rule_code USING ERRCODE = 'P0001';
  END IF;

  -- 1. the rule must be overridable at all
  IF NOT COALESCE(v_rule.override_allowed, FALSE) THEN
    RAISE EXCEPTION 'OTTOQ_OVERRIDE_FORBIDDEN: rule % is not overridable', p_rule_code USING ERRCODE = 'P0001';
  END IF;

  -- 2. the actor's role must meet/exceed the rule's required min role
  IF ottoq_role_rank(v_actor_type) < ottoq_role_rank(COALESCE(v_rule.override_min_role,'command_center_operator')) THEN
    RAISE EXCEPTION 'OTTOQ_OVERRIDE_ROLE_INSUFFICIENT: % requires %, got %',
      p_rule_code, COALESCE(v_rule.override_min_role,'command_center_operator'), v_actor_type USING ERRCODE = 'P0001';
  END IF;

  -- 3. justification floor (kept; SM.005 audit-note policy, OD-33)
  IF p_justification IS NULL OR length(trim(p_justification)) < 10 THEN
    RAISE EXCEPTION 'OTTOQ_OVERRIDE_JUSTIFICATION_REQUIRED: >=10 chars' USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO ottoq_rule_overrides
    (rule_code, rule_version, entity_type, entity_id, override_actor_type, override_actor_id,
     approved_by, justification, effective_from, depot_id, fleet_operator_id, payload,
     declared_actor_type, actor_auth_uid, identity_source)
  VALUES
    (p_rule_code, v_rule.version, p_entity_type, p_entity_id, v_actor_type, v_actor_id,
     v_actor_id, p_justification, NOW(), p_depot_id, p_fleet_operator_id,
     jsonb_build_object('authorized_by','ottoq_l1_override_authorized','min_role',v_rule.override_min_role,
                        'identity_source', v_identity),
     p_actor_type, v_who.auth_uid, v_identity)
  RETURNING override_id INTO v_id;
  RETURN v_id;
END;
$function$;
-- @@ function public.ottoq_assert_context_sufficient(p_action_context text, p_context jsonb)
CREATE OR REPLACE FUNCTION public.ottoq_assert_context_sufficient(p_action_context text, p_context jsonb)
 RETURNS TABLE(sufficient boolean, missing_inputs text[])
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_required text[];
  v_missing  text[] := '{}';
  v_key      text;
BEGIN
  -- Per-action required-input sets (the safety-critical inputs each gate needs).
  -- Conservative: if an action_context is unknown here, require depot_id at minimum.
  v_required := CASE p_action_context
    WHEN 'stall_assignment'      THEN ARRAY['depot_id','vehicle_id','stall_id']
    WHEN 'charge_session_start'  THEN ARRAY['depot_id','vehicle_id','stall_id','requested_kw']
    WHEN 'power_increase'        THEN ARRAY['depot_id','charger_id','requested_kw']
    WHEN 'charge_session_throttle' THEN ARRAY['depot_id','charger_id']
    WHEN 'task_start'            THEN ARRAY['depot_id','vehicle_id']
    WHEN 'redeployment'          THEN ARRAY['vehicle_id','fleet_operator_id']
    WHEN 'release'               THEN ARRAY['vehicle_id']
    WHEN 'oem_acceptance'        THEN ARRAY['vehicle_id','fleet_operator_id']
    WHEN 'vehicle_state_change'  THEN ARRAY['from_state','to_state']
    WHEN 'bess_dispatch'         THEN ARRAY['depot_id','bess_id']
    ELSE ARRAY['depot_id']
  END;

  FOREACH v_key IN ARRAY v_required LOOP
    IF NULLIF(p_context ->> v_key, '') IS NULL THEN
      v_missing := array_append(v_missing, v_key);
    END IF;
  END LOOP;

  RETURN QUERY SELECT (cardinality(v_missing) = 0), v_missing;
END;
$function$;
-- @@ function public.ottoq_evaluate_rules_for_action(p_action_context text, p_entity_type text, p_entity_id uuid, p_context jsonb, p_fleet_operator_id uuid, p_depot_id uuid, p_triggered_by_event_id uuid, p_override_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_evaluate_rules_for_action(p_action_context text, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_context jsonb DEFAULT '{}'::jsonb, p_fleet_operator_id uuid DEFAULT NULL::uuid, p_depot_id uuid DEFAULT NULL::uuid, p_triggered_by_event_id uuid DEFAULT NULL::uuid, p_override_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(rule_code text, passed boolean, reason text, enforcement_taken text, evaluation_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_rc     TEXT;
  v_result RECORD;
BEGIN
  FOR v_rc IN
    SELECT r.rule_code FROM ottoq_rules r
     WHERE r.status IN ('active','shadow')
       AND p_action_context = ANY(r.applies_to_actions)
     ORDER BY CASE r.severity
                WHEN 'safety_critical' THEN 1 WHEN 'critical' THEN 2
                WHEN 'error' THEN 3 WHEN 'warning' THEN 4 WHEN 'info' THEN 5 ELSE 6 END,
              r.rule_code
  LOOP
    SELECT * INTO v_result FROM ottoq_evaluate_rule(
      p_rule_code             := v_rc,
      p_entity_type           := p_entity_type,
      p_entity_id             := p_entity_id,
      p_context               := p_context,
      p_action_context        := p_action_context,
      p_fleet_operator_id     := p_fleet_operator_id,
      p_depot_id              := p_depot_id,
      p_triggered_by_event_id := p_triggered_by_event_id,
      p_override_id           := p_override_id        -- WIRE-5: forward
    );
    rule_code         := v_rc;
    passed            := v_result.passed;
    reason            := v_result.reason;
    enforcement_taken := v_result.enforcement_taken;
    evaluation_id     := v_result.evaluation_id;
    RETURN NEXT;
  END LOOP;
END;
$function$;
-- @@ function twin.ottoq_sim_materialize_schedule(p_sim_run_id uuid)
CREATE OR REPLACE FUNCTION twin.ottoq_sim_materialize_schedule(p_sim_run_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_depot   UUID;
  v_clock   TIMESTAMPTZ;
  v_day     DATE;
  v_vehicle RECORD;
  v_sched   UUID;
  v_count   INTEGER := 0;
  v_svc_def UUID;
  v_wash_def UUID;
BEGIN
  SELECT depot_id, sim_clock_current INTO v_depot, v_clock FROM ottoq_sim_runs WHERE sim_run_id = p_sim_run_id;
  IF v_depot IS NULL THEN RETURN 0; END IF;
  v_day := v_clock::date;

  SELECT id INTO v_svc_def  FROM service_definitions WHERE code = 'inspection'    LIMIT 1;
  SELECT id INTO v_wash_def FROM service_definitions WHERE code = 'exterior_wash' LIMIT 1;

  FOR v_vehicle IN
    SELECT v.id, v.fleet_operator_id, v.current_state, v.config->>'svc_step' AS svc_step
      FROM vehicles v
     WHERE v.home_depot_id = v_depot AND v.category = 'autonomous'
       AND v.current_state IN ('in_wash_bay','in_detail_bay','in_service_bay','service_complete_holding',
                               'staged_awaiting_service','staged_for_departure')
     ORDER BY v.id   /* 0054: run-stable cursor order */
  LOOP
    -- ensure a vehicle_schedules row for (vehicle, day)
    SELECT id INTO v_sched FROM vehicle_schedules
     WHERE vehicle_id = v_vehicle.id AND depot_id = v_depot AND scheduled_date = v_day LIMIT 1;
    IF v_sched IS NULL THEN
      INSERT INTO vehicle_schedules (vehicle_id, depot_id, scheduled_date, arrival_time, status, planned_services)
      VALUES (v_vehicle.id, v_depot, v_day, v_clock, 'in_progress',
              jsonb_build_array('exterior_wash','inspection'))
      RETURNING id INTO v_sched;
    END IF;

    -- WASH task: completed once the vehicle is past the wash bay
    INSERT INTO schedule_tasks (vehicle_schedule_id, schedule_id, vehicle_id, depot_id, service_definition_id,
        service_code, sequence_order, scheduled_start, scheduled_end, status,
        actual_end)
    SELECT v_sched, v_sched, v_vehicle.id, v_depot, v_wash_def, 'exterior_wash', 1, v_clock, v_clock,
        (CASE WHEN v_vehicle.current_state IN ('in_wash_bay','in_detail_bay') THEN 'in_progress' ELSE 'completed' END)::task_status,
        (CASE WHEN v_vehicle.current_state IN ('in_wash_bay','in_detail_bay') THEN NULL ELSE v_clock END)
    WHERE NOT EXISTS (SELECT 1 FROM schedule_tasks t WHERE t.vehicle_schedule_id = v_sched AND t.service_code = 'exterior_wash');

    -- SERVICE/INSPECTION task: completed once past the service bay
    INSERT INTO schedule_tasks (vehicle_schedule_id, schedule_id, vehicle_id, depot_id, service_definition_id,
        service_code, sequence_order, scheduled_start, scheduled_end, status, actual_end)
    SELECT v_sched, v_sched, v_vehicle.id, v_depot, v_svc_def, 'inspection', 2, v_clock, v_clock,
        (CASE WHEN v_vehicle.current_state IN ('staged_for_departure','service_complete_holding') OR v_vehicle.svc_step IN ('need_deploy','ready')
              THEN 'completed' WHEN v_vehicle.current_state = 'in_service_bay' THEN 'in_progress' ELSE 'pending' END)::task_status,
        (CASE WHEN v_vehicle.current_state IN ('staged_for_departure','service_complete_holding') OR v_vehicle.svc_step IN ('need_deploy','ready')
              THEN v_clock ELSE NULL END)
    WHERE NOT EXISTS (SELECT 1 FROM schedule_tasks t WHERE t.vehicle_schedule_id = v_sched AND t.service_code = 'inspection');

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$function$;
-- @@ function public.ottoq_apply_bess_setpoint(p_bess_id uuid, p_target_kw numeric, p_max_ramp_kw numeric, p_now timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ottoq_apply_bess_setpoint(p_bess_id uuid, p_target_kw numeric, p_max_ramp_kw numeric DEFAULT 250, p_now timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(applied_kw numeric, direction text, clamped boolean, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_bess  ottoq_bess_units%ROWTYPE;
  v_cur   numeric;
  v_want  numeric := p_target_kw;
  v_cap   numeric;
  v_clamped boolean := false;
  v_reason text := 'ok';
  v_dir   text;
BEGIN
  SELECT * INTO v_bess FROM ottoq_bess_units WHERE bess_id = p_bess_id;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 0::numeric, 'idle'::text, true, 'bess_not_found'; RETURN;
  END IF;
  v_cur := COALESCE(v_bess.current_power_kw, 0);

  -- 1. power clamp to the unit rating (charge +max_charge_kw, discharge -max_discharge_kw)
  IF v_want > 0 THEN
    v_cap := COALESCE(v_bess.max_charge_kw, 0);
    IF v_want > v_cap THEN v_want := v_cap; v_clamped := true; v_reason := 'clamped_to_max_charge'; END IF;
  ELSIF v_want < 0 THEN
    v_cap := COALESCE(v_bess.max_discharge_kw, 0);
    IF abs(v_want) > v_cap THEN v_want := -v_cap; v_clamped := true; v_reason := 'clamped_to_max_discharge'; END IF;
  END IF;

  -- 2. dwell guard: a sign flip (charge<->discharge) must pass through ~0 first.
  --    If current and target have opposite sign and current is non-trivial, force to 0
  --    (standby) this step — the next step can ramp into the new direction.
  IF sign(v_want) <> 0 AND sign(v_cur) <> 0 AND sign(v_want) <> sign(v_cur) AND abs(v_cur) > 5 THEN
    v_want := 0; v_clamped := true; v_reason := 'dwell_through_standby';
  END IF;

  -- 3. ramp limit vs current power
  IF abs(v_want - v_cur) > p_max_ramp_kw THEN
    v_want := v_cur + sign(v_want - v_cur) * p_max_ramp_kw;
    v_clamped := true;
    v_reason := CASE WHEN v_reason='ok' THEN 'ramp_limited' ELSE v_reason||'+ramp_limited' END;
  END IF;

  v_dir := CASE WHEN v_want > 0.5 THEN 'charge' WHEN v_want < -0.5 THEN 'discharge' ELSE 'standby' END;
  RETURN QUERY SELECT round(v_want,2), v_dir, v_clamped, v_reason;
END;
$function$;
-- @@ function public.ottoq_reserve_stall(p_stall_id uuid, p_vehicle_id uuid, p_now timestamp with time zone, p_ttl_seconds integer)
CREATE OR REPLACE FUNCTION public.ottoq_reserve_stall(p_stall_id uuid, p_vehicle_id uuid, p_now timestamp with time zone, p_ttl_seconds integer DEFAULT 600)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE v_ok boolean;
BEGIN
  -- atomic: reserve only if free (no current vehicle, and no live reservation by another vehicle)
  UPDATE stalls
     SET reserved_by = p_vehicle_id, reserved_at = p_now,
         reservation_expires_at = p_now + (p_ttl_seconds || ' seconds')::interval
   WHERE id = p_stall_id
     AND current_vehicle_id IS NULL
     AND (reserved_by IS NULL OR reserved_by = p_vehicle_id
          OR reservation_expires_at IS NULL OR reservation_expires_at <= p_now)
  RETURNING true INTO v_ok;
  RETURN COALESCE(v_ok, false);
END;
$function$;
-- @@ function ottoq.ottoq_release_stall_reservation(p_stall_id uuid, p_vehicle_id uuid)
CREATE OR REPLACE FUNCTION ottoq.ottoq_release_stall_reservation(p_stall_id uuid, p_vehicle_id uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
  UPDATE stalls SET reserved_by = NULL, reserved_at = NULL, reservation_expires_at = NULL
   WHERE id = p_stall_id AND (reserved_by = p_vehicle_id OR reserved_by IS NULL);
$function$;
-- @@ function public.ottoq_tick_claimed_kw(p_sim_run_id uuid, p_tick_seq bigint, p_resource text)
CREATE OR REPLACE FUNCTION public.ottoq_tick_claimed_kw(p_sim_run_id uuid, p_tick_seq bigint, p_resource text DEFAULT 'grid_kw'::text)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
  SELECT COALESCE(SUM(amount_kw), 0) FROM ottoq_tick_reservations
   WHERE sim_run_id = p_sim_run_id AND tick_seq = p_tick_seq AND resource = p_resource;
$function$;
-- @@ function public.ottoq_claim_tick_kw(p_sim_run_id uuid, p_tick_seq bigint, p_depot_id uuid, p_amount_kw numeric, p_entity_id uuid, p_resource text)
CREATE OR REPLACE FUNCTION public.ottoq_claim_tick_kw(p_sim_run_id uuid, p_tick_seq bigint, p_depot_id uuid, p_amount_kw numeric, p_entity_id uuid DEFAULT NULL::uuid, p_resource text DEFAULT 'grid_kw'::text)
 RETURNS uuid
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
  INSERT INTO ottoq_tick_reservations (sim_run_id, tick_seq, depot_id, resource, entity_id, amount_kw)
  VALUES (p_sim_run_id, p_tick_seq, p_depot_id, p_resource, p_entity_id, p_amount_kw)
  RETURNING reservation_id;
$function$;
-- @@ function public.ottoq_build_decision_context(p_action_context text, p_entity_type text, p_entity_id uuid, p_depot_id uuid, p_now timestamp with time zone)
CREATE OR REPLACE FUNCTION public.ottoq_build_decision_context(p_action_context text, p_entity_type text, p_entity_id uuid, p_depot_id uuid, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_ctx jsonb := jsonb_build_object('depot_id', p_depot_id, 'now_ts', p_now, 'action', p_action_context);
  v_veh RECORD;
BEGIN
  IF p_entity_type = 'vehicle' AND p_entity_id IS NOT NULL THEN
    SELECT current_soc, current_state, fleet_operator_id, inlet_type INTO v_veh FROM vehicles WHERE id = p_entity_id;
    v_ctx := v_ctx || jsonb_build_object('vehicle_id', p_entity_id, 'current_soc', v_veh.current_soc,
              'vehicle_state', v_veh.current_state, 'fleet_operator_id', v_veh.fleet_operator_id, 'inlet_type', v_veh.inlet_type);
  END IF;
  RETURN v_ctx;
END;
$function$;
-- @@ function public.ottoq_l2_propose_stall_assignment(p_vehicle_id uuid, p_depot_id uuid, p_context jsonb)
CREATE OR REPLACE FUNCTION public.ottoq_l2_propose_stall_assignment(p_vehicle_id uuid, p_depot_id uuid, p_context jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_soc   numeric := COALESCE((p_context->>'current_soc')::numeric, 50);
  v_now   timestamptz := COALESCE(NULLIF(p_context->>'now_ts','')::timestamptz, now());
  v_inlet text; v_inlet_kw numeric; v_want_type text; v_urgency text;
  v_stall RECORD; v_eff_kw numeric; v_headroom_kw numeric;
  v_run uuid; v_mode int; v_prefer_fit boolean;
  v_due timestamptz; v_target_soc numeric; v_batt_kwh numeric;
  v_fit_kw numeric; v_hours_needed numeric; v_hours_available numeric;
  v_want_kw numeric; v_ceiling numeric; v_wait_reason text := NULL; v_seat int; /* 0261 */
  v_veh_target numeric;   /* 0446 */
  v_kind_match int; v_n_dcfc int; v_n_want int;   /* 0548 (G277) */
BEGIN
  SELECT r0.sim_run_id INTO v_run FROM public.ottoq_sim_runs r0
   WHERE r0.status='running' AND r0.depot_id=p_depot_id ORDER BY r0.started_at DESC LIMIT 1;
  /* 0261: a non-zero proposer seat owns the in-tick fallback too, so a baseline arm
     is the baseline all the way down. Seat 0 is the text below, untouched. */
  v_seat := COALESCE(public.ottoq_policy_get(v_run, 'proposer_seat', 0), 0)::int;
  IF v_seat <> 0 THEN
    RETURN public.ottoq_l2_propose_stall_seat(p_vehicle_id, p_depot_id, p_context, v_seat);
  END IF;

  /* 0159: the visit need is where the asset states its deadline and target. */
  SELECT vn.urgency, vn.dispatch_due_at, vn.target_soc INTO v_urgency, v_due, v_target_soc
    FROM ottoq_visit_needs vn
   WHERE vn.vehicle_id = p_vehicle_id AND vn.status IN ('open','in_progress')
     AND COALESCE(vn.sim_run_id,'00000000-0000-0000-0000-000000000000'::uuid)
       = COALESCE(v_run,'00000000-0000-0000-0000-000000000000'::uuid)   /* 0124 */
   ORDER BY vn.created_at DESC LIMIT 1;
  v_want_type := CASE WHEN v_soc < 45 OR v_urgency = 'immediate_dispatch' THEN 'dcfc' ELSE 'l2' END;
  /* 0614: a live agent charge order that names this car for dcfc or l2 sets the kind it wants. An immediate dispatch
     keeps the fast charger the rule gives it, and 'either' leaves the rule's answer. Only the preference moves: every
     candidate gate below still applies, and a free charger of the other kind is still taken when it is the only one. */
  IF p_context ? 'agent_charge_order' AND COALESCE(v_urgency, '') <> 'immediate_dispatch'
     AND (p_context -> 'agent_charge_order' ->> 'kind') IN ('dcfc', 'l2') THEN
    v_want_type := p_context -> 'agent_charge_order' ->> 'kind';
  END IF;

  SELECT inlet_type, inlet_max_kw, battery_capacity_kwh, target_soc INTO v_inlet, v_inlet_kw, v_batt_kwh, v_veh_target
    FROM vehicles WHERE id = p_vehicle_id;

  /* 0156: headroom by EN.001's own arithmetic; v_ceiling is the absolute cap. */
  SELECT LEAST(d.service_max_kw, d.dcfc_max_concurrent_kw * (1 - COALESCE(d.dcfc_safety_margin_pct,10.0)/100.0)),
         LEAST(d.service_max_kw, d.dcfc_max_concurrent_kw * (1 - COALESCE(d.dcfc_safety_margin_pct,10.0)/100.0))
         - COALESCE(public.ottoq_depot_current_demand_kw(p_depot_id, v_now), 0)
    INTO v_ceiling, v_headroom_kw
    FROM depots d WHERE d.id = p_depot_id;
  v_headroom_kw := COALESCE(NULLIF(p_context->>'headroom_kw','')::numeric, v_headroom_kw);

  v_mode := public.ottoq_policy_get(v_run, 'charge_downgrade_policy', 1)::int;
  IF v_mode = 0 THEN
    v_prefer_fit := false; v_wait_reason := 'policy_wait_for_wanted';
  ELSIF v_mode = 2 THEN
    v_prefer_fit := true;
    SELECT max(LEAST(COALESCE(s.connector_max_kw,50), COALESCE(v_inlet_kw,250))
               * CASE WHEN COALESCE(s.connector_max_kw,50) <= 50 THEN 1.0
                      WHEN v_soc < 55 THEN 0.85 WHEN v_soc < 75 THEN 0.55 ELSE 0.30 END)
      INTO v_fit_kw FROM stalls s JOIN ottoq_ocpp_chargers c ON c.charger_id=s.ocpp_charger_id
     WHERE s.depot_id=p_depot_id AND s.stall_type IN ('dcfc','l2') AND s.current_vehicle_id IS NULL
       AND c.station_state='Available'
       AND (v_headroom_kw IS NULL OR (LEAST(COALESCE(s.connector_max_kw,50), COALESCE(v_inlet_kw,250))
               * CASE WHEN COALESCE(s.connector_max_kw,50) <= 50 THEN 1.0
                      WHEN v_soc < 55 THEN 0.85 WHEN v_soc < 75 THEN 0.55 ELSE 0.30 END) <= v_headroom_kw);
    SELECT max(LEAST(COALESCE(s.connector_max_kw,50), COALESCE(v_inlet_kw,250))
               * CASE WHEN COALESCE(s.connector_max_kw,50) <= 50 THEN 1.0
                      WHEN v_soc < 55 THEN 0.85 WHEN v_soc < 75 THEN 0.55 ELSE 0.30 END)
      INTO v_want_kw FROM stalls s WHERE s.depot_id=p_depot_id AND s.stall_type::text = v_want_type;
    IF v_due IS NOT NULL AND v_fit_kw IS NOT NULL AND v_fit_kw > 0 AND v_batt_kwh IS NOT NULL THEN
      v_hours_needed := (v_batt_kwh * GREATEST(COALESCE(v_target_soc, public.ottoq_default_target_soc()) - v_soc, 0) / 100.0) / v_fit_kw;
      v_hours_available := EXTRACT(epoch FROM (v_due - v_now)) / 3600.0;
      /* Hold ONLY if the slow point misses the deadline AND the fast point is
         physically grantable here - without the guard this reintroduces 0156. */
      IF v_hours_needed > v_hours_available
         AND v_want_kw IS NOT NULL AND (v_ceiling IS NULL OR v_want_kw <= v_ceiling) THEN
        v_prefer_fit := false; v_wait_reason := 'slow_point_misses_due_at';
      END IF;
    END IF;
  ELSE
    v_prefer_fit := true;
  END IF;

  WITH cand AS (
    SELECT s.id, s.stall_type, s.connector_max_kw, s.relative_y, s.reserved_by,
           (LEAST(COALESCE(s.connector_max_kw,50), COALESCE(v_inlet_kw,250))
            * CASE WHEN COALESCE(s.connector_max_kw,50) <= 50 THEN 1.0
                   WHEN v_soc < 55 THEN 0.85 WHEN v_soc < 75 THEN 0.55 ELSE 0.30 END) AS eff_kw
      FROM stalls s JOIN ottoq_ocpp_chargers c ON c.charger_id = s.ocpp_charger_id
     WHERE s.depot_id = p_depot_id AND s.stall_type IN ('dcfc','l2') AND s.current_vehicle_id IS NULL
       AND (s.reserved_by IS NULL OR s.reserved_by = p_vehicle_id OR s.reservation_expires_at <= v_now)
       AND c.station_state = 'Available' AND c.last_heartbeat_at >= v_now - INTERVAL '90 seconds'
       /* 0446 (G179): the session stops at LEAST(target, this stall type's cap now) - 0.5, so a stall that
          would stop the session before it starts is not a candidate. Without this, a vehicle at the DCFC
          daytime cap kept its DCFC reservation and looped on it, delivering nothing. */
       AND v_soc < LEAST(COALESCE(v_veh_target, public.ottoq_default_target_soc()),
                         public.ottoq_target_soc_cap(s.stall_type::text, v_now)) - 0.5
       /* 0494 (G226): the calendar is a gate too. The pick asked only the pointer, so a charger promised to an
          arriving car looked free, and each car in the charge step's cursor was offered it and refused at the
          emission gate in turn (22 in one tick on busy_day/171717/12 under 0493). A candidate is now a charger the
          gate accepts for this car at this moment, the call ottoq_emit_vehicle_command makes next (0467 did the
          same for the gate intake). */
       AND COALESCE((ottoq.ottoq_validate_assignment(p_vehicle_id, s.id, 'begin_charge', v_now, v_run)->>'ok')::boolean, false)
       AND (v_inlet IS NULL OR s.connector_type = v_inlet
         OR (s.connector_type = 'Multi' AND v_inlet = ANY(COALESCE(s.supported_inlet_types, ARRAY[]::text[])))
         OR (s.connector_type = 'NACS'  AND v_inlet IN ('NACS','Tesla_Proprietary'))))
  SELECT id, stall_type, connector_max_kw, eff_kw,
         (v_headroom_kw IS NULL OR eff_kw <= v_headroom_kw) AS fits
    INTO v_stall FROM cand
   /* v_prefer_fit false makes the first key constant, collapsing the ordering
      to the pre-0156 one exactly. */
   ORDER BY (v_prefer_fit AND (v_headroom_kw IS NULL OR eff_kw <= v_headroom_kw)) DESC,
            COALESCE(reserved_by = p_vehicle_id, false) DESC,
            (stall_type::text = v_want_type) DESC, relative_y ASC NULLS LAST, id
   LIMIT 1;

  IF v_stall.id IS NULL THEN RETURN jsonb_build_object('abstain', true, 'reason', 'no_compatible_available_stall'); END IF;

  /* 0548 (G277, research wing): at charge_kind_match = 1 a car that wants an L2 does not take a free fast charger
     while the cars waiting that want one are at least as many as the free fast chargers. It waits for an L2 (an
     abstention, as when no charger is free), and the fast charger goes to a car that wants it later in this tick.
     A spare fast charger is still taken, so no charger idles for the rule. At 0 (the default) nothing below changes. */
  v_kind_match := COALESCE(public.ottoq_policy_get(v_run, 'charge_kind_match', 0), 0)::int;
  IF v_kind_match = 1 AND v_want_type = 'l2' AND v_stall.stall_type::text = 'dcfc'
     AND (SELECT s0.reserved_by FROM stalls s0 WHERE s0.id = v_stall.id) IS DISTINCT FROM p_vehicle_id THEN
    SELECT count(*) INTO v_n_dcfc
      FROM stalls s JOIN ottoq_ocpp_chargers c ON c.charger_id = s.ocpp_charger_id
     WHERE s.depot_id = p_depot_id AND s.stall_type::text = 'dcfc' AND s.current_vehicle_id IS NULL
       AND (s.reserved_by IS NULL OR s.reserved_by = p_vehicle_id OR s.reservation_expires_at <= v_now)
       AND c.station_state = 'Available' AND c.last_heartbeat_at >= v_now - INTERVAL '90 seconds';
    SELECT count(*) INTO v_n_want
      FROM vehicles w
     WHERE w.home_depot_id = p_depot_id AND w.category = 'autonomous' AND w.id <> p_vehicle_id
       AND w.current_state IN ('arrived_at_gate', 'staged_awaiting_service')
       AND w.current_soc < COALESCE((SELECT vn.target_soc FROM ottoq_visit_needs vn
              WHERE vn.vehicle_id = w.id AND vn.status IN ('open','in_progress')
                AND COALESCE(vn.sim_run_id,'00000000-0000-0000-0000-000000000000'::uuid)
                  = COALESCE(v_run,'00000000-0000-0000-0000-000000000000'::uuid)
              ORDER BY vn.created_at DESC, vn.visit_key DESC LIMIT 1), public.ottoq_default_target_soc()) - 1
       AND (w.current_soc < 45
            OR COALESCE((SELECT vn.urgency = 'immediate_dispatch' FROM ottoq_visit_needs vn
                  WHERE vn.vehicle_id = w.id AND vn.status IN ('open','in_progress')
                    AND COALESCE(vn.sim_run_id,'00000000-0000-0000-0000-000000000000'::uuid)
                      = COALESCE(v_run,'00000000-0000-0000-0000-000000000000'::uuid)
                  ORDER BY vn.created_at DESC, vn.visit_key DESC LIMIT 1), false));
    IF v_n_want > 0 AND v_n_want >= v_n_dcfc THEN
      RETURN jsonb_build_object('abstain', true, 'reason', 'fast_charger_kept_for_a_car_that_wants_one',
        'rationale', jsonb_build_object('soc', v_soc, 'wanted_type', v_want_type, 'urgency', v_urgency,
                                        'kept_stall_id', v_stall.id, 'free_fast_chargers', v_n_dcfc,
                                        'cars_wanting_one', v_n_want, 'charge_kind_match', v_kind_match));
    END IF;
  END IF;
  v_eff_kw := v_stall.eff_kw;
  RETURN jsonb_build_object('abstain', false, 'resolved_action_context', 'stall_assignment', 'verb', 'assign_stall',
    'vehicle_id', p_vehicle_id, 'stall_id', v_stall.id, 'stall_type', v_stall.stall_type,
    'requested_kw', ROUND(v_eff_kw::numeric, 1),
    'rationale', jsonb_build_object('soc', v_soc, 'wanted_type', v_want_type, 'inlet', v_inlet,
      'urgency', v_urgency, 'eff_draw_kw', ROUND(v_eff_kw::numeric, 1),
      'headroom_kw', ROUND(v_headroom_kw::numeric, 1), 'fits_headroom', v_stall.fits,
      'downgrade_policy', v_mode, 'held_for_wanted', COALESCE(v_wait_reason,'-'),
      'power_downgrade', (v_stall.stall_type::text <> v_want_type AND v_stall.fits AND v_prefer_fit)));
END;
$function$;
-- @@ function public.ottoq_l1_safe_default_stall(p_vehicle_id uuid, p_context jsonb)
CREATE OR REPLACE FUNCTION public.ottoq_l1_safe_default_stall(p_vehicle_id uuid, p_context jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
  SELECT jsonb_build_object('verb','hold_at_gate','vehicle_id',p_vehicle_id,'reason','shield_blocked_proposal','requested_kw',0);
$function$;
-- @@ function public.ottoq_decide_tick(p_sim_run_id uuid)
CREATE OR REPLACE FUNCTION public.ottoq_decide_tick(p_sim_run_id uuid)
 RETURNS public.ottoq_decide_tick_result
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_depot uuid; v_clock timestamptz; v_tick bigint; v_snapshot_id uuid;
  v_seat int; /* 0261 */
  v_ao_order jsonb := '{}'::jsonb; v_ao_on boolean := false; v_ao_pin numeric := 90; v_ao_mode text := 'none';  /* 0614 */
  v_ao_kpos jsonb := '{}'::jsonb; v_ao_order_id bigint; v_ao_wait numeric;                                       /* 0614 */
  v_ok jsonb := '{}'::jsonb;                                                                                     /* 0642 */
  v_open_shop boolean := false;                                                                     /* 0782 (G502) */
  v_req RECORD; v_ctx jsonb; v_proposal jsonb; v_action jsonb;
  v_blocks int; v_block_codes text[]; v_rule_rows jsonb; v_disarm jsonb;
  v_outcome text; v_over boolean; v_safe boolean;
  v_t0 timestamptz; v_prop_ms int; v_shield_ms int; v_enact_ms int;
  v_built int := 0; v_enacted int := 0; v_overc int := 0; v_deferred int := 0; v_errored int := 0; v_disn int := 0;
  v_bess RECORD; v_energy RECORD;
  v_total_fleet int; v_curr_deployed int; v_target_pct numeric; v_demand_target int; v_deploy_budget int;
  v_charge_cap_kw numeric; v_ev_committed_kw numeric := 0; v_stage_stall uuid;
  v_charge_leg RECORD; v_bkg uuid;
  v_cmd_id uuid; v_cmd_status text; v_cmd_code text; v_cmd_detail text; /* 0493 */
  v_stage_leg_id uuid; v_stage_until timestamptz;
  v_bay_leg_id uuid; v_bay_leg_type text; v_bay_dur interval; v_bay_until timestamptz;
  v_bay_bkg uuid; v_bay_purpose text;
  -- P1 (needs-card space routing)
  v_need RECORD; v_space jsonb;
  v_wash_phys int; v_svc_phys int; v_wash_open int; v_svc_open int;
  -- 0003 (bay work recovery): resumption budget per lane per tick.
  v_res_share numeric; v_wash_res_cap int; v_svc_res_cap int;
  v_wash_res_used int := 0; v_svc_res_used int := 0;
BEGIN
  SELECT depot_id, sim_clock_current, tick_count INTO v_depot, v_clock, v_tick
    FROM ottoq_sim_runs WHERE sim_run_id = p_sim_run_id;
  IF v_depot IS NULL THEN RETURN ROW(0,NULL,0,0,0,0,0,0,0)::ottoq_decide_tick_result; END IF;
  v_snapshot_id := ottoq_capture_decision_snapshot(p_sim_run_id, v_tick, v_depot, v_clock);
  v_seat := COALESCE(public.ottoq_policy_get(p_sim_run_id, 'proposer_seat', 0), 0)::int; /* 0261 */

  -- P1 BAY RELEASE. twin.ottoq_sim_advance_service_flow STEP 1 moves a vehicle OUT of a bay
  -- back to staged_awaiting_service and never clears stalls.current_vehicle_id or
  -- vehicles.current_stall_id; nothing else clears a bay either. Physical bay occupancy is
  -- switched ON below, so without this sweep the 3 wash / 2 service bays would fill and
  -- NEVER free - a permanent depot deadlock after five vehicles. Release-only: this call can
  -- free a space but can never claim one, and it never touches dcfc/l2 stalls.
  -- BOOKING LIFECYCLE. Promote held -> active for every booking whose vehicle is now
  -- physically standing on its stall, BEFORE the release sweep below. This is what gives
  -- 'active' a meaning, and what lets the sweep close a REAL occupancy as 'done' (with its
  -- window truncated to the true end) instead of lumping it in with forward reservations
  -- that nobody ever used. Release-only and non-fatal, like the sweep itself.
  PERFORM ottoq.ottoq_activate_present_bookings(p_sim_run_id, v_clock);

  -- HONOUR OR RE-PLAN, NEVER LET IT ROT (2026-08-02). Runs BEFORE the release sweep on
  -- purpose: a bay reservation whose vehicle is still bolted to a charger is slid forward
  -- to when the car can actually be there, so the sweep below never sees it as a no-show.
  -- Bounded defers + explicit give-up: it can free a window or move one, never claim one.
  PERFORM ottoq.ottoq_reconcile_bay_reservations(p_sim_run_id, v_depot, v_clock);

  PERFORM ottoq.ottoq_release_vacated_spaces(p_sim_run_id, v_depot, v_clock);

  -- NO BAY ENTRY WITHOUT A BOOKING. twin.ottoq_sim_advance_service_flow STEP 2 admits
  -- vehicles into wash/detail/service bays on STAFF capacity and claims no stall at all,
  -- so those occupancies were invisible to the forward calendar -- which is how 22
  -- vehicles came to be "in" 2 physical service bays. OTTO-Q reconciles here: book what
  -- is physically there, in place, against a real stall. Release-only for chargers,
  -- non-fatal, and it never moves a vehicle that is already standing in a real bay.
  PERFORM ottoq.ottoq_bind_unbooked_bay_occupants(p_sim_run_id, v_depot, v_clock);

  SELECT lmp_usd_per_mwh INTO v_energy FROM ottoq_grid_snapshots WHERE sim_run_id=p_sim_run_id ORDER BY sim_clock_at DESC LIMIT 1;

  -- (1) ENERGY / BESS
  FOR v_bess IN SELECT bess_id, current_soc_pct FROM ottoq_bess_units WHERE depot_id = v_depot ORDER BY bess_id   /* 0054: run-stable cursor order */ LOOP
    v_built := v_built + 1; v_t0 := clock_timestamp(); v_over:=false; v_safe:=false; v_block_codes:='{}'; v_disarm:='[]'::jsonb;
    v_ctx := jsonb_build_object('depot_id',v_depot,'now_ts',v_clock,'sim_run_id',p_sim_run_id,  /* 0136 */'bess_id',v_bess.bess_id,
              'bess_soc_pct',v_bess.current_soc_pct,'lmp_usd_mwh',COALESCE(v_energy.lmp_usd_per_mwh,40));
    v_proposal := ottoq_l2_propose_bess(v_bess.bess_id, v_depot, v_ctx);
    v_prop_ms := EXTRACT(MILLISECOND FROM (clock_timestamp()-v_t0))::int;
    IF (v_proposal->>'abstain')::boolean THEN
      v_deferred := v_deferred+1;
      INSERT INTO ottoq_decisions (sim_run_id,tick_seq,sim_clock,depot_id,snapshot_id,action_context,entity_type,entity_id,context_frame,proposed_action,enacted_action,outcome_status,propose_latency_ms,total_latency_ms)
      VALUES (p_sim_run_id,v_tick,v_clock,v_depot,v_snapshot_id,'bess_dispatch','bess',v_bess.bess_id,v_ctx,v_proposal,'{}'::jsonb,'noop_no_candidate',v_prop_ms,v_prop_ms);
      CONTINUE;
    END IF;
    v_ctx := v_ctx || jsonb_build_object('requested_kw', v_proposal->>'requested_kw', 'action', v_proposal->>'action');
    v_t0 := clock_timestamp();
    SELECT count(*) FILTER (WHERE would_block), array_agg(rule_code) FILTER (WHERE would_block),
           jsonb_agg(jsonb_build_object('rule_code',rule_code,'passed',passed,'reason',reason,'enforcement_taken',enforcement_taken,'severity',severity))
      INTO v_blocks, v_block_codes, v_rule_rows
      FROM ottoq_shield_probe('bess_dispatch','bess',v_bess.bess_id,v_ctx,NULL,v_depot);
    v_shield_ms := EXTRACT(MILLISECOND FROM (clock_timestamp()-v_t0))::int;
    IF COALESCE(v_blocks,0)>0 THEN v_action:=ottoq_l1_safe_default_bess(v_bess.bess_id,v_ctx); v_safe:=true; v_over:=true; v_outcome:='overridden_to_default'; v_overc:=v_overc+1;
    ELSE v_action:=v_proposal; v_outcome:='enacted'; v_enacted:=v_enacted+1; END IF;
    v_t0 := clock_timestamp();
    IF v_outcome='enacted' THEN PERFORM ottoq_apply_bess_setpoint(v_bess.bess_id, (v_action->>'requested_kw')::numeric, 250, v_clock); END IF;
    v_enact_ms := EXTRACT(MILLISECOND FROM (clock_timestamp()-v_t0))::int;
    INSERT INTO ottoq_decisions (sim_run_id,tick_seq,sim_clock,depot_id,snapshot_id,action_context,resolved_action_context,entity_type,entity_id,context_frame,proposed_action,enacted_action,overridden,override_rule_codes,rule_results,safe_default_taken,outcome_status,propose_latency_ms,shield_latency_ms,enact_latency_ms,total_latency_ms)
    VALUES (p_sim_run_id,v_tick,v_clock,v_depot,v_snapshot_id,'bess_dispatch','bess_dispatch','bess',v_bess.bess_id,v_ctx,v_proposal,v_action,v_over,v_block_codes,COALESCE(v_rule_rows,'[]'::jsonb),v_safe,v_outcome,v_prop_ms,v_shield_ms,v_enact_ms,COALESCE(v_prop_ms,0)+COALESCE(v_shield_ms,0)+COALESCE(v_enact_ms,0));
  END LOOP;

  -- (2) DEPLOY-READINESS
  SELECT COUNT(*) INTO v_total_fleet FROM vehicles WHERE category='autonomous' AND home_depot_id=v_depot;
  SELECT COUNT(*) INTO v_curr_deployed FROM vehicles
    WHERE category='autonomous' AND home_depot_id=v_depot AND current_state IN ('deployed','en_route_to_deployment');
  SELECT COALESCE((s.fleet_overrides->>'target_deployed_fraction')::numeric, 0.55) INTO v_target_pct
    FROM ottoq_sim_runs r LEFT JOIN ottoq_sim_scenarios s ON s.scenario_code = COALESCE(r.scenario_code,'normal_day')
   WHERE r.sim_run_id = p_sim_run_id;
  v_demand_target := FLOOR(v_total_fleet * ottoq_deploy_target_fraction(EXTRACT(HOUR FROM (v_clock AT TIME ZONE 'America/Chicago'))::int, public.ottoq_deploy_peak_fraction(p_sim_run_id) /* 0434: the dispatcher's resolution, not this function's 0.55 */));
  v_deploy_budget := GREATEST(v_demand_target - v_curr_deployed, 0);

  FOR v_req IN
    SELECT v.id AS vehicle_id, v.current_soc, v.fleet_operator_id
      FROM vehicles v WHERE v.home_depot_id=v_depot AND v.category='autonomous'
       AND v.current_state='staged_for_departure'
       AND public.ottoq_departure_clear(v.id, p_sim_run_id, v_clock, true)   /* 0543 (CLAUDE.md rule 9) */
       AND NOT EXISTS (SELECT 1 FROM ottoq_visit_needs vn, jsonb_array_elements(vn.atoms) a
             WHERE vn.vehicle_id = v.id AND (vn.sim_run_id = p_sim_run_id OR vn.sim_run_id IS NULL) AND vn.status IN ('open','in_progress')
               AND ((a->>'svc' = 'software_update' AND COALESCE(a->>'status','pending') = 'in_progress')
                 OR (COALESCE((a->>'must_do')::boolean,false) AND a->>'svc' <> 'readiness_check'
                     AND COALESCE(a->>'status','pending') IN ('pending','in_progress'))))
       AND NOT EXISTS (SELECT 1 FROM ottoq_visit_needs vn2 WHERE vn2.vehicle_id = v.id
             AND vn2.status IN ('open','in_progress') AND COALESCE(vn2.sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE(p_sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) /* 0124 */ AND vn2.urgency = 'overnight_hold'
             AND vn2.dispatch_due_at IS NOT NULL AND vn2.dispatch_due_at > v_clock)
       AND NOT EXISTS (SELECT 1 FROM ottoq_visit_needs vn3, jsonb_array_elements(vn3.atoms) a3
             WHERE vn3.vehicle_id = v.id AND vn3.status IN ('open','in_progress') AND COALESCE(vn3.sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE(p_sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) /* 0124 */
               AND COALESCE((a3->>'requires_tech_greenlight')::boolean,false)
               AND NOT EXISTS (SELECT 1 FROM ottoq_ops_approvals ap
                     WHERE ap.vehicle_id = v.id AND ap.approval_type = 'tech_greenlight'
                       AND ap.status = 'approved' AND ap.created_at >= vn3.created_at))
       AND NOT EXISTS (SELECT 1 FROM ottoq_decisions d
             WHERE d.sim_run_id = p_sim_run_id
               AND d.entity_id = v.id
               AND d.action_context = 'redeployment'
               AND d.outcome_status = 'enacted'
               AND d.sim_clock >= COALESCE(v.last_state_change, '-infinity'::timestamptz))
     ORDER BY v.current_soc DESC, v.id LIMIT GREATEST(v_deploy_budget,0)
  LOOP
    v_built:=v_built+1; v_t0:=clock_timestamp(); v_over:=false; v_safe:=false; v_block_codes:='{}'; v_disarm:='[]'::jsonb;
    v_ctx := ottoq_build_decision_context('redeployment','vehicle',v_req.vehicle_id,v_depot,v_clock);
    -- A1: cuOpt/Nemotron may propose the redeploy; heuristic is the safe fallback.
    v_proposal := COALESCE(
      ottoq_l2_external_proposal(p_sim_run_id, 'redeployment', 'vehicle', v_req.vehicle_id),
      ottoq_l2_propose_deploy(v_req.vehicle_id, v_depot, v_ctx));
    v_prop_ms := EXTRACT(MILLISECOND FROM (clock_timestamp()-v_t0))::int;
    IF (v_proposal->>'abstain')::boolean THEN v_deferred:=v_deferred+1;
      INSERT INTO ottoq_decisions (sim_run_id,tick_seq,sim_clock,depot_id,snapshot_id,action_context,entity_type,entity_id,context_frame,proposed_action,enacted_action,outcome_status,propose_latency_ms,total_latency_ms)
      VALUES (p_sim_run_id,v_tick,v_clock,v_depot,v_snapshot_id,'redeployment','vehicle',v_req.vehicle_id,v_ctx,v_proposal,'{}'::jsonb,'noop_no_candidate',v_prop_ms,v_prop_ms);
      CONTINUE; END IF;
    v_t0:=clock_timestamp();
    SELECT count(*) FILTER (WHERE would_block), array_agg(rule_code) FILTER (WHERE would_block),
           jsonb_agg(jsonb_build_object('rule_code',rule_code,'passed',passed,'reason',reason,'enforcement_taken',enforcement_taken,'severity',severity))
      INTO v_blocks, v_block_codes, v_rule_rows
      FROM ottoq_shield_probe('redeployment','vehicle',v_req.vehicle_id,v_ctx,v_req.fleet_operator_id,v_depot);
    v_shield_ms := EXTRACT(MILLISECOND FROM (clock_timestamp()-v_t0))::int;
    v_t0:=clock_timestamp();
    IF COALESCE(v_blocks,0)>0 THEN v_action:=ottoq_l1_safe_default_deploy(v_req.vehicle_id,v_ctx); v_safe:=true; v_over:=true; v_outcome:='overridden_to_default'; v_overc:=v_overc+1;
    ELSE
      v_action:=v_proposal; v_outcome:='enacted'; v_enacted:=v_enacted+1;
      -- BRAIN/TWIN SEPARATION: OTTO-Q does NOT mutate vehicle state. It emits the
      -- command below; ottoq_sim_dispatch_vehicle (twin) performs the transition
      -- atomically with the dispatch record. Writing 'en_route_to_deployment'
      -- here created a limbo the rate-limited twin could not drain (task #169).
      -- (0075) The 'dispatch' command was a NO-OP: confirm_commands has no 'dispatch' verb and
      -- nothing consumes it. The twin dispatches via ottoq_sim_auto_dispatch_tick, which ranks by
      -- ottoq_brain_deploy_rank (reading THIS decision). Emitting it 965x against 91 real
      -- dispatches corrupted the audit ledger. The decision row below IS the deploy signal.
    END IF;
    v_enact_ms:=EXTRACT(MILLISECOND FROM (clock_timestamp()-v_t0))::int;
    INSERT INTO ottoq_decisions (sim_run_id,tick_seq,sim_clock,depot_id,snapshot_id,action_context,resolved_action_context,entity_type,entity_id,context_frame,proposed_action,enacted_action,overridden,override_rule_codes,rule_results,safe_default_taken,deploy_readiness,outcome_status,propose_latency_ms,shield_latency_ms,enact_latency_ms,total_latency_ms)
    VALUES (p_sim_run_id,v_tick,v_clock,v_depot,v_snapshot_id,'redeployment','redeployment','vehicle',v_req.vehicle_id,v_ctx,v_proposal,v_action,v_over,v_block_codes,COALESCE(v_rule_rows,'[]'::jsonb),v_safe,CASE WHEN v_outcome='enacted' THEN 'ready' ELSE 'held' END,v_outcome,v_prop_ms,v_shield_ms,v_enact_ms,COALESCE(v_prop_ms,0)+COALESCE(v_shield_ms,0)+COALESCE(v_enact_ms,0));
  END LOOP;

  -- P0 (2026-08-03): A REOPENED NEED IS A FIRST-CLASS DEMAND.
  -- ottoq.ottoq_readmit_resumed_visits was unreachable: its emergency_staged /
  -- retrieved_staged pair is produced ONLY by tow retrieval, whose dwell gate compares a
  -- REAL-clock last_state_change (clobbered by the BEFORE UPDATE trigger) against the SIM
  -- clock and is therefore never true. This stage is keyed on the NEED instead, so a
  -- cut-short charge competes for a plug in the SAME tick, through the SAME intake
  -- cursors below, as a fresh arrival. Self-silencing; can never abort the tick.
  PERFORM ottoq.ottoq_readmit_reopened_needs(p_sim_run_id, v_depot, v_clock);

  -- (3) STALL ASSIGNMENT
  -- P2 RIGHT OF FIRST REFUSAL (2026-08-02). Advance the cuOpt deferral
  -- ledger EXACTLY ONCE per decide tick, before the candidate cursor is opened.
  -- roll() step 1 releases every vehicle that a PREVIOUS tick held, so a hold can
  -- never span two consecutive decide ticks; step 2 then consumes this tick's
  -- freshly armed rows. roll() swallows its own errors: if the ledger is broken
  -- the engine simply behaves exactly as it did before this change.
  PERFORM public.ottoq_cuopt_defer_roll(p_sim_run_id, v_tick);
  v_charge_cap_kw := public.ottoq_ev_charge_allowance_kw(p_sim_run_id, v_depot, v_clock);  /* 0132; 0433: the cap is on grid import, so a DR call admits cap - building + solar + sustainable BESS */
  IF v_charge_cap_kw IS NOT NULL THEN
    IF COALESCE(public.ottoq_policy_get(p_sim_run_id, 'site_cap_gate_metered', 0), 0) >= 1 THEN
      /* 0727: a charge under way counts at the power its charger last metered (the field the site meter sums); a car
         not yet metered, at the band estimate below, as before. */
      SELECT COALESCE(SUM(COALESCE((cs.last_meter_value->>'power_kw')::numeric,
               LEAST(COALESCE(st.connector_max_kw,50), COALESCE(vv.inlet_max_kw,250)) * CASE WHEN COALESCE(st.connector_max_kw,50)<=50 THEN 1.0 WHEN COALESCE(vv.current_soc,50)<55 THEN 0.85 WHEN COALESCE(vv.current_soc,50)<75 THEN 0.55 ELSE 0.30 END)),0) INTO v_ev_committed_kw
        FROM vehicles vv JOIN stalls st ON st.id = vv.current_stall_id
        LEFT JOIN ocpp_sessions cs ON cs.stall_id = st.id AND cs.status = 'active' AND cs.vehicle_id = vv.id
       WHERE vv.home_depot_id = v_depot AND vv.current_state IN ('charging_dcfc','charging_l2');
    ELSE
    SELECT COALESCE(SUM(LEAST(COALESCE(st.connector_max_kw,50), COALESCE(vv.inlet_max_kw,250)) * CASE WHEN COALESCE(st.connector_max_kw,50)<=50 THEN 1.0 WHEN COALESCE(vv.current_soc,50)<55 THEN 0.85 WHEN COALESCE(vv.current_soc,50)<75 THEN 0.55 ELSE 0.30 END),0) INTO v_ev_committed_kw
      FROM vehicles vv JOIN stalls st ON st.id = vv.current_stall_id
     WHERE vv.home_depot_id = v_depot AND vv.current_state IN ('charging_dcfc','charging_l2');
    END IF;
  END IF;

  /* 0614: THE AGENT'S CHARGE ORDER, READ ONCE PER TICK. OTTO-Q's seat only, and only when this run's
     agent_charge_order dial is 1 and the agent's latest accepted order is younger than its ttl. Without one every
     variable keeps its default and the cursor's ORDER BY below is the one before 0614, key for key. A failure here is
     swallowed: the tick seats cars in the kernel's own order. */
  IF v_seat = 0 THEN
    BEGIN
      IF COALESCE(public.ottoq_policy_get(p_sim_run_id, 'agent_charge_order', 0), 0) >= 1 THEN
        v_ao_order := COALESCE(public.ottoq_agent_charge_order_live(p_sim_run_id, v_tick), '{}'::jsonb);
        v_ao_on := (v_ao_order <> '{}'::jsonb);
        IF v_ao_on THEN
          v_ao_pin := COALESCE(public.ottoq_policy_get(p_sim_run_id, 'agent_charge_order_pin_wait_min', 90), 90);
          v_ao_mode := COALESCE(public.ottoq_agent_charge_order_mode(p_sim_run_id, v_depot, v_clock), 'none');
          SELECT max((e.value ->> 'order_id')::bigint) INTO v_ao_order_id FROM jsonb_each(v_ao_order) e;
          SELECT COALESCE(jsonb_object_agg(k.vehicle_id::text, k.kernel_pos), '{}'::jsonb) INTO v_ao_kpos
            FROM public.ottoq_charge_queue_kernel_order(p_sim_run_id, v_depot, v_clock) k;
        END IF;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '0614 agent charge order read: % %', SQLSTATE, SQLERRM;
      v_ao_order := '{}'::jsonb; v_ao_on := false; v_ao_mode := 'none'; v_ao_kpos := '{}'::jsonb; v_ao_order_id := NULL;
    END;
  END IF;

  /* 0642 (G384): OTTO-Q's seat's own two keys after the agent's, read once per tick (ottoq_charge_order_keys):
     {car: [floor_key, minutes_key]}. Every other seat, the dials at 0, and a failure here leave it empty, and the
     cursor's ORDER BY is the one before 0642, key for key. */
  IF v_seat = 0 THEN
    BEGIN
      /* 0781 (G501): and, with charge_order_exit_first at 1, each car's exit key, its turn in the bays and its place in
         the line with its owner's exchange made: {car: [floor_key, minutes_key, exit_key, bay_eta_min, exit_rank]}. At
         0 every rank is NULL and each car carries 0642's two keys, as before. */
      SELECT COALESCE(jsonb_object_agg(k.vehicle_id::text,
               CASE WHEN k.exit_rank IS NULL THEN jsonb_build_array(k.floor_key, k.minutes_key)
                    ELSE jsonb_build_array(k.floor_key, k.minutes_key, k.exit_key, k.bay_eta_min, k.exit_rank) END),
               '{}'::jsonb)
        INTO v_ok
        FROM public.ottoq_charge_order_keys(p_sim_run_id, v_depot, v_clock) k
       WHERE k.floor_key IS NOT NULL OR k.minutes_key IS NOT NULL OR k.exit_rank IS NOT NULL;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '0642 charge order keys: % %', SQLSTATE, SQLERRM;
      v_ok := '{}'::jsonb;
    END;
  END IF;

  FOR v_req IN
    SELECT v.id AS vehicle_id, v.current_soc, v.fleet_operator_id, v.config AS ao_config, v.last_state_change AS ao_lsc
      FROM vehicles v WHERE v.home_depot_id=v_depot AND v.category='autonomous'
       -- P2 RIGHT OF FIRST REFUSAL (2026-08-02). Hold this vehicle out of the local
       -- greedy path for EXACTLY ONE decide tick while a cuOpt solve is in flight,
       -- so the optimizer's answer is not pre-empted by the stall it was solving for.
       -- ottoq_cuopt_defer_hold is READ-ONLY and goes FALSE the moment a usable
       -- proposal exists for this vehicle (right of FIRST REFUSAL, not veto) -- the
       -- vehicle then enters the cursor normally and the proposal is ENACTED here.
       -- It also goes FALSE unconditionally on the next decide tick. No vehicle can
       -- starve: see public.ottoq_cuopt_defer_roll / _arm.
       AND NOT public.ottoq_cuopt_defer_hold(p_sim_run_id, v.id, v_tick)
       -- 0557 (G291, CLAUDE.md rule 9): a car with an open vehicle fault is repaired before it charges. It waits in
       -- staging for the service bay, and this cursor reads a staged car by where it is parked, not what it waits for.
       AND NOT public.ottoq_vehicle_fault_open(v.config)
       AND (v.current_state = 'arrived_at_gate'
            OR (v.current_state = 'staged_awaiting_service' AND EXISTS (
                 SELECT 1 FROM stalls s2
                   JOIN ottoq_ocpp_chargers c2 ON c2.charger_id = s2.ocpp_charger_id
                  WHERE s2.depot_id = v_depot
                    AND s2.stall_type::text IN ('dcfc','l2')
                    AND s2.current_vehicle_id IS NULL
                    AND c2.station_state = 'Available'
                    AND (s2.reserved_by IS NULL OR s2.reserved_by = v.id
                         OR s2.reservation_expires_at <= v_clock))))
       -- 0493 (G210): the deriver's charge rule, below the visit target minus 1 (ottoq_derive_visit_needs and
       -- ottoq_reassess_charge_needs). At the target minus 1 the gate intake (3b) took the car as needing no charge
       -- while this cursor sent it to a charger, in the same tick.
       AND v.current_soc < COALESCE((SELECT vn.target_soc FROM ottoq_visit_needs vn
              WHERE vn.vehicle_id = v.id AND vn.status IN ('open','in_progress') AND COALESCE(vn.sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE(p_sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) /* 0123 */
              ORDER BY vn.created_at DESC, vn.visit_key DESC LIMIT 1), public.ottoq_default_target_soc()) - 1
     ORDER BY COALESCE((SELECT vn.urgency = 'immediate_dispatch' FROM ottoq_visit_needs vn
                 WHERE vn.vehicle_id = v.id AND vn.status IN ('open','in_progress') AND COALESCE(vn.sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE(p_sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) /* 0123 */
                 ORDER BY vn.created_at DESC, vn.visit_key DESC LIMIT 1), false) DESC,
              /* 0614: under a live agent charge order, a car that has waited the pin or longer goes first, in the
                 kernel's own order (the keys below); then the cars the agent ranked, in its order, the ones named for
                 the kind of charger free now first; then every other car, in the kernel's own order. Both keys are
                 NULL for every car without a live order, so they sort nothing. */
              CASE WHEN v_ao_on THEN public.ottoq_charge_wait_min(v.config, v.last_state_change, v_clock, p_sim_run_id) >= v_ao_pin END DESC NULLS LAST,
              CASE WHEN v_ao_on AND public.ottoq_charge_wait_min(v.config, v.last_state_change, v_clock, p_sim_run_id) < v_ao_pin
                   THEN public.ottoq_agent_charge_order_key(v_ao_order, v.id, v_ao_mode) END ASC NULLS LAST,
              /* 0546 (G271): a car with no open visit is not an immediate dispatch. As NULL it sorted, NULLS LAST,
                 after every car with a visit whatever it had waited: the boot cars G271 found at 91-98%. */
              /* 0261: under a baseline seat the queue order IS the policy: fifo by
                 arrival, greedy by depletion. Both keys are NULL for seat 0 and sort
                 nothing; the immediate_dispatch key above stays first for every seat. */
              CASE WHEN v_seat = 1 THEN v.last_state_change END ASC NULLS FIRST,
              CASE WHEN v_seat = 2 THEN v.current_soc END ASC,
              /* 0642 (G384): OTTO-Q's seat, after the agent's keys: a car that has waited charge_wait_floor_min (90)
                 or longer goes ahead of every car that has not, the longest wait first; then the highest response
                 ratio in minutes of charge, (minutes waited + minutes its charge takes) / minutes its charge takes.
                 Both NULL for every car on a baseline seat or with the dials at 0, and 0545's ratio below orders the
                 line as before; below the floor 0545's ratio breaks only the minutes' ties. */
              /* 0781 (G501): with charge_order_exit_first at 1, each car's place in the kernel's line
                 (ottoq_charge_order_keys' exit_rank): the order below, with each owner's cars below the floor and not
                 immediate reordered among the places that owner's cars hold, its cars whose charge is their exit first.
                 The floor and minutes after it then sort nothing. NULL for every car at 0: 0642's order. */
              (v_ok -> v.id::text ->> 4)::numeric ASC NULLS LAST,
              (v_ok -> v.id::text ->> 0)::numeric DESC NULLS LAST,
              (v_ok -> v.id::text ->> 1)::numeric DESC NULLS LAST,
              /* 0545 (G271, CLAUDE.md rule 9): OTTO-Q's seat takes the highest response ratio first, (minutes
                 waited in this state + points to charge) / points to charge. Lowest charge first starved a car that
                 needed only a top-off to 100%, which rule 9 keeps until it is full: nine cars sat the whole day at
                 91-98% on 9eab647f. The ratio rises for every car the longer it waits, so none starves. NULL for
                 the baseline seats, which keep their own keys above. */
              CASE WHEN v_seat = 0 THEN
                /* 0551 (G279): the wait is the car's whole wait in this run's episode, public.ottoq_charge_wait_min:
                   the minutes in its current waiting state plus those it banked earlier. A charger fault, or a move
                   from the gate to staging or to a bay, used to restart it at zero. */
                (public.ottoq_charge_wait_min(v.config, v.last_state_change, v_clock, p_sim_run_id)
                 + GREATEST(public.ottoq_effective_target_soc_at(v.id, v_clock) - v.current_soc, 1))
                / GREATEST(public.ottoq_effective_target_soc_at(v.id, v_clock) - v.current_soc, 1)
              END DESC NULLS LAST,
              v.current_soc ASC, v.id
     -- charging_staff gate: general techs plug in / unplug and do the interior
     -- clean at the stall, so STAFF (not stalls) cap how many cars can be on
     -- charge at once. Neutral staffing (cap >= the 45 physical charge stalls)
     -- leaves the cursor unbounded, so this is a no-op until the knob moves.
     LIMIT (CASE
              WHEN ottoq_sim_lane_capacity(p_sim_run_id, 'charging_staff', 45) >= 45
                THEN 2147483647
              ELSE GREATEST(0,
                     ottoq_sim_lane_capacity(p_sim_run_id, 'charging_staff', 45)
                     - (SELECT count(*) FROM vehicles vc
                         WHERE vc.home_depot_id = v_depot
                           AND vc.current_state IN ('charging_dcfc','charging_l2')))
            END)
  LOOP
    v_built:=v_built+1; v_t0:=clock_timestamp(); v_over:=false; v_safe:=false; v_block_codes:='{}'; v_disarm:='[]'::jsonb;
    v_ctx := ottoq_build_decision_context('stall_assignment','vehicle',v_req.vehicle_id,v_depot,v_clock);
    IF v_ok ? v_req.vehicle_id::text THEN  /* 0642: the keys this car was served by, for the record */
      v_ctx := v_ctx || jsonb_build_object('charge_order', jsonb_build_object(
                 'floor_key', v_ok -> v_req.vehicle_id::text -> 0, 'minutes_key', v_ok -> v_req.vehicle_id::text -> 1));
    END IF;
    IF v_ok -> v_req.vehicle_id::text ->> 4 IS NOT NULL THEN   /* 0781 (G501): its exit key, its turn in the bays, its place */
      v_ctx := jsonb_set(v_ctx, '{charge_order}', (v_ctx -> 'charge_order')
                 || jsonb_build_object('exit_key', v_ok -> v_req.vehicle_id::text -> 2,
                                       'bay_eta_min', v_ok -> v_req.vehicle_id::text -> 3,
                                       'exit_rank', v_ok -> v_req.vehicle_id::text -> 4));
    END IF;
    IF v_ao_on THEN  /* 0614: the order this seat is made under, for the stall pick and for the record */
      v_ao_wait := public.ottoq_charge_wait_min(v_req.ao_config, v_req.ao_lsc, v_clock, p_sim_run_id);
      v_ctx := v_ctx || jsonb_build_object('agent_charge_order', jsonb_build_object(
                 'order_id', v_ao_order_id,
                 'rank', v_ao_order -> v_req.vehicle_id::text -> 'rank',
                 'kind', v_ao_order -> v_req.vehicle_id::text ->> 'kind',
                 'mode', v_ao_mode,
                 'pinned', COALESCE(v_ao_wait >= v_ao_pin, false),
                 'wait_min', round(v_ao_wait, 1),
                 'kernel_pos', v_ao_kpos -> v_req.vehicle_id::text));
    END IF;
    v_proposal := ottoq_honour_reservation_proposal(p_sim_run_id, v_req.vehicle_id, v_depot, v_ctx);
    v_prop_ms := EXTRACT(MILLISECOND FROM (clock_timestamp()-v_t0))::int;
    IF (v_proposal->>'abstain')::boolean THEN v_deferred:=v_deferred+1;
      INSERT INTO ottoq_decisions (sim_run_id,tick_seq,sim_clock,depot_id,snapshot_id,action_context,entity_type,entity_id,context_frame,proposed_action,enacted_action,outcome_status,propose_latency_ms,total_latency_ms)
      VALUES (p_sim_run_id,v_tick,v_clock,v_depot,v_snapshot_id,'stall_assignment','vehicle',v_req.vehicle_id,v_ctx,v_proposal,'{}'::jsonb,'noop_no_candidate',v_prop_ms,v_prop_ms);
      IF (SELECT current_stall_id FROM vehicles WHERE id = v_req.vehicle_id) IS NULL THEN
        -- DOCTRINE (Chase 2026-07-28): never a gate queue; temp vs perimeter is chosen by
          -- PURPOSE and duration, not by whichever staging stall sorts first.
          DECLARE v_disp jsonb; v_hold jsonb;
          BEGIN
            v_disp := ottoq_arrival_disposition(p_sim_run_id, v_depot, v_req.vehicle_id, v_clock);
            IF (v_disp->>'action') IN ('perimeter_hold','temp_stage_await_resource','temp_stage_tech_hold','quarantine') THEN
              v_hold := ottoq_book_hold_stall(
                          p_sim_run_id, v_depot, v_req.vehicle_id,
                          COALESCE((v_disp->>'stage_from')::timestamptz, v_clock),
                          COALESCE((v_disp->>'stage_until')::timestamptz, v_clock + interval '30 minutes'));
              IF COALESCE((v_hold->>'booked')::boolean, false) THEN
                SELECT b.stall_id INTO v_stage_stall
                  FROM ottoq_stall_bookings b WHERE b.booking_id = (v_hold->>'booking_id')::uuid;
                IF v_stage_stall IS NOT NULL
                   AND ottoq_reserve_stall(v_stage_stall, v_req.vehicle_id, v_clock, 900) THEN
                  -- 0039: emit command instead of direct UPDATE
                  PERFORM ottoq.ottoq_emit_vehicle_command(p_sim_run_id, v_depot, v_req.vehicle_id, 'proceed_to_stall',
                          jsonb_build_object('stall_id', v_stage_stall, 'new_state', 'staged_awaiting_service'), v_clock);
                ELSE
                  -- 0471 (G203): the car is not going to this stall, so the hold is released now instead of keeping
                  -- the stall off the calendar for every other car until its window runs out.
                  UPDATE ottoq_stall_bookings
                     SET state = 'released', released_at = v_clock, release_reason = 'reserve_refused_decide_tick'
                   WHERE booking_id = (v_hold->>'booking_id')::uuid AND state = 'held';
                END IF;
              END IF;
            END IF;
          END;
      END IF;
      CONTINUE; END IF;
    v_ctx := v_ctx || jsonb_build_object('stall_id', v_proposal->>'stall_id', 'requested_kw', v_proposal->>'requested_kw');
    v_t0:=clock_timestamp();
    SELECT count(*) FILTER (WHERE would_block), array_agg(rule_code) FILTER (WHERE would_block),
           jsonb_agg(jsonb_build_object('rule_code',rule_code,'passed',passed,'reason',reason,'enforcement_taken',enforcement_taken,'severity',severity))
      INTO v_blocks, v_block_codes, v_rule_rows
      FROM ottoq_shield_probe('stall_assignment','vehicle',v_req.vehicle_id,v_ctx,v_req.fleet_operator_id,v_depot);
    v_shield_ms:=EXTRACT(MILLISECOND FROM (clock_timestamp()-v_t0))::int;
    v_t0:=clock_timestamp();
    IF COALESCE(v_blocks,0)>0 THEN v_action:=ottoq_l1_safe_default_stall(v_req.vehicle_id,v_ctx); v_safe:=true; v_over:=true; v_outcome:='overridden_to_default'; v_overc:=v_overc+1;
    ELSE
      v_action:=v_proposal;
      /* 0132: THE SITE POWER CAP IS A CONSTRAINT, NOT A NOTE. Refuse before the stall is
         reserved and before any command is emitted, so a refusal costs nothing and still
         falls through to the decision INSERT with its own reason code. */
      IF v_charge_cap_kw IS NOT NULL
         AND public.ottoq_policy_get(p_sim_run_id, 'enforce_site_charge_cap', 1) >= 1
         AND (COALESCE(v_ev_committed_kw,0) + COALESCE((v_action->>'requested_kw')::numeric,0)) > v_charge_cap_kw THEN
        v_outcome:='deferred_site_power_cap'; v_deferred:=v_deferred+1;
      ELSIF ottoq_reserve_stall((v_action->>'stall_id')::uuid, v_req.vehicle_id, v_clock, 600) THEN
        -- 0039: old-stall cleanup handled by twin on begin_charge confirmation
        -- 0039: emit charge command instead of direct UPDATE
        v_cmd_id := ottoq.ottoq_emit_vehicle_command(p_sim_run_id, v_depot, v_req.vehicle_id, 'begin_charge',
                jsonb_build_object(
                  'stall_id', (v_action->>'stall_id')::text,
                  'stall_type', v_action->>'stall_type',
                  'new_state', CASE WHEN v_action->>'stall_type'='dcfc' THEN 'charging_dcfc' ELSE 'charging_l2' END,
                  /* 0066: folded in from the duplicate emit removed below, so this one
                     command carries everything both used to. Nothing reads requested_kw
                     off a command -- ottoq_claim_tick_kw takes the real figure from
                     v_action on the next line -- but the record keeps it. */
                  'requested_kw', v_action->>'requested_kw'
                ), v_clock);
      -- 0039: charge stall claim handled by twin on command confirmation
        -- 0493 (G226): THE EMISSION GATE'S ANSWER IS READ. The gate refuses what ottoq_validate_assignment refuses,
        -- most often a live calendar booking held by another car. Everything below used to run anyway: the decision
        -- read enacted, the kW was claimed, and ottoq_record_enacted_booking superseded the other car's booking and
        -- booked this car on a charger it was not going to (57 of 217 on busy_day/171717/48, verdict 383). A refused
        -- command now claims, starts, plans and books nothing, the reservation taken above is released, and the
        -- refusal reactor reroutes it as before.
        SELECT c.status, c.reason_code, c.reason_detail INTO v_cmd_status, v_cmd_code, v_cmd_detail
          FROM public.ottoq_vehicle_commands c WHERE c.command_id = v_cmd_id;
        IF v_cmd_status = 'refused' THEN
          UPDATE public.stalls
             SET reserved_by = NULL, reserved_at = NULL, reservation_expires_at = NULL
           WHERE id = (v_action->>'stall_id')::uuid AND reserved_by = v_req.vehicle_id AND current_vehicle_id IS NULL;
          v_action := jsonb_build_object('verb', 'charger_refused', 'reason', COALESCE(v_cmd_code, 'refused'),
                                         'stall_type', v_action->>'stall_type', 'refused_detail', v_cmd_detail,
                                         'command_id', v_cmd_id);
          v_outcome := 'deferred_stale_entity'; v_deferred := v_deferred + 1;
        ELSE
        PERFORM ottoq_claim_tick_kw(p_sim_run_id, v_tick, v_depot, (v_action->>'requested_kw')::numeric, v_req.vehicle_id);
        PERFORM ottoq_start_concurrent_atoms(v_req.vehicle_id, v_clock);
        PERFORM ottoq_plan_visit_itinerary(p_sim_run_id, v_req.vehicle_id, v_clock);

        -- FORWARD AVAILABILITY / P0: ENACTMENT AND CALENDAR ARE ONE ACT.
        -- Every stall assignment that reaches this line - cuopt, deterministic, greedy and
        -- reservation_honoured all return through v_action above - is now recorded on the
        -- forward calendar in THIS transaction, against the EXACT stall enacted.
        --
        -- Previously the booking sat inside "IF v_charge_leg.leg_id IS NOT NULL", and the planner
        -- emits a charge leg only when the visit-need manifest carries an svc='charge' atom. When
        -- it does not, that branch never ran: 51 enacted charge assignments, 0 charge bookings,
        -- 0% end-to-end coverage. The booking no longer depends on a planned leg existing.
        --
        -- The leg is still PREFERRED when present, for two reasons: it carries the real timed
        -- window, and stamping to_stall_id is the existing sentinel that removes the leg from both
        -- booking cursors (ottoq_book_workflow / ottoq_find_and_book_stall), suppressing the second
        -- independent stall search. The calendar still RECORDS the decision, it never re-derives it.
        SELECT l.leg_id, l.leg_type, l.planned_start_sim, l.planned_end_sim
          INTO v_charge_leg
          FROM public.ottoq_itinerary_legs l
         WHERE l.sim_run_id  = p_sim_run_id
           AND l.vehicle_id  = v_req.vehicle_id
           AND l.status      = 'planned'
           AND l.to_stall_id IS NULL
           AND l.leg_type IN ('charge_dcfc','charge_l2')
           AND l.planned_start_sim IS NOT NULL
           AND l.planned_end_sim   IS NOT NULL
           AND l.planned_end_sim   > v_clock
         ORDER BY l.seq, l.planned_start_sim, l.planned_end_sim, l.leg_id /* 0129 */ LIMIT 1;

        -- p_purpose is left NULL so the purpose is derived from the stall ACTUALLY taken, not from
        -- what the planner intended. The helper supersedes phantom overlaps, is idempotent on
        -- (run, stall, vehicle, purpose, window), and can never abort this tick.
        v_bkg := ottoq.ottoq_record_enacted_booking(
                   p_sim_run_id, (v_action->>'stall_id')::uuid, v_req.vehicle_id, v_clock,
                   v_charge_leg.leg_id, v_charge_leg.planned_start_sim, v_charge_leg.planned_end_sim,
                   NULL, COALESCE(v_action->>'source','deterministic'));

        IF v_bkg IS NOT NULL AND v_charge_leg.leg_id IS NOT NULL THEN
          UPDATE public.ottoq_itinerary_legs
             SET to_stall_id = (v_action->>'stall_id')::uuid
           WHERE leg_id = v_charge_leg.leg_id;
        END IF;

        v_outcome:='enacted'; v_enacted:=v_enacted+1;
        v_ev_committed_kw := v_ev_committed_kw + COALESCE((v_action->>'requested_kw')::numeric,0);
        END IF;  -- 0493 (G226): the refused command's branch opens above the kW claim
        /* ══════════ 0066: THE DUPLICATE begin_charge EMIT IS REMOVED HERE ══════════
           This line used to emit a SECOND begin_charge for the same vehicle, stall and
           tick as the one already emitted at the top of this branch -- same branch, no
           conditional between them, so both always fired. Measured in re-cert #18 arm A:
           589 refusals on the surviving variant, 584 on this one. It halved the refusal
           reactor (LIMIT 20 per tick against an unbounded backlog) by making it re-read
           decisions it had already handled, and it manufactured the byte-tied duplicate
           command rows that broke the supersede ordering in #16 and forced 0062.
           The surviving emit above now carries requested_kw as well. */
      ELSE v_action:=ottoq_l1_safe_default_stall(v_req.vehicle_id,v_ctx); v_outcome:='deferred_stale_entity'; v_deferred:=v_deferred+1; END IF;
    END IF;
    v_enact_ms:=EXTRACT(MILLISECOND FROM (clock_timestamp()-v_t0))::int;
    INSERT INTO ottoq_decisions (sim_run_id,tick_seq,sim_clock,depot_id,snapshot_id,action_context,resolved_action_context,entity_type,entity_id,context_frame,proposed_action,enacted_action,overridden,override_rule_codes,rule_results,safe_default_taken,outcome_status,propose_latency_ms,shield_latency_ms,enact_latency_ms,total_latency_ms)
    VALUES (p_sim_run_id,v_tick,v_clock,v_depot,v_snapshot_id,'stall_assignment','stall_assignment','vehicle',v_req.vehicle_id,v_ctx,v_proposal,v_action,v_over,v_block_codes,COALESCE(v_rule_rows,'[]'::jsonb),v_safe,v_outcome,v_prop_ms,v_shield_ms,v_enact_ms,COALESCE(v_prop_ms,0)+COALESCE(v_shield_ms,0)+COALESCE(v_enact_ms,0));
  END LOOP;

  -- (3b) GATE INTAKE — NO-CHARGE ARRIVALS
  FOR v_req IN
    SELECT v.id AS vehicle_id, v.current_soc, v.fleet_operator_id
      FROM vehicles v
     WHERE v.home_depot_id = v_depot AND v.category = 'autonomous'
       AND v.current_state = 'arrived_at_gate'
       AND v.current_stall_id IS NULL
       AND EXISTS (SELECT 1 FROM ottoq_visit_needs vn
                    WHERE vn.vehicle_id = v.id AND vn.status IN ('open','in_progress') AND COALESCE(vn.sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE(p_sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) /* 0124 */
                      AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(vn.atoms) a
                                       WHERE a->>'svc' = 'charge' AND COALESCE(a->>'status','pending') <> 'done'))
       -- 0493 (G210): nothing else sent this car to a stall this tick. The charge step (3) runs first, and when both
       -- took a car the door kept one of the two by command type, not by what the car needed. 0472 gave the
       -- inspection seam the same guard.
       AND NOT EXISTS (SELECT 1 FROM public.ottoq_vehicle_commands vc
                        WHERE vc.vehicle_id = v.id AND vc.sim_run_id = p_sim_run_id
                          AND vc.issued_at = v_clock AND vc.status = 'issued'
                          AND vc.payload ? 'stall_id')
     ORDER BY v.last_state_change ASC NULLS FIRST, v.id   /* 0054: the sibling cursors' own fairness idiom, made explicit here too */
  LOOP
    -- 0467 (G199): take the first stall, in the intake's own order, that the emission gate accepts.
    -- ottoq_emit_vehicle_command refuses pre-flight whatever ottoq_validate_assignment refuses (pointer,
    -- reservation, stall status, and a live calendar booking held by another car at this moment). The pick
    -- asked only the pointer, so 51 of 61 intakes on 317d4331 were refused and rerouted. OFFSET 0 keeps the
    -- validator above the sort, so it runs only until it finds a stall; the outer ORDER BY pins the choice.
    SELECT c.id INTO v_stage_stall
      FROM (SELECT s.id, (s.staging_role = 'temp') AS temp_first, s.distance_from_entrance AS dist
              FROM stalls s
             WHERE s.depot_id = v_depot AND s.stall_type = 'staging'
               AND s.zone IS DISTINCT FROM 'arrival_inspection'
               AND s.current_vehicle_id IS NULL
               AND (s.reserved_by IS NULL OR s.reservation_expires_at <= v_clock)
             ORDER BY (s.staging_role = 'temp') DESC, s.distance_from_entrance NULLS LAST, s.id
            OFFSET 0) c
     WHERE COALESCE((ottoq.ottoq_validate_assignment(v_req.vehicle_id, c.id, 'proceed_to_stall',
                                                     v_clock, p_sim_run_id)->>'ok')::boolean, false)
     ORDER BY c.temp_first DESC, c.dist NULLS LAST, c.id LIMIT 1;
    IF v_stage_stall IS NOT NULL AND ottoq_reserve_stall(v_stage_stall, v_req.vehicle_id, v_clock, 900) THEN
      -- 0039: emit command instead of direct UPDATE — twin owns vehicle state
      PERFORM ottoq.ottoq_emit_vehicle_command(p_sim_run_id, v_depot, v_req.vehicle_id, 'proceed_to_stall',
              jsonb_build_object('stall_id', v_stage_stall,
                                 'reason', 'gate_intake',   -- 0467 (G199): from the second command, removed below
                                 'new_state', 'staged_awaiting_service',
                                 'svc_step', CASE WHEN EXISTS (SELECT 1 FROM ottoq_visit_needs vn2, jsonb_array_elements(vn2.atoms) a2
                                                               WHERE vn2.vehicle_id = v_req.vehicle_id AND vn2.status IN ('open','in_progress') AND COALESCE(vn2.sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE(p_sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) /* 0124 */
                                                                 AND a2->>'svc' IN ('mechanical_pm','fault_repair','sensor_calibration')
                                                                 AND COALESCE((a2->>'must_do')::boolean,false)
                                                                 AND COALESCE(a2->>'status','pending') = 'pending')
                                                THEN 'need_service' ELSE 'need_deploy' END), v_clock);
      -- 0039: stall claim now handled by twin on command confirmation
      PERFORM ottoq_start_concurrent_atoms(v_req.vehicle_id, v_clock);
      v_built := v_built + 1; v_enacted := v_enacted + 1;
      PERFORM ottoq_plan_visit_itinerary(p_sim_run_id, v_req.vehicle_id, v_clock);
      -- CALENDAR (staging). The single biggest gap: the whole service-only intake path
      -- enacted a stall and wrote NOTHING to the forward-occupancy calendar.
      -- We RECORD the stall the intake ALREADY picked above. We must NOT call
      -- ottoq_book_hold_stall here: it runs its OWN independent search, which is exactly
      -- the decision/calendar divergence fixed on 2026-08-01.
      SELECT l.leg_id INTO v_stage_leg_id
        FROM public.ottoq_itinerary_legs l
       WHERE l.sim_run_id = p_sim_run_id AND l.vehicle_id = v_req.vehicle_id
         AND l.status = 'planned' AND l.leg_type = 'stage' AND l.to_stall_id IS NULL
         AND l.planned_end_sim > v_clock
       ORDER BY l.seq, l.planned_start_sim, l.planned_end_sim, l.leg_id /* 0129 */ LIMIT 1;
      -- The car holds this staging stall until its itinerary is done: nothing in (4) or (5)
      -- clears stalls.current_vehicle_id, only (3)'s charge branch and redeploy do.
      -- Hard-capped so a runaway itinerary can never reserve a space indefinitely.
      SELECT max(l.planned_end_sim) INTO v_stage_until
        FROM public.ottoq_itinerary_legs l
       WHERE l.sim_run_id = p_sim_run_id AND l.vehicle_id = v_req.vehicle_id
         AND l.status = 'planned' AND l.planned_end_sim > v_clock;
      v_stage_until := GREATEST(
        LEAST(
          COALESCE(v_stage_until,
                   v_clock + make_interval(mins => ottoq_policy_get(p_sim_run_id,'staging_hold_default_min',30)::int)),
          v_clock + make_interval(mins => ottoq_policy_get(p_sim_run_id,'staging_hold_max_min',480)::int)),
        v_clock + interval '1 minute');
      -- 0476 (G206): recorded through the enacted-booking seam on the stall already picked, which runs no search of its
      -- own. A bare ottoq_book_stall collided with the car's own live hold on that stall (the validator exempts it) and
      -- the intake went on with no booking, 3 of 46 on 49c45bd4. The seam supersedes the car's own overlapping booking
      -- and truncates an overlapping done one first, as it does for every other enacted placement.
      v_bkg := ottoq.ottoq_record_enacted_booking(p_sim_run_id, v_stage_stall, v_req.vehicle_id, v_clock,
                 v_stage_leg_id, v_clock, v_stage_until, 'staging', 'gate_intake_staging');
      IF v_bkg IS NOT NULL THEN
        UPDATE public.ottoq_stall_bookings SET source = COALESCE(source, 'gate_intake_staging')
         WHERE booking_id = v_bkg;
      END IF;
      IF v_bkg IS NOT NULL AND v_stage_leg_id IS NOT NULL THEN
        -- same sentinel the charge path uses: a stamped to_stall_id removes the leg from
        -- ottoq_book_workflow's cursor, so no second independent search can re-derive it.
        UPDATE public.ottoq_itinerary_legs SET to_stall_id = v_stage_stall
         WHERE leg_id = v_stage_leg_id;
      END IF;
      INSERT INTO ottoq_decisions (sim_run_id,tick_seq,sim_clock,depot_id,snapshot_id,action_context,resolved_action_context,entity_type,entity_id,context_frame,proposed_action,enacted_action,outcome_status,propose_latency_ms,total_latency_ms)
      VALUES (p_sim_run_id,v_tick,v_clock,v_depot,v_snapshot_id,'stall_assignment','gate_intake_no_charge','vehicle',v_req.vehicle_id,
              jsonb_build_object('stall_id',v_stage_stall,'staging_pick','temp_first'),
              jsonb_build_object('verb','gate_intake','stall_id',v_stage_stall),
              jsonb_build_object('verb','gate_intake','stall_id',v_stage_stall,'booking_id',v_bkg),
              'enacted',0,0);
      -- 0467 (G199): a second proceed_to_stall to the same stall used to follow here, carrying only
      -- `reason` (now on the command above). Refused, the two became two reroutes to two stalls; the door kept
      -- one by stall id and the other's hour-long reservation and booking stayed behind (49 on 317d4331).
    END IF;
  END LOOP;

  -- (4) CHARGE DISPOSITION
  -- ═══════════ 0011-TETHER: THE IN-DEPOT MOVE DOOR ═══════════
  -- The founder decision is that a mated vehicle is blocked from ALL movement, not
  -- redeployment only. This cursor is the charge-stall -> wash-bay door, and it reads
  -- exactly the state a just-finished DCFC car is in, so without the predicate below a
  -- car would be sent to a wash bay while the arm is still retracting the cable.
  -- ottoq_vehicle_is_tethered is STABLE, NULL-safe and never raises, and fails OPEN, so
  -- it can only remove a candidate from this tick -- never abort the tick.
  FOR v_req IN
    SELECT v.id AS vehicle_id, v.current_soc, v.fleet_operator_id
      FROM vehicles v WHERE v.home_depot_id=v_depot AND v.category='autonomous'
       AND v.current_state='charge_complete_holding'
       AND NOT public.ottoq_vehicle_is_tethered(v.id, v_clock)
       -- 0695: nor a car whose data transfer holds it on its uplink stall (docs/DATA_OFFLOAD.md)
       AND NOT ottoq.ottoq_uplink_transfer_holds(v.id, p_sim_run_id)
     ORDER BY v.last_state_change ASC NULLS FIRST, v.id LIMIT 40
  LOOP
    v_built:=v_built+1; v_t0:=clock_timestamp(); v_over:=false; v_safe:=false; v_block_codes:='{}'; v_disarm:='[]'::jsonb;
    v_ctx := ottoq_build_decision_context('task_start','vehicle',v_req.vehicle_id,v_depot,v_clock) || jsonb_build_object('requires_charging','false','service','wash');
    v_proposal := ottoq_l2_propose_charge_disposition(v_req.vehicle_id, v_depot, v_ctx || jsonb_build_object('sim_run_id', p_sim_run_id));
    v_prop_ms:=EXTRACT(MILLISECOND FROM (clock_timestamp()-v_t0))::int;
    IF (v_proposal->>'abstain')::boolean THEN v_deferred:=v_deferred+1;
      INSERT INTO ottoq_decisions (sim_run_id,tick_seq,sim_clock,depot_id,snapshot_id,action_context,entity_type,entity_id,context_frame,proposed_action,enacted_action,outcome_status,propose_latency_ms,total_latency_ms)
      VALUES (p_sim_run_id,v_tick,v_clock,v_depot,v_snapshot_id,'task_start','vehicle',v_req.vehicle_id,v_ctx,v_proposal,'{}'::jsonb,'noop_no_candidate',v_prop_ms,v_prop_ms);
      CONTINUE; END IF;
    v_t0:=clock_timestamp();
    SELECT count(*) FILTER (WHERE would_block), array_agg(rule_code) FILTER (WHERE would_block),
           jsonb_agg(jsonb_build_object('rule_code',rule_code,'passed',passed,'reason',reason,'enforcement_taken',enforcement_taken,'severity',severity))
      INTO v_blocks, v_block_codes, v_rule_rows
      FROM ottoq_shield_probe('task_start','vehicle',v_req.vehicle_id,v_ctx,v_req.fleet_operator_id,v_depot);
    v_shield_ms:=EXTRACT(MILLISECOND FROM (clock_timestamp()-v_t0))::int;
    v_t0:=clock_timestamp();
    IF COALESCE(v_blocks,0)>0 THEN v_action:=ottoq_l1_safe_default_charge_disposition(v_req.vehicle_id,v_ctx); v_safe:=true; v_over:=true; v_outcome:='overridden_to_default'; v_overc:=v_overc+1;
    ELSE
      v_action:=v_proposal; v_outcome:='enacted'; v_enacted:=v_enacted+1;
      IF COALESCE(v_action->>'verb','admit_wash') = 'skip_wash' THEN
        -- SERVICE-NEED ROUTING (2026-08-01): no wash/detail work outstanding, so do
        -- NOT burn one of the depot's 3 wash bays on a clean car. Advance the vehicle
        -- inside the SAME atomic visit to what it does still need. Nothing is booked
        -- and no stall is claimed, so the calendar cannot over-report.
        -- 0039: emit staging command instead of direct UPDATE
        PERFORM ottoq.ottoq_emit_vehicle_command(p_sim_run_id, v_depot, v_req.vehicle_id, 'stage',
                jsonb_build_object('reason','no_wash_need','next_step',COALESCE(v_action->>'next_step','need_deploy')), v_clock);
        v_action := COALESCE(v_action,'{}'::jsonb) || jsonb_build_object('bay_booked', false, 'bay_stall_type', 'none');
      ELSE
      -- BAY ENTRY MOVED BELOW THE HELPER (Phase 3). It used to happen HERE, before any
      -- bay had been claimed or booked: if ottoq_enact_space_assignment then found no free
      -- bay, the vehicle was already 'in_wash_bay' with no stall and no calendar row --
      -- a bay physically occupied while the calendar showed it free. The state flip and
      -- the enter_wash command are now gated on the booking, exactly as (4b) already was.
      -- CALENDAR (wash/detail bay). CHOOSE + CLAIM + RECORD, one act.
      -- ottoq_enact_space_assignment picks the bay, reserves it, writes
      -- vehicles.current_stall_id and books the window in THIS transaction. The bay entry
      -- below is GATED on that result: no free bay means no entry, and the miss is recorded
      -- on the decision row as verb 'hold_no_bay'. The calendar can under-report a REFUSAL
      -- but it can no longer report a bay as free while a vehicle is standing in it.
      SELECT l.leg_id, l.leg_type, (l.planned_end_sim - l.planned_start_sim)
        INTO v_bay_leg_id, v_bay_leg_type, v_bay_dur
        FROM public.ottoq_itinerary_legs l
       WHERE l.sim_run_id = p_sim_run_id AND l.vehicle_id = v_req.vehicle_id
         AND l.status = 'planned' AND l.to_stall_id IS NULL
         AND l.leg_type IN ('wash','detail')
       ORDER BY l.seq, l.planned_start_sim, l.planned_end_sim, l.leg_id /* 0129 */ LIMIT 1;
      IF v_bay_leg_id IS NULL THEN
        -- FALLBACK -- THIS IS WHY leg_id WAS NULL ON EVERY ENACTED BOOKING (11 of 11 on
        -- run 4332b898, against 94 of 94 on the planner path). The forward planner
        -- ottoq_book_workflow books the leg AHEAD of time and stamps to_stall_id, so the
        -- cursor above (to_stall_id IS NULL) found nothing and enactment booked a SECOND
        -- row on a possibly different stall with no leg. Adopt the planned leg instead:
        -- ottoq_enact_space_assignment honours its reservation and
        -- ottoq_record_enacted_booking adopts that row rather than duplicating it.
        SELECT l.leg_id, l.leg_type, (l.planned_end_sim - l.planned_start_sim)
          INTO v_bay_leg_id, v_bay_leg_type, v_bay_dur
          FROM public.ottoq_itinerary_legs l
         WHERE l.sim_run_id = p_sim_run_id AND l.vehicle_id = v_req.vehicle_id
           AND l.status IN ('planned','active')
           AND l.leg_type IN ('wash','detail')
         ORDER BY (l.status = 'active') DESC, l.seq, l.planned_start_sim, l.planned_end_sim, l.leg_id /* 0129 */ LIMIT 1;
      END IF;
      -- TOTAL allow-list leg_type -> purpose. Only the two wash-lane leg types can reach
      -- here; nothing is ever passed through to the CLOSED 9-label purpose CHECK.
      -- (no detail_bay stalls are seeded - detail shares the wash lane, as in ottoq_book_workflow)
      v_bay_purpose := CASE WHEN COALESCE(v_action->>'bay_kind', v_bay_leg_type) = 'detail' THEN 'detail' ELSE 'wash' END;
      v_bay_until := v_clock + GREATEST(
        COALESCE(v_bay_dur,
                 make_interval(mins => ottoq_policy_get(p_sim_run_id,'wash_bay_default_min',25)::int)),
        interval '1 minute');
      v_space := ottoq.ottoq_enact_space_assignment(p_sim_run_id, v_depot, v_req.vehicle_id,
                     'wash_bay', v_bay_purpose, v_clock, v_bay_until,
                     v_bay_leg_id, 'charge_disposition');
      v_bay_bkg := NULLIF(v_space->>'booking_id','')::uuid;
      IF v_bay_bkg IS NOT NULL AND v_bay_leg_id IS NOT NULL THEN
        UPDATE public.ottoq_itinerary_legs
           SET to_stall_id = (SELECT b.stall_id FROM public.ottoq_stall_bookings b
                               WHERE b.booking_id = v_bay_bkg)
         WHERE leg_id = v_bay_leg_id;
      END IF;
      IF COALESCE((v_space->>'assigned')::boolean, false) THEN
        -- ENTRY AND CALENDAR ARE ONE ACT. A real wash bay has been claimed AND booked in
        -- this transaction, so the command names the stall, the booking and the leg.
      -- 0039: vehicle state update handled by twin on 'enter_wash' command confirmation
        PERFORM ottoq_emit_vehicle_command(p_sim_run_id, v_depot, v_req.vehicle_id, 'enter_wash',
                jsonb_build_object('stall_id',   v_space->>'stall_id',
                                   'booking_id', v_space->>'booking_id',
                                   'leg_id',     v_bay_leg_id,
                                   'purpose',    v_bay_purpose), v_clock);
        v_action := COALESCE(v_action,'{}'::jsonb) || COALESCE(v_space,'{}'::jsonb)
                    || jsonb_build_object('bay_booked', v_bay_bkg IS NOT NULL,
                                          'bay_purpose', v_bay_purpose,
                                          'bay_stall_type', 'wash_bay',
                                          'stall_id', v_space->>'stall_id',
                                          'booking_id', v_space->>'booking_id',
                                          'leg_id', v_bay_leg_id);
      ELSE
        -- NO BAY -> DO NOT ENTER ONE. The vehicle is left exactly where this proposer's own
        -- 'wash_lane_full_hold' abstain leaves it (charge_complete_holding) and is retried
        -- next tick. No state write, no command, no booking. Throughput cannot regress:
        -- this branch is only reachable when there is genuinely no bookable wash bay, and
        -- release step (b) hard-frees stale bay stalls earlier in this same tick.
        v_action := COALESCE(v_action,'{}'::jsonb) || COALESCE(v_space,'{}'::jsonb)
                    || jsonb_build_object('verb','hold_no_bay', 'bay_booked', false,
                                          'bay_purpose', v_bay_purpose,
                                          'bay_stall_type', 'wash_bay');
        v_outcome := 'noop_no_candidate'; v_enacted := v_enacted - 1; v_deferred := v_deferred + 1;
      END IF;
      END IF;
    END IF;
    v_enact_ms:=EXTRACT(MILLISECOND FROM (clock_timestamp()-v_t0))::int;
    INSERT INTO ottoq_decisions (sim_run_id,tick_seq,sim_clock,depot_id,snapshot_id,action_context,resolved_action_context,entity_type,entity_id,context_frame,proposed_action,enacted_action,overridden,override_rule_codes,rule_results,safe_default_taken,outcome_status,propose_latency_ms,shield_latency_ms,enact_latency_ms,total_latency_ms)
    VALUES (p_sim_run_id,v_tick,v_clock,v_depot,v_snapshot_id,'task_start','task_start','vehicle',v_req.vehicle_id,v_ctx,v_proposal,v_action,v_over,v_block_codes,COALESCE(v_rule_rows,'[]'::jsonb),v_safe,v_outcome,v_prop_ms,v_shield_ms,v_enact_ms,COALESCE(v_prop_ms,0)+COALESCE(v_shield_ms,0)+COALESCE(v_enact_ms,0));
  END LOOP;

  -- ══════════════════════════════════════════════════════════════════════════════════
  -- (4b) NEEDS-CARD SPACE ROUTING  —  P1, 2026-08-01
  --
  -- WHAT THIS CLOSES. Before this block the engine literally could not decide "send this
  -- vehicle to the wash bay". The ONLY door into in_wash_bay/in_detail_bay was section (4),
  -- whose cursor is current_state='charge_complete_holding'. Measured on run c177c1ca over
  -- 573 ticks: ZERO admit_wash decisions, 5 skip_wash — while 371 vehicles were promoted
  -- straight from staged_awaiting_service to staged_for_departure by (5), a state from which
  -- no wash/detail door existed at all. That is the whole reason 51 of 51 (and 209 of 209
  -- before) enacted assignments were charging while 3 wash bays sat 100 pct idle.
  --
  -- WHAT IT DOES. For each vehicle HOLDING in staging, read public.ottoq_vehicle_needs_card,
  -- take the highest-priority must-do need that requires a SPACE, and place the vehicle into
  -- the space that need's lane requires — through ottoq_enact_space_assignment, so choosing
  -- the stall and writing the forward-calendar booking are ONE act against the SAME stall
  -- (the P0 rule, now extended past chargers).
  --
  -- SPACE MAP is read from service_cadence_policy.lane, never hardcoded, and is TOTAL:
  --   lane 'wash_bay'    (exterior_wash)                        -> wash_bay,    purpose 'wash'
  --   lane 'detail'      (interior_deep_clean)                  -> wash_bay,    purpose 'detail'
  --        ^ zero detail_bay stalls are seeded; detail shares the wash lane, exactly as
  --          ottoq_book_workflow and twin STEP 2 already do.
  --   lane 'service_bay' (fault_repair, sensor_calibration,
  --                       mechanical_pm, cosmetic_repair)       -> service_bay, purpose 'service'
  --   lane 'anchor'      (charge)      -> NOT HANDLED HERE, see CHARGE FIREWALL.
  --   lane 'cabin'/'exterior'/'digital'/'gate' -> NO SPACE AT ALL. That work overlaps
  --        charging and is already started at the stall by ottoq_start_concurrent_atoms;
  --        spending one of 3 wash or 2 service bays on it would be a straight loss.
  --   any lane the catalogue gains later -> no space, silently skipped. TOTAL FUNCTION
  --        (the 2026-08-01 leg_type lesson): an unknown lane can never reach a CHECK.
  --
  -- ══ ORDERING / PRIORITY RULE ══
  --   WITHIN a vehicle : lowest service_cadence_policy.sequence_order wins, so the visit is
  --     worked in the catalogue's own order (fault_repair 30 -> wash 40 -> detail 45 ->
  --     calibration 55 -> pm 60 -> cosmetic 70). One space at a time; the vehicle comes back
  --     through this block on a later tick for the next item, inside ONE atomic visit.
  --   ACROSS vehicles  : 1. urgency rank DESC (critical > overdue > due > due_soon > ok)
  --                      2. (0545, G270: fits_window left this ordering. Under rule 9 no car leaves
  --                         unfinished, and a car past its deploy time never "fits", so it sorted
  --                         the latest cars last. Earliest deadline first below.) Was: do not burn a scarce bay on work that
  --                         provably cannot finish before the vehicle is due out
  --                      3. minutes_to_deploy ASC — earliest deadline first (EDF)
  --                      4. open_must_do_min ASC — shortest job first, so a scarce bay
  --                         clears more vehicles per hour
  --                      5. vehicle_id — deterministic, seed-stable tiebreak
  --
  -- ══ CHARGE FIREWALL — five independent reasons this cannot regress charging ══
  --  1. Sections (1),(2),(3),(3b) are byte-for-byte unchanged by this migration, including
  --     Gate B in ottoq_honour_reservation_proposal and the cuOpt 'source' passthrough.
  --  2. This block only ever asks for 'wash_bay' or 'service_bay', and
  --     ottoq_enact_space_assignment REFUSES 'dcfc'/'l2' outright. No path built here can
  --     reserve, occupy or book a charger.
  --  3. Any vehicle whose card still lists 'charge' in must_do_now is SKIPPED and left to
  --     section (3). Charge is the anchor leg (sequence_order 10): energy first, then bays.
  --  4. It runs AFTER (3), so every charge decision this tick is already made and its stalls
  --     already reserved before one bay is considered.
  --  5. Separate staff pools: charging is capped by 'charging_staff', wash by
  --     LEAST(cleaning_staff, wash_supervisor), service by 'service_staff'. Bay work cannot
  --     consume a charging tech.
  --  NET EFFECT ON CHARGING IS POSITIVE: today a vehicle in a bay still holds the l2/dcfc
  --  stall it charged on, because nothing clears it. Occupying the bay moves
  --  vehicles.current_stall_id, which fires trg_sync_stall_occupancy and hands that charger
  --  straight back to section (3). Chargers are freed sooner, never later.
  --
  -- ══ ANTI-STARVATION ══ wash and service headroom are computed with the TWIN'S OWN
  -- capacity formulas, verbatim, so this block can never admit past the lane the twin itself
  -- would allow, and the two lanes are counted separately so neither can starve the other.
  --
  -- ══ IN-DEPOT REASSIGNMENT / ZONES ══ the cursor is restricted to current_state
  -- 'staged_awaiting_service', a HOLDING state. It structurally cannot pick up a vehicle that
  -- is charging, washing or being serviced, so it can never re-route work in progress and
  -- therefore never needs ottoq_indepot_reassignment_guard — this is forward progression to
  -- the next due leg of the same visit, which is exactly what (4) and (5) already do. Zone C
  -- (malfunction / congestion / flag) vehicles are skipped and left to the exception path
  -- that owns them. Zone is NOT required to be 'A' here: ottoq_approach_zone fails closed to
  -- 'B' for any vehicle with no approach-band row, which is every in-depot vehicle, so an
  -- A-only test would silently disable the whole block.
  --
  -- ══ COST ══ ottoq_vehicle_needs_card is a 116-row / ~250 ms view. It is evaluated ONCE per
  -- tick and only after two cheap pre-checks find both a waiting vehicle and lane headroom.
  -- ══════════════════════════════════════════════════════════════════════════════════
  -- 0782 (G502): with bay_open_shop, the 0003 exception below admits any car, not only one owed interrupted bay work
  v_open_shop := COALESCE(public.ottoq_policy_get(p_sim_run_id, 'bay_open_shop', 0), 0) >= 1;
  SELECT count(*) FILTER (WHERE s.stall_type = 'wash_bay'::stall_type),
         count(*) FILTER (WHERE s.stall_type = 'service_bay'::stall_type)
    INTO v_wash_phys, v_svc_phys
    FROM stalls s
   WHERE s.depot_id = v_depot AND s.status NOT IN ('maintenance','closed');

  IF COALESCE(v_wash_phys,0) + COALESCE(v_svc_phys,0) > 0
     AND EXISTS (SELECT 1 FROM vehicles v
                  WHERE v.home_depot_id = v_depot AND v.category = 'autonomous'
                    AND v.current_state = 'staged_awaiting_service') THEN

    v_wash_open := GREATEST(0,
      LEAST(ottoq_sim_lane_capacity(p_sim_run_id,'cleaning_staff', GREATEST(COALESCE(v_wash_phys,0),1)),
            public.ottoq_wash_lane_staff_gate(p_sim_run_id, v_depot))   -- 0746: the supervisors, or none for robotic lanes
      - (SELECT count(*) FROM vehicles
          WHERE home_depot_id = v_depot AND current_state IN ('in_wash_bay','in_detail_bay')));
    v_svc_open := GREATEST(0,
      ottoq_sim_lane_capacity(p_sim_run_id,'service_staff', GREATEST(COALESCE(v_svc_phys,0),1))
      - (SELECT count(*) FROM vehicles
          WHERE home_depot_id = v_depot AND current_state = 'in_service_bay'));

    -- ══════════════ 0003 ANTI-STARVATION BUDGET ══════════════
    -- Resumed bay work outranks fresh work at equal urgency (see the cursor below), so
    -- without a ceiling a queue of interrupted vehicles could take an entire lane and
    -- fresh arrivals would wait. This caps how many of THIS TICK'S admissions per lane
    -- may go to resumption -- but ONLY while fresh candidates are actually competing for
    -- that same lane (fresh_waiting_lane > 0 in the loop). With no fresh demand the cap
    -- does not bite and idle bays are never held empty on principle.
    --   GREATEST(1, ...) is load-bearing: the defect being fixed is bay recovery of ZERO,
    --   so resumption must never be budgeted down to nothing.
    --   share 0.5 => at most half a lane's free bays (rounded up) per tick. With the
    --   depot's 3 wash / 2 service bays that is 1-2 per lane per tick, and the loop runs
    --   every tick, so five interrupted vehicles clear in a handful of ticks.
    v_res_share := LEAST(GREATEST(COALESCE(ottoq_policy_get(p_sim_run_id,'bay_resume_share_max',0.5),0.5), 0), 1);
    v_wash_res_cap := GREATEST(1, CEIL(COALESCE(v_wash_open,0) * v_res_share))::int;
    v_svc_res_cap  := GREATEST(1, CEIL(COALESCE(v_svc_open,0)  * v_res_share))::int;

    IF COALESCE(v_wash_open,0) + COALESCE(v_svc_open,0) > 0 THEN
      FOR v_need IN
        WITH card AS (
          SELECT c.vehicle_id, c.overall_urgency, c.must_do_now, c.minutes_to_deploy,
                 c.fits_window, c.open_must_do_min,
                 -- 0003: the ledger detector and the energy grade, read straight off the card.
                 c.owed_bay_svcs, c.rebook_owed, c.energy_urgency, c.soc_deficit_to_target
            FROM public.ottoq_vehicle_needs_card c
           WHERE c.depot_id = v_depot
             -- CHARGE FIRST (full-service visit doctrine, anchor leg): if energy is still a
             -- must-do, this vehicle belongs to section (3), not to a bay.
             --
             -- ══════════════ 0003: ONE NARROW EXCEPTION, AND WHY ══════════════
             -- MEASURED (run 093c20f4, vehicle 0ea2ccfe): its end-of-run card read
             -- must_do_now = {charge, interior_deep_clean, software_update}. The detail bay
             -- it had been pulled out of was still owed AND still must-do, and this single
             -- predicate excluded it anyway -- for the whole rest of the run.
             -- The exception is deliberately the narrowest one that fixes that case:
             --   (a) the vehicle OWES interrupted bay work (ledger, not cadence);
             --   (b) energy is not 'critical' -- a vehicle that will miss its SLA on charge
             --       is still section (3)'s, always;
             --   (c) there is NO free, available, unreserved charger at this depot RIGHT NOW.
             -- (c) is the load-bearing one. Section (3) has already run this tick with the
             -- very same availability predicate; if a plug existed this vehicle would be on
             -- it. So the bay costs the depot no charging whatsoever -- it is time the car
             -- would otherwise spend parked in staging waiting for a plug that does not exist.
             -- The moment a charger frees, the exception stops applying to new vehicles, and
             -- a car already in a bay is finishing an atomic leg, not being held off energy.
             AND ( NOT ('charge' = ANY (COALESCE(c.must_do_now, '{}'::text[]))
                        OR COALESCE(c.soc_pct, 0) < public.ottoq_effective_target_soc_at(c.vehicle_id, v_clock) - 1)   /* 0543: the one charge rule (G244); the card's deficit is to 100 and left a car at 99% to neither */
                   OR ( (COALESCE(c.rebook_owed, false) OR v_open_shop)   /* 0782 (G502): any car, with bay_open_shop */
                        AND COALESCE(c.energy_urgency, 'ok') <> 'critical'
                        AND NOT EXISTS (
                              SELECT 1 FROM stalls s3
                                JOIN ottoq_ocpp_chargers c3 ON c3.charger_id = s3.ocpp_charger_id
                               WHERE s3.depot_id = v_depot
                                 AND s3.stall_type::text IN ('dcfc','l2')
                                 AND s3.current_vehicle_id IS NULL
                                 AND c3.station_state = 'Available'
                                 AND (s3.reserved_by IS NULL OR s3.reserved_by = c.vehicle_id
                                      OR s3.reservation_expires_at <= v_clock)) ) )
        ), spaced AS (
          SELECT k.vehicle_id, k.overall_urgency, k.minutes_to_deploy, k.fits_window,
                 k.open_must_do_min, x.svc, p.lane, p.sequence_order,
                 -- 0003: is THIS pick a resumption of work the depot already took away?
                 COALESCE(x.svc = ANY (COALESCE(k.owed_bay_svcs, '{}'::text[])), false) AS is_resume,
                 -- 0003: EFFECTIVE urgency. A job that was booked, started and then
                 -- interrupted was must-do when it was booked, so it is at least 'due' --
                 -- even if the twin has since reset its cadence clock by crediting a
                 -- 0.46-minute service as finished (run 093c20f4, vehicle 5cee8fb3). Floor
                 -- it at 'due' (rank 3) and no higher: fresh 'overdue'/'critical' work still
                 -- wins outright, so this can never starve a genuinely urgent new arrival.
                 -- overall_urgency itself is NOT touched -- too many readers depend on it.
                 GREATEST(public.ottoq_urgency_rank(k.overall_urgency),
                          CASE WHEN x.svc = ANY (COALESCE(k.owed_bay_svcs, '{}'::text[]))
                               THEN public.ottoq_urgency_rank('due') ELSE 0 END) AS eff_rank,
                 CASE p.lane WHEN 'wash_bay'    THEN 'wash_bay'
                             WHEN 'detail'      THEN 'wash_bay'
                             WHEN 'service_bay' THEN 'service_bay' END AS stall_type,
                 CASE p.lane WHEN 'wash_bay'    THEN 'wash'
                             WHEN 'detail'      THEN 'detail'
                             WHEN 'service_bay' THEN 'service' END AS purpose,
                 CASE p.lane WHEN 'wash_bay'    THEN 'in_wash_bay'
                             WHEN 'detail'      THEN 'in_detail_bay'
                             WHEN 'service_bay' THEN 'in_service_bay' END AS new_state,
                 CASE p.lane WHEN 'wash_bay'    THEN 'wash_time'
                             WHEN 'detail'      THEN 'detail_time'
                             WHEN 'service_bay' THEN 'maintenance_time' END AS time_key,
                 CASE p.lane WHEN 'wash_bay'    THEN 9
                             WHEN 'detail'      THEN 25
                             ELSE 40 END AS base_min
            FROM card k
            -- 0543 (CLAUDE.md rule 9): the card's must-do list and every wash or detail service still open on the car's
            -- visit. Every service OTTO-Q finds a car to need is required, and a staged car has no other door to those
            -- bays: the service flow's wash lane takes only cars coming off a charger.
            CROSS JOIN LATERAL (SELECT DISTINCT u.svc
                                  FROM unnest(COALESCE(k.must_do_now, '{}'::text[])
                                              || ARRAY(SELECT a->>'svc'
                                                         FROM ottoq_visit_needs vn
                                                         CROSS JOIN LATERAL jsonb_array_elements(vn.atoms) a
                                                         JOIN public.service_cadence_policy cp
                                                           ON cp.svc = a->>'svc' AND cp.is_active
                                                          AND cp.lane IN ('wash_bay','detail')
                                                        WHERE vn.vehicle_id = k.vehicle_id AND vn.sim_run_id = p_sim_run_id
                                                          AND vn.status IN ('open','in_progress')
                                                          AND COALESCE(a->>'status','pending') NOT IN ('done','cancelled','skipped'))) AS u(svc)) AS x(svc)
            JOIN public.service_cadence_policy p ON p.svc = x.svc AND p.is_active
           WHERE p.lane IN ('wash_bay','detail','service_bay')
        ), pick AS (
          -- SEQUENCE inside the visit: the catalogue's own order -- except that 0003 puts
          -- UNFINISHED work first. If a vehicle both owes an interrupted job and has fresh
          -- cadence work due, finish what the depot already started. That is the atomic
          -- full-service visit read literally.
          SELECT DISTINCT ON (s.vehicle_id) s.*
            FROM spaced s
           ORDER BY s.vehicle_id, s.is_resume DESC, s.sequence_order, s.svc
        ), ranked AS (
          SELECT pk.vehicle_id, pk.svc, pk.lane, pk.stall_type, pk.purpose, pk.new_state,
                 pk.time_key, pk.base_min, pk.overall_urgency, pk.minutes_to_deploy,
                 pk.fits_window, pk.open_must_do_min, pk.sequence_order, pk.is_resume,
                 pk.eff_rank, v.fleet_operator_id,
                 -- 0747 (G461): the uptime-first key, NULL with bay_order_uptime_first off (then NULLs tie, and the
                 -- order below is the order before 0747)
                 public.ottoq_bay_uptime_order_key(p_sim_run_id, pk.vehicle_id, pk.svc, pk.is_resume, v_clock) AS upf_key
            FROM pick pk
            JOIN vehicles v ON v.id = pk.vehicle_id
           WHERE v.home_depot_id = v_depot AND v.category = 'autonomous'
             AND v.current_state = 'staged_awaiting_service'
             AND COALESCE(public.ottoq_approach_zone(pk.vehicle_id, p_sim_run_id),'B') <> 'C'
             -- 0761 (G479): a car its stall's cleaning arm is at work in, or an unfinished data transfer holds on its
             -- uplink stall, is passed over, as section (4) passes it over (0695, 0758). The twin stages a robotic
             -- charger's car in the tick its charge stops, still on the charger. False for every car while no dial
             -- raises such work.
             AND NOT ottoq.ottoq_uplink_transfer_holds(pk.vehicle_id, p_sim_run_id)
             -- 0761 (G472): and with bay_walkin_waits_for_the_arm, a car the charge arm still holds (the interlock's
             -- own test), as section (4) passes it over (0011-TETHER). Asked to move it, the interlock refuses and the
             -- refusal is filed as an exception; the car is read again next tick, once the arm lets go.
             AND NOT (public.ottoq_policy_get(p_sim_run_id, 'bay_walkin_waits_for_the_arm', 0) >= 0.5
                      AND public.ottoq_vehicle_is_tethered(pk.vehicle_id, v_clock))
        )
        SELECT rk.*,
               -- 0003: how many FRESH candidates are competing for this same lane this tick.
               -- Window functions are evaluated over the whole qualifying set BEFORE the
               -- LIMIT, so this is the true competing demand, not just what fits in 20 rows.
               -- The resumption budget below only bites when this is > 0.
               count(*) FILTER (WHERE NOT rk.is_resume) OVER (PARTITION BY rk.stall_type)
                 AS fresh_waiting_lane
               -- 0169: rank over the WHOLE qualifying set so the loop can see the
               -- candidates the tick budget excludes, instead of dropping them
               -- before they are ever named. Same ordering as the LIMIT it replaces.
               , row_number() OVER (ORDER BY rk.upf_key ASC NULLS LAST,   -- 0747
                                             rk.eff_rank DESC,
                                             rk.is_resume DESC,
                                             rk.minutes_to_deploy ASC NULLS LAST,
                                             rk.open_must_do_min ASC NULLS LAST,
                                             rk.vehicle_id) AS seat_rank
               , count(*) OVER () AS seat_qualified
          FROM ranked rk
         ORDER BY rk.upf_key ASC NULLS LAST,   -- 0747
                  rk.eff_rank DESC,
                  rk.is_resume DESC,
                  rk.minutes_to_deploy ASC NULLS LAST,
                  rk.open_must_do_min ASC NULLS LAST,
                  rk.vehicle_id
      LOOP
        -- 0169: the tick budget, recorded rather than silent. A vehicle past the
        -- budget was never considered; noop_no_candidate would be a lie about it.
        IF v_need.seat_rank > public.ottoq_policy_get(p_sim_run_id, 'decide_seat_batch', 20) THEN
          INSERT INTO ottoq_decisions (sim_run_id,tick_seq,sim_clock,depot_id,snapshot_id,action_context,entity_type,entity_id,context_frame,proposed_action,enacted_action,outcome_status,propose_latency_ms,total_latency_ms)
          VALUES (p_sim_run_id,v_tick,v_clock,v_depot,v_snapshot_id,'stall_assignment','vehicle',v_need.vehicle_id,
                  jsonb_build_object('seat_rank',v_need.seat_rank,'seat_qualified',v_need.seat_qualified,
                                     'seat_batch',public.ottoq_policy_get(p_sim_run_id,'decide_seat_batch',20),
                                     'stall_type',v_need.stall_type,'lane',v_need.lane),
                  '{}'::jsonb,'{}'::jsonb,'deferred_tick_budget',0,0);
          CONTINUE;
        END IF;
        IF v_need.stall_type = 'wash_bay'    AND COALESCE(v_wash_open,0) <= 0 THEN CONTINUE; END IF;
        IF v_need.stall_type = 'service_bay' AND COALESCE(v_svc_open,0)  <= 0 THEN CONTINUE; END IF;
        -- 0003 ANTI-STARVATION: hold resumption to its per-lane share of THIS tick's
        -- admissions, and only while fresh work is actually queued for the same lane.
        -- Skipping here is a pure CONTINUE: the vehicle keeps its place in the next tick's
        -- cursor with its 'due' floor intact, so nothing is dropped, only sequenced.
        IF COALESCE(v_need.is_resume,false) AND COALESCE(v_need.fresh_waiting_lane,0) > 0 THEN
          IF v_need.stall_type = 'wash_bay'    AND v_wash_res_used >= COALESCE(v_wash_res_cap,1) THEN CONTINUE; END IF;
          IF v_need.stall_type = 'service_bay' AND v_svc_res_used  >= COALESCE(v_svc_res_cap,1)  THEN CONTINUE; END IF;
        END IF;

        v_built := v_built + 1; v_t0 := clock_timestamp();
        v_over := false; v_safe := false; v_block_codes := '{}'; v_rule_rows := NULL;
        v_ctx := ottoq_build_decision_context('task_start','vehicle',v_need.vehicle_id,v_depot,v_clock)
                 || jsonb_build_object('need', v_need.svc, 'lane', v_need.lane,
                      'stall_type', v_need.stall_type, 'purpose', v_need.purpose,
                      'overall_urgency', v_need.overall_urgency,
                      'minutes_to_deploy', v_need.minutes_to_deploy,
                      'fits_window', v_need.fits_window,
                      'open_must_do_min', v_need.open_must_do_min,
                      'sequence_order', v_need.sequence_order,
                      -- 0003: make bay RECOVERY countable straight off the decision row.
                      'is_resume', COALESCE(v_need.is_resume,false),
                      'eff_urgency_rank', v_need.eff_rank,
                      'fresh_waiting_lane', v_need.fresh_waiting_lane,
                      'resume_cap_lane', CASE WHEN v_need.stall_type = 'wash_bay'
                                              THEN v_wash_res_cap ELSE v_svc_res_cap END,
                      'requires_charging','false','service', v_need.purpose)
                 || CASE WHEN v_need.upf_key IS NULL THEN '{}'::jsonb
                         ELSE jsonb_build_object('uptime_key', to_jsonb(v_need.upf_key)) END   -- 0747
                 || CASE WHEN v_open_shop AND ottoq.ottoq_vehicle_owes_charge_now(v_need.vehicle_id, v_clock)
                         THEN jsonb_build_object('bay_before_charge', true) ELSE '{}'::jsonb END;   -- 0782 (G502)
        v_proposal := jsonb_build_object('abstain', false, 'verb','assign_stall',
                        'resolved_action_context','stall_assignment', 'source','needs_card',
                        'vehicle_id', v_need.vehicle_id, 'stall_type', v_need.stall_type,
                        'purpose', v_need.purpose, 'need', v_need.svc, 'requested_kw', 0,
                        -- 0003: recorded on the PROPOSAL, not on the booking. p_source of
                        -- ottoq.ottoq_enact_space_assignment is deliberately left at the
                        -- existing literal 'needs_card' -- inventing a new vocabulary value
                        -- for a downstream writer is exactly the 2026-08-01 leg_type trap.
                        'is_resume', COALESCE(v_need.is_resume,false));
        v_prop_ms := EXTRACT(MILLISECOND FROM (clock_timestamp()-v_t0))::int;

        v_t0 := clock_timestamp();
        SELECT count(*) FILTER (WHERE would_block), array_agg(rule_code) FILTER (WHERE would_block),
               jsonb_agg(jsonb_build_object('rule_code',rule_code,'passed',passed,'reason',reason,'enforcement_taken',enforcement_taken,'severity',severity))
          INTO v_blocks, v_block_codes, v_rule_rows
          FROM ottoq_shield_probe('task_start','vehicle',v_need.vehicle_id,v_ctx,v_need.fleet_operator_id,v_depot);
        v_shield_ms := EXTRACT(MILLISECOND FROM (clock_timestamp()-v_t0))::int;

        v_t0 := clock_timestamp();
        IF COALESCE(v_blocks,0) > 0 THEN
          -- SHIELD BLOCKS => take NO space. The vehicle stays in staging and section (5)
          -- handles it exactly as today. Bays are ADDITIVE, so a refusal here can only ever
          -- return the engine to its pre-P1 behaviour - never worse.
          v_action := jsonb_build_object('verb','hold_no_space','reason','shield_block');
          v_safe := true; v_over := true; v_outcome := 'overridden_to_default'; v_overc := v_overc + 1;
        ELSE
          -- TIMING BELONGS TO THE TWIN. ottoq_sim_service_minutes is the exact function
          -- twin STEP 2 uses for its own admissions, so routing a car here cannot invent a
          -- new dwell regime. The planner's timed leg is preferred whenever one exists.
          -- 0549 (G278): the leg's length from now, not its planned end. A car seated now is
          -- served now; asking for the bay until a leg planned hours later held the bay until then.
          SELECT l.leg_id, v_clock + (l.planned_end_sim - l.planned_start_sim) INTO v_bay_leg_id, v_bay_until
            FROM public.ottoq_itinerary_legs l
           WHERE l.sim_run_id = p_sim_run_id AND l.vehicle_id = v_need.vehicle_id
             AND l.status = 'planned' AND l.to_stall_id IS NULL
             AND l.leg_type = public.ottoq_svc_to_leg_type(v_need.svc)
             AND l.planned_end_sim IS NOT NULL AND l.planned_end_sim > v_clock
           ORDER BY l.seq, l.planned_start_sim, l.planned_end_sim, l.leg_id /* 0129 */ LIMIT 1;
          v_bay_until := GREATEST(
            COALESCE(v_bay_until,
                     v_clock + make_interval(mins => GREATEST(
                       ottoq_sim_service_minutes(p_sim_run_id, v_need.time_key, v_need.base_min)::int, 1))),
            v_clock + interval '1 minute');

          v_space := ottoq.ottoq_enact_space_assignment(
                       p_sim_run_id, v_depot, v_need.vehicle_id, v_need.stall_type,
                       v_need.purpose, v_clock, v_bay_until, v_bay_leg_id, 'needs_card');
          -- 0553 (G283): a bay held for a car that cannot be here before this one would finish gives way to it.
          -- ottoq_yield_bay_holds moves those holds to their car's ETA; then the assignment is tried once more.
          IF NOT COALESCE((v_space->>'assigned')::boolean, false)
             AND COALESCE(v_space->>'reason', '') = 'no_free_space' THEN
            IF ottoq.ottoq_yield_bay_holds(p_sim_run_id, v_depot, v_need.stall_type, v_clock, v_bay_until,
                                           v_need.vehicle_id) > 0 THEN
              v_space := ottoq.ottoq_enact_space_assignment(
                           p_sim_run_id, v_depot, v_need.vehicle_id, v_need.stall_type,
                           v_need.purpose, v_clock, v_bay_until, v_bay_leg_id, 'needs_card')
                         || jsonb_build_object('yielded_holds', true);
            END IF;
          END IF;

          IF COALESCE((v_space->>'assigned')::boolean, false) THEN
               -- 0039: bay entry handled by twin on command confirmation below
            IF v_need.stall_type = 'wash_bay' THEN
              v_wash_open := v_wash_open - 1;
              IF COALESCE(v_need.is_resume,false) THEN v_wash_res_used := v_wash_res_used + 1; END IF;
            ELSE
              v_svc_open := v_svc_open - 1;
              IF COALESCE(v_need.is_resume,false) THEN v_svc_res_used := v_svc_res_used + 1; END IF;
            END IF;
            v_action := v_proposal || v_space
                        || jsonb_build_object('verb','assign_stall',
                             'stall_id', v_space->>'stall_id',
                             'bay_booked', (v_space->>'booking_id') IS NOT NULL,
                             -- 0003: THE P0 NUMERATOR. A true here is one unit of
                             -- "cut-short bay work re-booked into a space it holds".
                             'resumed_bay_work', COALESCE(v_need.is_resume,false),
                             'resumed_need', CASE WHEN COALESCE(v_need.is_resume,false)
                                                  THEN v_need.svc ELSE NULL END);
            v_outcome := 'enacted'; v_enacted := v_enacted + 1;
            -- 0081: a bay assignment must SEAT the vehicle. proceed_to_stall only moves
            -- current_stall_id and leaves current_state unchanged, so the wash/service never
            -- started, section (5) yanked the still-staged vehicle back out, and the booking
            -- died 'bay_exit_before_planned_end' -- measured 28x in one run. enter_wash /
            -- enter_service carry the state transition (in_wash_bay / in_detail_bay /
            -- in_service_bay) exactly like sections (4) and (5) already emit for their bays.
            PERFORM ottoq_emit_vehicle_command(p_sim_run_id, v_depot, v_need.vehicle_id,
              CASE WHEN v_need.stall_type = 'service_bay' THEN 'enter_service' ELSE 'enter_wash' END,
              jsonb_build_object('stall_id',   v_space->>'stall_id',
                                 'booking_id', v_space->>'booking_id',
                                 'leg_id',     v_bay_leg_id,
                                 'purpose',    v_need.purpose,
                                 'reason',     'needs_card_' || v_need.purpose,
                                 'need',       v_need.svc), v_clock);
          ELSE
            v_action := v_proposal || COALESCE(v_space,'{}'::jsonb)
                        || jsonb_build_object('verb','hold_no_space',
                             'resumed_bay_work', COALESCE(v_need.is_resume,false));
            v_outcome := 'noop_no_candidate'; v_deferred := v_deferred + 1;
          END IF;
        END IF;
        v_enact_ms := EXTRACT(MILLISECOND FROM (clock_timestamp()-v_t0))::int;
        -- action_context 'task_start' matches the probe context used by (4) and (5) for bay
        -- admissions; resolved_action_context 'stall_assignment' is the HONEST classification
        -- because a space really was claimed AND booked - which is also what makes bays
        -- finally countable in the enacted_stall_by_space_type metric that read 51/51 charging.
        INSERT INTO ottoq_decisions (sim_run_id,tick_seq,sim_clock,depot_id,snapshot_id,action_context,resolved_action_context,entity_type,entity_id,context_frame,proposed_action,enacted_action,overridden,override_rule_codes,rule_results,safe_default_taken,outcome_status,propose_latency_ms,shield_latency_ms,enact_latency_ms,total_latency_ms)
        VALUES (p_sim_run_id,v_tick,v_clock,v_depot,v_snapshot_id,'task_start','stall_assignment','vehicle',v_need.vehicle_id,v_ctx,v_proposal,v_action,v_over,v_block_codes,COALESCE(v_rule_rows,'[]'::jsonb),v_safe,v_outcome,v_prop_ms,v_shield_ms,v_enact_ms,COALESCE(v_prop_ms,0)+COALESCE(v_shield_ms,0)+COALESCE(v_enact_ms,0));
      END LOOP;
    END IF;
  END IF;

  -- (5) SERVICE SEQUENCING
  -- 0081: SERVICE SEQUENCING must not promote a vehicle that still owes must-do WASH or
  -- DETAIL work. That work belongs to (4b), which routes it to the wash lane. Before this guard,
  -- ottoq_l2_propose_service saw no service_bay atom on a wash-due vehicle, returned
  -- 'promote_ready', and emitted stage(ready:true) in the SAME tick (4b) routed it to the wash
  -- bay -- the vehicle oscillated and the wash never ran. Skip wash/detail-must-do vehicles here;
  -- (4b) seats them, and this loop re-sees them on a later tick once the wash is done.
  FOR v_req IN
    SELECT v.id AS vehicle_id, v.fleet_operator_id, v.config->>'svc_step' AS svc_step
      FROM vehicles v WHERE v.home_depot_id=v_depot AND v.category='autonomous'
       AND v.current_state='staged_awaiting_service'
       -- 0761 (G479, G472): passed over while the cleaning arm or a data transfer holds the car, and with
       -- bay_walkin_waits_for_the_arm while the charge arm does, as in (4b) above.
       AND NOT ottoq.ottoq_uplink_transfer_holds(v.id, p_sim_run_id)
       AND NOT (public.ottoq_policy_get(p_sim_run_id, 'bay_walkin_waits_for_the_arm', 0) >= 0.5
                AND public.ottoq_vehicle_is_tethered(v.id, v_clock))
       AND NOT EXISTS (SELECT 1 FROM ottoq_visit_needs n, jsonb_array_elements(n.atoms) a
                        WHERE n.vehicle_id = v.id AND n.status IN ('open','in_progress') AND COALESCE(n.sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE(p_sim_run_id, '00000000-0000-0000-0000-000000000000'::uuid) /* 0124 */
                          AND a->>'svc' IN ('exterior_wash','interior_deep_clean')
                          AND COALESCE(a->>'must_do','false') = 'true'
                          AND COALESCE(a->>'status','pending') NOT IN ('done','cancelled','skipped'))
     ORDER BY v.last_state_change ASC NULLS FIRST, v.id LIMIT 40
  LOOP
    v_built:=v_built+1; v_t0:=clock_timestamp(); v_over:=false; v_safe:=false; v_block_codes:='{}'; v_disarm:='[]'::jsonb;
    v_ctx := ottoq_build_decision_context('task_start','vehicle',v_req.vehicle_id,v_depot,v_clock) || jsonb_build_object('svc_step', v_req.svc_step, 'requires_charging','false','service','service');
    -- A1: cuOpt/Nemotron may propose the service order; heuristic is the fallback.
    v_proposal := COALESCE(
      ottoq_l2_external_proposal(p_sim_run_id, 'service_sequencing', 'vehicle', v_req.vehicle_id),
      ottoq_l2_propose_service(v_req.vehicle_id, v_depot, v_ctx));
    v_prop_ms:=EXTRACT(MILLISECOND FROM (clock_timestamp()-v_t0))::int;
    v_t0:=clock_timestamp();
    SELECT count(*) FILTER (WHERE would_block), array_agg(rule_code) FILTER (WHERE would_block),
           jsonb_agg(jsonb_build_object('rule_code',rule_code,'passed',passed,'reason',reason,'enforcement_taken',enforcement_taken,'severity',severity))
      INTO v_blocks, v_block_codes, v_rule_rows
      FROM ottoq_shield_probe('task_start','vehicle',v_req.vehicle_id,v_ctx,v_req.fleet_operator_id,v_depot);
    v_shield_ms:=EXTRACT(MILLISECOND FROM (clock_timestamp()-v_t0))::int;
    v_t0:=clock_timestamp();
    IF COALESCE(v_blocks,0)>0 THEN v_action:=ottoq_l1_safe_default_service(v_req.vehicle_id,v_ctx); v_safe:=true; v_over:=true; v_outcome:='overridden_to_default'; v_overc:=v_overc+1;
    ELSE
      v_action:=v_proposal; v_outcome:='enacted'; v_enacted:=v_enacted+1;
      IF v_action->>'verb'='admit_service' THEN
        -- BAY ENTRY MOVED BELOW THE HELPER (Phase 3) -- same defect and same fix as (4).
        -- CALENDAR (service bay). CHOOSE + RECORD ONLY, never gating - same contract as (4).
        SELECT l.leg_id, (l.planned_end_sim - l.planned_start_sim)
          INTO v_bay_leg_id, v_bay_dur
          FROM public.ottoq_itinerary_legs l
         WHERE l.sim_run_id = p_sim_run_id AND l.vehicle_id = v_req.vehicle_id
           AND l.status = 'planned' AND l.to_stall_id IS NULL
           AND l.leg_type IN ('service','mechanical_pm','fault_repair','sensor_calibration','cosmetic_repair')
         ORDER BY l.seq, l.planned_start_sim, l.planned_end_sim, l.leg_id /* 0129 */ LIMIT 1;
        IF v_bay_leg_id IS NULL THEN
          -- FALLBACK: adopt the leg the forward planner already booked (see section (4)).
          SELECT l.leg_id, (l.planned_end_sim - l.planned_start_sim)
            INTO v_bay_leg_id, v_bay_dur
            FROM public.ottoq_itinerary_legs l
           WHERE l.sim_run_id = p_sim_run_id AND l.vehicle_id = v_req.vehicle_id
             AND l.status IN ('planned','active')
             AND l.leg_type IN ('service','mechanical_pm','fault_repair','sensor_calibration','cosmetic_repair')
           ORDER BY (l.status = 'active') DESC, l.seq, l.planned_start_sim, l.planned_end_sim, l.leg_id /* 0129 */ LIMIT 1;
        END IF;
        -- TOTAL allow-list: all five of those leg types collapse to the single legal
        -- purpose 'service'. The leg_type itself is NEVER passed through.
        v_bay_until := v_clock + GREATEST(
          COALESCE(v_bay_dur,
                   make_interval(mins => ottoq_policy_get(p_sim_run_id,'service_bay_default_min',45)::int)),
          interval '1 minute');
        v_space := ottoq.ottoq_enact_space_assignment(p_sim_run_id, v_depot, v_req.vehicle_id,
                       'service_bay', 'service', v_clock, v_bay_until,
                       v_bay_leg_id, 'service_sequencing');
        v_bay_bkg := NULLIF(v_space->>'booking_id','')::uuid;
        IF v_bay_bkg IS NOT NULL AND v_bay_leg_id IS NOT NULL THEN
          UPDATE public.ottoq_itinerary_legs
             SET to_stall_id = (SELECT b.stall_id FROM public.ottoq_stall_bookings b
                                 WHERE b.booking_id = v_bay_bkg)
           WHERE leg_id = v_bay_leg_id;
        END IF;
        IF COALESCE((v_space->>'assigned')::boolean, false) THEN
      -- 0039: vehicle state update handled by twin on 'enter_service' command confirmation
          PERFORM ottoq_emit_vehicle_command(p_sim_run_id, v_depot, v_req.vehicle_id, 'enter_service',
                  jsonb_build_object('stall_id',   v_space->>'stall_id',
                                     'booking_id', v_space->>'booking_id',
                                     'leg_id',     v_bay_leg_id,
                                     'purpose',    'service'), v_clock);
          v_action := COALESCE(v_action,'{}'::jsonb) || COALESCE(v_space,'{}'::jsonb)
                      || jsonb_build_object('bay_booked', v_bay_bkg IS NOT NULL,
                                            'bay_purpose', 'service',
                                            'bay_stall_type', 'service_bay',
                                            'stall_id', v_space->>'stall_id',
                                            'booking_id', v_space->>'booking_id',
                                            'leg_id', v_bay_leg_id);
        ELSE
          -- NO BAY -> DO NOT ENTER ONE. Identical in effect to this proposer's own
          -- 'hold_in_queue': the vehicle stays in staged_awaiting_service and is retried.
          v_action := COALESCE(v_action,'{}'::jsonb) || COALESCE(v_space,'{}'::jsonb)
                      || jsonb_build_object('verb','hold_no_bay', 'bay_booked', false,
                                            'bay_purpose', 'service',
                                            'bay_stall_type', 'service_bay');
          v_outcome := 'noop_no_candidate'; v_enacted := v_enacted - 1; v_deferred := v_deferred + 1;
        END IF;
      ELSIF v_action->>'verb' = 'hold_in_queue' THEN
        -- SERVICE-NEED HOLD: must-do bay work outstanding and no free bay (or the
        -- shield blocked). Leave the vehicle in staged_awaiting_service - no state
        -- write at all - so the service queue keeps it instead of redeploying a
        -- vehicle with mandatory work open. The proposer bounds this with a
        -- patience threshold, so a hold can never strand a vehicle.
        NULL;
      ELSE
      -- 0469 (G200): no command. This emitted stage {ready: true} every tick for every ready car (7,686 on
        -- 317d4331) and the door maps stage to no transition; the release happens in the service flow's
        -- readiness gate, which reads the car's step. The decision row below still records the verdict.
        NULL;
      END IF;
    END IF;
    v_enact_ms:=EXTRACT(MILLISECOND FROM (clock_timestamp()-v_t0))::int;
    INSERT INTO ottoq_decisions (sim_run_id,tick_seq,sim_clock,depot_id,snapshot_id,action_context,resolved_action_context,entity_type,entity_id,context_frame,proposed_action,enacted_action,overridden,override_rule_codes,rule_results,safe_default_taken,outcome_status,propose_latency_ms,shield_latency_ms,enact_latency_ms,total_latency_ms)
    VALUES (p_sim_run_id,v_tick,v_clock,v_depot,v_snapshot_id,'task_start','task_start','vehicle',v_req.vehicle_id,v_ctx,v_proposal,v_action,v_over,v_block_codes,COALESCE(v_rule_rows,'[]'::jsonb),v_safe,v_outcome,v_prop_ms,v_shield_ms,v_enact_ms,COALESCE(v_prop_ms,0)+COALESCE(v_shield_ms,0)+COALESCE(v_enact_ms,0));
  END LOOP;

  -- A3: close the external-proposal lifecycle for this tick — consumed
  -- (entity got an enacted decision) → 'enacted'; past-freshness → 'expired'.
  UPDATE ottoq_external_proposals p
     SET status='enacted', disposition_reason='enacted_by_kernel',
         disposed_at=clock_timestamp(), disposed_tick=v_tick
   WHERE p.sim_run_id=p_sim_run_id AND p.status='pending'
     AND EXISTS (SELECT 1 FROM ottoq_decisions d
                  WHERE d.sim_run_id=p_sim_run_id AND d.tick_seq=v_tick
                    AND d.entity_id=p.entity_id AND d.outcome_status='enacted'
                    AND d.enacted_action->>'source' = p.source);
  -- honest pre-emption: the entity was decided this tick, but NOT by this proposal
  UPDATE ottoq_external_proposals p
     SET status='superseded', disposition_reason='entity_decided_by_other_proposal',
         disposed_at=clock_timestamp(), disposed_tick=v_tick
   WHERE p.sim_run_id=p_sim_run_id AND p.status='pending'
     AND EXISTS (SELECT 1 FROM ottoq_decisions d
                  WHERE d.sim_run_id=p_sim_run_id AND d.tick_seq=v_tick
                    AND d.entity_id=p.entity_id AND d.outcome_status='enacted');
  PERFORM public.ottoq_dispose_external_proposals(p_sim_run_id, v_tick, v_clock, false);

  -- ══════════════════ BUILD 3: THE INSPECT SEAM (ADDITIVE) ══════════════════
  -- 177 inspect legs ended the prior run still 'planned' across 110 arriving vehicles
  -- while 14 inspection stalls per depot sat idle, because (1) the needs card never
  -- emits 'interior_inspection', (2) this tick's bay loop filters to lanes
  -- wash_bay/detail/service_bay and inspection is lane 'cabin', and (3) inspection
  -- stalls are stall_type='staging' so no caller could address them.
  -- Placed HERE, last, on purpose: charging (3), the bay loop and service sequencing
  -- (5) have all already run, so the seam can only take vehicles nothing else claimed.
  -- It never raises (see the handler inside) -- the 2026-08-01 leg_type lesson.
  v_enacted := v_enacted + COALESCE(
    ottoq.ottoq_enact_inspection_seam(p_sim_run_id, v_depot, v_tick, v_snapshot_id, v_clock), 0);

  PERFORM ottoq.ottoq_link_bookings_to_decisions(p_sim_run_id, v_tick);

  RETURN ROW(v_tick, v_clock, v_built, v_enacted, v_overc, v_deferred, v_errored, v_disn,
             (SELECT COALESCE(SUM(total_latency_ms),0) FROM ottoq_decisions WHERE sim_run_id=p_sim_run_id AND tick_seq=v_tick))::ottoq_decide_tick_result;
END;
$function$;
-- @@ function public.ottoq_l2_propose_deploy(p_vehicle_id uuid, p_depot_id uuid, p_context jsonb)
CREATE OR REPLACE FUNCTION public.ottoq_l2_propose_deploy(p_vehicle_id uuid, p_depot_id uuid, p_context jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
DECLARE
  v_soc      numeric := COALESCE((p_context->>'current_soc')::numeric, 0);
  v_fleet_op uuid    := NULLIF(p_context->>'fleet_operator_id','')::uuid;
  v_floor    numeric;
BEGIN
  -- Read the SAME deploy floor the shield (SLA.001) enforces, so L2 proposes only
  -- shield-passable deploys. Guarded: a NULL/absent fleet op falls back to 80.
  BEGIN
    SELECT min_soc_at_deployment_pct INTO v_floor FROM ottoq_get_active_sla(v_fleet_op);
  EXCEPTION WHEN OTHERS THEN
    v_floor := NULL;
  END;
  v_floor := COALESCE(v_floor, 80);

  IF v_soc < v_floor THEN
    RETURN jsonb_build_object('abstain', true, 'reason', 'soc_below_deploy_floor',
      'soc', v_soc, 'floor', v_floor);
  END IF;
  RETURN jsonb_build_object('abstain', false, 'resolved_action_context','redeployment',
    'verb','deploy', 'vehicle_id', p_vehicle_id, 'fleet_operator_id', p_context->>'fleet_operator_id',
    'rationale', jsonb_build_object('soc', v_soc, 'floor', v_floor));
END;
$function$;
-- @@ function public.ottoq_l1_safe_default_deploy(p_vehicle_id uuid, p_context jsonb)
CREATE OR REPLACE FUNCTION public.ottoq_l1_safe_default_deploy(p_vehicle_id uuid, p_context jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'twin', 'ottoq', 'public', 'extensions'
AS $function$
